INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('1731 Fine & Rare Guatemala Gran Reserva Rum', 'https://rombo.dk/products/1731-fine-rare-guatemala', 399, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ff682b69-28af-45c6-87db-12f780abe142.png?v=1769439769', '1731 Fine &amp; Rare Guatemala Gran Reserva Rum er en kolonne-destilleret rom fra et enkelt og unavngivet destilleri i mellemamerikanske Guatemala, hvorfra vi også kender Ron Zacapa. 1731 Fine &amp; Rare serien består af naturlig rom uden tilsat sukker, og det gælder også denne Guatemala udgave. Der er ej heller tilsat farve eller anvendt kølefiltrering. Rommen er tropisk lagret på ex-bourbonfade i minimum fire år og udgivet af 1731 Fine &amp; Rare, der ligger i Holland. 46% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Old St. Croix XO Explorer Danmark', 'https://rombo.dk/products/ah-riise-old-st-croix-xo-explorer-danmark', 599, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2e6e0a23-1038-4c42-9016-3a430bfce791.png?v=1769437421', 'A.H. Riise Old St. Croix XO Explorer Danmark er pr. 1. august 2024 en ny eksklusiv Explorer-serie til hyldest af de modige forskere, eventyrere og opdagelsesrejsende, der på A.H. Riise''s tid bidrog til kortlægningen og forståelsen af verden. A.H. Riise XO Explorer-serien består af en række Limited Editions, der udkommer i en række forskellige lande i et meget begrænset antal flasker, som alle er nummererede. A.H. Riise Old St. Croix XO Explorer Danmark er skabt specielt til A.H. Riise fans og samlere i de respektive lande, hvor Explorer udgivelserne frigives, og disse flasker udkommer i et meget begrænset antal. Den danske XO Explorer udgave er begrænset til kun 6.960 flasker, og der er tale om et eksklusivt Limited Edition-blend fra Vestindien og Mellemamerika. I duften finder man karamel og moden frugt, mens smagen byder på noter af kraftig umami fra egetræ, tobak, gammelt læder og sødme fra brændte figner samt kandiseret citrusskal. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A1710 Bête à Feu Rhum Blanc Extraordinaire Rom', 'https://rombo.dk/products/a1710-bete-a-feu-rom', 475, true, 70, 50.9, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a7f33f02-b9ab-4cc4-b885-1032acd87b79.png?v=1769427402', 'A1710 Bête à Feu Rhum Blanc Extraordinaire rom har fået sit navn efter ildfluen, som også pryder etiketten, og som ofte kan ses over sukkerrørsmarkerne ved solnedgangstid hos A1710. A1710 blev grundlagt i 2016 og er allerede kendt for at lave øens bedste hvide rom. Bête à Feu Rhum Blanc Extraordinaire er lavet på frisk sukkerrørssaft og destilleret på destilleriets pot still , som har fået navnet ’la Belle Aline’. Det er en enkelt kobberkedel kombineret med en mindre kolonne med syv kobberplader. Rommen er blevet langsomt reduceret og tappet ved 50,9 % ABV. Den har smag af friske sukkerrør, honning, pære, blomster og peber med en mineralsk eftersmag, der gør den fortrinlig til cocktails. A1710 Bête à Feu har vundet adskillige priser, bl.a. dobbelt guld ved Caribbean Rum Awards i 2020 og World’s Best Agricole &amp; Sugar Cane Juice ved World Rum Awards i 2021. 50,9% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A1710 Diamond Rock Rhum Blanc Extraordinaire Rom', 'https://rombo.dk/products/a1710-diamond-rock-rom', 499, true, 70, 50.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/A1710DiamondRockRhumBlancExtraordinaireRom.png?v=1774517984', 'A1710 Diamond Rock Rhum Blanc Extraordinaire rom er destilleriets bestseller og opkaldt efter en klippeø 3 km syd for Martinique, der ligner en diamant, når solens stråler genspejles i klipperne. Rommen er fremstillet af frisk sukkerrørssaft og destilleret på destilleriets pot still, som har fået navnet ’la Belle Aline’, som er en enkelt kobberkedel kombineret med en mindre kolonne med syv kobberplader. A1710 Diamond Rock Rhum Blanc Extraordinaire har smagsnoter af blommer, kastanjer, hvide frugter, mandler og sukkerrør, efterfulgt af læder og mineralitet. Rommen er destilleriets bestseller og en let tilgængelig, drikkevenlig rom, der egner sig godt som ingrediens i diverse cocktails. 50,5% ­– 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A1710 La Perle Brute 66* Millésime 2021 Rom', 'https://rombo.dk/products/la-perle-brute-66', 449, true, 50, 66, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_533e89ac-6c93-4915-a94b-8d5411dc931f.png?v=1769423640', 'La Perle Brute 66* er en hvid Rhum Agricole fra det mindre A1710 destilleri på Martinique. Denne rom er ikke AOC Martinique godkendt, da den er destilleret på en Alambique Pot Still (og ikke enkeltkolonne), men det gør den ikke til en ringere oplevelse. La Perle Brute 66* Millésime 2021 er tappet ved fadstyrke uden nogen tilsætning og altså ikke-lagret. En rom, der byder på en smidig og indbydende næse. Frugtagtige noter, krydret og pebret. Ved sine 66% er La Perle Brute 66* naturligvis heftig, men samtidig dejlig blød og rund. 66% - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo 12 år + Abuelo XII Two Oaks 20 cl sample', 'https://rombo.dk/products/abuelo-12-og-xii-two-oaks-sample', 385, true, 90, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_12_ar_Abuelo_XII_Two_Oaks_20_cl_sample.png?v=1770194818', 'Ron Abuelo Anejo Gran Reserva Rum 12 år er blandet af to typer: en let, ren rom, der er destilleret til en højere alkoholprocent og en mere aromatisk rom med en stor, krydret smag. Efter blandingen lagres rommen på egefade, der giver den noter af vanilje og karamel. Den har duft af sukkerrør og appelsin og smag, der er krydret og fyldig med en god balance. Eftersmag: lang og sød. Her får du Abuelo 12 års 70 cl flasken i en gaveæske sammen med en Abuelo XII Two Oaks 20 cl smageflaske. 40% - 90 cl. (70 cl. + 20 cl.)');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo 12 år Gran Reserva Rom', 'https://rombo.dk/products/ron-abuelo-12-gran-reserva-rum', 325, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_12_ar_Gran_Reserva_Rom.png?v=1774519021', 'Ron Abuelo Anejo Gran Reserva Rum 12 år er blandet af to typer: en let, ren rom, der er destilleret til en højere alkoholprocent og en mere aromatisk rom med en stor, krydret smag. Efter blandingen lagres rommen på egefade, der giver den noter af vanilje og karamel. Duft af sukkerrør og appelsin og smag, der er krydret og fyldig med en god balance. Eftersmag: lang og sød. Ron Abuelo 12 år Anejo Gran Reserva har vundet guld-medalje ved International Rum Expert Panel 2010.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo 5 år Anejo Reserva Especial Rom', 'https://rombo.dk/products/ron-abuelo-5-anejo-reserva-especia', 175, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_5_ar_Anejo_Reserva_Especial_Rom.png?v=1774519151', 'Ron Abuelo Anejo Reserva Especial 5 års rom er den yngste rom hos Abuelo, men har alligevel opnået masser af smag og dybde. Den har duft af rørsukker krydret med nougat, mokka, lys chokolade og vanille. Smag: frisk og syrlig med en fyldig sødme. Ron Abuelo Anejo Reserva Especial 5 års rom har en lang og sødmefuld eftersmag, som fylder hele munden. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo 7 år Anejo Reserva Superior Rom', 'https://rombo.dk/products/ron-abuelo-7-superior-rom', 235, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_7_r_Anejo_Reserva_Superior_Rom.png?v=1787054413', 'Smagsnoter for Ron Abuelo Anejo Reserva Superior Rum 7 år: fyldig duft med noter af appelsin og kandis. Smag: kompleks, og sukkeret spiller godt med krydderierne, hvilket gør rommen spændende. Eftersmag: Sød og med karamel.Ron Abuelo Anejo Reserva Superior 7 års rom har vundet guld ved adskillige konkurrencer - blandt andet guld ved San Francisco World Spirits Competition i 2009 og dobbelt guld ved San Francisco World Spirits Competition i 2010. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo Centuria Reserva de la Familia Solera Rum 30 år', 'https://rombo.dk/products/ron-abuelo-centuria-rom-30', 999, true, 70, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_Centuria_Reserva_de_la_Familia_Solera_Rum_30_ar.png?v=1774519307', 'For tilhængerne af den søde rom-stil er der en god grund til at Ron Abuelo Centuria Reserva de Familia er kåret som Bedste Nye rom ved Golden Rum Barrel Awards Oktober 2011 i London. Ron Abuelo Centuria har også opnået 95/100 points på Romhatten.dk - se deres bedømmelse her: http://www.romhatten.dk/Abuelo_Centuria_Reserva_de_la_Familia.php . Smagsnoter for Ron Abuelo Centuria Reserva de la Familia. Næse: tyk, klæbrig, sirupsagtig næse med røgede noter af melasse og sort sirup. Vanille og tønde char, et strejf af fedtet espresso bønne og en smuk notat af cedertræ. Det udvikler sig til antydninger af asfalt på en varm dag i sommer, gamle reb og æble drysset med mørk, brun sukker. Smag: Sød og afrundet, intenst frugtrig som æblestrudel med blød, saftig sultanas, muskatnød og kanel. Smeltede vanille-is, ristet brioche med Demerara sukker, karamel æbler og bare et strejf af røg. Hele pakken er ikke ulig brød og smør budding. Finish: Middellang finish med svesker og valnød. Antydninger af kardemomme på halen. Det føles næsten også som en rigtig Pedro Ximinez sherry eftersmag.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XII Three Angels Rom', 'https://rombo.dk/products/abuelo-xii-anos-three-angels', 549, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b3b58787-6db7-4332-8cdb-a61990bdd4e9.png?v=1769434668', 'Abuelo XII Three Angels er en dejlig blød "single estate" rom fra Varela Hermanos destilleriet i Panama, omend den er en smule mere kraftfuld og intens end den populære Abuelo XII Two Oaks udgave. Både Abuelo XII Three Angels og Abuelo XII Two Oaks er dobbeltlagrede i 12 år. Først i bourbonfade og herefter i ekstra-toastede og nye egetræsfade. Forskellen er, at Three Angels er udgaven udelukkende er taget fra fadene på den øverste række på Ron Abuelos vintage pallet varehuse, hvor temperaturen når helt op på 35°C, hvilket gør, at fordampningen (angel''s share) når helt op på 15% om året, hvilket også er med til at accellerere modningen og kompleksiteten. Næse: ristede hasselnødder, søde krydderier, eksotisk frugt, læder, mørk chokolade og ristede kaffebønner. Smag: brændt egetræ, vanilje, honning og tørret frugt. Eftersmagen er lang, krydret og "brændt" med noter af kakao. Abuelo XII Three Angels er tappet ved 43%, som er en smule højere end de sædvanlige 40% i Abuelo-serien. 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XII Two Oaks Rom', 'https://rombo.dk/products/abuelo-xii-anos-two-oaks', 475, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_XII_Two_Oaks_Rom.png?v=1787050307', 'Abuelo XII Anos Two Oaks er en dejlig blød rom fra Varela Hermanos i Panama. Der er tale om en 12 år gammel rom, som er blevet lagret i to karakteristiske egetræsfade. Først i nøje udvalgte ex-bourbon fade for derefter at komme i helt nye og ekstra forkullede fade af amerikansk egetræ. Fadene udvælges og behandles med omhu i Napa Valley, Californien. De ristes ved 180 ° C i lange 60 minutter for forsigtigt at åbne træet, og derefter skrues varmen op til 220 ° C for at opnå den dybe forkulning på de ønskede 8 mm. Denne totrinsproces gør det muligt for Abuelo XII Anos Two Oaks at trække utrolig meget smag fra træet, og der skabes et naturligt kulfilter, der giver en usædvanlig blød Two Oaks finish. Næse: stor duft af egetræ, let røg og fine noter af vanilje, kaffe og ristede mandler. Smag: fremtrædne egetræsnoter med en speciel røgfyldt sødme. Karamel, krydderier,og ristede kaffebønner med fine noter af cola og nødder. 40% vol. - 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV 15 år Napoleon Cognac Cask Finish Rom', 'https://rombo.dk/products/abuelo-xv-15-napoleon-cognac', 625, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_XV_15_ar_Napoleon_Cognac_Cask_Finish_Rom.png?v=1774518643', 'Ron Abuelo XV 15 år Napoleon Cognac Cask Finish Rum er en del af Abuelo''s 2016 Collection Finish udgivelser, der også indeholder en Oloroso Sherry Finish og en Tawny Port Finish. Der har længe været et stort spring i pris (og kvalitet?) fra Abuelo''s 12-års udgave til deres eksklusive Centuria udgave, og med Ron Abuelo XV 15 år Napoleon Cognac Cask Finish får vi en rom, der ligger imellem disse 2. Rommen skulle være udvalgt iblandt Abuelo''s fineste reserver, og efter en indledende lagring i amerikanske egetræsfade er den afsluttende lagring foregået i Napoleon Cognac fade. 40% - 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV 15 år Oloroso Sherry Cask Finish Rom', 'https://rombo.dk/products/abuelo-xv-15-oloroso-sherry', 625, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_XV_15_ar_Oloroso_Sherry_Cask_Finish_Rom.png?v=1774518557', 'Ron Abuelo XV 15 år Oloroso Sherry Cask Finish Rum er en del af Abuelo''s 2016 Collection Finish udgivelser, der også indeholder en Tawny Port Finish og en Napoleon Cognac Finish. Der har længe været et stort spring i pris (og kvalitet?) fra Abuelo''s 12-års udgave til deres eksklusive Centuria udgave, og med Ron Abuelo XV 15 år Oloroso Sherry Cask Finish skulle vi få en rom, der ligger imellem disse 2. Rommen skulle være udvalgt iblandt Abuelo''s fineste reserver, og efter en indledende lagring i amerikanske egetræsfade er den afsluttende lagring foregået i Oloroso Sherry fade. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV 15 år Tawny Port Cask Finish Rom', 'https://rombo.dk/products/abuelo-xv-15-tawny-port', 625, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_XV_15_ar_Tawny_Port_Cask_Finish_Rom.png?v=1774518455', 'Ron Abuelo XV 15 år Tawny Port Cask Finish er en del af Abuelo''s 2016 Collection Finish udgivelser, der også indeholder en Oloroso Sherry Finish og en Napoleon Cognac Finish. Der har længe været et stort spring i pris (og kvalitet?) fra Abuelo''s 12-års udgave til deres eksklusive Centuria udgave, og med Ron Abuelo XV 15 år Tawny Port Cask Finish får vi en rom, der ligger imellem disse 2. Rommen skulle være udvalgt iblandt Abuelo''s fineste reserver, og efter en indledende lagring i amerikanske egetræsfade er den afsluttende lagring foregået i Tawny Port fade. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV Finish Collection Three Pack 3 x 20cl Rom', 'https://rombo.dk/products/abuelo-xv-finish-collection-3-pack', 699, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Abuelo_XV_Finish_Collection_Three_Pack_3_x_20cl_Rom.png?v=1770217964', 'Abuelo XV Finish Collection Three Pack er en gaveæske med 3 stk 20cl flasker af Abuelo XV Oloroso, Abuelo XV Napoleon og Abuelo XV Tawny. Abuelo XV Oloroso er en 14 år gammel rom, lavet gennem solera-processen på amerikanske hvide egetræsfade og derefter modnet færdig i 1 år på Oloroso Sherry-fade. Næse: Kakao og vanille. Smag: Sød frugt, vanilje og noter af træ. Abuelo XV Napoleon Er ligeledes 14 år gammel rom, lavet gennem solera-processen, nøje udvalgt af Varela Hermanos selv og derefter modnet færdig i 1 år på Napoleon Cognac-fade indtil øjeblikket for aftapning. Noter af vanilje, karamel, træ og en smule peber. Abuelo XV Tawny Også 14 år gammel rom, lavet gennem solera-processen og derefter modnet færdig i 1 år på Tawny Port fade. Kun produceret i lille mængde, hvilket gør denne rom mere eksklusiv. Sød og rund med smag af chokolade og modnet frugt.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura 1787 Super Premium Rom 15 år', 'https://rombo.dk/products/angostura-1787-premium-rum', 625, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Angostura_1787_Super_Premium_Rom_15_r.png?v=1787052434', 'Angostura 1787 er en blending af rom, der er lagret i 15 år på brugte egetræsfade. Næse: banan, tørret frugt, æble og egetræ (samt lidt Caroni?). Smag: tørrede blommer, toffee og egetræ (samt lidt Caroni?). Da vi selv talte med Master Distiller fra Angostura, John Georges, sagde han, at der ikke var Caroni i denne Angostura 1787 rom-blending, men kan det nu også passe? Vi fornemmer ihvertfald en lille del Caroni i både næse og mund, og Angostura har jo også købt en del af de gamle Caroni-fade. En velafbalanceret, fyldig og generøs rom. 40% vol. – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura 1824 Premium Rom', 'https://rombo.dk/products/angostura-1824-premium-rum', 449, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_faeef285-4d0b-42c0-a7f3-5974035a8785.png?v=1769421043', 'Angostura 1824 Premium Rum Master er samtidigt en hyldest til kirurgen Johann Gottlieb Benjamin Siegert, der gjorde tjeneste i Simon Bolivars hær under revolutionen i Venezuela i 1824. I medicinens tjeneste var han med til at skabe de aromatiske Angostura bittere, der siden skulle bliver berømte verden over. Skibet på flaskens gaverør symboliserer bitternes rejse over verdenshavene, såvel som den unge læges personlige rejse. Angostura 1824 Premium Rum Master bliver skabt i hånden af Angosturas Master Blender. Den er et exceptionelt blend af de fineste, modnede rom, der fyldes med største omhu på brændte, amerikanske ex-bourbon egefade og lagres i mindst 12 år. Farven er flot mørk med tekstur så blød som silke og en fyldig krop. Angostura 1824 Premium Rum smager fantatsisk med fuldtonede noter af tørret frugt, sød melasse, ristet vanille, honning, krydderier og cognac. Lækker rom til en meget rimelig pris. 40% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura 1919 Premium Rom 13 år', 'https://rombo.dk/products/angostura-1919-premium-rom', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6a61f684-fc46-4742-a745-f2ff2b534dfe.png?v=1769420584', 'Angostura 1919 rom er en blend af lette og kraftige årgangs-rom, der er lagret i mindst 13 år på egetræsfade, der før har været brugt til Bourbon, som man også kender det fra produktionen af maltwhisky. God fadlageret rom har efterhånden vundet mange danskeres hjerte, da det ofte er mere sødt og let at drikke end for eksempel whisky og cognac. Næse: Vanilje-drøm i næsen. Umådelig massiv, og det er svært at finde andet end et spor af sødme og karakteristisk ''rom gummi'' i næsen. Smag: Vanilje, men den udvikler sig tør og kompleks, da den første sødme hurtigt forvandler sig til noget krydret. Fra sød karamel til salt, peber og lakrids på få sekunder. Eftersmag: Krydret finish, let sødme, trækker lange spor af ''rom gummi''. En behagelig finish. Angostura 1919 er en lidt overraskende rom, da næsen er vanilje, men smagen er krydret og fremstår ukompliceret. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura 3 år Superior White Rum', 'https://rombo.dk/products/angostura-reserva-white-rum', 159, true, 70, 37.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Angostura3arSuperiorWhiteRum_3e5c2b94-b930-4a06-ba56-2f686cc75591.png?v=1784104400', 'Angostura Superior White Rum er en blød, let og lys rom. Faktisk er rommen lagret i 3 år, men man har fjernet farven fra lagringen i fadene ved hjælp af filtrering. Angostura 3 års Superior White Rum har brændte mandler, citrusblomster og cremede noter i næsen, og smagen byder på tropiske frugter, bananer og kokosnød samt strejf af mint, hvid peber og mango. Mellemlang eftersmag med citrus og lime. Angostura Superior White Rum er specielt velegnet til long drinks og cocktails, men denne lyse rom kan også sagtens nydes alene eller med is. 37,5% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura 5 år Gold Rum', 'https://rombo.dk/products/angostura-5-gold-rum', 175, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Angostura5arsrom.png?v=1771851629', 'Angostura 5 år Gold Rum er et blend af lette og kraftige romdestillater fra Angosturas destilleringsapparat med 5 kolonner, hvorefter den er modnet på amerikanske egedafe og til sidst let filtreret gennem trækul. Smagen er en smule sødere end andre tilsvarende rom og har noter af brændt karamel, vanille og æble. Angostura 5 år Gold Rum er velegnet til at nyde ren, men den er også perfekt i en Manhattan eller en Old Fashioned. 40% vol. – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura 7 år Dark Rum', 'https://rombo.dk/products/angostura-7-ar-dark-rum', 225, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7292964f-189b-4925-87fa-9fb3eb3a928b.png?v=1769421218', 'Angustura 7 år Dark Rum er et blødt blend af lette, middel og kraftige romdestillater fra Angosturas kolonneapparat og herefter modnet i 7 år på nye egetræsfade. Smagen er intens og velafbalanceret med noter af læder og tobak, eksotiske frugter, muskatnød, karamel og krydderi. Angustura 7 år Dark Rum bør nydes ublandet: Giv denne rom 1 minuts stilhed i glasset, så smag og aroma kommer til sin fulde ret. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura Cask Collection No.1 Oloroso Sherry Cask Rum - Edition 3', 'https://rombo.dk/products/angostura-cask-collection-no-1-oloroso-sherry-cask-rum-edition-3', 799, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_85037004-8ce2-4636-801f-2b9778b3997b.png?v=1769436448', 'Angostura Cask Collection No.1 Oloroso Sherry Cask Rum Edition 3 er en såkaldt dobbeltlagret rom, der indledningsvis er lagret på amerikanske bourbonfade for derefter at blive lagret på brugte Oloroso sherryfade i yderligere 9 måneder. Denne særlige aftapning af tredje udgave af Angostura No. 1 Cask Collection blev produceret ved hjælp af en unik blanding af modne, lagrede rom af høj kvalitet alle udvalgt med omhu og præcision og valgt på baggrund af deres unikke smag og karaktertræk. Tappet ved 40% og er den første rom, som Angostura har modnet i sherry-fade. Angostura® Cask Collection No. 1 Oloroso Sherry er en udsøgt, silkeblød kompleks blanding – skabt med en fusion af teknikker, der er lært fra den gamle verden og forfinet i den nye verden. Den har en rig ravfarve med en enestående klarhed. Du vil opleve varme, afrundede aromaer med en delikat duft af kakao, melasse, egetræ og søde svesker. Smagen er en dejlig, velafbalanceret blanding med noter af træagtighed, ristede nødder og antydninger af sherry. Rommen har en medium krop og en medium, rund og egeagtig eftersmag, der fuldender den samlede smagsoplevelse. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura Tamboo Spiced', 'https://rombo.dk/products/angostura-tamboo-spiced', 199, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Angostura_Tamboo_Spiced.png?v=1774517161', 'Angostura Tamboo Spiced "spirit drink" er baseret på den legendariske Angostura rom – tilsmagt med caribiske krydderier som kanel, kardemomme og nelliker – naturligt sødet med sukkerrørsmelasse. En gylden, varm og krydret sukkerrørsspiritus skabt til livets festlige stunder med dans, musik og sjov i gaden. Navnet stammer fra den såkaldte Tamboo Bamboo, en bambustromme, som har sørget for karnevalsrytmer i gaderne på Trinidad &amp; Tobago siden 1884. I øvrigt længe før ”steel drums” blev opfundet på øerne. Angostura Tamboo Spiced har en fortryllende ravfarve. I duften indfanges man hurtigt af en krydret og rig aroma, hvor noter af vanilje og toffeeæbler træder tydeligt frem. Dette suppleres af subtile hints af kardemomme og kanel, der tilsammen skaber en dyb og indbydende oplevelse. Når den først berører tungen, mærkes en varm kanel, der smukt komplementerer den fremtrædende vanilje og noter af kage. Drikken fortsætter med at fortrylle med sine indbydende nuancer af muskatnød og røget kardemomme, før den kulminerer i en blød afslutning med smag af marcipan. Den har en medium lang eftersmag, der efterlader en lyst til at tage endnu en tår. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura Tribute Distiller''s Cut Private Cask Collection Rum', 'https://rombo.dk/products/angostura-tribute-distillers-cut-rum', 799, true, 70, 44.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/AngosturaTributeDistiller_sCutPrivateCaskCollectionRum.png?v=1774518328', 'Angostura Tribute Distillers Cut Private Cask Collection Rum er en limited edition rom og den seneste version fra Angostura Tribute-serien. Den første Chairman’s Choice nåede slet ikke fra Trinidad &amp; Tobago til Danmark, før den var udsolgt. Med denne særlige rom fejrer House of Angostura deres Master Distiller John Georges, som har bidraget med sin enestående viden og sine høje standarder i over 40 år, inden han for nyligt pensionerede sig selv. Angostura Tribute Distillers Cut fadene er blevet særligt udvalgt af Angostura''s blendere for dens søde og røgfyldte dybde med aromaer af søde æbler og vanilje samt brændte trænoter. Blandingen indeholder ultra-premium rom fra Angostura''s fineste fade, der er lagret op til 25 år. En fornem hyldest til Master Distiller John Georges. Efter selv at have smagt denne glimrende rom, er vi i øvrigt ganske overbeviste om, at der også er nogle gamle Caroni-fade i det færdige blend. 44,7% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Appleton Estate 12 år Rare Blend Rom', 'https://rombo.dk/products/appleton-estate-12-extra-rum', 365, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Appleton_Estate_12_r_Rare_Blend_Rom.png?v=1787047257', 'Appleton Estate Rare Blend 12 års Jamaica-rom har lagret alle årene i Jamaicas tropiske klima, og derfor føles den faktisk som ”gammel”! Rommen har en blændende, lys bronz farve og næse af modne dufte af valnødder, muskatnød, appelsin og vanille, samt noter af kaffe, kakao, ristet eg og mandel. Smag: smøragtig og cremet brun sukker, med frugtige noter af mango, banan, kaffe og eg. Eftersmag: bittersød og saftig. Appleton Estate Rare Blend 12 år er en dristig og selvsikker rom, der bør nydes rent eller on the rocks. 43% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Appleton Estate 21 år Nassau Valley Casks Rom', 'https://rombo.dk/products/appleton-estate-21-ar-nassau-valley-casks', 995, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6aa8367d-184d-40ff-a64c-3d44a0785d09.png?v=1769421179', 'Appleton Estate 21 års Nassau Valley Casks rom er en hyldest til Nassau Valley, hvor rommen produceres. Rommen er blandet af nøje udvalgte fade og har fyldige duftnoter af appelsinskal, muskatnød, vanille, mandler, kaffe og kakao, mens smagen tilfører noter af nødder, melasse og eg. Appleton Estate 21 års Nassau Valley Casks rom har en lang, tør eftersmag, hvor fornemmelsen af brunt sukker dukker frem. Rommen har vundet flere priser. 43% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Appleton Estate Black River Casks 15 års Rom', 'https://rombo.dk/products/appleton-estate-black-river-casks-15-ars-rom', 499, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c2946778-2250-4c53-83c9-48e829351d2a.png?v=1769425876', 'Appleton Estate Black River Casks 15 år er et blend af udvalgte rom, der er produceret med det kalkstensfiltrede vand fra Black River. Rommen er nøje udvalgt og sammensat af Appletons højtestimerede Master Blender Joy Spence, der i øvrigt er den første kvindelige Master Blender i spiritusindustrien. Alle rom i Appleton Estate Black River Casks 15 år er lavet på melasse fra Appletons egne sukkerrør og har lagret i 15 år på Number One Select American Oak-tønder, der afgiver ekstra vaniljenoter og gør rommen mere blød og mindre træagtig i smagen. Appleton Estate Black River Casks 15 år har aroma af ristede mandler, hasselnødder og appelsinskal og noter af vanilje, ristet kaffe og melasse. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Appleton Estate Reserve Rum 8 år', 'https://rombo.dk/products/appleton-estate-reserve-rum-8-ar', 299, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/AppletonEstateReserveRum8ar.png?v=1774517303', 'Appleton Estate Reserve Rum 8 år er sammensat af Appletons Master Blender Joy Spence og er en blanding af kolonnedestilleret og kedeldestilleret rom, som har lagret i minimum 8 år i tropisk klima. Appleton Estate Reserve Rum 8 år har en krydret og frugtig aroma med hints af honning, vanilje og appelsinskal. Rommen vandt guldmedalje ved San Francisco Spirits Competition i 2020 og fik 97 ud af 100 points ved Ultimate Spirits Challenge i 2020. 43% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Appleton Kingston 62 White Jamaica Rum', 'https://rombo.dk/products/appleton-kingston-62-white-jamaica-rum', 189, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ae5a1006-4973-4bea-9274-25f520d8f861.png?v=1769425982', 'Appleton Kingston 62 White Jamaica Rum er en lidt usædvanlig lys rom, da den har lagret på fad, og siden fået en filtrering gennem kulfilter for at fjerne farven igen. Appleton Kingston 62 White Jamaica Rum er en smagfuld, smooth cocktailkomponent, der bidrager med smagsnoter af ristet kokosnød og æblekage, ananas, banan og søde druer i din drink. 40%-70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Appleton Signature Blend Rom', 'https://rombo.dk/products/appleton-signature-blend-rum', 225, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_092ccc8c-acec-4270-a01c-9f1aafa5c742.png?v=1769422468', 'Appleton Estate Signature Blend er et rom-blend af 15 forskellige Appleton-rom med forskellig stil og alder. Hvert trin i Appletons romproduktion er nøje koordineret - fra udvælgelsen af sukkerrør til valg af gær og lagringen på fad, hvilket viser sig i rommens kvalitet. De 15 rom, der indgår i Appleton Estate Signature Blend, har en gennemsnitsalder på 4 år og skaber tilsammen en veloplagt blanding, der kan nydes ren eller i drinks. Appleton Estate Signature Blend har frugtagtige og søde noter af citrus, appelsinskal, tørret abrikos, frisk fersken, melasse og egetræ. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Arcane Rum Extraroma - Rom fra Mauritius', 'https://rombo.dk/products/arcane-rum-extraroma', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_89482832-16ac-4fc9-9910-fa0b03c14bfc.png?v=1769420654', 'Arcane Extraroma rom fra øen Mauritius i det Indiske Ocean er en ultra frisk rom, der også er en en lidt usædvanlig flaske. Næse: Tørret banan, abrikos, vanille, kandiserede æbler, overmodne bananer - simpelthen en frugtkurv. Smag: Mandariner, rosiner, sødme og kokos. Kompleks i den søde, frugtagtige afdeling. Eftersmag: Lang, sød og krydret banan tilsidst. Arcane Extraroma rom er sød, ja - men nærmest overmoden, tung sødme. Frugt trifli. 40% 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Autentico Nativo Overproof Rum', 'https://rombo.dk/products/autentico-nativo-overproof-rum', 375, true, 70, 54, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c0927bf6-a281-4f59-b2e7-c43838a7b20e.png?v=1769425109', 'Autentico Nativo Overproof Rum er udviklet i et samarbejde mellem Autentico Nativo Rum og den store rom-legende fra Cuba, Don Pancho Fernandez, der har mere end 50 års erfaring med romproduktion. Denne Autentico Nativo Overproof Rum er destilleret hos Destilería Las Cabras i Panama, hvor Don Pancho nu er bosiddende. Rommen er også modnet i Panama i 8-10 år på brugte amerikanske whiskey-fade. Efterfølgende er den så blevet overflyttet til nye fade, der tidligere har indeholdt naturligt kakao-ekstrakt, og dette giver noget helt særligt til den kraftige rom. Autentico Nativo Overproof Rum har en markant note af chokolade/kakao samt noter af bl.a. karamel, brændt sukker og moden frugt. Den minder på mange måder om den gamle "Panama Red" udgave, eller den nuværende Companero Panama Extra . Alkoholstyrken er i den høje ende, men der også en del sødme, så rommen kan samlet set betegnes som mellemsød. Denne rom vandt guld i 2019 ved World Spirits Competition i San Francisco. 54% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Autentico Nativo Rum 15 års', 'https://rombo.dk/products/autentico-nativo-15-rum', 425, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_10c8db20-ab3c-4ecf-90c8-4dbfb32e6781.png?v=1769425113', 'Autentico Nativo Rum 15 års rom er udviklet i et samarbejde mellem Autentico Nativo Rum og den store rom-legende fra Cuba, Don Pancho Fernandez, der har mere end 50 års erfaring med romproduktion. Denne Autentico Nativo Rum 15 års rom er destilleret hos Destilería Las Cabras i Panama, hvor Don Pancho nu er bosiddende. Rommen er også tropisk lagret i Panama i minimum 15 år (det skulle således ikke være efter Solera princippet?) på brugte amerikanske whiskey-fade. Autentico Nativo Rum 15 års rom har noter af bl.a. tørret frugt, flødekaramel, vanilje, blomme og rosin. Denne rom kan betegnes som mellemsød, og den har bl.a. vundet guld ved German Rum Fest i 2018 samt dobbelt-guld ved Madrid Rum Fest i 2018. 40% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Autentico Nativo XO Rum Finished in Cognac Barrels', 'https://rombo.dk/products/autentico-nativo-xo-rum', 849, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Autentico_Nativo_XO_Rum_Finished_in_Cognac_Barrels.png?v=1774520152', 'Auténtico Nativo XO Rum er en mellemsød rom fra Destilería Las Cabras i Panama, og det er ingen andre end legenden Don Pancho Fernandez, som har udviklet rom-serien. Rommen er ekstraordinær gammel, og den har ifølge Autentico Nativo lagret i 20-25 år på brugte bourbonfade inden den afsluttende lagring på cognacfade. Der er tale om den klassiske, spanske rom-stil. Rommen er baseret på sukkerrørsmelasse, og den er kolonnedestilleret og færdiglagret i Panama. Den dobbelte lagring er med til at give denne særlige Autentico Nativo rom-udgave både ekstra finesse og kompleksitet samtidig med, at den er behagelig blød og sødmefuld. Når man dufter til Autentico Nativo XO Rum Finished in Cognac Barrels, fornemmes især krydderier og vanilje. I smagen finder man noter af bl.a. egetræ, vanilje, frugtig cognac, nødder, karamel og kirsebær. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bapt & Clem''s Belize 4 års Rom', 'https://rombo.dk/products/bapt-clems-belize-4-ans', 499, true, 70, 47, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a106e84c-b180-4f0f-b88f-7318500743e5.png?v=1769423716', 'Bapt &amp; Clem''s Belize 4 ans d''age er udgivet af den franske armagnac-producent Darroze, og rommen kommer fra Travellers Distillers på øen Belize. Travellers bruger lokal melasse, der er gæret og destilleret i en tredobbelt kolonne. Marc Darroze har udvalgt denne rom efter flere års fadlagring på Belize, hvorefter den er fragtet til Gascogne og lagret i ekstra 9 måneder i små egetræsfade, der tidligere indeholdt søde vine fra Jurançon. Bapt &amp; Clem''s Belize 4 ans d''age rommen har en smag af bl.a. blomster, honning, fine krydderier og tørret frugt. Bapt &amp; Clem’s navnet kommer iøvrigt fra Marc Darroze''s 2 sønner, som hedder Baptiste og Clément. Begrænset aftapning - kun 1.010 flasker. 47% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barbancourt Rhum 5 Star 8 års Rom', 'https://rombo.dk/products/barbancourt-rhum-5-stars-8', 399, false, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_3864d3bd-c2d5-4c5a-bae7-7fa07d46fae7.png?v=1769420657', 'Rhum Barbancourt 5 Stars 8 års Haiti rom fremstilles af Barbancourt-destilleriet, der blev grundlagt i 1862 af en fransk cognac-bonde fra Charente - Dupré Barbancourt. Det er stadig efterkommere af Dupré, som driver destilleriet. Den nuværende direktør Thierry mener, at destilleriet er ansvarlig for at 20.000 fattige Haiti-borgere har en indtægt. Så selvom Haiti-rommen både er af høj kvalitet og har en meget fair pris er det lige før, at man blot kan nyde rommen for den ekstra gode samvittighed! Barbancourt-rommen er kun lagret på fade af fransk Limousin-eg, som har en lidt mere åben struktur og derfor tillader bedre iltning af rommen. Barbancourt 5 Stars 8 års rom kendetegnes ved en sød aroma med noter af gummi, sød appelsin, citrus og abrikos. Smag: blød og sød, fyldig, let abrikos smag, olieret, let bourbon/rye karakter. Eftersmag: krydret eftersmag, vokser i eftersmagen, tørt egefad til allersidst. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barbancourt Rhum Réserve du Domaine Rum 15 år', 'https://rombo.dk/products/barbancourt-rhum-reserve-du-domaine-15', 649, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_0d39176d-cf49-4f78-ae75-e8cda97fff23.png?v=1769420660', 'Barbancourt Rhum Réserve du Domaine var oprindeligt forbeholdt Barbancourt-familien og dens venner, men blev udbudt til offentligt salg for første gang i midten af 1960-erne. I dag er Réserve du Domaine blevet en veritabel institution blandt verdens romkendere. Den kom først til Europa i 2009. Næse: Næsen er parfumeret og kompleks med kandiserede citrusfrugter og en ristet, tanninrig smag. Smag: Er kraftfuld med en stor aromatisk rigdom. Næsten eksplosiv med kogt pære, citrus frugter, kanel og peber. Eftersmag: Er lang med et hint af citrusfrugter og krydderier. Barbancourt Rhum Réserve du Domaine 15 års rom vandt bronze-medalje ved International Rum Expert Panel 2010. En rom som Haiti kan være stolt af. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barceló Gran Añejo Rom', 'https://rombo.dk/products/ron-barcelo-gran-anejo', 175, true, 70, 37.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_84707d8e-8f50-415a-8dfa-a91b15dba4c7.png?v=1769421480', 'Ron Barceló er en blød, fyldig rom, der er mørkt ravfarvet med smagsnoter af ristet kokosnød, tør karamel, kalk og et strejf af peber. I næsen er der sød, smøragtig karamel, nødder og delikate krydderier og smagen har desuden noter af citron, fersken og egetræ. En populær rom i Den Dominikanske Republik, hvor man ser de lokales go to-mærker Brugal og Ron Barceló overalt. 37,5% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barcelo Imperial 40 Aniversario Rom', 'https://rombo.dk/products/barcelo-imperial-40-aniversario-rom', 1295, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Barcelo_Imperial_40_Aniversario_Rom.png?v=1774520569', 'Barcelo Imperial 40 Aniversario jubilæumsrom er et blend af vellagret rom, der har modnet i op til 10 år i særligt udvalgte amerikanske egefade og herefter har fået en 2 års finish på franske egefade med forskellig grad af ristning. Herefter har master blenderen udvalgt de bedste partier af denne rom og lagt den til yderligere 10 års lagring på franske egefade med et fremragende resultat. Barcelo Imperial 40 Aniversario rom har duftnoter af rosiner, karamel, creme brulee og tørre krydderier og kirsebær. Smagen er halvtør og afrundet med frugt, nødder og krydret eg, der munder ud i en lang finish af peber og tobak. Barcelo Imperial 40 Aniversario rom kan drikkes alene eller i selskab med en god cigar, moden ost, mørk chokolade og rødt kød. 43% -70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barceló Imperial Rum', 'https://rombo.dk/products/ron-barcelo-imperial-rum', 275, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_74f1ccaf-1556-4250-b84a-854a3e30e170.png?v=1769421036', 'Ron Barceló Imperial rom er lagret på amerikanske egetræsfade i 8 år. Rommen er ravfarvet med et kobberrødt skær. I næsen modne tropiske frugter med minder om rosiner og figner. Svage vanilje nuancer. Lang og blød eftersmag. Denne Ron Barcelo Imperial rom er i 2000 præmieret af Beverage Tasting Institute of Chicago som Verdens Bedste Rom med 97 point med betegnelsen "a superlative world-class spirit" og har vundet guldmedalje i kategorien “Old Aged” ved Miami Rum Festival 2013. Leveres i en flot flaske og lækker karton, som gør rommen ideel som gave. 38% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barceló Onyx Imperial Rum', 'https://rombo.dk/products/barcelo-onyx-imperial-rum', 365, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/BarceloOnyxImperialRum.png?v=1774520694', 'Barceló Onyx Imperial Rum er ift. de øvrige Barceló-varianter lagret på hårdt brændte egetræsfade i 8-10 år, og derudover er rommen filtreret over sorte Onyx sten, før den blev tappet på flaske. Duft: egetræsfad, espresso kaffe, nødder og mørk chokolade. Smag/eftersmag: vanilje, brændte egetræskrydderier, flødekarameller, kirsebær, kaffe, nødder og mørk chokolade. Vi har selv haft fornøjelsen af at smage Barceló Onyx Imperial, der fremstår meget let at nyde "på trods af" den manglende sukkertilsætning. Som Ingvar "Rom-Thomsen" skrev om Onyx i sin artikel om Ron Barceló i Whisky &amp; Rom Magasinet i april 2017: "Vil helt sikkert blive et hit hos romdrikkere, der er til autentisk ikke-sødet rom". 38% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barceló Organic Rum', 'https://rombo.dk/products/barcelo-organic-rum', 225, true, 70, 37.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_39bb3327-4b49-47e9-ad35-1d1b0089c7fd.png?v=1769424788', 'Ron Barceló fra Den Dominikanske Republik er verdens måske mest "grønne" destilleri. Destilleriet er miljøgodkendt efter den internationale ISO 14.001 standard og fremstiller naturlig rom uden tilsætning af sukker, og rommen er lavet af den friskpressede sukkerrørssaft (som Rhum Agricole). Denne Barceló Organic rom er ift. de øvrige Barceló-varianter desuden lavet som en økologisk rom. Barceló begyndte allerede i 2015 at forberede sukkerrørsmarkerne for at sikre, at der ikke var nogen gødningsrester tilbage i plantagen, der strækker sig over et areal på hele 1.500 km2. De økologiske sukkerrørsplantager ligger 3 km fra destilleriet, og på denne måde er der intet overskudsvand, som ødelægger de økologiske marker. Desuden har man anvendt økologisk gær, og som et lille kuriosum er etiketten på Barceló Organic lavet af vegetabilske fibre fra sukkerrør og printet med økologisk blæk. Barcelo Organic rom har en duft af bl.a. karamelliseret kirsebær, kakao og tobak. I smagen finder vi bl.a. modne frugter, ristede tørrede frugter og et strejf af rød peber. 37,5% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Belize Shared Single Cask Rum', 'https://rombo.dk/products/belize-shared-single-cask-rum', 799, true, NULL, 69.6, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RomboSharedSingleCaskBelize2022.png?v=1773239285', 'Belize Shared Single Cask Rum er en "enkeltfadsrom", der blev udvalgt sammen med en række skønne kunder, som deltog på Rombo''s tur til 1423 ApS i efteråret 2025 for at smage på rom og for at se det imponerende lager med de mere end 2.000 fade. Denne helt unikke Belize rom blev destilleret hos Traveller''s Distillery i 2017 og har først lagret på bourbonfade, hvorefter den blev lagt på et lille 40 liters Virgin Oak fad i 2022 indtil den endelige aftapning i december 2025. Rommen er kolonnedestilleret og lavet af sukkerrørsmelasse. Der blev tappet i alt 42 flasker Belize Shared Single Cask Rum ved 69,6% fadstyrke, og Rombo købte de resterende 24 flasker efter kundernes andele. Disse sælges nu til andre.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Belizean Blue Signature Blend Rum', 'https://rombo.dk/products/belizian-blue-signature-blend-rum', 375, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8809c800-c7b1-41f1-864e-628880c2ff8a.png?v=1769439525', 'Belizean Blue Signature Blend Rum er en mellemsød rom, der er fremstillet hos Travellers Liquors Ltd. og lagret i Belize i op til 7 år på ex-bourbonfade. Destilleriet blev grundlagt i 1953 af Jaime Omario Perdomo, og den anvendte melasse er fra to lokale sukkerfabrikker på Belize-øen. Når man dufter og smager Belizean Blue Signature Blend rommen, fornemmes et skønt strejf af kokos og vanilje samt en smule sødme. En afbalanceret rom, der hverken er for sød eller for sprittet. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Black Tot Rum Finest Caribbean', 'https://rombo.dk/products/black-tot-rum', 399, true, 70, 46.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Black_Tot_Rum_Finest_Caribbean.png?v=1787050504', 'Black Tot Rum Finest Caribbean rom har fået sit navn efter Black Tot - den endegyldigt sidste, daglige romration, der blev udskænket i den britiske flåde 31. juli 1970. Black Tot Rum er et forsøg på at genskabe flådens unikke rom-blend og er baseret på rom-destillater fra henholdvis Jamaica, Barbados og Guyana. Der er ikke tilsat sukker, så her får du en "naturlig sømandsrom". Black Tot Rum har noter af bl.a. ananas, melon, kokos, creme brulee og espresso. Barbados giver de frugtige noter, Guyana giver fyldigheden og Jamaica giver de "funky" noter. 46,2% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran 15 år Solera Reserva Rom', 'https://rombo.dk/products/botran-15-solera-reserva-rom', 259, true, 70, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_723e6bd9-c13b-44ab-9865-3b5a1e7a6967.png?v=1769422029', 'Botran 15 Solera Reserva Ron Anejo modnes i op til 15 år på amerikanske egetræsfade, der førhen har været brugt til modning af whisky, sherry og portvin. Botran 15 Solera Reserva har farve som poleret mahogni med glimt af reflekterende lys. Smagen er kompleks med en tydelig smag af ristet eg og en snert af vanille. Grønne æbler, tørrede tranebær, citronskal og appelsin følges af en duft af nellike, kanel og muskatnød mikset med karamel. En vedblivende robust og moden smag. Botran 15 år Solera Reserva fik en flot 2. plads i kategorien "Solera rom" ved German Rum Festival i oktober 2014.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran 18 år Solera Gran Reserva Rom', 'https://rombo.dk/products/botran-18-solera-gran-reserva-rom', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_0e393584-293a-40b8-a1a7-7ca747b42b38.png?v=1769422032', 'Botran 18 år Solera Gran Reserva laves på sukkerrørsjuiceekstrakt kaldet ’virgin honey’. Ekstrakten fermenteres og destilleres i en langsom proces. Botran 18 Solera Gran Reserva er en sofistikeret blanding af rom modnet i op til 18 år. Botran 18 Solera har en dyb mahogni farve med gyldne toner. De første noter er rige på træ, ristet kakao, vanille og karamel. Når rommen udvikler sig i glasset, træder aromaer af tørrede frugter, tørrede tranebær, appelsinskal og citrus frem. Den er robust og saftig i smagen, men samtidigt tør og eksplosiv med elegante noter af kandiseret frugt, nelliker, muskatnød, peber, ristet kakao og delikate citrusfrugter. 40% 70cl');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran Cobre Spiced Rum', 'https://rombo.dk/products/botran-cobre-spiced-rum', 599, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7959cb10-b54d-48b0-9666-70517ecbcb7a.png?v=1769423300', 'Botran Cobre Spiced Rum er inspireret af en traditionel drink fra Guatemala; nemlig "Ponche", hvori der indgår en blanding af tropisk frugt, kardemomme, kanel, ingefær og nelliker. Botran Cobre Spiced Rum er gæret på "virgin sugar cane honey" og destilleret på kobber-kolonner 2300 meter over havoverfladen i Guatemalas bjerge, hvor den bliver blendet efter den gamle solera-metode fra Spanien. Denne aftapning er produceret i 10.000 flasker til hele verden. Når Botran Cobre Spiced Rum hældes i glasset mødes man af duftindtryk fra kardemomme, kanel, ingefær, nelliker og egetræ fra fadlageringen. Smagsindtrykket er langt og komplekst med masser af fylde fra de forskellige botanicals, der er tilsat undervejs i dens lagring. Kommer i flot gaverør. 45% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran Ki Rom', 'https://rombo.dk/products/botran-ki-rom', 299, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_72501121-8bc4-449e-a8ac-d66d1374bfbb.png?v=1769438337', 'Botran KI'' rom fra Guatemala er lavet på sukkerrørshonning af den højeste kvalitet. KI'' betyder "sol" på mayasproget, og flasken afspejler varmen og sjælen i Guatemala. Rommen er modnet på særligt udvalgte fade, der bl.a. har indeholdt Moscatel-vin, hvilket giver Botran KI'' en smule sødme og rundhed. Fremstillingen gøres helt uden tilsætning af sukker, hvorved man bevarer rommens autentiske smag og naturlige karakter, og det betyder også, at denne rom er mere tør end sød. Botran KI’ skiller sig ud ved sin dynamiske lagringsproces i et tilpasset solera-system, som skaber en unik harmoni mellem både unge og gamle fade. Botran Ki'' rom har en blød, fyldig smag med raffinerede noter og en kompleks eftersmag. Den alsidige rom er perfekt til at nyde ved stuetemperatur, og den fungerer også godt i cocktails til intense smagsoplevelser. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran Miracielo Artesenal Spirit Drink', 'https://rombo.dk/products/botran-miracielo-artesenal-spiced', 299, false, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/BotranMiracieloArtesenalSpiritDrink_79c37160-e569-4368-9069-610a4c863fb0.png?v=1789471363', 'Miracielo Artesenal Spiced "spirit drink" fra Ron Botran i Guatemala er blandet af rom, der er mellem 5 og 15 år. Den har en gylden farve fra fadlagringen og en inciterende næse af rosiner, tørret frugt, kaffe og læder. Smagen er sød og blød med noter af tørret frugt. Botran Miracielo Artesenal Spiced bør drikkes ren og egner sig godt som digestive efter et godt måltid, eventuelt i selskab med mørk chokolade eller en god cigar. 38% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran Rare Blend Vintage French Wine Cask Rom', 'https://rombo.dk/products/botran-rare-blend-french-wine-cask-rom', 799, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_faea9adc-895b-4db3-a095-6f7af5675505.png?v=1769434242', 'Botran Rare Blend Vintage French Wine Cask rom laves på sukkerrørsjuiceekstrakt kaldet ’virgin honey’, og ekstrakten fermenteres og destilleres i en langsom proces på mellem 100 og 120 timer. Der er tale om et 100% Guatemala-produkt, da sukkerrørshøsten, destilleringen, lagringen og aftapningen alt sammen er foregået i Guatemala. Botran Rare Blend rom modnes i Guatemala''s bjerge ved brug af Solera systemet, og de 8-25 år gamle fade til denne flaske er håndplukket iblandt Botran''s eksklusive reserver. Der anvendes 5 forskellige typer fade i det endelige blend: brugte whiskeyfade fra USA, toastede whiskeyfade fra USA, ex-sherry fade fra Spanien og ex-portvinsfade fra Portugal samt en finish på franske hvidvinsfade. I næsen finder man træ, vanilje, nødder, tørret frugt og krydderi Smagen byder på noter af bl.a. brændt egetræ, vanilje, karamel og krydderi, der munder ud i en frugtig eftersmag af abrikos, honning og et strejf af citrus. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran Roajú Rom', 'https://rombo.dk/products/botran-roaju', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RonBotranRoajurom.png?v=1779447843', 'Botran Roajú hylder historien om de fem Botran Merino-brødre, der forlod den spanske region Duero for at slå sig ned i Guatemala. Rommen er et blend af rom, der er lagret på sherry- (Oloroso) og portvins- (Tawny) og to forskellige American Whiskey-fade. De forskellige rom har en alder mellem 8 og 20 år. Lagringen er baseret på den en dynamisk Solera-metode, der er specifik for Botran-destilleriet. Inden aftapning har rommen fået afsluttende lagring på fade, der tidligere har indeholdt en spansk vin fra Burgos, Botran-brødrenes hjemregion. Casa Botran ligger i Quetzaltenango højlandet 2.300 meter over havets overflade. Her lagrer de deres rom ved en kølig gennemsnitstemperatur på 14˚C. Dette betyder, at 5% af rommen går tabt som den såkaldte "Angel’s share" hvert år, hvilket betyder, at det er det perfekte sted for langsom, højdealdring. Botran Merino brødrene foretog i starten af 1900-tallet en øjenåbnende rejse, fra solrige Spanien til pragtfulde Guatemala. Og i 1940 grundlagde de Botran. En rom med en karakteristisk attitude. Siden blev de et af verdens første bæredygtige rommærker. Botran Roajú har en farve af mørkt kobber og byder på en duft af ristet træ, karamelliserede noter samt sorte frugter og svesker med en krydret tone af kanel og peber. Ved smagen opdages noter af toffee, sorte frugter som svesker og sort kirsebær, sammen med ristet træ og ristet kaffe. Afslutningsvis fremhæves toffee-noterne. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bristol Classic Reserve Rum of Haiti 2004', 'https://rombo.dk/products/bristol-classic-haiti', 675, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Bristol_Classic_Reserve_Rum_of_Haiti_2004_53bb6a4c-692c-4d06-98db-79799aa8c2d7.png?v=1774521845', 'Bristol Classic Reserve Rum of Haiti 2004 kommer fra Rhum Barbancourt på Haiti. Gæringen af den friske sukkerrørsjuice foregår i 72 timer, derefter bliver mæsken kedel-destilleret for siden at lagre på amerikanske egetræsfade. Bristol Classic Reserve Rum of Haiti 2004 er destilleret i juni 2004 og aftapningen er foregået i 2015 uden brug af nogen form for tilsætning. Bristol Classic Reserve Rum of Haiti 2004 byder på den "ægte" vare. En flot, gylden farve, og duften er blød og frugtagtig. Smagen er mindre sød end den gennemsnitlige rom, men velafbalanceret med noter af frugt og egetræ.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bristol Classic Rum 2009 Jamaica Trelawney County 12 år', 'https://rombo.dk/products/bristol-classic-rum-jamaica-trelawney-county-2009', 1295, true, 70, 47.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_17b5d338-4df3-472f-861c-7e953717f6e8.png?v=1769426080', 'Bristol Classic Rum Jamaica Trelawney County 2009 er en rom i Bristol Classic Rum-serien, hvor John Barrett udvælger specielle fade i Caribien og færdiglagrer dem i Liverpool (tidligere var det i Bristol og deraf navnet). Barrett er tilhænger af så naturlig rom som muligt, og for at beholde den enkelte roms individuelle karakter benytter Bristol Spirits sig af forsigtig tapning, ingen tilsætning og minimum filtrering af produkterne. Bristol Classic Rum Jamaica Trelawney County 2009 blev destilleret på pot still i 2009 og tappet i 2021. Den har kraftige duftnoter af frugt og høje estere, der er karakteristisk for pot still rom fra Trelawney County. Smagen har masser af frugt og en mellemlang eftersmag, der ofte kendetegner denne type rom. Tappet uden koldfiltrering. 47,5% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bristol Classic Rum Finest Mauritius Cane Juice Rhum', 'https://rombo.dk/products/bristol-classic-rum-finest-mauritius-rom', 349, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_0f8b649c-59b9-4c4c-9272-c056887f412c.png?v=1769421561', 'Bristol Classic Rum Finest Mauritius Cane Juice Rhum er destilleret på det smukke "La Bourdonnais" i den nordlige del af Mauritius. Denne agricole-lignende rom er baseret på den rene sukkerrørsjuice og kolonnedesteilleret. Den er tappet direkte fra fad ved sin bedste styrke, uden brug af nedkøling og med en kun ganske let filtrering. Bristol Classic Rum Finest Mauritius Cane Juice Rhum har en duft af frugt (frisk æble). Frugten går igen i smagen, der er frisk og rund med noter af enebær. Anbefales til brug i cocktails og long drinks. 43% – 700 ml. Disse rom er fyldt på flaske direkte fra tønden når de har ramt den optimale styrke, uden nedkøling og kun med let filtrering. Det gøres for at bevare finesserne af smag. Di Disse rom er fyldt på flaske direkte fra tønden når de har ramt den optimale styrke, uden nedkøling og kun med let filtrering. Det gøres for at bevare finesserne af smag. DiDenne agricole-lignende rom er baseret på den rene sukkerrørsjuice og kolonne destilleret. Bristol Classic Rum Finest Mauritius Cane Juice Rhum har en duft af frugt (frisk æble). Frugten går igen i smagen, der er rund og kort med noter af enebær. Anbefales til brug i cocktails og long drinks. 43% – 700 ml. Disse rom er fyldt på flaske direkte fra tønden når de har ramt den optimale styrke, uden nedkøling og kun med let filtrering. Det gøres for at bevare finesserne af smag. DiDenne agricole-lignende rom er baseret på den rene sukkerrørsjuice og kolonne destilleret. Bristol Classic Rum Finest Mauritius Cane Juice Rhum har en duft af frugt (frisk æble). Frugten går igen i smagen, der er rund og kort med noter af enebær. 