INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bristol Classic Rum Old Demerara Rum Port Mourant 1990 32 år', 'https://rombo.dk/products/bristol-classic-rum-port-mourant-1990', 3695, true, 70, 46.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_bbb84165-b9e7-4844-bc83-e5e9e5085e46.png?v=1769426063', 'Bristol Classic Rum Port Mourant 1990 er en rom i Bristol Classic Rum-serien, hvor John Barrett udvælger specielle fade i Caribien og færdiglagrer dem i Liverpool (tidligere var det i Bristol og deraf navnet). Barrett er tilhænger af så naturlig rom som muligt, og for at beholde den enkelte roms individuelle karakter benytter Bristol Spirits sig af forsigtig tapning, ingen tilsætning og minimum filtrering af produkterne. Bristol Classic Rum Port Mourant 1990 fra Gyuana blev destilleret tilbage i 1990 og har modnet på et amerikansk egetræsfad. Siden 2002 har rommen lagret i Storbritannien, frem til aftapningen i 2022. Rommen har en gylden, let rødlig farve og de, komplekse duftnoter, der er typisk for Port Mourant-rom med frugt og et hint af anis. Bristol Classic Rum Port Mourant har smagsnoter af læder, anis og tørrede frugter og byder på en lang, vedvarende eftersmag. Tappet ved 46,7% ABV uden brug af koldfiltrering. Bemærk: stærkt begrænset antal, derfor sælges max 1. flaske pr. kunde. 46,7% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('British Royal Navy Rum One Imperial Gallon 57,15 % 4,54 liter - Rom fra Caribien', 'https://rombo.dk/products/british-royal-navy-rum-one-imperial-gallon', 39999, false, NULL, 57.15, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_13575bee-c553-4a90-a139-18acf648cdfe.png?v=1769422829', 'British Royal Navy Rum indeholder One Imperial Gallon = 4,54 liter, og den sjældne flaske er fra ca. 1970, hvor den britiske flåde den 31. juli afsluttede den daglige udskænkning af rom til søfolket (denne dag kaldes også for Black Tot Day). Der findes stadig nogle af disse oprindelige British Royal Navy Rums fra dengang, og indpakningen er ekstraordinær. "Demijohn" flasken er godt beskyttet i en flettet kurv med håndtag, og der medfølger en flot trækasse med lækkert tilbehør (kan ses i vores butiksvindue på Falkoner Alle 46). Vi har selv haft fornøjelsen af at smage British Royal Navy Rum, og det er en fantastisk oplevelse, hvis man er til fyldig rom og kraftfuld smag. PLEASE NOTICE: the bottle price is a "click and collect" price, so please choose "own pick-up" if ordering online. If transportation is needed, this would be something to organise by yourself.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Brugal 1888 Rom', 'https://rombo.dk/products/brugal-1888-rum', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Brugal_1888_Rom.png?v=1787059429', 'Lagringen af Brugal 1888 rom foregår på amerikanske hvide egetræsfade og spanske egetræsfade, der tidligere har været brugt til sherry. Rommen er kendt for sin karakteristisk tørre smagsprofil kombineret med en balanceret palette af smagsnuancer. Den er god at nyde ren, med is eller som ingrediens i forskellige cocktails. Farve: mørk rav. Duften er kompleks med krydrede toner, hints fra chokolade, ristede kaffebønner samt en anelse kanel og tørret frugt. Rommen har en behagelig og blød smag, der er levende med “full body” og en bemærkelsesværdig afrunding af karamel, træ og lakrids. Brugal 1888 Rum vandt guld i kategorien "Premium Aged Rum" ved Miami Rum Festival 2015. 40% vol. – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Brugal 1888 rom gaveæske m/glas og barske', 'https://rombo.dk/products/brugal-1888-gaveaeske', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d2955fc2-1a10-4606-8868-61d7dfd2cec9.png?v=1769439792', 'Lagringen af Brugal 1888 rom foregår på amerikanske hvide egetræsfade og spanske egetræsfade, der tidligere har været brugt til sherry. Rommen er kendt for sin karakteristisk tørre smagsprofil kombineret med en balanceret palette af smagsnuancer. Den er god at nyde ren, med is eller som ingrediens i forskellige cocktails. Her får du ovenikøbet den klassiske Brugal 1888 rom i en flot gaveæske med 2 originale glas og en barske. Farve: mørk rav. Duften er kompleks med krydrede toner, hints fra chokolade, ristede kaffebønner samt en anelse kanel og tørret frugt. Rommen har en behagelig og blød smag, der er levende med “full body” og en bemærkelsesværdig afrunding af karamel, træ og lakrids. Brugal 1888 Rum vandt guld i kategorien "Premium Aged Rum" ved Miami Rum Festival 2015. Gaveæske med 2 glas og en barske. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Brugal Colección Visionaria Edicion 03 rom', 'https://rombo.dk/products/brugal-coleccion-visionaria-edicion-03-rom', 699, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/BrugalColeccionVisionariaEdicion03rom.png?v=1790592786', 'Brugal Colección Visionaria Edicion 03 er den tredje rom i Colección Visionaria serien fra Brugal i Den Dominikanske Republik. Det meste af den dominikanske rom er i den søde ende, men faktisk laver Brugal primært en mere tør rom, og det gælder også denne udgave. Brugal Colección Visionaria Edicion 03 er lagret på nye franske egetræsfade, der efter placering af kokos-stykker er blevet toastet indvendigt. Herpå er fadet blevet tømt for disse kokos-stykker, inden det er blevet påfyldt med rom fra Brugal rom. Den færdiglagrede rom har bløde noter af vaniljestang, ristet egetræ og subtile hints af karameliseret kokos. Desuden fornemmes en afbalanceret fylde, som afsluttes med friske lag af sød citrus og dens let bitre skal. Limited edition. 45% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Brugal Maestro Reserva rom', 'https://rombo.dk/products/brugal-maestro-reserva-rom', 995, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/BrugalMaestroReserva.png?v=1790598644', 'Brugal Maestro Reserva er en eksklusiv rom fra Den Dominikanske Republik. Det meste af den dominikanske rom er i den søde ende, men faktisk laver Brugal primært en mere tør rom, og det gælder også denne særlige udgave. Brugal Maestro Reserva er lagret på amerikanske sherryfade, der er blevet tømt og toastet iht. Brugal''s "Dark Aromatic Toasting" teknik. Den færdiglagrede rom har noter af vanilje, karamel og nødder. Limited edition. 45% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cane Island Single Estate Rum Nicaragua 12 års rom', 'https://rombo.dk/products/cane-island-single-estate-nicaragua', 499, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_63a6b5d4-1600-4139-a440-399225d55f1e.png?v=1769439537', 'Cane Island Single Estate Rum Nicaragua 12 års rom kommer fra ét - og kun ét - hemmeligt destilleri i Nicaragua i Mellemamerika, hvor den er bleve kolonnedestilleret. Rommen er minimum 12 år gammel, hvilket er lang tid, når der er tale om tropisk lagring. Hele lagringen er foregået på fade af amerikansk hvid-eg. Når man dufter og smager denne Cane Island Single Estate Rum Nicaragua 12 års rommen, fornemmes noter af vanilje, mørk karamel, læder og cigar. Eftersmagen er lang og kompleks. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cane Island Single Estate Trinidad Sherry Cask Finish 8 års Rom', 'https://rombo.dk/products/cane-island-single-estate-trinidad-sherry-cask-finish-8-years-old-rom', 449, false, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7989f3e6-8fa5-4915-aec1-fc2199f99d9d.png?v=1769435714', 'Cane Island Single Estate Trinidad Sherry Cask Finish 8 Years Old Rom er en limited edition rom, som er destilleret af Trinidad Distillers i Caribien. Herefter er rommen lagret i 8 hele år på på hvide egetræsfade i det tropiske klima på destilleriet i Trinidad. Efter lagringen er rommen færdiggjordt på tidligere Oloroso-fade i 9 måneder, hvilket har tilføjet et fantastisk strejf af sødme og sherry-noter til denne frugtige og karakterfulde rom. Cane Island Single Estate Trinidad Sherry Cask Finish 8 Years Old Rom har en mørk ravfarve og en varm smag med behagelige noter af moden banan og eg. En behagelig balance mellem krydret træsmag og delikat sødme, som bliver efterfulgt af en meget blid finish. 43%­ – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cane Island Single Island Blend Panama Rom', 'https://rombo.dk/products/cane-island-single-blend-panama-rom', 349, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_18cb87f3-3aa1-4681-80f6-2314765a5c1e.png?v=1769435707', 'Cane Island Single Island Blend Panama er en del af Cane Island-serien, der har samlet rom fra Centralamerika og Caribien, der i særlig grad besidder de træk, der kendetegner rom derfra. Denne rom er en blanding af rom fra forskellige destillerier i Panama, der har lagret mellem 3 og 8 år på gamle bourbonfade i det tropiske klima i Panama, hvilket resulterer i en rom med en fløjlsagtig og cremet tekstur, med noter af toffee, slik, appelsiner, kokos, vanilje og et hint af egetræ på finishen. 40%­ – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cane Island Thailand 5 år Single Estate Rum', 'https://rombo.dk/products/cane-island-thailand-5-ar-single-estate-rum', 399, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rombo_Cane_Island_Thailand_Single_Estate_Rum_5_ars_rom.png?v=1770724401', 'Denne særlige Cane Island 5 års rom er en såkaldt Single Estate Rum fra Thailand, hvor man faktisk laver en del rom, men der er desværre ikke mange af dem, som finder vej til Danmark. Faktisk er rommen skøn, frisk og frugtig med noter af bl.a. vanilje og tobak. "Single Estate" udtrykket betyder, at denne rom kun kommer fra et enkelt destilleri og derfor ikke er sammenstykket af forskellige destillerier. De 5 års tropiske lagring gør, at rommen pga den hurtige modning i varmen er ganske kompleks og velbalanceret. Cane Island Thailand 5 år Single Estate Rum er mellemsød. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cargo Cult Banana Spiced Spirit Drink', 'https://rombo.dk/products/cargo-cult-banana-spiced-spirit-drink', 275, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5e4564da-1d03-4f43-b7e8-71e1244518c9.png?v=1769438063', 'Cargo Cult Banana Spiced Spirit Drink er en sukkerrørsspiritus fra det sydlige Stillehav. Den gærede og destillerede rom fra Fiji og Papua New Guinea er blevet lagret i ex-bourbon fade i Australien, hvor den også er blevet infuseret med australske bananer fra North Queensland. Resultatet er en mellemsød sukkerrørsspiritus med noter af modne bananer, kanel, ingefær og vanilje. Der er ikke anvendt sukkertilsætning ved fremstillingen af Cargo Cult Banana Spiced Spirit Drink. Small Batch. 38% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cargo Cult Navy Strength Rum', 'https://rombo.dk/products/cargo-cult-navy-strength-rum', 299, true, 70, 54.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_0533dfe1-7537-4e5b-a569-a4f2cc2219b2.png?v=1769438059', 'Cargo Cult Navy Strength Rum er en smagfuld og kraftfuld rom fra det sydlige Stillehav. Rommen er nærmere betegnet gæret og destilleret på Stillehavs-øen Fiji, hvorefter den er blevet færdiglagret i ex-bourbon fade i Australien. Cargo Cult Navy Strength Rum er en Pure Pot Still rom lavet som "Small Batch". Rommen kan nydes rent, og den kunne også være et fint alternativ til den legendariske Smith &amp; Cross, som mange ynder at anvende til cocktails, der skal peppes op med en mere intensiv romsmag. 54,5% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Carupano Reserva 12 Exclusiva Rom', 'https://rombo.dk/products/carupano-12-exclusiva', 299, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b5900f34-5420-451a-a220-0f4312157fba.png?v=1769424926', 'Carupano rom-serien er fra Venezuela, hvorfra vi også kender bl.a. Diplomatico og Santa Teresa . Ron Carupano er et familieejet destilleri, der laver sødmefuld rom iht. den "spanske stil". Historien går helt tilbage til år 1762, hvor den spanske kaptajn, Felix del Fierro, grundlagde haciendaen i Carupano-dalen i Macarapana. Ron Carupano er i dag blandt de førende producenter i Venezuela, og man har også landets første og eneste kvindelige Master Blender, Carmen López de Bastidas. Fadene er forseglede og bliver ikke genopfyldt efterhånden, som rommen fordamper. Carupano Reserva 12 Exclusiva rom ligger i den mellemsøde ende og indeholder op til 12 år gamle destillater fra ex-bourbonfade. Carupano Reserva 12 Exclusiva rom har noter af bl.a. karamel, havsalt, kokos og ristede nødder. Rommen kan nydes rent og giver også et flot udtryk i cocktails. 40% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Carupano Reserva 18 Limitada Rom', 'https://rombo.dk/products/carupano-18-limitada', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_43323d95-1d26-4d34-8242-56e6bb76abf4.png?v=1769424930', 'Carupano rom-serien er fra Venezuela, hvorfra vi også kender bl.a. Diplomatico og Santa Teresa . Ron Carupano er et familieejet destilleri, der laver sødmefuld rom iht. den "spanske stil". Historien går helt tilbage til år 1762, hvor den spanske kaptajn, Felix del Fierro, grundlagde haciendaen i Carupano-dalen i Macarapana. Ron Carupano er i dag blandt de førende producenter i Venezuela, og man har også landets første og eneste kvindelige Master Blender, Carmen López de Bastidas. Fadene er forseglede og bliver ikke genopfyldt efterhånden, som rommen fordamper. Carupano Reserva 18 Limitada rom ligger i den mellemsøde ende og indeholder op til 18 år gamle destillater fra amerikanske egetræsfade. Carupano Reserva 18 Limitada rom har noter af bl.a. figen, honning, kandiseret frugt, vanilje og chokolade. Rommen blev lanceret i 2020 og kommer i et flot gaverør. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Carupano Reserva 21 Privada Rom', 'https://rombo.dk/products/carupano-21-privada', 499, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d6c086c4-d2ed-4339-bd56-ed6ddc87ee54.png?v=1769424932', 'Carupano rom-serien er fra Venezuela, hvorfra vi også kender bl.a. Diplomatico og Santa Teresa . Ron Carupano er et familieejet destilleri, der laver sødmefuld rom iht. den "spanske stil". Historien går helt tilbage til år 1762, hvor den spanske kaptajn, Felix del Fierro, grundlagde haciendaen i Carupano-dalen i Macarapana. Ron Carupano er i dag blandt de førende producenter i Venezuela, og man har også landets første og eneste kvindelige Master Blender, Carmen López de Bastidas. Fadene er forseglede og bliver ikke genopfyldt efterhånden, som rommen fordamper. Carupano Reserva 21 Privada rom ligger i den mellemsøde ende og indeholder op til 21 år gamle destillater fra ex-bourbonfade. Rommen kommer i et flot gaverør. Carupano Reserva 21 Privada rom har noter af bl.a. appelsin, mørk karamel, tobak, smørcreme, saltkaramel og vanilje. 40% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman''s Reserve 1931 Rom', 'https://rombo.dk/products/chairmans-reserve-1931', 699, false, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d61e3e94-c44b-46f3-ac9e-18daaac6c1b8.png?v=1769423373', 'Chairman''s Reserve 1931 rom fra St. Lucia Distillers er en hyldest til romfilosofien og håndværket etableret af Denis Barnard. Dette flagskibsprodukt er et blend af kolonnedestilleret rom (Coffey still) og tre kobber-destillationsapparater, som derefter er lagret i bourbonfade fra 7 til 12 år. 90% af blendet er af traditionel melasse rom, mens 10% er af sukkerrørsjuice (agricole rom) fra sukkerrør dyrket ved St. Lucia Distillers selv. Næse: rosiner, ristet egetræ, læder, krydderier og tobak. Smag: rosiner med en lille note af karamel og blød egetræ i ganen. En fin kompleks afslutning, først de søde rosiner, så tør og tannisk fra egetræet samt en fin aromatisk sødme, som balancerer den totale smagsoplevelse. 46% 70cl');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman''s Reserve Original Rom', 'https://rombo.dk/products/chairmans-reserve-original-rum', 249, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ea2a3f37-6762-41a6-a558-89f0d04c197f.png?v=1769422181', 'Chairman''s Reserve Original Rum fra St. Lucia Distillers er et blend af kolonnedestilleret rom og pot still destilleret rom med en gennemsnitlig alder på 5 år. Rommen er modnet i brugte, amerikanske egetræsfade fra Jim Beam, Jack Daniels og Buffalo Trace. Indledningsvis foregår modningen separat i de forskellige fade, men efter blendingen får rommen yderligere 6 måneder i samme fad. Chairman''s Reserve Original Rum har noter af honning, eg, banan, vanille, rosiner, tobak og krydderier. Den kan nydes rent, men gør sig nok endnu bedre i cocktails som Mai Tai og Old Fashioned. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman''s Reserve Rum Vintage 2011', 'https://rombo.dk/products/chairmans-reserve-rum-vintage-2011', 599, true, 70, 46.8, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Chairman_sReserveRumVintage2011rom.png?v=1777385251', 'Chairman''s Reserve Rum Vintage 2011 er fra St. Lucia Distillers, der her kommer med en helt særlig "limited release" og den 3. Vintage-udgave, hvor der er blevet leget med fadene. Vintage 2011 er en kombination af pot still og kolonnedestilleret rom, der først er lagret i 11 år på henholdsvis brandyfade og vinfade, inden de blev blandet sammen af Master Blender, Deny Duplessis. Herefter har den sammenstukne rom fået en afsluttende lagring i 10 måneder i bourbonfade. Når man dufter til Chairman''s Reserve Rum Vintage 2011 rommen, fornemmes rosiner, toffee, pære og lemon. Smagen og eftersmagen byder på noter af jordbær, egetræskrydderier, æbler og kokos. 46,8% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman''s Reserve Spiced Original Rom', 'https://rombo.dk/products/chairmans-reserve-spiced-original-rum', 249, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e7c20b00-27f4-4251-86ea-67579a46d000.png?v=1769424886', 'Chairman''s Reserve Spiced Original Rum fra St. Lucia Distillers er et blend af kolonnedestilleret rom og pot still destilleret rom med en gennemsnitlig alder på 5 år. Rommen er modnet i brugte, amerikanske egetræsfade fra Jim Beam, Jack Daniels og Buffalo Trace. Indledningsvis foregår modningen separat i de forskellige fade, men efter blendingen får rommen yderligere 6 måneder i samme fad. Chairman''s Reserve Spiced Original Rum udgaven har fået tilsat "Bois Bandé bark" samt lokale krydderier og frugter så som kanel, kryddernellike, muskat, vanilje, lemon og appelsinskal. Chairman''s Reserve Spiced Original Rum kan nydes rent eller anvendes til long drinks / cocktails. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman''s Reserve The Forgotten Casks Rom', 'https://rombo.dk/products/chairman-s-reserve-the-forgotten-casks', 425, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ca33f7c6-842e-406e-b57e-a0a511e37c67.png?v=1769422187', 'Chairman''s Reserve The Forgotten Casks Rum er først separat modnet i brugte fade fra Jim Beam, Jack Daniels og Buffalo Trace. Herefter blandes rommen, og det endelige blend bliver i den samme fadtype de sidste 5 år af lagringstiden. Navnet "The Forgotten Casks" refererer til, at en række fade blev glemt efter en større brand hos St. Lucia Distillers i 2007. Da de blev fundet igen, viste det sig, rommen indeni havde fået en forrygende. kompleks smag. Chairman''s Reserve The Forgotten Casks Rum har noter af rosiner, tobak, vanille, honning og krydderier. Begrænset oplag. 40% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cihuatán Cinabrio 12 års Rom', 'https://rombo.dk/products/cihuatan-cinabrio-12-rum', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_fb115b13-4e43-4848-a672-99b3366bb158.png?v=1769424956', 'Cihuatán Cinabrio 12 år er en rom, der er fremstillet af Licorera Cihuatan S.A. de C.V i El Salvador, som er den umiddelbart eneste kendte romproducent fra El Salvador. Navnet Cinabrio refererer til Cinabrio mineralen, som det lokale Maya-folk anvendte til at fremstille den røde farve, vi på dansk kender som cinnoberrød. Cihuatán Cinabrio 12 år er kolonnedestilleret og et blend af rom, der er lagret i ex-bourbonfade i 12 år (Solera?). Smagen byder på noter af bl.a. karamelliseret appelsinskal, guarapo, blommer, pistacienødder og toastet egetræ. Kommer i flot og dekorativ gaveæske. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cihuatán Folklore Selección Nordica Rom', 'https://rombo.dk/products/cihuatan-folklore-seleccion-nordica-rom', 899, true, 70, 53.6, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d4c8f120-f8cf-45b7-8d0b-b2b9f302ae79.png?v=1769427438', 'Cihuatán Folklore Selección Nordica rom er første udgivelse i Cihuatáns Creación-serie, der er sammensat af master blender Gabriela Ayala for at fremhæve samspillet mellem egetræsfad og rom. Til serien har hun håndplukket 13 forskellige fade blandt Cihuatáns private reserver og udvalgt denne 17 år gamle rom fra et tidligere cognacfad til sin Selección Nordica, der er tappet kun til det nordiske marked. Cihuatán Folklore Selección Nordica rom har aroma af vanilje, karamel og kogte frugter, og tilsat et par dråber vand får den tilmed et strejf af brændte mandler. Smagen er stærk og krydret med noter af egetræ, myntechokolade og mandler samt et hint af syltede kirsebær og tobak, der kommer frem med et par dråber vand. 53,6% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Clairin Ansyen Single Cask #CA21MG-104 Coalition Denmark 2026', 'https://rombo.dk/products/clairin-ansyen-single-cask-ca21mg-104-coalition-denmark-2026', 699, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/ClairinAnsyenSingleCask_CA21MG-104CoalitionDK2026rom.png?v=1788262960', 'Clairin fra Haiti er en naturligt gæret rom, der er lavet på den friske sukkerrørssaft. De lokale Haiti indbyggere er så glade for denne rom-type, at de selv tager til destilleriet for at få fyldt de medbragte plastikdunke. Det var Luca Gargano fra Velier, der "opdagede Clairin", og det er sidenhen lykkedes ham at få tappet nogle af de særlige udgaver på flaske, så resten af verden også kan nyde det. Når man smager en Clairin - inklusive denne Ansyen single cask fra Casimir - så skal man være klar til en intens og anderledes oplevelse, da der ikke er tilsat sukker eller farve, og da både gæringen og de små pot still skaber grobund for den unikke karakter. Denne unikke Clairin Ansyen Single Cask fra producenten Casimir på Haiti er en enkeltfadsaftapning, der har lagret i 26 måneder. Fadet er blevet udvalgt af Coalition Denmark, der består af en række top-cocktailbarer: Gedulgt (Aarhus), Hella (Aarhus), Visit (Odense), Skodsborg Hotel, Esmee (København), Gensyn (Frederiksberg og Amager), LuLu (København) og Ambra (København).');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Clairin Communal', 'https://rombo.dk/products/clairin-communal', 339, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/ClairinCommunalHaitirom.png?v=1788261025', 'Clairin fra Haiti er en naturligt gæret rom, der er lavet på den friske sukkerrørssaft. De lokale Haiti indbyggere er så glade for denne rom-type, at de selv tager til destilleriet for at få fyldt de medbragte plastikdunke. Det var Luca Gargano fra Velier, der "opdagede Clairin", og det er sidenhen lykkedes ham at få tappet nogle af de særlige udgaver på flaske, så resten af verden også kan nyde det. Når man smager en Clairin - inklusive denne ulagrede Communal - så skal man være klar til en intens og anderledes oplevelse, da der ikke er tilsat sukker eller farve, og da både gæringen og de små pot still skaber grobund for den unikke karakter. Clairin Communal er en "lys rom", der for de øvede kan sippes rent, og den også kan anvendes til cocktails.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Clément VSOP Rhum Agricole Rom', 'https://rombo.dk/products/clement-vsop-rhum-agricole-rom', 375, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Clement_VSOP_Rhum_Agricole_Rom.png?v=1786016640', 'Clément VSOP Rhum Agricole er "landbrugsrom" fra Martinique, som er en tidligere fransk koloni. Clément, der blev grundlagt i 1887, rangerer højt blandt Martinique''s udbydere af Rhum Agricole. Rommen fremstilles af frisk sukkerrørsjuice og lagres i minimum 4 år på 200-liters egetræsfade. Clément VSOP har noter af egetræ, krydderier, kanel, vanille, mandler og ristede kakaobønner.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Clément XO Rhum Agricole Rom', 'https://rombo.dk/products/clement-xo-rhum-agricole-rom-7719', 499, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ee2e6704-6fe1-4971-8910-e74338b6950a.png?v=1769423497', 'Clément XO Rhum Agricole er (minimum) 6 år gammel "landbrugsrom" fra Martinique, som er en tidligere fransk koloni. Clément, der blev grundlagt i 1887, rangerer højt blandt Martinique''s udbydere af Rhum Agricole. Rommen fremstilles af frisk sukkerrørsjuice og lagres i minimum 6 år i delvis friske egetræsfade og delvis i brugte, toastede egetræsfade. Clément XO har en lidt røget aroma og byder især på florale smagsnoter samt lang eftersmag. 42% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Come Hell or High Water Spiced Vanilla & Cola', 'https://rombo.dk/products/hell-or-high-water-spiced', 215, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/ComeHellorHighWaterSpicedVanillaCola.png?v=1776956101', 'Come Hell or High Water Spiced Vanilla &amp; Cola er en sukkerrørsspiritus fra One Eyed Spirits, der bl.a. også står bag bl.a. Volbeat og Origines rom (sidstnævnte i samarbejde med den legendariske Master Blender, Don Pancho Fernandez). Come Hell or High Water er i øvrigt et udtryk for, at man aldrig giver op uanset modgang og besværlige tider, og det må man sige, at de finske personer bag One Eyed Spirits i hvert fald selv lever op til. I mange år stod de bag Ron de Jeremy rom-mærket, men pga. den i skrivende stund verserende retssag imod frontfiguren Ronald Jeremy Hyatt er man blevet tvunget til at ændre produktnavnet. Come Hell or High Water Spiced er en kombination af sukkerrørsspiritus fra Barbados, Guyana og Den Dominikanske Republik. Denne spiritus er blended med krydderier såsom vanilje, kanel, kardemomme, anis og koriander. I duften finder man især vanilje, kanel og muskatnød, mens smagen byder på noter af bl.a. vanilje og karamel. Come Hell or High Water Spiced er velegnet til long drink med cola eller klassiske cocktails. 38% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Come Hell or High Water XO Rom', 'https://rombo.dk/products/hell-or-high-water-xo-rum', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c76eacb0-1b0d-4598-b9b7-87e7b7ac2d83.png?v=1769425312', 'Hell or High Water XO Rum er en rom fra One Eyed Spirits, der bl.a. også står bag bl.a. Volbeat og Origines rom (sidstnævnte i samarbejde med den legendariske Master Blender, Don Pancho Fernandez). Come Hell or High Water er i øvrigt et udtryk for, at man aldrig giver op uanset modgang og besværlige tider, og det må man sige, at de finske personer bag One Eyed Spirits i hvert fald selv lever op til. I mange år stod de bag Ron de Jeremy rom-mærket, men pga. den i skrivende stund verserende retssag imod frontfiguren Ronald Jeremy Hyatt er man blevet tvunget til at ændre produktnavnet. Hell or High Water XO Rum er en blanding af op til 15 år gammel rom fra Barbados, Trinidad, Jamaica og Guyana, der har lagret på ex-bourbonfade. I duften finder man bl.a. sukkerrør og egetræ, mens smagen byder på noter af bl.a. tropisk frugt, bagekrydderier, brunt sukker, karamelliserede nødder og honning. Hell or High Water XO Rum er en mellemsød rom med tilsætning af mindre en 20 gram sukker/liter. Flasken kommer i flot gaverør. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie des Indes Australia Beenleigh 2022 Rom', 'https://rombo.dk/products/cdi-australia-beenleigh-ad116-dk-edt-2022-rom', 799, true, 70, 59.1, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a1ad16a1-0d00-4b0e-b6f3-75b9760a384b.png?v=1769434158', 'Compagnie Des Indes Australia Beenleigh AD116 DK edt. 2022 rom er en 8-års single cask aftapning fra den sympatiske franskmand Florent Beuchet, der står bag den uafhængige romaftapper Compagnie des Indes (CDI). Rommen blev destilleret på Beenleigh-destilleriet i South Queenland, Austrailen, i december 2013 og tappet i september 2022. Rommen er lavet på lokal australsk sukkerrørsmelasse, og til fermenteringen er der brugt flere forskellige gærtyper. Det giver rommen en frisk karakter og en sødmefuld, frugtig smag, der forstærkes af destilleringen på kobber pot still. Compagnie Des Indes Australia Beenleigh AD116 DK edt. 2022 rom har en lys farve og dejligt friske duftnoter af frugt og friskslået græs. Smagen har noter af honning, stenfrugt og vanilje, der munder ud i frisk græs i eftersmagen. Rommen er tappet ved fadstyrke og er helt uden tilsat sukker eller farvestof. Begrænset udgave på 225 nummererede flasker. Bør nydes ren. 59,1%- 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie des Indes Great Whites Ghana Overproof Rom', 'https://rombo.dk/products/cdi-great-whites-ghana-overproof-rom', 435, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_40a28969-71d7-4303-96e6-ba376397a962.png?v=1769434167', 'Compagnie Des Indes Great Whites Ghana Overproof er en af de første rom i Compagnie Des Indes nye serie af ekstraordinær, hvid rom fra hele verden. Alle rom i serien er udvalgt for deres særligt kraftfulde karakter og tappes som ’overproof’ med en ABV på 50%. Compagnie Des Indes Great Whites Ghana Overproof rom er lavet på frisk sukkerrørssaft og blev destilleret på pot still i december 2020 på Mid West Ghana Distillery. Rommen blev tappet i september 2022 og har frugtig og let parfumeret aroma af mango og blomme. Smagen er olieret med noter af hvid peber, lys frugt, mandler og en snert af eukalyptus. Den kan drikkes rent – og også meget gerne i en daiquiri eller mai tai. Begrænset udgivelse på 1000 flasker. 50% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie des Indes Great Whites Vietnam Overproof Rom', 'https://rombo.dk/products/cdi-great-whites-vietnam-overproof-rom', 435, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f55d10e3-cb01-4392-bcfe-a86970f57828.png?v=1769434165', 'Compagnie Des Indes Great Whites Vietnam Overproof rom er en af de første rom i Compagnie Des Indes nye serie af ekstraordinær, hvid rom fra hele verden. Alle rom i serien er udvalgt for deres særligt kraftfulde karakter og tappes som ’overproof’ med en ABV på 50%. Compagnie Des Indes Great Whites Vietnam Overproof rom er lavet på frisk sukkerrørssaft og destilleret på et kolonnedestilleringsapparat af kobber i på Quang Nam Distillery i marts 2021. Rommen har krydrede aromaer af hummus, sandeltræ, trøffel, friske sukkerrør og røgelse. Den har smagsnoter af pære, træ, karamel og hvid te. Bør nydes ren og siden i en mai tai eller en daiquiri. Begrænset udgivelse på 1000 flasker. 50% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie Des Indes Guyana 14 ans Armagnac Finish rom', 'https://rombo.dk/products/compagnie-des-indes-guyana-14-armagnac', 899, true, 70, 61.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7f8888a0-6c73-4206-98b9-afdb2f5789e5.png?v=1769425263', 'Compagnie Des Indes Guyana 14 ans Small Batch rom er fra den sympatiske franskmand Florent Beuchet, der står bag den uafhængige aftapper af rom, Compagnie des Indes (CDI). Denne særlige Guyana udgave er en 14 års rom, der er destilleret hos DDL (Demerara Distillers Ltd.), og rommen har fået en afsluttende lagring på brugte armagnac-fade hos CDI i Frankrig. Compagnie Des Indes Guyana 14 ans er en "high proof" single cask udgivelse ved fadstyrke og i kun 479 eksemplarer. 61,2% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie des Indes Jamaica 9 års Rom', 'https://rombo.dk/products/compagnie-des-indes-jamaica-9-ar-83', 899, true, 70, 64.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5975f872-2b6e-4399-bce0-141953a1e1e5.png?v=1769425580', 'Compagnie des Indes er kendt for at tappe nogle af de allerbedste Jamaica-rom og deres CDI Jamaica 9 år #83 er absolut ingen undtagelse. Fad nummer JKD83, som destillaterne har ligget på, blev tappet i juli 2021 efter 9 års lagring og resultatet er en lys, ravgylden rom med duft af brændt melasse, citrus og tropisk frugt. Smagen er stor, frugtig og typisk jamaicansk, mens alkoholen er tydelig uden at vælte læsset. Dette ''multi distillery blend'' er en Jamaica-rom fra øverste hylde, der kan nydes rent, men også sende en rombaseret drink på himmelflugt. Sælges kun i Danmark. 64,2% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie des Indes Jamaica Clarendon 2022 Rom', 'https://rombo.dk/products/cdi-clarendon-jamaica-djc1-dk-edt-2022-rom', 1395, true, 70, 63.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2ac59722-d034-415e-a058-6eb2ca364c21.png?v=1769434152', 'Compagnie Des Indes Clarendon Jamaica DJC1 DK edt. 2022 rom er en 11-års single cask aftapning fra den sympatiske franskmand Florent Beuchet, der står bag den uafhængige romaftapper Compagnie des Indes (CDI). Rommen kommer fra Clarendon Distillery på Jamaica, og med denne aftapning får man fuld Jamaica-valuta og høj alkoholprocent for pengene.Compagnie Des Indes Clarendon Jamaica DJC1 DK edt. 2022 er en funky sag med noter af let overmodne bananer og ananas. Dens let overmodne duftnoter suppleres af masser af power i smagen - moden tropefrugt, vanilje og masser af cremede noter fra det friske bourbonfad. Samtidigt er alkoholen kraftig, men meget velintegreret i rommen, så den ikke fremstår sprittet. Compagnie Des Indes Clarendon Jamaica DJC1 DK edt. 2022 er tappet ved fadstyrke og helt uden tilsat sukker eller farvestof. Begrænset udgave på 276 nummererede flasker. Bør nydes ren. 63,2%- 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie des Indes Jamaica Navy Strength 4 års rom', 'https://rombo.dk/products/compagnie-des-indes-jamaica-navy-strength-4-ars-rom', 399, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/CompagniedesIndesJamaicaNavyStrength4arsrom.png?v=1773758100', 'Denne 2026-udgivelse af Compagnie des Indes Jamaica Navy Strength 4 års rom i nyt design er en opfølger til den gamle Compagnie des Indes Jamaica Navy Strength 5 års rom. Jamaica rommen er udgivet af den uafhængige franske aftapper, Compagnie des Indes, og den har lagret i tidligere bourbonfade i minimum 4 år. Smagen byder på noter af bl.a. tropiske frugter, marcipan og chokolade. Compagnie des Indes Jamaica Navy Strength er en mellemsød rom. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie des Indes Jamaica New Yarmouth 2022 Rom', 'https://rombo.dk/products/cdi-new-yarmouth-jne16-jamaica-rom-dk-edt-2022', 1395, true, 70, 59.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b8bc4e05-957c-42fa-b8f0-90c2f34d3d68.png?v=1769434148', 'Compagnie Des Indes New Yarmouth JNE16 Jamaica DK edt. 2022 rom er en 12-års single cask aftapning fra den sympatiske franskmand Florent Beuchet, der står bag den uafhængige romaftapper Compagnie des Indes (CDI). Rommen er destilleret hos New Yarmouth på Jamaica, der leverer Jamaica-rom med smæk på. Det får man også i denne særlige aftapning, hvor noter af neglelakfjerner, tropisk frugt og brændt egetræ forenes på vild vis. Compagnie Des Indes New Yarmouth JNE16 Jamaica DK edt. 2022 rom har en syrlig bolsjeduft med noter af stikkelsbær, grøn te, ananas og et kemisk strejf. Den har fuld krop og kraftfuld smag af tropisk frugt, brændt egetræ, friskrevet muskatnød og vanilje. Compagnie Des Indes New Yarmouth JNE16 Jamaica DK edt. 2022 rom er tappet ved fadstyrke og helt uden tilsat sukker eller farvestof. Begrænset udgave på 360 nummererede flasker. Bør nydes ren. 59,5%- 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compagnie des Indes Latino 4 års Rom', 'https://rombo.dk/products/compagnie-des-indes-latino-blend', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/CompagniedesIndesLatino4arsrom_ee4eff35-09c9-46cf-9605-d54b5cfb9866.png?v=1773754940', 'Compagnie des Indes Latino 4 års rom er fra Venezuela og udgivet af den uafhængige franske aftapper, Compagnie des Indes. Rommen har lagret i tidligere bourbonfade i minimum 4 år. Smagen byder på noter af bl.a. vanilje, brændt sukker, kokos og ristede egetræskrydderier . Compagnie des Indes Latino er en mellemsød rom. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Companero Coconut', 'https://rombo.dk/products/companero-coconut', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_19b2aa29-c9aa-4955-9a02-07569c844928.png?v=1769439446', 'Compañero Coconut er en tropisk oplevelse og i skrivende stund (2025) det nyeste medlem af Compañero serien. Denne bløde, dominikanske og kolonnedestillerede sukkerrørsspiritus er lagret på både amerikanske og franske egetræsfade, og den er tilsat naturlig kokos. Resultatet er en skøn cremet likør med noter af frisk kokos, blød karamel og et strejf af frugt. Eftersmagen bliver elegant afrundet med vanilje og ahornsirup. Når man dufter til Compañero Coconut, finder man forførende frisk kokos, der bliver ledsaget af blød karamel og et strejf af tropisk frugt. I baggrunden anes fine noter af vanilje og gylden ahornsirup. Smagen er silkeblød og sødmefuld kokos i et perfekt samspil med cremet vanilje, og den afsluttes med en lang, rund eftersmag af varm karamel, som bliver hængende på tungen. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compañero Elixir Extra', 'https://rombo.dk/products/companero-elixir-extra', 299, true, 70, 47, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Companero_Elixir_Extra.png?v=1787046533', 'Compañero Elixir Extra er et vellykket blandingseksperiment fra 1423, hvor den populære Compañero Elixir Orange fra Jamaica møder Compañero Panama. Elixiren fra Jamaica bidrager med spicy noter af appelsiner og frisk kokosnød, mens Panama-udgaven tilføjer noter af kakao. Til sammen giver de en sød, blød og velafbalanceret sukkerrørsspiritus, der er velegnet til dessert eller almindelig sød hygge. Compañero Elixir Extra dufter af kakao, appelsin og mælkechokolade med et strejf af ristet eg og har smagsnoter af modne appelsiner og mørk chokolade, tilsat et hint af mint. Lang finish med vedvarende orangenoter. 47% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compañero Elixir Orange', 'https://rombo.dk/products/companero-elixir-orange-jamica', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Companero_Elixir_Orange.png?v=1787058456', 'Compañero Elixir Orange er udgivet af danske 1423 ApS, og det er en "spiced" sukkerrørsspiritus med appelsin og kokos. Compañero Elixir Orange har fyldig smag af både kokos og appelsin og er velegnet til dessert eller almindelig sød nydelse. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compañero Gran Reserva', 'https://rombo.dk/products/companero-gran-reserva', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5df7efcf-b107-4c5d-8b20-3645a2cdd39e.png?v=1769422714', 'Compañero Gran Reserva er en sukkerrørsspiritus, der er udgivet af danske 1423, som har blendet Jamaica (pot still) og Trinidad (kolonne- destillering). Compañero Gran Reserva er først lagret i Caribien og herefter færdiglagret samt tappet på flaske i Danmark. Den intense og skarpe smag fra Jamaica og den blødere stil fra Trinidad udgør en velafbalanceret helhed i en sukkerrørsspiritus, hvor man får meget for pengene. 40% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Compañero Panama Extra Añejo', 'https://rombo.dk/products/companero-pananma-extra-anejo', 325, true, 70, 54, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Companero_Panama_Extra_Anejo.png?v=1787048334', 'Compañero Panama Extra Añejo er den tredje udgave i Compañero serien. De 54% bliver gemt væk i chokoladenoterne, der giver varme til denne Panama sukkerrørsspiritus. Compañero er det spanske ord for kammerat, og det danner rammen om denne serie af produkter fra 1423, hvor smag, kompleksitet og finish er ultimative nøgleord. De to første produkter i serien, Gran Reserva og Elixir Orange , er begge fra Caribien, mens den tredje så er fra Panama. Næse: Tung mørk chokolade, varm fløde og strejf af citrus. Smag: Næsten som mini muh chokolade og kakao-agtig. Compañero Panama Extra Añejo er fadpræget og med en lille bitte smule orange, men chokoladen overdøver det meste. 54% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cortez Blanco Rom', 'https://rombo.dk/products/cortez-blanco-rom', 175, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_91fc74d8-de85-4710-8ef8-c5b9037045bf.png?v=1769422634', 'Ron Cortez Blanco er opkaldt efter den spanske erobrer Hernan Cortez. Cortez var den første, som forstod den strategiske vigtighed af Panamas landtange i forhold til at skabe en forbindelse mellem Atlanterhavet og Stillehavet. Cortez kommunikerede det til Spaniens konge Carlos V tilbage i 1524, men forbindelsen blev først opnået næsten 400 år senere med konstruktionen af Panamakanalen. Siden kanalen blev bygget har Panama været et knudepunkt for transport, handel og alverdens racer og kulturer. Ron Cortez Blanco er en klar rom, der er frugtig, blød og let. Rommen har fået en 18 måneders lagring på tidligere bourbonfade og dens lette, delikate og frugtige karakter gør den ideel i en mojito-cocktail. 40% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cristobal Nina 8-12 Years Old Spirit Drink', 'https://rombo.dk/products/cristobal-nina-8-12-years-old-spirit-drink', 349, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/CristobalNina8-12YearsOld_b7008c7a-6709-4a40-b63f-7c13bbbec2de.png?v=1789995207', 'Cristobal Niña 8-12 Years er en sød spirit drink fra Den Dominikanske Republik, og den er skabt af nøje udvalgte melassebaserede destillater, som er lagret mellem 8 og 12 år i amerikanske bourbonfade i tropisk klima. Lagringen har givet en kompleks karakter med balanceret dybde og elegance. Navnet ”Niña” er en hyldest af en af de berømte og smukke karaveller, der ledsagede Christopher Columbus på hans opdagelsesekspeditioner. Niña var ét af de tre skibe, der blev brugt af Christopher Columbus til at krydse Atlanten i 1492. Niña hed oprindeligt Santa Clara, men dets kælenavn var Niña. De to andre skibe var Santa Maria og Pinta. Cristobal Nina 8-12 Years har en duft af jordbær, blomster, frisk eg og creme brulée. Smagen er fyldig og sød med noter af myntechokolade og marshmallows samt vanilje i eftersmagen.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Deadhead Monkey Dark Chocolate', 'https://rombo.dk/products/deadhead-monkey-dark-chocolate', 449, true, 70, 35, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_80136489-88f8-44c3-8d87-ee8fae505eba.png?v=1769424904', 'Deadhead Monkey Dark Chocolate er baseret på sukkerrørsspiritus fra Veracruz i Mexico og infuseret med økologisk kakao, så det kan kategoriseres som en "spirit drink" eller likør med chokolade / kakao. Og man kan uden oevrdrivelse sige, at den kommer i en meget anderledes flaske. Deadhead Monkey Dark Chocolate er mere konkret baseret på den almindelige Deadhead, som er lagret i 6 år på brugte bourbonfade, og som har noter af kaffe, chokolade, kanel, valnød, nellike, anis og karamel. 35% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Deadhead Rom', 'https://rombo.dk/products/deadhead-rum', 425, true, NULL, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_dc445bae-20c2-4dfe-8dd1-e84aeae5da9d.png?v=1769422304', 'Deadhead Rum er fremstillet på melasse fra producentens egne sukkerrørsplantager. Gæringen foregår i små partier og herefter dobbeltdestilleres melassen på pot stills. Rommen har efter destillering lagret i 6 år på brugte franske og amerikanske bourbonfade. Deadhead Rum har noter af kaffe, chokolade, kanel, valnød, nellike, anis og karamel og kan drikkes alene eller i en række klassiske cocktails. 40% – 70.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador Destillery Icon Reserve 12 års Solera Rom', 'https://rombo.dk/products/dictador-12-icon-reserve-rum', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2067d51d-bc5b-4c5f-87f4-7314d81f58d7.png?v=1769420687', 'Dictador Solera Icon Reserve 12 års rom er produceret i Cartagena ved den caribiske kyst. Klimaet omkring Cartagena er da også det første sted i Sydamerika, man startede med at producere sukkerrør. Dictador Solera Icon Reserve 12 år har en intens aroma med blød karamel, honning, tørrede frø, brændt kaffe og egetræ. Smag: Blød og rund med karamel, kakao, honning, kaffe og egetræ med en høj kompleksitet. Dictador Solera Icon Reserve 12 års rom vandt Guld ved International Rum Expert Panel 2010 i Miami. 40% – 70cl. På grund af sin geografiske placering, er Colombia en af de tre største sukkerrørsproducenter, som sikrer et produkt i høj kvalitet. Cartagena og landskabet omkring er kendt for at være det første sted for dyrkning af sukkerrørsproduktion i Sydamerika. På grund af sin geografiske placering, er Colombia en af de tre største sukkerrørsproducenter, som sikrer et produkt i høj kvalitet. Cartagena og landskabet omkring er kendt for at være det første sted for dyrkning af sukkerrørsproduktion i Sydamerika. På grund af sin geografiske placering, er Colombia en af de tre største sukkerrørsproducenter, som sikrer et produkt i høj kvalitet. Cartagena og landskabet omkring er kendt for at være det første sted for dyrkning af sukkerrørsproduktion i Sydamerika');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador Destillery Icon Reserve 20 års Solera Rom', 'https://rombo.dk/products/dictador-20-solera-rum', 449, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8a739de3-2761-4d83-acab-072c5da6da2f.png?v=1769420691', 'Dictador Solera Destillery Icon Reserve 20 år bliver efter gæring destilleret i stålkolonner og fyldt på egetræsfade, hvor den bliver lagret efter solera-metoden.Til sidst aftappes rommen under den højeste kvalitetskontrol. Næsen: Er fast med bløde karamel, vanille, røget honning, karamel, tørrede frø, ristet kaffe. Dictador Solera Destillery Icon Reserve 20 års smag: meget blød og rund med karamel vanille, kakao, ristet honning og med en høj, sjælden tekstur og ekstraordinær kompleksitet, der kun ejes af Dictador rom. Dictador Solera Destillery Icon Reserve 20 års rom vandt guld ved International Rum Expert Panel 2010 i Miami. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Ambassador Rom', 'https://rombo.dk/products/diplomatico-ambassador-selection-cask-strength-rum', 1995, true, NULL, 47, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_0551046d-06fa-48ed-9b4d-0e3c545bfac0.png?v=1769421111', 'Diplomatico Ambassador Selection rom er destilleret i 100% kobber pot stills og efter 12 års lagring i hvide egetræsfade, er den blevet efterlagret 2 år i Pedro Ximinez fade. Smagsnoter: en dejlig skarp næse, hvor de diskrete aromaer af tørret frugt er kombineret med rig aroma af vanille, krydderier og sukkerrør sirup samt lidt røg i baggrunden. På ganen fortsætter tegnene fra aromaen og går over i en stærk, sammensat blanding af mørk chokolade, aldret tørret frugt, kaffe og vanille; alle med en dejlig cremet mundfornemmelse. Eftersmagen er lang, varm og kraftfuld. Diplomatico Ambassador Selection rom vandt 2012 Rum Expert Gold og får også den varmeste anbefaling af Rombo.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Chancellor Ron Extra Antiguo', 'https://rombo.dk/products/diplomatico-chancellor-ron-extra-antiguo', 13995, true, 70, 47, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Diplomatico_Chancellor_Ron_Extra_Antiguo.png?v=1777624733', 'Den eksklusive Diplomatico Chancellor Ron Extra Antiguo er en 2026 limited release rom med kun 1.000 flasker til det globale marked, og der er kun kommet 24 flasker til Danmark. Diplomatico Chancellor er skabt af meget få fade med noget af det ældste pot still rom, der er på lager hos Diplomatico. Rommen er "triple matured" i håndplukkede fade af fransk egetræ, amerikansk virgin oak og "seasoned American oak casks". Når man dufter til Diplomatico Chancellor Ron Extra Antiguo, fornemmes noter af egetræ, vanilje, urter, citrus, karamel og tobak. Smagen er elegant og rig med frugtige noter, vanilje og citrus. Der er i sandheden kræset om det visuelle, da den æstetiske flaske kommer i en gaveæske af træ samt en ydre beskyttelseskasse. 47% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Mantuano Ron Extra Anejo Rom', 'https://rombo.dk/products/diplomatico-mantuano-extra-anejo', 265, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_405ebe3b-6b12-428f-aedb-928d70f70096.png?v=1769422693', 'Diplomatico Mantuano Ron Extra Anejo er absolut et godt sted at starte, hvis man ikke har så stor erfaring med at drikke rom. Rommen har lagret på tidligere bourbonfade og er dejlig krydret og sødmefuld. Næse: Abrikos, figner, chokolade, krydderi, sødme. Smag: Kompleks, sød og harmonisk, men stadig med en hale af krydderier. Diplomatico Mantuano Ron Extra Anejo har en lang, let, frugtig og sød eftersmag. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Planas Rom', 'https://rombo.dk/products/diplomatico-planas-rom', 249, true, 70, 47, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e981a359-35f5-447a-b195-870315d6d474.png?v=1769422783', 'Ron Diplomatico Planas er en ekstraordinær blanding af pot Stills, kolonner og batch kettle rom. Lagret i op til 6 år, er der en elegant, rig og overraskende intensitet for en hvid rom. Den komplekse kul-filtrering, der udføres før aftapningen, giver denne rom sin krystalklare udseende og glatte finish. Næsen er frisk og fyldt tropiske aromaer, så som kaffe og kokos. Smagen er svagt frugtagtig med cremet smag. Den ekstraordinære balance af denne udsøgte rom giver en delikat og udtalt finish. 47% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Reserva Exclusiva Rom', 'https://rombo.dk/products/diplomatico-reserva-exclusiva-rom', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Diplomatico_Reserva_Exclusiva_Rom.png?v=1787041330', 'Ron Diplomatico Reserva Exclusiva er en rom, der smager af mere, og som vi kan stærkt anbefale her hos Rombo, hvis man mest er til den søde rom. Det er også et godt sted at starte sin rom-rejse. Nyd en næse af abrikos, figner, krydderi og sødme, der leder tankerne hen mod den velkendte "Dumle slikkepind". Ved første sip møder du en kompleks, sød og harmonisk smagsoplevelse, der stadig efterlader en hale af krydderier. Diplomatico Reserva Exclusiva byder på en lang, krydret og sød eftersmag. 40% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Seleccion de Familia Rom', 'https://rombo.dk/products/diplomatico-seleccion-de-familia-rum', 439, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4c882f53-53e5-4865-8587-20d394a5b259.png?v=1769424748', 'Den velkendte Diplomatico rom, der har sin oprindelse i Venezuela ved foden af Andes-bjergene, er blevet et familie medlem rigere i 2020 med lanceringen af Diplomatico Seleccion de Familia rom. Rommen er lidt mere tør, kompleks og krydret end den klassiske Diplomatico Reserva Exclusiva, men vi befinder os stadig indenfor den bløde og afrundede stil, som har gjort Diplomático rom så umådelig populær hos mange. Diplomatico Seleccion de Familia er et blend af 90% pot still rom, 5% "batch kettle" og 5% Barbet kolonnedestilleret rom, så man får altså både kompleksiteten og letheden. Lagringen er foregået i op til 12 år på nøje udvalgte fade. Først lagres rommen på "let-toastede" amerikanske hvide egetræsfade, og herefter lagres rommen yderligere i fade, der tidligere har været anvendt til bourbon, whisky og sherry, så man derved får mangfoldige indtryk i den færdige rom. Det endelige blend doseres med lidt under 20 gram sukker/liter inden aftapningen til flaske, så Diplomatico Seleccion de Familia kan betegnes som en mellemsød rom. I duften finder man bl.a. honning, røde frugter, honning og egetræ, imens smagen byder på noter af bl.a. træ, blommer og karamel. 43% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Single Vintage Rum 2008', 'https://rombo.dk/products/diplomatico-single-vintage-rum-2008', 999, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Diplomatico_Single_Vintage_Rum_2008_c17035b7-6190-47db-ab03-4b9dd1b2425f.png?v=1780483598', 'Diplomático Single Vintage 2008 er fremstillet af et udvalg af særlige rom destilleret i 2008. De udvalgte rom udviklede sig på en exceptionel måde og vakte interesse hos Diplomaticos Maestros Roneros på grund af deres distinkte karakter. Denne særlige rom adskilles fra resten af Diplomaticos destilleringer fra 2008 på grund af dens enestående karakter og for at blive delt med romentusiaster. Efter destillering i vintage kobberpotstills, blev rommen lagret i bourbon- og single malt whiskyfade i tolv år. Efter lagringsprocessen blander Maestros Roneros omhyggeligt rommen for at opnå den struktur, krop, personlighed, smag og aroma, de søger. Endelig tilbringer rommen et år i spanske sherryfade for at give den den perfekte afslutning. Rommen er en Limited edition og en opfølgning på Diplomatico Single Vintage 1997, 2000, 2001, 2002, 2004, 2005 og 2007 udgaverne. Diplomático Single Vintage 2008 er en mørk ravfarvet rom med en duft af røget træ, kaffe, chokolade, vanilje og modne frugter. Den har en velafbalanceret og utroligt velsmagende smag, der afsluttes med subtile toner af røde frugter. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Don Papa Baroko', 'https://rombo.dk/products/don-papa-baroko', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_850dc447-cc3e-42bd-97a4-f8f6bd33f369.png?v=1769425019', 'Don Papa Baroko er en filippinsk sukkerrørsspiritus, der er lagret på egetræsfade ved foden af Mount Kanlaon. Don Papa fremstilles af Bleeding Heart Rum Company på den filippinske ø Negros i et område, der også er kendt som Sugarlandia. Her er der optimale forhold for at dyrke sukkerrør, og i fremstillingen bruges udelukkende lokal melasse i topklasse. Efter destillering lagres Don Papa Baroko på amerikanske egetræstønder. Don Papa Baroko har smagsnoter af vanilje, frugt og en snert af citrus. Det er en sukkerrørsspiritus i den sødere ende, der igennem de senere år har været meget populær. 40% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Don Papa Gayuma Rum', 'https://rombo.dk/products/don-papa-gayuma-rum', 699, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8c672068-d5ff-4fba-a1c7-e2d08141e89a.png?v=1769434374', 'Don Papa Gayuma Rum er filippinsk rom lavet på melasse fra de lokale, filippinske sukkerrør, der dyrkes i Sugarlandia-området omkring vulkanen Mount Kanlaon. Rommen har først modnet i 3 år på tidligere amerikanske bourbonfade og har derefter fået en dobbelt finish: først 6 måneder på spanske Rioja-vinfade og siden tre måneder på egefade, der tidligere har indeholdt røgfyldt Islay whisky. Don Papa Gayuma Rum dufter let røget og frugtig og har en delikat krydret smag med noter af vanilje, appelsinskal, nelliker, kakao og mynte. Røgen giver et behageligt krydret, sødmefuldt strejf til eftersmagen. Mellemsød rom. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Don Papa Quincentennial Edition Small Batch 2025 Release Rum', 'https://rombo.dk/products/don-papa-quincentennial-edition-small-batch-2025-release-rum', 4995, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Don_Papa_Quincentennial_Edition_Small_Batch_2025_Release_Rum.png?v=1773152657', 'Der er historisk set kun lavet 500 flasker om året af denne unikke Don Papa Quincentennial Edition Small Batch Rum. Den særlige udgivelse er en fejring af 500-året for den første jordomsejling og den første landgang på Filippinerne, som blev iværksat af den portugisiske søfarer Ferdinand Magellan. Don Papa Quincentennial fra Filippinerne er en dobbeltlagret rom, der først er modnet i to år bourbonfade, og herefter færdigmodnes den 5 år i brugte portvinsfade på øen Negros. Portvinsfadene tilfører rommen masser af frugt og sødme. Når man smager denne Don Papa Quincentennial Edition Small Batch 2025 Release rom, fornemmer man noter af bl.a. røde bær, citrus, vanilje og tropiske frugter. Bemærk: det skal for god ordens skyld nævnes, at der i 2025 er skruet væsentligt op for antallet og lavet 18.800 flasker til verdensmarkedet, og derfor er prisen også justeret til 4.995 kr. fra de oprindelige 7.995 kr., som den tidligere har kostet.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Don Papa Single Island 7 års Rom', 'https://rombo.dk/products/don-papa-single-island-rum', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1793e44c-d774-42fa-9992-00b672edecef.png?v=1769435522', 'Don Papa Single Island Rum er den originale ’single island rum’ fra Filippinerne, lavet som en hyldest til øen Negros Occidental flora og fauna, samt inspireret af Papa Isio, som var revolutionshelt og shaman på øen Negros, hvor rommen er produceret. Her bliver Don Papa Single Island Rum lagret på egetræsfade i minimum 7 år, der herefter er blandet kildevand fra Mount Kanlaon til 40% ABV. Filippinerne er blandt de 5 største lande af rom og sukkerrørsbaseret spiritus i verden, og med Don Papa Single Island Rum får man en sød rom med en let parfumeret og frugtagtig duft. Smagen byder på vanilje, honning, mørk karamel og kandiseret frugt. 40% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Don Q 151 Overproof Rom', 'https://rombo.dk/products/don-q-151-overproof-rum', 325, true, 70, 75.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4c64513e-5584-4afb-936c-2ae64df5af84.png?v=1769422832', 'Don Q 151 er en Overproof Rum fra Puerto Rico produceret af Destilleria Serralles. Destilleriet har i dag over 100.000 fade med rom på lager, hvilket gør det til et af de største i Caribien. Don Q navnet kommer fra den kendte "Don Quixote", som var Serralles-familiens ynglingsbog. Vi har selv på internationale rom-messer efterhånden mødt Don Q nogle gange, og de har indtil videre fokuseret på det amerikanske marked. Lidt ærgerligt, da manden bag Don Q, Roberto Serralles, er en meget visionær og kyndig person. Nu er der langt om længe kommet mere fokus på Europa og også en dansk importør. Her får du Don Q 151 Overproof Rum udgaven, der kan bruges som basis-rom i diverse cocktails. Rommen er gæret på sukkerrørsmelasse og herefter kolonnedestilleret. På destilleriet arbejder man med både lette romdestillater og tunge romdestillater, hvilket giver mulighed for at sammensætte en bred palette af forskellige romtyper. Don Q hører under den "spanske romstil", men når det er sagt, så er de grundlæggende imod tilsætning af sukker, og derfor er sødmen også mindre udpræget i deres produkter. Don Q 151 Overproof Rum Puerto Rico rom 75,5% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Don Q Double Cask Port Finish Rom', 'https://rombo.dk/products/don-q-port-cask-finish-rum', 649, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_75ec6851-08ec-491d-91c8-7e91657a4c8e.png?v=1769434652', 'Don Q Double Cask Port Finish Rum er en "limited edition" rom fra Puerto Rico, hvor rommen produceres af Destilleria Serralles. Destilleriet har i dag over 100.000 fade med rom på lager, hvilket gør det til et af de største i Caribien. Don Q navnet kommer fra den kendte "Don Quixote", som var Serralles-familiens ynglingsbog. Vi har selv på internationale rom-messer efterhånden mødt Don Q nogle gange, og de har indtil videre fokuseret på det amerikanske marked. Lidt ærgerligt da manden bag Don Q, Roberto Serralles, er en meget visionær og kyndig person. Nu er der langt om længe kommet mere fokus på Europa og også en dansk importør. Her får du Don Q Double Cask Port Finish rom udgaven, der først er blevet modnet i amerikanske egetræsfade i 5-8 år, og efter at være blendet sammen er den lagret yderligere 3 år i portvinsfade. Rommen er gæret på sukkerrørsmelasse og herefter kolonnedestilleret. På destilleriet arbejder man med både lette romdestillater og tunge romdestillater, hvilket giver mulighed for at sammensætte en bred palette af forskellige romtyper. Don Q hører under den "spanske romstil", men når det er sagt, så er de grundlæggende imod tilsætning af sukker, og derfor er sødmen også mindre udpræget i deres produkter. Don Q Double Cask Port Finish rom har noter af bl.a. tørret frugt, kanel, nellike, rosiner og portvinssødme. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Don Q Gran Reserva Anejo XO Rom', 'https://rombo.dk/products/don-q-gran-reserva-anejo-xo-puerto-rico-rom', 599, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e48a75cc-4464-4ae4-9aab-e0fc20690b3a.png?v=1769425583', 'Don Q Gran Reserva Anejo XO er rom fra Puerto Rico, hvor rommen produceres af Destilleria Serralles, der er et familieejet, meget moderne og miljøvenligt romdestilleri. Destilleriet har i dag over 100.000 fade med rom på lager, hvilket gør det til et af de største i Caribien. Don Q navnet kommer fra den kendte "Don Quixote", som var Serralles-familiens ynglingsbog. Her får du Don Q Gran Reserva Anejo XO-udgaven, der efter destillering har modnet i mellem 9 og 12 år på amerikanske hvideg-fade. Den indeholder både lette og tunge romdestillater – blandt andet solera-rom, der har lagret i over 50 år i sherry-tønder. Rommen har en flot balance mellem de søde og de tørre smagsnoter og smagen af karamel og vanilje er både rund og kompleks. Don Q hører under den "spanske romstil", der normalt er mere sød, men her er der tale om en usødet rom, der er destilleriets stolthed. Kommer i gaveæske. 40 % – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly''s 12 år Fine Old Barbados Rum', 'https://rombo.dk/products/doorlys-12-fine-old-rum', 425, true, NULL, 10, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Doorly_s_12_r_Fine_Old_Barbados_Rum.png?v=1787062324', 'Doorly''s 12 år Fine Old Barbados Rum fremstilles hos Foursquare, der er et af de mest moderne og miljøvenlige destillerier i verden. Richard Seale, der står bag Foursquare, er en visionær kendis i branchen, og han værner passioneret om sin romproduktion uden tilsætning af sukker og farve. Doorly''s 12 år Fine Old Barbados Rum er lagret fuldt ud i 12 år, og den er som det øvrige rom fra Foursquare en blanding af pot still rom (ca. 10%) og kolonnedestilleret rom (ca. 90%). Vi har selv smagt Doorly''s 12 års rommen, og kan kun anbefale den på det varmeste, medmindre man er til den meget søde rom.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly''s 14 år Fine Old Barbados Rum', 'https://rombo.dk/products/doorlys-14-fine-old-barbados-rum', 649, true, 70, 48, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_054675e5-4207-4ff4-9342-8ef9dd05426d.png?v=1769423568', 'Doorly''s 14 års rom Fine Old Barbados Rum fremstilles hos Foursquare, der er et af de mest moderne og miljøvenlige destillerier i verden. Richard Seale, der står bag Foursquare, er en visionær kendis i branchen, og han værner passioneret om sin romproduktion uden tilsætning af sukker og farve. Doorly''s 14 år Fine Old Barbados Rum er lagret fuldt ud i 14 år i "small American White Oak casks", og denne rom må som det meste af det øvrige rom fra Foursquare antages at være en blanding af pot still rom (ca. 10%) og kolonnedestilleret rom (ca. 90%). 48% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly''s 3 år Fine Old Barbados Rum', 'https://rombo.dk/products/doorlys-3-rum', 245, true, 70, 47, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4eb7f77c-eea7-4799-9e48-a305bd0c881d.png?v=1769423926', 'Doorly''s 3 år Fine Old Barbados Rum er fremstillet hos Foursquare Distillery, der ledes af Richard Seale og i dag fremstår som et af de mest moderne, "ærlige" og visionære romdestillerier. Doorly''s 3 år Fine Old Barbados Rum er ikke tilsat sukker for at søde rommen. Destillationsmetoden med både pot still og kolonnekedel samt den efterfølgende lagring i egetræsfade sikrer en naturlig sødme og en fyldig smag. Denne hvide rom er faktisk lagret i 3 år, hvorefter man har fjernet farven, men ikke smagen. Næse: frugtig og aromatisk med noter af ananas og andre tropiske frugter. Smag: frisk og frugtagtig med noter af kokos. 47% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly''s 5 år Fine Old Barbados Rum', 'https://rombo.dk/products/doorlys-5-rum', 235, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1888c11c-4597-42f5-a0d5-94bfa28d538c.png?v=1769422335', 'Doorly''s Aged 5 Years Fine Old Barbados Rum er fremstillet på Foursquare Distillery, der ledes af Richard Seale og i dag fremstår som et af de mest moderne, "ærlige" og visionære romdestillerier. 5 år lyder ikke af meget, men når rommen kommer fra Foursquare på Barbados, så betyder det, at denne Doorly''s rom er minimum 5 år gammel, og at den er af allerhøjeste kvalitet og faktisk kan nydes rent. Doorly''s 5 år Barbados Rum er ca. 90% kolonnedestillering og 10% pot still. Krydret smag af sukkerrør, med frugtagtige, florale noter og st strejf af karamel og vanilje. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly''s XO Fine Old Barbados Rum', 'https://rombo.dk/products/doorlys-xo-fine-old-rum', 325, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_bd3ed833-1749-483a-9e5b-19c58ef90524.png?v=1769420695', 'Doorly''s XO er husets premium rum og er en blend af 6 år til 12 år gammel Barbados-rom, hvor lagringen afsluttes med en Oloroso finish. Destilleriet "The Foursquare Plantation", hvor Doorly''s XO blandes og lagres, er omkring 350 år gammel, og de ældste optegnelser antyder, at den særlige rom-vin-mølle tilknyttet molassefabrikken har været i produktion siden 1730. Destilleriet blev totalt renoveret i 1995 og fremstår i dag som en blanding mellem historien og den nye teknologi. Samtidig er romproduktionen på stedet blevet erklæret 100% miljørigtig. Næse: Gummi, sherry fad, krydderi - og snuser man kraftigt, kunne det narre og være en whisky med sherry lagring. Smag: Stor fylde af rom- og sherry nuancer, meget kompleks, vanille og nødder. Eftersmag: Olieret, lang og sødmefyldt, spor af sherry. En meget fin balance i eftersmagen. Doorly''s XO Fine Old Rum er en meget afbalanceret rom, og sherry-inspirationen gør den anderledes og spændende. 43% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas 5+5 års Rom Gaveæske m/2 glas', 'https://rombo.dk/products/dos-maderas-5-5-ar-gaveaeske', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f86eb214-d549-4415-aa19-a57f40d393ca.png?v=1769423420', 'Dos Maderas-huset blev grundlagt i 1877 af Sir Alexander Williams, der var en stor beundrer og connaisseur af sherry, og Arthur Humbert, der var specialist i internationale relationer. Hos Williams &amp; Humbert udvælger Master blenderen rom fra Barbados og Guyana, og når den ønskede blanding er fundet, lagrer man rommen 5 år i Caribien. Efter denne del af lagringsprocessen bliver blandingen sejlet over Atlanten til Williams &amp; Humbert i Spanien, hvor anden del af lagringen begynder. Rommen bliver nu lagret 3 år i egetræsfade, der tidligere har været brugt til at modne den internationale prisvindende sherry ”Dos Cartados” Oloroso, og for at fuldende denne Dos Maderas 5+5 rom bliver den til sidst lagret 2 år på den tungere og mere fyldige ”Don Guido” Pedro Ximenez sherry. Smagen er blød og delikat med noter af rosin, figen og vanille. Dos Maderas Caribbean Double Aged PX 5+5 år vandt guld-medalje ved International Rum Expert Panel 2010. Her får du rommen i en fin gaveæske, der også indeholder 2 autentiske Dos Maderas glas. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Atlantic Double Aged Rum', 'https://rombo.dk/products/dos-maderas-atlantic', 299, true, 70, 37.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c83a0d72-db1d-4741-b626-92c4f20583ac.png?v=1769437234', 'Dos Maderas rom-mærket produceres og lagres indledningsvis i Barbados og Guyana, hvorefter rommen sendes til Spanien for at få en yderligere lagring på sherryfade hos Williams &amp; Humbert, der er eksperter indenfor sherry og lagring af spiritus. "Dos Maderas" betyder på spansk "2 slags træ" med reference til lagringsmetoden, der typisk starter på ex-bourbonfade i Caribien og altså slutter med sherrylagringen i Spanien. Den afsluttende lagring på sherryfade tilføjer sødme og balance til den robuste og karakterfulde rom fra Barbados og Guyana. Den nye Dos Maderas Atlantic 2024-udgivelse er et blend af 5-årig rom fra Barbados og 5-årig rom fra Guyana. Efter sammenblandingen af disse er rommen lagret yderligere i et år på brugte Pedro Ximenez sherryfade i Jerez i det sydlige Spanien. Dos Maderas Atlantic har en velafbalanceret duft og smag med noter af bl.a. egetræ, krydderier, karamel, vanilje, honning, ristede nødder og rosiner. 37,5% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Luxus Double Aged Rum', 'https://rombo.dk/products/dos-maderas-luxus-rum-10-5', 1075, true, NULL, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/DosMaderasLuxusDoubleAgedRum.png?v=1787228422', 'Dos Maderas Luxus Barbados-Guyana Blended Rum lagres først 10 år i Caribien, hvorefter lagringen af rommen fortsættes i mindst 5 år i ”Don Guido” (Pedro Ximenez) sherryfade i Williams &amp; Humberts Bodega i Jerez, Spanien. Næse: mandler, marcipan, kirsebær og "ris á la mande". Smag: cremet, lidt sød og masser af krydderier. Eftersmag: lang, sen sødme med en krydret hale. Dos Maderas Luxus 10+5 år er en fremragende, kompleks rom med søde og krydrede noter.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Seleccion Tripple Aged Rum', 'https://rombo.dk/products/dos-maderas-seleccion', 449, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e57d6803-313a-45b2-babe-1a46535d68bb.png?v=1769423293', 'Dos Maderas Seleccion er et blend af forskellige fade, der er aftappet ved 42% og har fantatiske aromaer af sød Pedro Ximenez sherry og vanilie-noter fra de amerikanske bourbon-fade. Smagen følger fint op på duften og begynder med den 10 år lagrede rom, der først giver en klassisk oplevelse af rustik rund og tør rom, for derefter at blive efterfulgt af fine noter af sødme fra de legendariske sherry-fade fra Williams &amp; Humbert i Jerez. 42% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Tripple Aged 5+5 år', 'https://rombo.dk/products/dos-maderas-px-5-5', 375, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Dos_Maderas_Tripple_Aged_5_5_r.png?v=1787050661', 'Dos Maderas huset blev grundlagt i 1877 af Sir Alexander Williams, en stor beundrer og connaisseur af sherry, og Arthur Humbert, specialist i internationale relationer. Nu ejes huset af Medina-familien og har vundet stort anerkendelse for deres sherry, brandy, rom og sukkerrørsspiritus. Når Master blenderen har fundet den ønskede blanding mellem udvalgt rom fra Barbados og Guyana er fundet, lagrer man den 5 år i Caribien. Efter denne del af lagringsprocessen bliver blandingen sejlet over Atlanten til Williams &amp; Humbert i Spanien, hvor anden del af lagringen begynder. Dos Maderas PX 5+5 år Tripple Aged sukkerrørsspiritus bliver nu lagret 3 år i særligt udvalgte egetræsfade, der tidligere har været brugt til at modne den internationalt prisvindende sherry ”Dos Cartados” Oloroso. Til sidst lagrer man i 2 år på fade fra den tungere, mere fyldige ”Don Guido” Pedro Ximenez sherry, begge certificeret og godkendt af DO-Jerez – Xéres Sherry til at have en gennemsnitsalder på 20 år. Det sidste stadie, hvor denne populære spiritus lagrer i Pedro Ximénez fade, giver den flotte farve, og der tappes på flaske med en sødme, der klassificerer Dos Maderas PX 5+5 år Tripple Aged som en sukkerrørsspiritus. Smagen er blød og delikat med noter af rosin, figen og vanilje. Dos Maderas Caribbean Double Aged PX 5+5 år vandt guld-medalje ved International Rum Expert Panel 2010. 40% vol. – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 1998 The Last Casks Black Label Limited Edition Rum', 'https://rombo.dk/products/el-dorado-1998-the-last-casks-black', 2695, true, 70, 50.3, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_fe65c547-ce84-4ff0-a3cd-96ae9a7e8e73.png?v=1769437493', 'El Dorado 1998 The Last Casks Black Label er en "limited edition" rom fra Demerara Distillers Ltd i Guyana. El Dorado har længe været anerkendt som et af Caribien''s førende rom-mærker, da destilleriet - Diamond Distillery - ejer nogle af de ældste og mest bemærkelsesværdige destilleringsapparater indenfor rom-verdenen, og disse anvendes på forskellige måder til fremstillingen af El Dorado rom. Den unikke El Dorado 1998 The Last Casks Black Label Edition rom er lavet af de allersidste eksisterende fade af det karamelfarvede og lette blend fra Tri-Canada Redistillation Still, der sidenhen er lukket ned. Dette blend er i The Last Casks Black udgaven blevet lagret og blended sammen med rom fra de legendariske Port Mourant Double Wooden Pot Still og Enmore Wooden Coffey Still destilleringsapparaterne. De i alt 24 års lagring er foregået i ex-bourbon egetræsfade. I duften finder man brændte og mineralske aromaer af rosiner, svesker, kanel, vanilje, mandler og træ. Smagen er kompleks og tør med noter af appelsinskal, honning, toffee og mørk chokolade. Cask strength - tappet ved fadstyrke. 50,3% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 1998 The Last Casks Red Label Limited Edition Rum', 'https://rombo.dk/products/el-dorado-1998-the-last-casks-red', 2695, true, 70, 49.1, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_eb73921b-a340-4592-8ff5-3fe2a6e385e7.png?v=1769437498', 'El Dorado 1998 The Last Casks Red Label er en "limited edition" rom fra Demerara Distillers Ltd i Guyana. El Dorado har længe været anerkendt som et af Caribien''s førende rom-mærker, da destilleriet - Diamond Distillery - ejer nogle af de ældste og mest bemærkelsesværdige destilleringsapparater indenfor rom-verdenen, og disse anvendes på forskellige måder til fremstillingen af El Dorado rom. Den unikke El Dorado 1998 The Last Casks Red Label Edition rom er lavet af de allersidste eksisterende fade af det karamelfarvede og lette blend fra Tri-Canada Redistillation Still, der sidenhen er lukket ned. Dette blend er i The Last Casks Red udgaven blevet lagret og blended sammen med rom fra Diamond Coffey Still destilleringsapparatet. De i alt 24 års lagring er foregået i ex-bourbon egetræsfade. I duften finder man honning, mandler, appelsin og banan. Smagen byder på noter af lakrids, mørk chokolade, grønne æbler og tørret frugt. Cask strength - tappet ved fadstyrke. 49,1% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 2000 The Last Casks Gold Label Limited Edition Rum', 'https://rombo.dk/products/el-dorado-2000-the-last-casks-gold', 2695, true, 70, 54.4, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f5d4d12d-790f-4332-b3d8-7c81568d8361.png?v=1769437501', 'El Dorado 2000 The Last Casks Gold Label er en "limited edition" rom fra Demerara Distillers Ltd i Guyana. El Dorado har længe været anerkendt som et af Caribien''s førende rom-mærker, da destilleriet - Diamond Distillery - ejer nogle af de ældste og mest bemærkelsesværdige destilleringsapparater indenfor rom-verdenen, og disse anvendes på forskellige måder til fremstillingen af El Dorado rom. Den unikke El Dorado 2000 The Last Casks Gold Label Edition rom er baseret på en 1 år gammel rom, der blev destilleret på Diamond Coffey Still destilleringsapparatet. Denne rom blev siden hen lagret i yderligere 21 på brugte fade, der tidligere indeholdt rom fra Uitvlugt Distillery, som lukkede i 2000. De i alt 22 års lagring er foregået i ex-bourbon egetræsfade. I duften finder man honning, karamel, vanilje, kanel, muskatnødder, lakrids, valnødder og hasselnødder. Smagen er sødmefuld og byder på noter af rig melasse, honning, karamel, vanilje og muskatnødder samt en lang, vedvarende eftersmag. Cask strength - tappet ved fadstyrke. 54,4% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 2008 Uitvlugt Enmore Blended in the Barrel Rum', 'https://rombo.dk/products/el-dorado-2008-uitvlugt-enmore-rum', 1395, true, 70, 47.4, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_525040f2-a77c-4b32-8ea5-a39379272879.png?v=1769437861', 'El Dorado 2008 Uitvlugt Enmore Blended in the Barrel Rum er en "limited edition" rom fra Demerara Distillers Ltd (DDL) i Guyana. El Dorado har længe været anerkendt som et af Caribien''s førende rom-mærker, da destilleriet - Diamond Distillery - ejer nogle af de ældste og mest bemærkelsesværdige destilleringsapparater indenfor rom-verdenen, og disse anvendes på forskellige måder til fremstillingen af El Dorado rom. Blended in the Barrel rom-serien fra El Dorado indeholder forskellige udgaver, hvor DDL - som navnet siger - har fundet fade fra forskellige destilleringsapparater med forskellige marques og blended dem i bourbonfade, hvorefter de er blevet færdiglagret. El Dorado 2008 Uitvlugt Enmore Blended in the Barrel rom er et blend af romdestillater fra Uitvlugt Continuous Savalle Still (marque "ICBU" og marque "GS/20") og fra det legendariske Enmore Wooden Coffey Still (marque "EHP") . De i alt 11 års lagring er foregået i ex-bourbon egetræsfade. Cask strength - tappet ved fadstyrke. 47,4% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 2010 Diamond Port Mourant Blended in the Barrel Rum', 'https://rombo.dk/products/el-dorado-2010-diamond-port-mourant-rum', 1395, false, 70, 49.1, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_18a5479c-1b4a-423b-a057-ebc625b42d66.png?v=1769437857', 'El Dorado 2010 Diamond Port Mourant Blended in the Barrel Rum er en "limited edition" rom fra Demerara Distillers Ltd (DDL) i Guyana. El Dorado har længe været anerkendt som et af Caribien''s førende rom-mærker, da destilleriet - Diamond Distillery - ejer nogle af de ældste og mest bemærkelsesværdige destilleringsapparater indenfor rom-verdenen, og disse anvendes på forskellige måder til fremstillingen af El Dorado rom. Blended in the Barrel rom-serien fra El Dorado indeholder forskellige udgaver, hvor DDL - som navnet siger - har fundet fade fra forskellige destilleringsapparater med forskellige marques og blended dem i bourbonfade, hvorefter de er blevet færdiglagret. El Dorado 2010 Diamond Port Mourant Blended in the Barrel rom er et blend af romdestillater fra Diamond Continuous Coffey Still (marque "SV") og fra det legendariske Port Mourant Double Wooden Pot Still (marque "PM"). De i alt 9 års lagring er foregået i ex-bourbon egetræsfade. Cask strength - tappet ved fadstyrke. 49,1% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 2010 Port Mourant Uitvlugt Blended in the Barrel Rum', 'https://rombo.dk/products/el-dorado-2010-port-mourant-uitvlugt-rum', 1395, true, 70, 51, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e894ad54-4c6a-40a8-a861-ab7ba1734e44.png?v=1769437850', 'El Dorado 2010 Port Mourant Uitvlugt Blended in the Barrel Rum er en "limited edition" rom fra Demerara Distillers Ltd (DDL) i Guyana. El Dorado har længe været anerkendt som et af Caribien''s førende rom-mærker, da destilleriet - Diamond Distillery - ejer nogle af de ældste og mest bemærkelsesværdige destilleringsapparater indenfor rom-verdenen, og disse anvendes på forskellige måder til fremstillingen af El Dorado rom. Blended in the Barrel rom-serien fra El Dorado indeholder forskellige udgaver, hvor DDL - som navnet siger - har fundet fade fra forskellige destilleringsapparater med forskellige marques og blended dem i bourbonfade, hvorefter de er blevet færdiglagret. El Dorado 2010 Port Mourant Uitvlugt Blended in the Barrel rom er et blend af romdestillater fra det legendariske Port Mourant Double Wooden Pot Still (marque "PM") og fra Uitvlugt Continuous Savalle Still (marque "ICBU"). De i alt 9 års lagring er foregået i ex-bourbon egetræsfade. Cask strength - tappet ved fadstyrke. 51% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 2010 Port Mourant Uitvlugt Diamond Blended in the Barrel Rum', 'https://rombo.dk/products/el-dorado-2010-port-mourant-uitvlugt-diamond-rum', 1395, true, 70, 49.6, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_44eb1b8d-6185-4429-9eb2-cab5358a6963.png?v=1769437853', 'El Dorado 2010 Port Mourant Uitvlugt Diamond Blended in the Barrel Rum er en "limited edition" rom fra Demerara Distillers Ltd (DDL) i Guyana. El Dorado har længe været anerkendt som et af Caribien''s førende rom-mærker, da destilleriet - Diamond Distillery - ejer nogle af de ældste og mest bemærkelsesværdige destilleringsapparater indenfor rom-verdenen, og disse anvendes på forskellige måder til fremstillingen af El Dorado rom. Blended in the Barrel rom-serien fra El Dorado indeholder forskellige udgaver, hvor DDL - som navnet siger - har fundet fade fra forskellige destilleringsapparater med forskellige marques og blended dem i bourbonfade, hvorefter de er blevet færdiglagret. El Dorado 2010 Port Mourant Uitvlugt Diamond Blended in the Barrel rom er et blend af romdestillater fra det legendariske Port Mourant Double Wooden Pot Still (marque "PM"), fra Uitvlugt Continuous Savalle Still (marque "ICBU") og fra Diamond Continuous Coffey Still (marque "SVW"). De i alt 9 års lagring er foregået i ex-bourbon egetræsfade. Cask strength - tappet ved fadstyrke. 49,6% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado Rum 12 år', 'https://rombo.dk/products/el-dorado-rum-12', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1b0ba4ba-29de-4123-bc06-91038184bf28.png?v=1769420999', 'El Dorado Rum 12 år er blanding af særligt udvalgte gamle rom, hvor den yngste er ikke mindre end 12 år gammel, og den er lavet på en kombination af Enmore og Diamond Coffey Stills og Port Mourant double wood Pot Stills, hvorefter den blandes til perfektion og lagres på gamle bourbon egetræsfade. Smagsnoter: Duft af frodige, tropiske frugter og krydderier med strejf af honning og mørk sukker. Smagen er kompleks og fyldig med rige noter af frugt og krydderier. Eftersmagen er elegant og tør. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado Rum 15 år', 'https://rombo.dk/products/el-dorado-rum-15', 465, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/El_Dorado_Rum_15_r.png?v=1787058593', 'El Dorado 15 år er en blanding af særligt udvalgte gamle rom, hvor den yngste er ikke mindre end 15 år gammel. Den er lavet på en kombination af Enmore og Diamond Coffey Stills, Port Mourant double wood Pot Stills og Versailles single wood pot stills, hvorefter den blandes til perfektion og lagres på gamle bourbon egetræsfade. Smagsnoter for El Dorado 15 år: Næse fyldt med mørk kaffe, kandiseret appelsin, mandler, mørk chokolade, peber og rig vanilje. Smukt afrundet i ganen med en stor spredning af smagsvarianter: grillet tropisk frugt med krydderi - den er kompleks, levende og moderat fyldig. 43% vol. – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado Rum 21 år', 'https://rombo.dk/products/el-dorado-rum-21', 849, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a9ae2d5d-2f25-4c00-8d94-cb4209d311d3.png?v=1769421007', 'El Dorado 21 års rom er blevet kaldt "En monumental ældet rom, der er en af verdens største rom-oplevelser" - det er sådan, The Beverage Tasting Institute of Chicago opsummerede deres påskønnelse af El Dorado 21 Year Old Special Reserve. Den er designet til ægte rom-kendere med sine varme nuancer, der bedst nydes langsomt på egen hånd - og deles med et par meget specielle venner. Master Blender blander specielt udvalgte rom, der er lagret i mindst 21 år og lavet fra Enmore wooden Coffey still, Versailles single wood pot still og Albion Savalle still. Smagsnoter: Duft af frodige, tropiske frugter og krydderier med strejf af honning og mørk sukker. Kompleks og fyldig smag med rige noter af frugt og krydderier. 43% –70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado Rum 3 år', 'https://rombo.dk/products/el-dorado-rum-3', 169, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_da72976d-36ed-4a5d-a31e-899d0a7e4e9b.png?v=1769437457', 'El Dorado Rum 3 år er en Guyana-rom fra Demerara Distillers Ltd. Rommen er lagret i minimum 3 år og er herefter blevet kulfiltreret 2 gange for at fjerne farven fra fadlagringen, så den igen er blevet lys. El Dorado 3 års rom er derfor også overraskende blød ift. lys rom generelt, og den anvendes til cocktails, punch, long drinks, m.m. Noter: citrus, vanilje, chokolade, rosin, kokos og frugt. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado Rum 8 år', 'https://rombo.dk/products/el-dorado-rum-8', 235, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_206843a1-aeea-43e7-86cf-53e53e2522c4.png?v=1769437461', 'El Dorado Rum 8 år er blanding af særligt udvalgte gamle rom, hvor den yngste er ikke mindre end 8 år gammel. Rommen er fremstillet hos Demerara Distillers Limited (DDL), hvor den blandes til perfektion og lagres på gamle bourbon egetræsfade. El Dorado 8 års rom kan både nydes rent eller som base i en cocktail. Noter: tobak, karamel toffee, tørret frugt, flamberet banan, egetræ og flødekaramel. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Ron Prohibido 15 år Solera', 'https://rombo.dk/products/el-ron-prohibido-solera-15-rom', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f0a58752-c5f1-4465-8e92-e8062b43f365.png?v=1769422908', 'El Ron Prohibido 15 år er lagret efter Solera-metoden og indeholder derfor rom, der er op til 15 år gammel. El Ron Prohibido betyder "den forbudte rom", og det skyldes, at den spanske konge i 1796 forbød den pågældende rom-recept fra Mexico, da den var blevet så populær i Spanien, at den var blevet en trussel for de lokale producenter. El Ron Prohibido er en genskabelse af "den forbudte rom", der opstod i ca. år 1700, hvor man i Mexico fyldte den lokale rom (Chinquirito) på fade, der havde indeholdt sød, spansk vin. Dette gav rommen en helt speciel karakter, der blev vældig populær og altså sidenhen forbudt. El Ron Prohibido blev også kaldt Habanero, da Havana på Cuba var det sidste stop på sejlturen fra Mexico til Spanien. El Ron Prohibido Solera 15 års udgaven i duft: brun sukker, nødder, vanilje, og så svesker og nogle noter af mørk rosin. I smagen finder man honning, mørk chokolade, kaffe, muskat og rosiner. 40% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Ron Prohibido Reserva 22 år Solera', 'https://rombo.dk/products/ron-prohibido-reserva-22', 475, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_3e51433f-f132-4ffe-ab3a-c544b6dff5cc.png?v=1769424920', 'El Ron Prohibido Reserva 22 år er lagret efter Solera-metoden og indeholder derfor rom, der er op til 22 år gammel. El Ron Prohibido betyder "den forbudte rom", og det skyldes, at den spanske konge i 1796 forbød den pågældende rom-recept fra Mexico, da den var blevet så populær i Spanien, at den var blevet en trussel for de lokale producenter. El Ron Prohibido er en genskabelse af "den forbudte rom", der opstod i ca. år 1700, hvor man i Mexico fyldte den lokale rom (Chinquirito) på fade, der havde indeholdt sød, spansk vin. Dette gav rommen en helt speciel karakter, der blev vældig populær og altså sidenhen forbudt. El Ron Prohibido blev også kaldt Habanero, da Havana på Cuba var det sidste stop på sejlturen fra Mexico til Spanien. El Ron Prohibido Reserva Solera 22 års udgaven har noter af bl.a. brunt sukker, chokolade vanilje, kaffe, fersken og rosin. 40% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('English Harbour 5 års Rom', 'https://rombo.dk/products/english-harbour-5-antigua-rum', 275, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f59d2b9f-4693-48ba-904b-c886959f2a2d.png?v=1769419963', 'English Harbour 5 års rom er produceret på Antigua Distillery Limited – et estimeret familieforetagende, som blev grundlagt i 1932 og nu drives af 4. generation. English Harbour 5 års rom har vundet et væld af priser: Dobbelt guld ved San Francisco World Spirits Competition 2004 og 2005, guld ved Beverage Testing Institute 2005 og 2006, og Forbes Magazine Worlds 10 Most Remarkable Rums i 2006. Som med de fleste andre rom, er der anvendt lagring på ex-bourbon fade, og smagen har noter af brændt sukker, melasse, frugt, vanille og karamel. Den er en anelse mere skarp end sød, men er stadig meget velafbalanceret. English Harbour 5 års rom er god kvalitet for pengene. 40% - 70 cl');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('English Harbour Coeur de Savalle Rom', 'https://rombo.dk/products/english-harbour-coeur-de-savalle-rom', 24995, true, 70, 73.6, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_efc0cbd1-d699-4d2a-aa22-6c85a6310e10.png?v=1769425857', 'English Harbour Coeur de Savalle er en ublandet, single cask rom, der er tappet ved fadstyrke for at få alle rommens naturlige smagsnuancer med. English Harbour Coeur de Savalle er en unik aftapning, der på fornem vis opfylder destilleriets Cellar Masters vision om at skabe en ren, ublandet og uspoleret rom, udelukkende er kolonnedestilleret på Antigua Distillerys originale, franske Savalle-still. Resultatet er Coeur de Savalle, den ultimative Savalle-rom, der er aromatisk og elegant med et rent kobber-udtryk. English Harbour Coeur de Savalle er den første i Antigua Distillers’ serie Cask Strength Expression, og kommer i et meget begrænset oplag. 73,6% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('English Harbour Madeira Cask Finish Rom', 'https://rombo.dk/products/english-harbour-madeira-cask-finish', 349, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/English_Harbour_Madeira_Cask_Finish_Rom.png?v=1770195934', 'English Harbour Madeira Cask Finish kombinerer arven fra grundlæggerne af English Harbour med den gamle tradition for romproduktion. Denne rom bygger videre på English Harbour 5 år, som lagrer i mindst 5 år i Bourbon-tønder, hvorefter denne udgave færdiggøres i 5 måneder i Madeira Wine Barrels fra den prestigefyldte Blandy''s Madeira Wine Company på Madeira, hvor English Harbours grundlæggere stammer fra. Når lagringen er afsluttet, tilsættes 5% af English Habours 10 årige rom til den endelige blanding, og produktet tappes ved 46% ved hjælp af en ikke-kølefiltreret metode for at bevare produktets integritet. Denne forening resulterer i en blanding med velafbalancerede noter, en fejlfri glathed og rige smagsnuancer. I modsætning til English Harbour Port Cask Finish og English Harbour Sherry Cask Finish, hvor kun ét type vinfad blev brugt, blev der til denne udgave brugt fire forskellige typer Madeira-tønder. Tønderne er en blanding af Bual, Sercial, Malvasia og Tinta, hvilket giver denne færdiggørelse en kompleksitet, der ikke let kan beskrives. Rommen har en klar gylden farve og en varm velkommende duft af valnødder og hasselnødder, der åbner døren til klare kanelnoter, frisk citrus og marcipan. Smagsoplevelsen begynder med bløde florale toner, der leder vejen til marcipanens som også var i duften. Midtpunktet udfolder sig med hvid chokolade og livlig citrus med behagelige krydrede nuancer af græskar. 46% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('English Harbour Reserve 10 års Rom', 'https://rombo.dk/products/english-harbour-reserve-rum-10-ar-40-70cl-rom-fra-antigua', 425, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8d1ca535-c7db-4182-84d2-d53c78a3d4c6.png?v=1769420636', 'Da romproduktionen startede på Antigua (omkring 1650), var det små særskilte ejendomme og plantager, der lavede "hjemmeproduktion". Men rommen fra Antigua blev hurtigt kendt for sin egenart og elegante, aromatiske stil. I slutningen af 1800-tallet var der ikke mindre end 78 fabrikker på øen, der producerede sukker og lavede rom. Den lokale rom blev blandet af lokale bar-ejere, der sammensatte deres egne "blends" og mærker. I 1932 gik en række af disse i kompagniskab, og etablerede Antigua Distillers. I dag er Antigua Distillers et familieforetagende på 4. generation og de seneste år er deres'' "English Harbour"- produkter blevet et etableret navn på eksportmarkeder rundt omkring i verden. English Harbour Reserve 10 Year Old Rum er en blanding af udvalgte, modnede rom. Den yngste af dem har lagret på gamle bourbonfade i mindst 10 år og har en vellagret roms aroma og kompleksitet. Rommen her er i den tørre ende – ikke uden lighed med whisky og bourbon. Den har smag af røget eg, citrusfrugter, brændt sukker og vanilje og kokosnød med strejf af kaffe, bagte æbler, kanel og tropiske blomster. 40% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Espero Caribbean Coconut', 'https://rombo.dk/products/espero-caribbean-coconut', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Espero_Caribbean_Coconut.png?v=1787059009', 'Espero Caribbean Coconut er eksotisk, cremet og uimodståelig. Denne likør er lavet på mørk, lagret rom fra Den Dominikanske Republik, der er blevet tilsat naturlige noter af saftig kokos. Resultatet er en perfekt balance og tropisk sødme. I duften møder du Espero Caribbean Coconut med varme aromaer af kokos, vanilje og let karamel, mens smagen er fyldig, rund og silkeblød med masser af moden kokos og sødme. Nyd den ren, over is, i eksotiske cocktails – eller som et luksuriøst twist i desserter. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Espero Caribbean Orange Liqueur', 'https://rombo.dk/products/espero-caribbean-orange-liqueur', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_cd95ff14-4729-4dcd-bd35-59a540442ab6.png?v=1769439519', 'Espero Caribbean Orange Liqueur er en delikat mørk orange-likør, der er baseret på sukkerrørsspiritus fra Den Dominikanske Republik. Espero tilsætter ubehandlet appelsinskal i sin sukkerrørsspiritus, og resultatet er en meget interessant likør, der i høj grad kan nydes rent, og den er også egnet som ingrediens til cocktails. Den valgte sukkerrørsspiritus er 7-12 år og lagret i et Solera-system (yngre og ældre blandet sammen). Espero Caribbean Orange Liqueur har en blid sødme og en vidunderlig note af appelsin i både duft og smag. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Fanø Skibsrom - Gavekasse med Havfruen & Havmanden', 'https://rombo.dk/products/fano-skibsrom-gavekasse-havfruen-havmanden', 549, true, NULL, 41.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_913fb863-9386-457e-b2cb-5a3a97b4c188.png?v=1769434684', 'Gavekasse med 35 cl Havfruen &amp; 35 cl Havmanden fra Fanø Skibsrom indeholder Havfruen, som er en sød og aromatisk sukkerrørsspiritus samt Havmanden, som er en mellemsød og aromatisk sukkerrørsspiritus. Begge varianter tapper ind i en 300 år gammel romtradition. Fanø Skibsrom er baseret på rom, der er blevet destilleret på Jamaica og har lagret på portvinsfade på Fanø. Dette sæt er en oplagt mulighed for at smage varianter af Fanø Skibsrom, inden du eventuelt køber de større flasker. Og så er det jo en perfekt lille gave til enhver lejlighed. Havfruen vandt bronzemedalje ved IWSC 2019, og Havmanden vandt sølvmedalje ved IWSC 2019. Begge rom er tappet ved 41,5 %. Æsken indholder to flasker á 35 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Fanø Skibsrom Havfruen', 'https://rombo.dk/products/fano-skibsrom-havfruen', 395, true, 70, 41.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e931f6a9-a77a-474c-8774-3be373f0141c.png?v=1769433945', 'Fanø Skibsrom Havfruen er en sød og aromatisk sukkerrørsspiritus, der tapper ind i en 300 år gammel romtradition. Gennem flere hundrede år var rom en vigtig del af søfolkenes daglige proviant, og for at få den til at glide nemmere blev datidens rom som regel blandet op med lokale krydderier, sukker og frugter, før den blev hældt på tønder og lagret ombord. Fanø Skibsrom Havfruen er en sukkerrørsspiritus, som er baseret på rom, der er blevet destilleret på Jamaica og derefter har lagret på portvinsfade på Fanø. Fanø Skibsrom Havfruen er blevet krydret med lynghonning og havtorn fra Fanø, samt vanilje fra Madagascar og muscovadosukker. 41,5 % - 70 cl. Fanø Skibsrom Havfruen vandt bronzemedalje ved IWSC 2019.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Fanø Skibsrom Havmanden', 'https://rombo.dk/products/fano-skibsrom-havmanden', 395, true, 70, 41.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_98413b2b-8dea-4b21-ad24-da3198c5aec9.png?v=1769433948', 'Fanø Skibsrom Havmanden er en mellemsød og aromatisk sukkerrørsspiritus, der tapper ind i en 300 år gammel romtradition. Gennem flere hundrede år var rom en vigtig del af søfolkenes daglige proviant, og for at få den til at glide nemmere ned blev rommen blandet op med lokale krydderier, sukker og frugter, før den blev hældt på tønder og lagret ombord. Fanø Skibsrom Havmanden sukkerrørsspiritus er baseret på rom, der er blevet destilleret på Jamaica. Først lagres denne med lynghonning og havtorn fra Fanø, samt vanilje fra Madagascar og muscovadosukker. Herefter får Havmanden sukkerrørsspiritus en efterlagring på portvinsfade. 41,5 % - 70 cl. Fanø Skibsrom Havmanden vandt sølvmedalje ved IWSC 2019.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Fanø Skibsrom Kaptajnen', 'https://rombo.dk/products/fano-skibsrom-kaptajnen', 695, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/FanoSkibsromKaptajnen.png?v=1789050523', 'Fanø Skibsrom Kaptajnen blev udgivet ifm. i anledning af, at Fanø Spirits grundlægger Lars J. Schous havde 80 års fødselsdag. "Kaptajnen" er krydret og lagret, lige som han ville ønske det. Fanø Skibsrom Kaptajnen er destilleret på Jamaica og efterfølgende forædlet på Fanø. Smagsnoterne er komplekse og fyldige med noter af træ, tobak og lidt sødme. Kommer i en trækasse. 43% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Fanø Skibsrom Søhesten', 'https://rombo.dk/products/fano-skibsrom-sohesten', 395, true, 70, 41.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_375e7312-818b-4463-a59e-ec70265394ef.png?v=1769436397', 'Fanø Skibsrom Søhesten er destilleret på Jamaica og efterfølgende forædlet på Fanø. Forædlingen består af en to-trins-lagring. Først lagres Fanø Skibsrom Søhesten med naturlige smagsgivere (bl.a. Fanø Lynghonning, havtorn og Madagaskar vanilje). Herefter efterlagres den på portvinsfade. Smagen er rund og balanceret med sødmefulde noter af vanilje, muscovado og pomerans. Den giver en smagsoplevelse, som sender dig fra Fanø til eksotiske himmelstrøg - og tilbage igen. Fanø Skibsrom Søhesten kan betegnes som en ekstra sød sukkerrørsspiritus. Fanø Skibsrom sukkerrørsspiritus udgaverne bygger videre på den mere end 300 år gamle skibsromtradition. Rom fra Caribien var i århundreder en vigtig del af søfolkenes proviant på de store sejlskibe, så de kunne stå imod de barske vilkår til søs. Fanø Skibsrom sukkerrørsspiritus er baseret på en sukkerrørsspiritus, der destilleres på Jamaica og efterfølgende krydres med naturlige, lokale råvarer og lagres på portvinsfade på Fanø. 41,5 % - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor de Caña 14 års rom', 'https://rombo.dk/products/flor-de-cana-14-rom', 425, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_fa917b74-13a1-454f-9384-796072c8bda6.png?v=1769438349', 'Flor de Caña 14 års rom er fra Nicaraguas mest kendte destilleri, Compañia Licorera de Nicaragua, der blev grundlagt som familievirksomhed i 1890. Flor de Caña 12 års og 18 års rom-udgaverne har igennem de senere år været de mest solgte i butikken, og nu er det tilmed lykkedes os at skaffe 14 års udgaven. Flor de Caña 14 års rommen er bæredygtig, Co2 neutral og Fair Trade certificeret. Fremstillingen af denne rom er foregået med hjælp fra vedvarende energi, og lagringen er foregået naturligt uden kunstige ingredienser. Mellemsød/naturlig. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor de Caña Centenario 12 års Rom', 'https://rombo.dk/products/flor-de-cana-12-rum', 349, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4844c055-42a8-4620-adc6-b4d4b1ae0489.png?v=1769421055', 'Flor de Cana Centenario Rum 12 år fra Nicaragua med den rødlige rav-farve er en rom, der kan drikkes rent, med is eller med et stænk af vand eller sodavand. Flor de Cana 12 års rom er vinder af 13 internationale priser og har en halvsød smag af nougat, mandel smør, melasse og sherry. Eftersmagen byder på pebret krydderi, mørk karamel og forkullede egetræsfade.40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor de Caña Centenario 18 års Rom', 'https://rombo.dk/products/flor-de-cana-18-rum-70-cl', 499, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_10ca1eed-2a20-4d23-b4a5-caf96d9d0d12.png?v=1769425833', 'Flor de Cana 18 Centenario Rum fra Nicaragua er en fyldig rom med rig kompleksitet og blødhed. Flor de Cana 18 Centenario følger den spanske rom-tradition i hver eneste dråbe. Smag: en rig indgang fører til en tyktflydende, tør, fyldig smag med mørk chokolade, karamel, ristede nødder, og brune krydderier. Eftersmagen er lang med noter af forkullet eg, vanille og ristede nødder. Som noget usædvanligt er denne rom ikke blandet af forskellige årgange, men slow aged på amerikanske egefade i 18 år. En rom, der er en ren fornøjelse. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor de Caña Gran Reserva 7 års Rom', 'https://rombo.dk/products/flor-de-cana-7-rum', 249, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/FlordeCanaGranReserva7arsRom.png?v=1789644425', 'Flor de Cana Gran Reserva 7 år vandt 2010 Gold Medal ved San Francisco World Spirits Competition. Smag: medium fyldig af mørk karamel og ristede nødder, der går over i en eftersmag af tør ristet kokos. Flor de Cana Gran Reserva 7 år er en smidig og fyldig rom, der kan drikkes on-the-rocks, med et stænk af cola eller vand. Den er også velegnet, hvis du skal lave en virkelig god Grand Mojito. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare Epilogue Exceptional Cask Selection Single Blended Rum', 'https://rombo.dk/products/foursquare-epilogue-exceptional-cask-selection-single-blended-rum', 1149, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/FoursquareEpilogueExceptionalCaskSelectionRum.png?v=1785842241', 'Foursquare Epilogue Exceptional Cask Selection Single Blended Rum (Mark XXXI) er fra Foursquare Rum Distillery på Barbados, hvor den ideologiske Richard Seale laver naturlig rom uden tilsætning af sukker. Rommen er den 31. og desværre sidste udgave i den klassiske Exceptional Cask Selection serie, hvor der bliver leget med forskellige fade og med højere alkoholprocent. Den unikke Foursquare Epilogue rom er et blend af pot still rom og kolonnedestilleret rom, der er tropisk lagret i intet mindre end 19 år i ex-bourbonfade. Faktisk kan vi ikke huske at have set en ældre Foursquare aftapning nogensinde. Rommen er uden tilsætning af sukker, uden farvejustering og uden kølefiltrering for at bevare den naturlige smag. Limited edition. 57% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare Penultimus Exceptional Cask Selection Single Blended Rum', 'https://rombo.dk/products/foursquare-penultimus-exceptional-cask-selection-single-blended-rum', 1095, false, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Foursquare_Penultimus_Exceptional_Cask_Selection_Single_Blended_Rum.png?v=1780486568', 'Foursquare Penultimus Exceptional Cask Selection Single Blended Rum (Mark XXX) er fra Foursquare Rum Distillery på Barbados, hvor den ideologiske Richard Seale laver autentisk rom uden tilsætning af sukker. Rommen er den 30. udgave i den klassiske Exceptional Cask Selection serie, hvor der bliver leget med forskellige fade og med højere alkoholprocent. Efter sigende er dette desværre den næstsidste udgivelse i Exceptional Cask Selection serien. Den unikke Foursquare Penultimus rom er et blend af pot still rom og kolonnedestilleret rom, der er tropisk lagret i 15 år. Først 10 år i ex-bourbonfade og herefter 5 år i Moscatel-vinfade. Rommen er uden tilsætning af sukker, uden farvejustering og uden kølefiltrering for at bevare den naturlige smag. Når man nyder denne Foursquare Penultimus rom, fornemmes mørk chokolade, moden ananas, krydret karamel og citron. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare Supernum Single Blended Rum', 'https://rombo.dk/products/foursquare-supernum-single-blended-rum', 2295, false, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/FoursquareSupernumSingleBlendedRum.png?v=1791209369', 'Foursquare Supernum Single Blended Rum er resultatet af et årelangt samarbejde mellem Richard Seale fra Foursquare Rum Distillery og Luca Gargano fra Velier. Sædvanen tro er der blevet leget med fadene, alderen og alkoholprocenten, og der er kun lavet 2.800 flasker til verdensmarkedet. Med sine 21 års tropiske lagring er Foursquare Supernum indtil videre den ældste rom, som Foursquare og Velier har udgivet sammen. Rommen er et blend af rom, der er lagret i klassiske bourbonfade og rom, der er dobbeltlagret i bourbonfade og Pineau des Charentes fade. Destilleringen er foregået i en kombination af kobber pot stills og Coffey column still, hvilket er signaturen på det meste rom fra Foursquare. Når man dufter til denne Foursquare Supernum Single Blended Rum, fornemmes modne og kandiserede frugter, blommer, abrikos, søde krydderier, vanilje og egetræ. Smagen byder på noter af tørret frugt, karamel, mørk chokolade, egetræskrydderier, blommer, kanel og valnødder. Limited edition. 55% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Gosling''s Black Seal Rom', 'https://rombo.dk/products/goslings-black-seal-80-proof-rum', 225, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Gosling_s_Black_Seal_Rom.png?v=1787045820', 'Gosling''s Black Seal Rum fra Bermuda har en rig, kompleks smag, der er velafbalanceret og nuanceret med flødekaramel, vanilje og egetræskrydderier. Overbevisende nok til at modtage The Beverage Testing Institute''s højeste ære - en Platinum Medal. I modsætning til de fleste andre rom-produkter er Gosling''s Rum destilleret fra såvel pot stills som kolonne stills. Førstnævnte bibringer smag og sidstnævnte giver diskret elegance. Goslings Black Seal Rum er i øvrigt den originale rom i den populære Dark and Stormy cocktail, der har gået sin sejrsgang over hele verden. Mix den med Goslings Ginger Beer og lime, og skab din egen Dark and Stormy cocktail. 40% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Gosling''s Family Reserve Old Rum', 'https://rombo.dk/products/goslings-family-reserve-old-rum', 699, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_06ec89b5-0a46-4995-a23c-86a0b5f77ff7.png?v=1769421160', 'Gosling''s Family Reserve Old Rum har fået en ekstra saftig, nuanceret kompleksitet og er blevet en rigtig "sipping" rom, der skal nydes en stille stund. Den har vanilje og tobak i næsen og smagen udvikler over tid noter af vanilje, tobak, eg og mørk chokolade. Gosling''s Family Reserve Old Rum er en rom, der produceres i begrænset mængde, og hver flaske er nummereret. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Great Dane 15 års rom', 'https://rombo.dk/products/great-dane-15-rom', 599, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f4ec8a70-34a9-4ae6-8305-793216fef1a3.png?v=1769438382', 'Great Dane 15 års rom er lavet på sukkerrørsmelasse og destilleret i henholdsvis Spanien og Venezuela, inden den er blevet lagret i 15 år på ex-bourbonfade. Den lange lagring har givet rommen både dybde og kompleksitet. Når man dufter til denne Great Dane 15 års rom fornemmes noter af flormelis, karamel, ananas og fersken. Smagen er langvarig, blød og tropisk mellemsød med noter af fersken, ananas og kokos. Rommen er ikke kølefiltreret og har ikke fået tilsat farve, så man får den rene og autentiske smagsoplevelse. Great Dane 15 års rommen er desuden Fairtrade-certificeret på baggrund af den bæredygtige og etiske produktion. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Great Dane Extra Sweet Spirit Drink', 'https://rombo.dk/products/great-dane-extra-sweet', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_44e758b3-73e2-4cbe-8f2e-dfc47911dab4.png?v=1769425553', 'Great Dane Extra Sweet Spirit Drink er en sukkerrørsspiritus, som er baseret på destillater fra Guatemala, Den Dominikanske Republik, Barbados Jamaica og Panama. Afslutningsvis har denne sukkerrørsspiritus lagret på gamle bourbon-og sherryfade. Great Dane Extra Sweet Spirit Drink har tydelig duft af brun farin, tørret appelsinskal og rosiner, og en sødmefuld smag af karamel, mørk chokolade og vanilje. Drik den ren som lækker hygge eller brug den i drinks. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Great Dane Rum', 'https://rombo.dk/products/great-dane-rum', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4cd88826-110a-46e4-80b1-8b4e4a164fdb.png?v=1769423472', 'Great Dane Rum er en sød rom fra (Anders) Skotlander, der har lavet et blend af rom fra udvalgte destillerier i Guatemala, Den Dominikanske Republik, Barbados, Jamaica og Panama. Great Dane Rum er først destilleret og lagret op til 8 år i tropisk klima på ex bourbon fade, og efter ankomsten til det kolde danske klima har rommen efterlagret i fade, der tidligere er brugt til den danske Skotlander Rum. Rommen er justeret med en smule muscovadosukker. 1.000 flasker pr. batch. 40% - 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Great Dane Rum Barbados 5 års rom', 'https://rombo.dk/products/great-dane-5-ars-rom-fra-danmark', 449, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_448efd65-4224-47ff-a5ab-4c3c246d7a5e.png?v=1769425549', 'Great Dane 5 års rom er skabt af sukkerrørsmelase fra Barbados og destilleret på Foursquare Rum Distillery. Herefter har rommen lagret i 5 år på gamle amerikanske bourbon egetræsfade - 3 år i tropisk klima og 2 år i Danmark under koldere temperaturer. Great Dane Barbados 5 år er en sød rom med 20 gram sukker pr. liter. I næsen er der friskbagt brød, honningkage, vanilje, tørret frugt og tørt egetræ. Rommen har en sødmefuld smag af tørret frugt, karamel, rosiner, flormelis, modne bananer og honning. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Guyana Port Mourant Shared Single Cask Rum', 'https://rombo.dk/products/guyana-port-mourant-shared-single-cask-rum', 799, true, NULL, 59, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rombo_Shared_Single_Cask_Guyana_2022_bd513310-a41e-413b-801e-ba366ea4f470.png?v=1773237968', 'Guyana Port Mourant Shared Single Cask Rum er en "enkeltfadsrom", der blev udvalgt sammen med en række skønne kunder, som deltog på Rombo''s tur til 1423 ApS i efteråret 2025 for at smage på rom og for at se det imponerende lager med de mere end 2.000 fade. Denne helt unikke Guyana rom blev destilleret i den legendariske Port Mourant Double Wooden Pot still hos Diamond Distillers Limited (DDL) i 2022. Herefter blev den transporteret til Danmark og lagt på et 130 liters Pedro Ximenez (PX) sherryfad indtil den endelige aftapning i december 2025. Rommen er lavet af sukkerrørsmelasse. Der blev tappet i alt 167 flasker Guyana Port Mourant Shared Single Cask Rum ved 59% fadstyrke, og Rombo købte de resterende 125 flasker efter kundernes andele. Disse sælges nu til andre.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hampden 15 Years Pure Single Jamaican Rum', 'https://rombo.dk/products/hampden-15-years', 3895, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a2ed27a7-0af1-4adb-b957-5ab522149c0f.png?v=1769439826', 'Hampden 15 Years Pure Single Jamaican Rum er den ældste rom-udgivelse fra Hampden Estate til dato. Det er en exceptionel udgivelse, der hylder Hampden''s rom-historie, destilleringsmetoder og lagringsteknik i det tropiske klima. "Englenes andel" er på hele 75%, hvilket har bidraget til den effektive modning og aromatiske kompleksitet, men til gengæld har der ikke været mange af de skønne dråber tilbage i rom-fadene. Hampden 15 års rommen er fremstillet i det såkaldte LROK (Light Rum Owen Kelly) mark med et ester-indhold på 200-400 g/hl. Lagringen er foregået i ex-bourbonfade. Når man dufter til denne Hampden 15 Years Pure Single Jamaican Rum fremkommer rige noter af peber, figen, mandler, valnødder og honning. Smagen byder på bl.a . mango, guava, petroleum, ingefær og kanel samt florale noter i eftersmagen. Limited Edition: 4.400 flasker. 50% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hampden Estate 1753 Pure Single Jamaican Rum', 'https://rombo.dk/products/hampden-estate-1753', 475, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_65eb21c0-acf7-4373-abcd-4e61dd96cc30.png?v=1769438494', 'Hampden Estate 1753 Pure Single Jamaican Rum er en nyere 2025 destilleri-udgivelse fra det velkendte Hampden Distillery i Trelawny, Jamaica. Hampden Estate har sin egen sukkerrørsplantage, og melassen gennemgår en lang og unik gæringsproces med vildgær, hvorefter der udelukkende destilleres på pot stills. Fremstillingen gør, at Hampden rom er kendt for sin "heavy pot still" Jamaica rom-profil med masser af aroma og estere (smagsgivere). Helt specifikt er ester-indholdet målt til 476,9 på denne flaske. Hampden Estate 1753 rommen er tropisk lagret i 3 år på ex-bourbonfade, hvilket ifølge Hampden svarer til 10 år i Europa pga. den høje varme og "angel''s share" på Jamaica. Der er ikke tilsat hverken sukker eller farve, så her får du en helt naturlig rom med masser af funk og intensitet. Dufter man til rommen, fornemmes florale og vegetabilske noter samt tropisk frugt. I smagen finder man bl.a. ananas, banan, krydderier og nødder. 46% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hampden Estate 8 års Rom', 'https://rombo.dk/products/hampden-estate-46-jamaican-rum', 599, true, NULL, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_93f6f952-20d9-4ae4-b598-5e77bcbeb93c.png?v=1769423676', 'Hampden Estate 8 år Pure Single Jamaican Rum 46% er Hampden''s egen destilleri-udgivelse, som er skabt i samarbejde med Velier. Igennem en årrække har man kun fundet rom fra Hampden i diverse rom-udgivelser fra uafhængige aftappere, der har købt fade hos destilleriet. Hampden Estate har sin egen sukkerrørsplantage, og melassen gennemgår en lang og unik gæringsproces med vildgær, hvorefter der udelukkende destilleres på pot stills. Fremstillingen gør, at Hampden rom er kendt for sin "heavy pot still" Jamaica rom-profil med masser af aroma og estere (smagsgivere). De 8 års lagring er alle foregået "tropisk" hos Hampden. Denne Hampden Estate 8 år Pure Single Jamaican Rum ved 46% ABV er et godt eksempel på, hvad man får fra Hampden, og selv om 46%-udgaven er mildere end 60%-udgaven, så er der stadig pænt smæk på smagen. I næsen finder man bl.a. noter af ristede nødder, syrlig frugt og banan, imens smagen byder på noter af bl.a. banan, ananas og nellike. Flaskestørrelse: 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hampden Estate Fresh', 'https://rombo.dk/products/hampden-estate-fresh', 315, true, NULL, 63, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/HampdenEstateFreshWhiteTrelawnyPureSingleRum.png?v=1791204630', 'Hampden Estate Fresh Trelawny Pure Single Rum er en hvid rom, der er særdeles egnet til forskellige cocktails. På etiketten finder man faktisk opskrifter på Barracuda, Piña Colada, Last Word og Daiquiri med anvendelse af denne Hampden Estate Fresh rom. Rommen er i modsætning til den legendariske Rum Fire 63% fra Hampden noget lavere i både sin alkoholprocent (42%) og i sin "funkiness". Det er dog stadig en tydelig Jamaica pot still rom. Når man dufter til Hampden Estate Fresh, fornemmes bl.a. melon, citrus, ananas og banan. Smagen byder på de samme noter, og der fremkommer desuden en smule finsk lakrids.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hampden Estate HLCF Classic Rum', 'https://rombo.dk/products/hampden-estate-hlcf-classic-coffret', 799, true, 70, 60, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/HampdenEstateHLCFClassicRum.png?v=1790940950', 'Hampden Estate HLCF Classic er rom fremstillet efter Hampden Estates 5 grundprincipper. Man bruger lokalt, naturligt kildevand, langtidsgæring med naturligt gær, destillerer udelukkende på pot still og lagrer rommen i tropisk klima. Sidst, men ikke mindst, tilsætter Hampden aldrig sukker eller farve i sin rom. Hampden Estate HLCF Classic har en gylden farve og funky duftnoter af grillede bananer, mentol, acetone og citrusskal. Der er fuld kraft på smagen, der også byder på noter af tropisk frugt og kandiseret citron. En potent rom med høj ester, der kan nydes alene eller i cocktails. 60% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hampden Great House Distillery Edition 2025', 'https://rombo.dk/products/hampden-great-house-2025', 1175, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d9221749-ad9a-4b3c-b6db-222dd6e82f1f.png?v=1769439628', 'Hampden Great House Distillery Edition 2025 er den syvende rom-udgivelse af den eksklusive Distillery Edition. Denne aftapning er en hyldest til destilleriets Great House, som blev bygget i 1779, og stadig står i sin oprindelige form. Huset blev bygget ved siden af destilleriet af Stirling-familien, og førstesalen blev brugt til romlager indtil det 20. århundrede. I dag er det omgivet af en fantastisk tropisk have og blevet til et besøgscenter, hvor man tager imod gæster og besøgende. Flaskens etiket afspejler designet af det store hus, hvor der er blevet produceret utrolige rom i over tre hundrede år. Denne nye 2025 version af Great House er en blanding af de mest repræsentative marks af den unikke stil af rom fra Hampden Estate. Den er produceret af melasse og dunder efter en opskrift, der varierer fra år til år, og giver mulighed for at se Hampden Estates rom i et andet lys. Ligesom de tidligere udgaver er denne aftapning meget speciel, da det er en rom, der normalt kun kan købes på destilleriet i Jamaica eller i meget sjældne udgaver uden for det jamaicanske marked. Hampden Great House Distillery Edition 2025 duften er dyb og rig. Der er aromaer af bl.a. fermenteret ananas, vanilje og kandiseret ingefær, Smagen er intens med karakteristisk Hampden-funk, moden banan, lakrids og hints af chili. Eftersmagen er elegant og kompleks med noter af bl.a. muskatnød, kanel, kamfer og egetræskrydderier. 57% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hampden Rum Fire White Overproof Rum 63%', 'https://rombo.dk/products/rum-fire-white-overproof-rum', 335, true, 70, 63, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_74d06098-7eab-4109-9522-c4433b9102eb.png?v=1769422702', 'Rum Fire White Overproof Rum er fremstillet hos Hampden Estate, der er kendt for sin esterfyldte rom. Det meste rom fra Hampden Estate er historisk set blevet videresolgt til uafhængige aftappere, men under deres eget navn laves Rum Fire White Overproof Rum, der er en velsmagende lys rom, som vil gøre sig godt i mange cocktails og long drinks og kan også nydes rent). I senere tid er Hampden også kommet med deres egne, lagrede aftapninger ved 46% og 60% samt nogle specialaftapninger, der oftest bliver udsolgt med det samme. Hampden Rum Fire White Overproof Rum er fyldig, intens og aromatisk med noter af bl.a. frisk citrus, brændte sukkerrør og et strejf af tjære. 63% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Havana Club 3 års Rom', 'https://rombo.dk/products/havana-club-3-rom', 169, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c4ad9fa7-d0b8-49f6-a2be-36d7648768d5.png?v=1769421130', 'Havana Club 3 år har lagret 3 år på fad og er en oplagt rom til blanding af cocktails. Det er vel nok den mest anvendte rom i verden til dette formål, og Havana Club 3 års rom gør sig da også virkelig godt i din Daiquiri eller hvad du ellers finder på. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Havana Club 7 års Rom', 'https://rombo.dk/products/havana-club-7-anejo-rom', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_aa386f77-af03-49d8-8229-065c3338cdcb.png?v=1769421065', 'Havana Club Anejo 7 år er en typisk Cuba-rom og Havanas rom-flagskib. Farve: guldagtig med en brunlig nuance. Næse: aromaer af melasse, sukkerrør og en diskret note af tobak. Smag: Blød med vanille, egetræ og en svag melassesødme med et strejsf af kastanje, vanilje og kakao. Diskret eftersmag af tobak og røg med en smule mørkt krydderi. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('HSE Rhum Blanc Agricole Rom', 'https://rombo.dk/products/saint-etienne-rhum-blanc-aoc', 225, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ab267f2e-a077-44bf-ad72-6386241b988a.png?v=1769436208', 'HSE Saint Etienne Rhum Agricole Blanc AOC er en rom fra den franske ø Martinique. De har lavet et sæt regler for deres rom i samme tradition, som man måske kender det for Cognac og Champagne. De kalder deres stil for Rhum Agricole. Rhum Agricole produceres ved at anvende sukkerrørsjuice, modsat til den mest anvendte metode, hvor man bruges sukker-biproduktet melasse til at producere rommen. Agricole rom er derfor også markant anderledes end den (søde) spanske stil. Rommen er mere tør, og kan på mange måder virke mere som whisky end som rom. HSE Saint Etienne Rhum Agricole Blanc AOC er den eneste rum i verden der bliver gradvist reduceret i alkohol, hvor det bliver fortyndet fra 70 % til 50 % over en periode på 2 år. Andre reducere typisk hele mængden af en gang lige efter destillationen og derefter sætter på flaske kort efter eller i de følgende måneder. Denne teknik giver rommen mulighed for hvile og udvikle sig lang mere end nogen anden hvide rom, da reduceringsprocessen sker naturligt ved fordampning. Det forhindre de delikate aromaer og mund fornemmelsen i at formindskes da man formindsker den egentlige mængde vand der bliver tilsat. Denne roms finesse, elegance og rene sukkerrørs smag er virkelig udenfor normen. Hvis du vil prøve hvad hvid rom burde smage af, så skal du prøve den! Duften er intens og fyldig med blomsteragtige og frugtagtige toner akkompagneret af et strejf af hvid peber. Disse noter fra næsen fortsætter ind i smagen, hvilket skaber en harmonisk oplevelse. Eftersmagen er langvarig med nuancer af moden sukkerør. 50% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('HSE Rhum Extra Vieux XO Rom', 'https://rombo.dk/products/saint-etienne-xo-rhum-agricole', 635, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_77eb82f2-6130-4e27-95da-2cc6151bbf9d.png?v=1769420622', 'I denne Saint Etienne (HSE) XO Rhum Agricole Extra Vieux Grande Reserve rom er der min. 10% agricole rhum fra vintage 1960. Næse: gummi, vanille, sødme, fyldig, agricole karakter, sorte bær. Smag: tobaksæske, sød lakrids, karakter af sorte bær, gummi i baggrunden - en rom, der er lige til at gå til. Eftersmag: lang, kompleks eftersmag af sød lakrids, fed og fyldig. Tør bitterhed runder af. Saint Etienne XO Rhum Agricole Extra Vieux Grande Reserve har fyldig karakter af fad og frugter. 43% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('HSE Rhum Trés Vieux VSOP Rom', 'https://rombo.dk/products/saint-etienne-vsop-rhum-agricole', 399, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_22ef7d4d-4dc4-46c4-8c46-cf3f5241134f.png?v=1769420619', 'Saint Etienne (HSE) Rhum Trés Vieux Reserve Speciale VSOP er en rigtig Matinique-rom med kombinerede elementer af bær, tobak og lakrids. I næsen er der engelsk vingummi, solbær, noter af tequila, lakrids, meget fyldig næse. Delikat. Saint Etienne Rhum Trés Vieux Reserve Speciale VSOP smag: Tobak, fylde, markant rom karakter, agricole rum og syrlige hindbær. Eftersmag: Lang, spændende og kompleks med hints af mokka, krydderier, frugt og lakrids. 45% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Infernal - Rum Paris To Berlin', 'https://rombo.dk/products/infernal-rum-paris-to-berlin', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5ea8f329-e9b8-45f2-bc66-cefe00cc15f0.png?v=1769436009', 'Med Rum Paris To Berlin, ønskede Infernal at lave en rom som både kan nydes til festen, men som også kan nydes i sin rene form. En rom for begyndere men også for den som elsker at nyde en god rom. En rom som er let at gå til, med en elegant fremtoning. De har udvalgt rom fra Venezuela og Den Dominikanske Republik, lagret i forskellige tønder som ex-bourbon, fransk og amerikansk eg, og med aldre på 5, 6 og 8 år og derudover forener melasse og sukkerrørssaft baseret rom på bedste vis. Denne rom byder på en forførende duft, der er frisk og levende med lette noter af appelsin. Når du tager et øjeblik at trække vejret dybt, vil du opdage nuancer af mynte, vanilje, og træ, som alle komplementeres af en subtil sødme, der lover en dybdegående smagsoplevelse. Ved første sip mødes ganen af mørk sukker og vanilje, der bliver fulgt op af den jordbundne karakter af træ. Dens tekstur er meget blød, og man kan fornemme en let varme fra alkoholen, der kildrer tungen med en skarp peberprikken. Dens afslutning er lang og behagelig, hvor en svag syrlighed bliver hængende og sørger for en afrundet og tilfredsstillende oplevelse. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Infernal Club Sunrise', 'https://rombo.dk/products/infernal-club-sunrise', 435, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/InfernalClubSunriseCoconutOrange.png?v=1781524297', 'Infernal Club Sunrise er en sød spirit drink / sukkerrørsspiritus fra musikgruppen Infernal med blandt andre Lina Rafn og Paw Lagermann. Her præsenterer Infernal med egne ord selv sin flaske: "Vi skaber musik. Vi skaber premium spiritus. Club Sunrise er det, der sker, når de to verdener mødes. Vi har altid ment, at de bedste aftener har et soundtrack og en drink, der er værd at huske. Club Sunrise er en stemning på flaske – en skål for, hvor end musikken tager dig hen.” Infernal Club Sunrise er kolonnedestilleret og op til 12 år gammel. Et tropisk blend infuseret med solmodne appelsiner og kokosnød. Varme krydderier, vanilje, egetræ og et strålende strejf af citrus – fuldendt af den fyldige smag af kokos. Alt sammen går op i en sød og lækker smagsoplevelse af caribisk nydelse i glasset. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Infernal Personal Selection IPS Barbados Rom (med autografer)', 'https://rombo.dk/products/infernal-personal-selection-ips-barbados', 999, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Infernal_Personal_Selection_IPS_Barbados_Rom_med_autografer.png?v=1770196580', 'Infernal Personal Selection IPS Barbados er en rom, som er pensonligt udvalgt og designet af Paw Lagermann og Lina Rafn fra musikgruppen, Infernal. Paw og Lina''s interesse for rom er igennem årene steget så meget, at de i 2018 begyndte at lave deres rom-serie, og faktisk blev de første mange udgaver eksklusivt solgt igennem Rombo. Denne Infernal Personal Selection IPS Barbados er en nøje kurateret rom, der opfylder Infernals personlige præferencer, som ikke længere er den søde rom, men nu i stedet er blevet den komplekse, udfordrende og ikke-søde rom. Barbados er en blanding af pot still destilleret og kolonnedestilleret rom fra Barbados. Rommen er tropisk lagret på Barbados i 8 år på ex-bourbonfade og herefter færdiglagret i yderligere 4 år i Danmark på amerikanske egetræsfade, der har indeholdt portvin. Duften byder på noter af melon, melasse, tør egetræ og røde druer. I smagen finder man søde, røde bær, krydderier og karamel, mens eftersmagen er tør og "vaniljet". 52% - 70 cl. BEMÆRK: Paw og Lina har skrevet deres personlige autografer på både gaveæske og flaske.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Infernal Personal Selection IPS Trinidad Rom', 'https://rombo.dk/products/infernal-personal-selection-ips-trinidad-rom-forudbestilling', 999, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/InfernalPersonalSelectionIPSTrinidadRom_9401caee-4fe1-403d-a678-22f8a81a8eeb.png?v=1787906271', 'Infernal Personal Selection IPS Trinidad er en rom, der er pensonligt udvalgt og designet af Paw Lagermann og Lina Rafn fra musikgruppen, Infernal. Paw og Lina''s interesse for rom er igennem årene steget så meget, at de i 2018 begyndte at lave deres rom-serie, og faktisk blev de første mange udgaver eksklusivt solgt igennem Rombo. Denne IPS 3 blev kolonnedestilleret hos Trinidad Distillers Limited (TDL) i 2016, og rommen er tropisk lagret på ex-bourbonfade, inden den blev sendt til Europa, hvor den fik yderligere fire års lagring på Virgin Oak- og spanske Moscatel-fade. Resultatet er en intens og elegant rom med stor dybde, krydrede nuancer og en frugtig sødme. Når man dufter til Infernal Personal Selection IPS Trinidad 52% rom, fornemmes Duften vanilje, brun farin, tørret frugt, rosiner, appelsinskal og krydret egetræ. Smagen byder på noter af fyldig karamel, honning, modne druer, abrikos, varme krydderier og let ristede noter fra Virgin Oak-fadene. Eftersmagen er lang og varm med tørret frugt, krydret egetræ og en vedvarende, vinøs sødme. 52% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Jamaica Shared Single Cask Rum', 'https://rombo.dk/products/jamaica-shared-single-cask-rum', 699, true, NULL, 63.4, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rombo_Shared_Single_Cask_Jamaica_2022_d1f92197-8436-4871-ba1e-37ece007e9b8.png?v=1773239007', 'Jamaica Shared Single Cask Rum er en "enkeltfadsrom", der blev udvalgt sammen med en række skønne kunder, som deltog på Rombo''s tur til 1423 ApS i efteråret 2025 for at smage på rom og for at se det imponerende lager med de mere end 2.000 fade. Denne helt unikke Jamaica rom blev destilleret hos Worthy Park i 2022 som marque WPH (Worthy Park Heavy), hvilket svarer til et "ester count" på 240-360 gr/hL AA. Efter transporten til Danmark blev rommen herefter lagt på et lille 40 liters fad lavet af dansk egetræ i 2022 indtil den endelige aftapning i december 2025. Rommen er pot still destilleret og lavet af sukkerrørsmelasse. Der blev kun tappet i alt 45 flasker Jamaica Shared Single Cask Rum ved 63,4% fadstyrke, og Rombo købte de resterende 33 flasker efter kundernes andele. Disse sælges nu til andre.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kaniche Artisanal Rum XO Double Wood', 'https://rombo.dk/products/kaniche-xo-rum-double-wood', 475, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_53f0780f-201b-441a-b6b4-a83ae992d202.png?v=1769421499', 'Kaniche XO Artisanal Rum Double Wood Kaniche XO Rum er først lagret i mange år i tropisk klima på brugte bourbon egetræsfade på Barbados. Herfefter er rommen skibet til Frankrig, hvor den har fået en afsluttende lagring på brugte små, cognac-fade. Det er denne Double Wood-lagring, der har givet rommen sit navn og sin bløde og samtidigt komplekse smag. Kaniche XO Artisanal Rum Double Wood Kaniche XO Rum har sukkerrør, egetræ, vanille, kokosnød og kakao i næsen. I smagen finder man også komplekse smagsnoter af cedertræ, vanille og karamel. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kirk and Sweeney Gran Reserva Superior Rom', 'https://rombo.dk/products/kirk-and-sweeney-gran-reserva-superior', 425, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7d711709-03da-48c0-b63a-179e44dcc44f.png?v=1769427421', 'Kirk and Sweeney Gran Reserva Superior er en rom-aftapning fra 3 Badge Beverage, som ligger i den gamle brandstation i byen Sonoma, Californien. Medlemmer af familien Sebastiani har tidligere sørget for at slukke brande fra selv samme brandstation og da den kom til salg i 2014, var det et oplagt valg som nyt tilholdsted for firmaet. Udover brandslukning havde familien også startet deres første vingård i 1904 og det var naturligt også at få et sortiment af luksus spiritus, bl.a. Kirk and Sweeney rom-serien fra den Dominikanske Republik. Rommen er opkaldt efter en skonnert, der efter sigende skulle have smuglet rom fra Caribien til USA under forbudstiden. Kirk and Sweeney Gran Reserva Superior Dominican Rum er en af efterfølgerne til Kirk and Sweeneys 12-års, 18-års og 23-års rom-serie. Kirk and Sweeney Gran Reserva Superior er en melassebaseret rom, der er blandet af nøje udvalgte 5-23 år gammel rom, som har lagret på californiske og franske egetræsfade. Rommen har aroma af tørrede frugter og ristet brød og smagsnoter af vanilje, karamel og honning, efterfulgt af mandler, tørrede figner, svesker og sherry. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kirk and Sweeney Reserva Rom', 'https://rombo.dk/products/kirk-and-sweeney-reserva', 315, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8d7c49f1-e092-4aec-97d8-7595601e3c17.png?v=1769439300', 'Kirk and Sweeney Reserva er en rom-aftapning fra 3 Badge Beverage, som ligger i den gamle brandstation i byen Sonoma, Californien. Medlemmer af familien Sebastiani har tidligere sørget for at slukke brande fra selv samme brandstation og da den kom til salg i 2014, var det et oplagt valg som nyt tilholdsted for firmaet. Udover brandslukning havde familien også startet deres første vingård i 1904 og det var naturligt også at få et sortiment af luksus spiritus, bl.a. Kirk and Sweeney rom-serien fra den Dominikanske Republik. Rommen er opkaldt efter en skonnert, der efter sigende skulle have smuglet rom fra Caribien til USA under forbudstiden. Kirk and Sweeney Reserva Dominican Rum er en af efterfølgerne til Kirk &amp; Sweeneys gamle 12-års, 18-års og 23-års rom-serie. Kirk and Sweeney Reserva er en melassebaseret rom, der er blandet af nøje udvalgte 2-12 år gammel rom, som har lagret på californiske og franske egetræsfade. Rommen har en aroma af sukkerrør, vanilje og toastede egetræskrydderier. Smagen byder på noter af nektar/honning, vanilje og egetræskrydderier, efterfulgt af en fyldig, sød, blød og langvarig eftersmag. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('La Hechicera Fine Aged Rum', 'https://rombo.dk/products/la-hechicera-rum', 399, true, NULL, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_058cc2f7-d198-45af-8a59-2aa7982b1b78.png?v=1769422074', 'La Hechicera Fine Aged Rum fra Colombia er solera-lagret rom fra fade af amerikansk hvid-eg. Rommen er sat sammen af rom, der er mellem Rommen har noter af toffee, appelsinskal, tobak og ristet kaffe. La Hechicera Fine Aged Rum er fremstillet uden nogen form for farve- og smagstilsætning. Vores egen prøvesmagning af La Hechicera Fine Aged Rum gav os en yderst positiv og velafbalanceret smagsoplevelse. Her har vi en colombiansk rom, der demonstrerer, at landet kan lave god rom udover Dictador. Det er iøvrigt en meget tiltalende flaske med flot indgravering og voksmærke.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Legendario 7 år Elixir de Cuba', 'https://rombo.dk/products/legendario-elixir-de-cuba-7', 235, false, 70, 34, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e1649f11-7260-4cbe-ae9a-f647a62bfa51.png?v=1769421153', 'Legendario Elixir de Cuba 7 år fra Cuba er en likøragtig drik med noter af sirup, rosin, vanilje, appelsin og karamel. Den er et stort hit i Spanien, men er også ved at slå igennem andre steder i verden. Kan drikkes med is som en aperitivo, med cola eller blandes i en dark and stormy. 34% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Longueteau Genesis Millésime 2017 Agricole Rom', 'https://rombo.dk/products/longueteau-genesis-millesime-2017', 699, true, 70, 72, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_862caf31-3e38-4507-9924-96a9c64a44db.png?v=1769422861', 'Longueteau Genesis Millésime 2017 Agricole er fremstillet af den røde sukkerrørs sort, og der er tale om en begrænset udgave med kun 5.000 flasker. Efter destilleringen i 2017 hvilede Longueteau Genesis Millésime 2015 Agricole i 24 måneder i rustfri ståltanke, hvor den blev modnet og "giftede sig" / fandt den rette balance. Longueteau Genesis Millésime 2017 Agricole er en ren lys rom med noter af røde bær (især friske hindbær). En karakteristik ved denne rom er selvfølgelig den høje procent på 72%, og da den ikke er blevet nedvandet, har rommen en meget aromatisk og kraftfuld (men absolut formidabel) smag.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Magnifica Bica do Alambique Cachaca', 'https://rombo.dk/products/magnifica-bica-do-alambique-cachaca', 199, true, 50, 48, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/MagnificaBicadoAlambiqueCachaca_591c9c55-26fb-48df-9837-80734480d2d6.png?v=1791636818', 'Magnifica de Faria Bica do Alambique er en brasiliansk cachaca, der er fremstillet i en triple pot still destilleringskedel. Bica do Alambique betyder "tappet fra pot still destilleringskedlen", og denne cachaca bliver netop tappet på flaske lige efter destilleringen for at opnå den optimale friskhed og aroma. Magnifica Bica do Alambique Cachaca er naturligvis en oplagt kandidat til en god caipirinha, men den smager faktisk også ganske forrygende rent. Brasilianernes nationaldrik. 48% - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Magnum Compañero Elixir Orange - 3 liter', 'https://rombo.dk/products/companero-elixir-orange-magnumflaske-3-liter', 1299, true, 30, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b907d0c7-a150-40f7-b869-a787d9a0ded4.png?v=1769425861', 'Compañero Elixir Orange er udgivet af danske 1423, og er en "spiced" likør/elixir baseret på Jamaica-spiritus med fyldig aroma. Compañero Elixir Orange har fyldig smag af både kokos og appelsin og er en rund og rar likør, der er velegnet til dessert eller almindelig sød nydelse. Den populære udgave kommer her i en 3-liters magnumflaske, så der er nok til at dele, når man skal fejre små og store ting ammen med sine ''companeros''. 40% - 3 liter.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Magnum Compañero Panama Extra Añejo - 3 liter', 'https://rombo.dk/products/companero-panana-extra-anejo-magnumflaske-3-liter', 1499, true, 30, 54, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_677a362e-2dbd-4074-a54f-435784e26695.png?v=1769425866', 'Compañero Panama Extra Añejo er den tredje udgave i Compañero serien fra 1423. Compañero er det spanske ord for kammerat, og det danner rammen om denne serie af produkter fra 1423, hvor smag, kompleksitet og finish er ultimative nøgleord. De to første produkter i serien, Gran Reserva og Elixir Orange , er begge fra Caribien, mens den tredje sukkerrørsspiritus så er fra Panama, der holder hele 54%. De 54% bliver dog gemt væk i chokoladenoterne, der giver varme til denne Panama sukkerrørsspiritus. Næse: Tung mørk chokolade, varm fløde og strejf af citrus. Smag: Næsten som mini muh chokolade og kakao-agtig. Compañero Panama Extra Añejo er fadpræget og med en lille bitte smule orange, men chokoladen overdøver det meste. Magnumflaske på 3 liter, så der er nok til at dele med dine companeros. 54% - 3 liter.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Magnum Diplomatico Reserva Exclusiva Rum - 3 liter', 'https://rombo.dk/products/diplomatico-reserva-exclusiva-magnum-rom', 1395, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6303361e-83ec-4abf-8704-3564d6c55f6d.png?v=1769423547', 'Diplomatico Reserva Exclusiva rommen er en absolut publikumsfavorit, som kan stærkt anbefales, hvis man mest er til den søde rom. Det er også et godt sted at starte sin rom-rejse. Næse: Abrikos, figner, krydderi, sødme, "Dumle slikkepind". Smag: Kompleks, sød og harmonisk, men stadig med en hale af krydderier. Lang, krydret og sød eftersmag. Kan du ikke få nok af denne populære Diplomatico Reserva Exclusiva rom, så findes den nu i denne 3 liters Magnum-udgave.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Magnum Hampden The Younger LROK 4 års Rom - 3 liter', 'https://rombo.dk/products/hampden-lrok-the-younger-2018-rom-3-liter', 3150, true, 30, 47, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2f2620c3-1529-4106-bb06-b2b618586152.png?v=1769434170', 'Hampden LROK The Younger 2018 Pure Single Jamaica Rum har fået en ekstra lang fermentering med naturligt gær, hvorefter den er blevet destilleret på en double retort kobber pot still i 2018. Rommen har siden lagret i tropisk klima på tidligere bourbonfade frem til aftapningen i 2022. Selvom rommen med sine 4 år er ’younger’, virker den på grund af sin tropiske lagring væsentligt ældre, og har en angel share på &gt;28%. Hampden Estate The Younger 2021 er en LROK, hvilket står for Light Rum Owen Kelly, som dækker over et højt esterindhold på mellem 200 og 400 gram pr. hektoliter ren alkohol. Med et esterindhold på 370,1 g/hlpa rammer Hampden Estate The Younger 2022 flot indenfor skiven. Rommen er en klassisk Jamaica-rom med en delikat duft af banan, mango, lak og peber, og smagsnoter af appelsinskal, ananas og nelliker. Den bør nydes ren eller med en dråbe vand. Naturlig farve. 47% - 3 liter.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Magnum Planteray XO 20th Anniversary Rom - 1,75 liter', 'https://rombo.dk/products/planteray-xo-20th-anniversary-magnum-175-cl', 999, true, 175, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_45a1b5ad-2f5d-4f77-883b-8ba25aec1904.png?v=1769427341', 'Planteray (tidligere kaldt "Plantation") XO Plantation XO 20th Anniversary er tropisk lagret rom fra Barbados, der har efterlagret på små cognacfade hos cognachuset Pierre Ferrand i Cognac, Frankrig. Cognacfadene har givet rommen blød frugt og et væld af smagsnoter, som var med til at sikre den gamle Plantation XO 20th Anniversary Barbados rom en guldmedalje i kategorien "Premium Aged Rum" ved Miami Rum Festival 2015. Rommen har duftnoter af vanille, tørrede frugter, kokos og bagte bananer, efterfulgt af toffee, mælkechokolade og orientalske krydderier. Den smager af vanilje, abrikos og rosin efterfulgt af kanel, Demerara rørsukker og kakao. Noter af eg, pibetobak og crème brulée afslutter oplevelsen. Planteray XO 20th Anniversary fra Barbados har en sød, lækker og indbydende smag. Denne udgave er en magnumflaske på 40% – 175 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Magnum Rammstein Rum - 4,5 liter', 'https://rombo.dk/products/rammstein-rum-magnum', 2175, true, 45, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_135000e2-01fe-453d-ab3c-7f18fe74d636.png?v=1769423709', 'Rammstein Rum er fra bandet Rammstein, der blev grundlagt i 1994 og idag er et af de mest berømte rockbands i hele verden. De er kendte for kæmpe shows med masser af pyroteknik og mørk stemning. I anledning af deres 25-årige jubilæum tog Rammstein på turné i 2019, bl.a til København, og udgav deres første Rammstein Rum, som er et rom-blend fra Jamaica, Guyana og Trinidad. Både Guyana og Jamaica rom er iblandt mange eksperter højt værdsat for deres stærke krop og dybe aromaer. Den stærke karakter af begge pot still rom er tæmmet af den blødere modstander fra Trinidad. Resultatet er en afbalanceret Rammstein Rum med krydrede noter og bløde frugtnoter. Rommen er modnet i op til 12 år i brugte bourbon fade, hvilket giver en antydning af røg. Er du ekstra stor fan af Rammstein, så kan du her få deres rom i en 4,5 liter magnum-flaske (billedet viser 70 cl udgaven). ABV: 40% - 4,5 liter.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Magnum Rum Nation Guatemala Gran Reserva 4,5 liter', 'https://rombo.dk/products/rum-nation-guatemala-magnum-flaske', 2275, true, NULL, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_595ecaf2-adde-45ee-a0ed-7aeff4b6df04.png?v=1769423783', 'Rum Nation Guatemala Gran Reserva Magnum er en melassebaseret rom, som er gæret og destilleret på destilleriet S.A. TULULA. Når rommen er færdigdestilleret på kolonne-destilationsapparater, transporteres den til den nord-østlige del af Guatemala, 185 meter over havets overflade. Her lagres rommen på hvide egetræsfade, som tidligere har indeholdt amerikansk bourbon. Denne fyldige rom hviler nu i 4 år i regionen ved Hondo-floden, som giver et fugtigt lagringsklima og dermed giver rommen mulighed for at få accelereret modningen, fordi Rio Hondo næsten er et tropisk klimaområde i Guatemala. Rum Nation Guatemala Gran Reserva har klassiske rom-noter fra den spanske romstil såsom ristede nødder, bihonning, mørk chokolade og overmoden banan. Her får du rommen i en 4,5 liter magnum flaske. 40% vol.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Mhoba Select Reserve French Cask Rom', 'https://rombo.dk/products/mhoba-select-reserve-french-cask-aged-rum', 875, true, 70, 65, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_064ebaac-5022-4dfc-8f41-eec1aaa5dd67.png?v=1769425032', 'Mhoba Select Reserve French Cask Aged Cask Strength Rum er fra Sydafrika, som vi normalt ikke ser så ofte på rom-verdenskortet. Rombo mødte selv Mhoba til UK Rum Fest i London for nogle år siden, og Mhoba-standen på rom-messen var så absolut den stand, som vi besøgte allermest, da det både var nogle meget søde mennesker og ikke mindst noget meget spændende rom, hvis man er til den naturlige og mere kraftfulde ikke-søde rom. Vi er glade for, at Mhoba nu også findes på det danske marked. Mhoba Select Reserve French Cask Aged Rum er en "Pure Sugarcane Rum", som er lavet på den friske sukkerrørsjuice fra sukkerrørene, der gror på Mhoba Sugar Estate ved den lille landsby Malalane i Sydafrika. Rommen er batch-destilleret i pot stills, som man selv har bygget. Mhoba Select Reserve French Cask Aged Rum er lagret i mere end 2 år på brændte, franske egetræsfade, der tidligere har indeholdt Cape Red wine. Rommen har duft af feber, vanilje og egetræ og god kompleksitet i smagen med noter af vanilje, egetræ og flot syrlighed. Kun 1.200 flasker, der er tappet ved fadstyrke. 65% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Mini Diplomatico Reserva Exclusiva Rum - 35 cl.', 'https://rombo.dk/products/diplomatico-reserva-exclusiva-halvflaske-rom', 195, true, 35, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d5cca416-4424-485c-b1e3-8c3eb39b0acf.png?v=1769423551', 'Diplomatico Reserva Exclusiva rommen er en absolut publikumsfavorit, som kan stærkt anbefales, hvis man mest er til den søde rom. Det er også et godt sted at starte sin rom-rejse. Næse: Abrikos, figner, krydderi, sødme, "Dumle slikkepind". Smag: Kompleks, sød og harmonisk, men stadig med en hale af krydderier. Diplomatico Reserva Exclusiva har en lang, krydret og sød eftersmag. Her får du rommen i en "nuttet", lille og gaveværdig 35 cl flaske.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Monsters of Rum Anansi - Jamaicansk rom', 'https://rombo.dk/products/monsters-of-rum-anansi-jamaica', 375, true, 70, 58, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_465e8508-1854-46db-b5dc-c0a23e582895.png?v=1769439294', 'Denne særlige Monsters of Rum Anansi er en jamaicansk rom på 58% med en smule sødme, så her får du både et intenst "kick" og en behagelig blødhed i smagen, der byder på noter af ananas, vanilje, chokolade og funk. Monsters of Rum er en serie af rom, der hylder de varme landes musik, fortællinger og kultur. Hver eneste flaske i serien er dedikeret til et monster eller et sagnvæsen fra de mystiske historier i Caribien og Sydamerika. En okkult verden af mystik og musik, og det afspejles i rommen, der ikke er for de sarte sjæle. Navnet bygger på den gamle myte om den trommespillende mand, der på Jamaica var kendt som den ækle edderkoppemand, Anansi. Han startede som en edderkop på en regnbue, men endte sine dage som en historiefortællende gavtyv på Jamaica. Monsters of Rum Anansi. Jamaicansk rom. 58% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Monsters of Rum Caimán - Colombiansk rom', 'https://rombo.dk/products/monsters-of-rum-caiman-colombia', 375, true, 70, 58, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7f48c138-6b1a-4489-aab8-c61fb8a59ee1.png?v=1769439286', 'Denne særlige Monsters of Rum Caimán er en colombiansk rom på 58% med en smule sødme, så her får du både et intenst "kick" og en behagelig blødhed i smagen, der byder på noter af vanilje, karamel, chokolade og frugt. Monsters of Rum er en serie af rom, der hylder de varme landes musik, fortællinger og kultur. Hver eneste flaske i serien er dedikeret til et monster eller et sagnvæsen fra de mystiske historier i Caribien og Sydamerika. En okkult verden af mystik og musik, og det afspejles i rommen, der ikke er for de sarte sjæle. Caimán navnet bygger på myten om "El Hombre Caimán", der i Colombia var kendt som den lurende unge mand, Saul, som spillede harmonika, belurede de badende kvinder og endte sine dage som halv mand, halv alligator. Monsters of Rum Caimán. Colombiansk rom. 58% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Mount Gay Black Barrel Rom', 'https://rombo.dk/products/mount-gay-black-barrel-rum', 325, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_26d443fb-14a3-4f30-aa65-2eea9584f6b5.png?v=1769422370', 'Mount Gay Black Barrel Rum er en blending af pot still og kolonnedestilleret rom, og i den afsluttende 2. lagring, foregår dette i meget forkullede ex-bourbonfade - deraf navnet Black Barrel. Mount Gay Black Barrel Rum har kraftige noter af krydderier samt noter af ristet egetræ, frugt, vanilje og karamel. En kompleks, men også velafrundet rom, hvor man få meget for pengene. 43% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Mount Gay Eclipse Rom', 'https://rombo.dk/products/mount-gay-eclipse-rum-70cl', 185, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5df5b1ac-94b7-492e-b5e8-89149a96c35f.png?v=1769420771', 'Mount Gay Eclipse rom er også på flere måder et enestående produkt. Rommen produceres af sukkerrør, der er dyrket på Mount Gay''s egen plantage og med vand fra den underjordiske kilde, som løber under plantagen. Efter 72 timers gæring af sukkerrør og vand i de fineste egetræsfade, dobbeltdestilleres Mount Gay rom – ligesom cognac – i kobber pot stills. Til sidst modnes Mount Gay i originale Kentucky Bourbon hvidegsfade, der giver Mount Gay sin karakteristiske gyldne farve og en let røget, rund smag. Mount Gay er meget kendt blandt sejlere, bl.a. fordi Mount Gay er sponsor for den mest prestigefyldte sejlsportskonkurrence i verden: Americas Cup. Mount Gay Eclipse rom har en smag, der i overensstemmelse med duften er blød, rig og velafbalanceret brændt egetræ, brændte mandler og frugt. Farve: Gylden rav. Duft: velafbalanceret aroma med anstrøg af vanilje, banan, karamel og sommefrugt og egetræ. Nydes ren, med is, med mineralvand eller som ingrediens i drinks. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Mount Gay Single Estate Series 2024 Rum', 'https://rombo.dk/products/mount-gay-single-estate-series-2024', 3750, true, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7b03394d-5fcc-4c85-8da9-e9a6eb98c866.png?v=1769438177', 'Mount Gay Single Estate Series 2024 Rum er den anden udgave i en ny årlig romserie fra Mount Gay. Til denne 2. udgivelse af Single Estate Series skabte Master Blender Trudiann Branker en blanding af rom lavet af sukkerrørshøsten fra 2018 og destilleret på 2 forskellige pot stills. Det er en utrolig kompleks blanding, der vækker kompleksiteten i St. Lucy, Barbados og Mount Gay Estate-terroiret til live. Mount Gay Single Estate Series rom blev skabt ved hjælp af 100% sukkerrørsmelasse, der er dyrket på Mount Gay Estate i St. Lucy, Barbados. Melassen har karakteristika af en meget høj sukkerindhold (72%). Herefter har den gennemgået, en meget lang gæringstid (9 dage mod vores standard 4 dage), hvilket førte til en sekundær gæring, som giver en karakteristisk smag og tilføjer noter specifikke for Barbados, som ananas eller guava, hvilket man normalt ikke oplever i Mount Gay rom. Rommen er 100% destilleret på pot stills, nærmere bestemt pot still #82 og #83. Herefter har rommen lagret i 5 år på ex-bourbon-fade. Mount Gay Single Estate Series 2024 rommen har en lys gylden farve med duftnoter af citrus, grapefrugt, søde blommer, banan, mandler, havsalt og mælkechokolade. Smagsoplevelsen har florale noter og byder desuden på en kombination af brunt sukker, egetræ, grapefrugt og salt. Der er produceret 5.418 flasker af denne rom, som alle er nummererede. 55% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Mount Gay XO Triple Cask Blend Rom', 'https://rombo.dk/products/mount-gay-xo-triple-cask-blend-rum', 435, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5cbc8b89-1d15-4d6d-a127-7bf29d09e121.png?v=1769423930', 'Mount Gay XO Triple Cask Blend består af et kompleks blend af specielt udvalgte romdestillater både fra kolonnedestillering og fra dobbelt pot still. Derefter er rommen lagret imellem 5 og 17 år på 3 forskellige fade: amerikanske whiskeyfade, bourbonfade og cognacfade. Mount Gay XO Triple Cask Blend har en flot balance og duft-indtryk af modne bananer, toast og varme krydderier. Smag: noter af saltet karamel, bagte figner, nellike og mørk chokolade. Eftersmagen er rund og blød. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Myers''s Rum Original Dark', 'https://rombo.dk/products/myerss-rum-original-dark', 159, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_dec33c28-33bd-4009-b343-811cc2bf7aca.png?v=1769421203', 'Myers''s Rum Original Dark er baseret på 100% jamaicansk melasse, og den bliver produceret ved anvendelse af såvel kolonne-destillering og pot-still destillering. Rommen er lagret i op til 4 år på white-oak fade og blandet af op til ni forskellige rom i forskellige aldre. Rommen har noter af sukkerrør, tobak, honning, læder, karamel og chokolade. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Navy Island Navy Strength Rom', 'https://rombo.dk/products/navy-island-navy-strength-rom', 449, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c213fe47-9b9f-4d7d-86b8-7de00846b388.png?v=1769436089', 'Navy Island Navy Strength Rom er en blanding lavet af 11 omhyggeligt udvalgte små batches af rom af forskellige aldre. Denne unikke 100% rene Pot Still rom er tappet ved Navy Strength for intens smag og maksimal nydelse. Navy Island er en lille tropisk ø ud for kysten af Port Antonio, Jamaica. I det 18. århundrede blev øen brugt af den britiske Royal Navy (deraf navnet). Ifølge en lokal legende skiftede Navy Island hænder i 1940''erne under et romdrevet pokerspil med en Hollywood-kendis. Den rige og levende historie om Navy Island inspirerede dette traditionelle jamaicanske rommærke og Navy Strength refererer for eksempel også til rom, der er tappet præcis ved 57% alkohol i volumen. Navy Island Navy Strength er en fantastisk rom, der repræsenterer det bedste, traditionelle håndværk har at tilbyde. Den har en dyb ravfarve og er en rom med høj ester og en meget markant karakter. Den er intenst aromatisk med en fantastisk balance af modne frugter, bananer og et strejf af vanilje. Dette er en rom, der er tung, har en fuld krop og en dejlig lang eftersmag, der er dyb og særdeles velafbalanceret. Navy Island Navy Strength er uden tvivl en meget tilfredsstillende rom. Navy Island Navy Strength vandt en sølvmedalje ved International Wine &amp; Spirit Competition (IWSC) 2019 i London. Den smukke flaske og den tiltalende etiket suppleres af en tilsvarende flot gaveæske. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Navy Island XO Reserve Rom', 'https://rombo.dk/products/navy-island-jamaica', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ed039ec8-2c49-440c-bbdc-7d421594ef1b.png?v=1769422729', 'Navy Island XO Reserve Rum har et gennemsnitligt Jamaica ester-niveau og er virkelig en god introduktions-rum til den meget aromatiske rom-stil på Jamaica, som ofte laves på pot stills og er langtids-gæret. Navy Island er en lille tropisk ø ud for Port Antonio i Jamaica, der i det 18. århundrede blev anvendt af den britiske flåde (deraf navnet). Ifølge lokale myter skiftede ejerskabet af Navy Island øen hænder i 1940''erne, hvor en Hollywoodstjerne med et glas rom i hånden vandt øen i et spil poker. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Nega Fulo Aguardente de Cana Cachaca', 'https://rombo.dk/products/nega-fulo-cachaca-aguardente-de-cana', 199, true, 70, 41.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_fb041e2a-b712-49ec-b241-f955955da51d.png?v=1769421545', 'Nega Fulo Aguardente de Cana er en cachaca med en lang tradition bag sig, da producenten Nega Fulo går helt tilbage til 1827. Cachaca er brasilianernes ynglingsdrik og landet har flere tusind forskellige cachaca-mærker. Faktisk producerer Brasilien årligt omkring en mia. liter cachaca, og dens popularitet overgås kun af øl. Nega Fulo Aguardente de Cana er destilleret, så smagen og duften af sukkerrør er bevaret, og byder desuden på smagsnoter af mandler og vanilje. Cachaca kan nydes ren eller som ingrediens i f.eks. en caipirinha cocktail. 41,5% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old Monk Gold Reserve 12 års Rom', 'https://rombo.dk/products/old-monk-rum-12-gold-reserve', 249, true, 70, 42.8, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d37fc380-ad19-4c07-8728-60b120785a68.png?v=1769421523', 'Old Monk 12 år Gold Reserve Rum har en en dyb, kobbergylden farve og duftnoter af melasse, tobak, brunt sukker og vanilje, efterfulgt af sort peber, kanel, nelliker og valnødder. I smagen finder man noter af melasse, tobak, chokolade og sort te, samt varme krdyderier som kanel, sort peber og nelliker. Eftersmagen er let tør med et strejf af nødder, tobak og lakrids. Old Monk 12 år Gold Reserve Rum kan drikkes ren eller blandes i en cocktail. 42,8% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old Monk Supreme XXX Rum', 'https://rombo.dk/products/old-monk-supreme-rum', 299, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5e4e3412-e0c2-49e0-86c0-3d64c5317946.png?v=1769422158', 'Old Monk Supreme XXX Rum er en rom fra Indien, der især gør sig bemærket med den særprægede flaske, der forestiller en munk. Old Monk Supreme XXX Rum har en del krydrede og sødmefulde noter som kanel, nellike og peber og har kraftig smag af melasse, flødekaramel, chokolade, kaffe og kakao. Old Monk Supreme XXX Rums konfektagtige smag og duft gør den god som mixer-rom i en Cuba Libre eller andre søde, rombaserede drinks.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old Monk Very Old Vatted 7 års Rom', 'https://rombo.dk/products/old-monk-rum-7-rom', 249, true, 70, 42.8, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_Monk_Very_Old_Vatted_7_rs_Rom.png?v=1787048118', 'Old Monk 7 års Very Old Vatted Rum er en mørk, indisk rom med bl.a. de karakteristiske noter af vanilje og karamel. Old Monk 7 års rom er sødmefuld og specielt velegnet til cocktails. 42,8% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix 1888 Copenhagen Medal', 'https://rombo.dk/products/old-st-croix-1888-copenhagen-sample', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_1888_Copenhagen_Medal.png?v=1787040888', 'Old St. Croix (tidligere "A.H. Riise") 1888 Copenhagen Medal er lavet på baggrund af den store Nordiske Industri-, Landbrugs &amp; Kunstudstilling, som København i 1888 var vært for. Albert Heinrich Riise deltog også i udstillingen med sin daværende rom på den Vestindiske pavillon, og efter sigende blev denne rom belønnet med en guldmedalje. Andre rygter/kilder siger, at det faktisk var en sølvmedalje, men ihvertfald er det denne hæder og begivenhed, som ligger bag det tidligere navn på denne flaske. Når man dufter til Old St. Croix 1888 Copenhagen, fornemmes noter af egetræ, læder og tørret abrikos. Smagen byder på noter af varme krydderier, julekage, appelsinskal og engelsk vingummi. I eftersmagen følger tørret frugt, egetræskrydderier og hint af sherry. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Black Barrel', 'https://rombo.dk/products/old-st-croix-black-barrel', 275, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Black_Barrel.png?v=1787044762', 'Old St. Croix (tidligere A.H. Riise) Black Barrel er tilsat en hemmelig krydderiblanding, der giver et strejf af blandt andet kanel og vanilje. Derudover skulle den være lagret i længere tid på egetræsfade, der er brændt indvendigt, så overfladen er forkullet. Processen skulle være med til at give den sorte farve, og deraf kommer navnet Old St. Croix Black Barrel (Det Sorte Fad). Prøv den som en Stormy St. Croix: 4 cl Black Barrel 8 cl ginger beer En smule frisk limesaft Garnér evt. med en tør skive lime 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Christmas XO Reserve', 'https://rombo.dk/products/old-st-croix-christmas-xo-reserve', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ea3a9e85-4f43-4928-9edc-7fb57b18c753.png?v=1769422898', 'Efter års omhyggelig lagring i udvalgte fade er denne blanding blevet sammensat med subtile noter af velkendte og traditionelle julesmage. Det er simpelthen en ekstra touch af den oprindelige julestemning. Old St. Croix (tidligere "A.H. Riise") Christmas Limited Edition er en blanding lavet af destillater fra nogle de allerbedste destillerier i Vestindien og Centralamerika. Udgangspunktet for Old St. Croix Christmas er XO Reserve udgaven, der har fået en yderligere fadlagring på gamle Pedro Ximinez sherry fade. Med denne blanding vil enhver sæson føles som juletid. Flasken præsenterer sig med en fortryllende kobberfarve, og ved første duft åbner en symfoni af tropiske aromaer sig. Noter af saftig ananas, moden mango og sødmefyldt honningmelon danser sammen med blød vaniljecreme, og kompleksiteten forstærkes af en undertone af mælkechokolade med sprøde strejf af appelsin og delikat kokos. Ved yderligere udforskning af næsen opstår en behagelig let krydret duft, der tilføjer dybde og dimension til oplevelsen. Ved smagningen afslører denne sukkerrørsspiritus sin fulde karakter, hvor melonsalaten fra næsen flamberer på tungen i en lækker symfoni af smag. Den søde frugt smelter sammen med en fornøjelig let urteagtig undertone, der tilføjer en velafbalanceret kompleksitet. Den lækre kombination af tropiske frugter og subtile krydrede elementer gør det til en sand fornøjelse for ganen. Efter en fortryllende duft- og smagsoplevelse afsluttes rejsen med en mild og gradvist fremtrædende krydret tone fra fadet. Denne langvarige finish tilføjer en fornemmelse af dybde og varme, hvilket skaber en mindeværdig og velafbalanceret spiritusoplevelse, der vækker sanserne og Old St. Croix Christmas kommer i en juleagtig gaveæske. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Danish Navy The Frigate Jylland', 'https://rombo.dk/products/old-st-croix-frigate-jylland', 449, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Danish_Navy_The_Frigate_Jylland.png?v=1770197844', 'Old St. Croix (tidligere "A.H. Riise") Danish Navy The Frigate Jylland opkaldt eftter Fregatten Jylland – verdens længste træskib, den danske flådes stolthed, tidligere kongeskib og et dansk nationalklenodie. Fregatten Jylland har tætte historiske bånd til de tidligere Dansk Vestindiske øer. I årene 1871-1887 var skibet på fem togter til Vestindien for at repræsentere danske interesser. Royal Danish Navy Fregatten Jylland er en eksklusiv udgave af Royal Danish Navy udgaven. Det er de gamle apoteksmetoder, der bruges den dag i dag til at skabe denne flaske, og den er udviklet fra planter, som Albert Heinrich Riise dengang indsamlede omkring de Dansk Vestindiske øer for at lave sin egen rom. Selv om Fregatten Jylland nu ligger permanent i Ebeltoft, bør man ikke gå glip af chancen for at smage flasken fra denne vigtige æra i den danske søfarts historie. For hver solgt flaske doneres et beløb til bevarelsen af Fregatten Jylland. Næse: en mørk og intens aroma af cigaræsker, karamel og chokolade med et ”grønnere” lag på toppen af ​​græs og mynte. Smag: begynder mildt, men intensiverer med ananas, honningmelon, banan og en dejlig rig smag af mælkechokolade og med et finish af orange crunch efterfulgt af en let krydret afslutning. 45% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Family Reserve 1838', 'https://rombo.dk/products/old-st-croix-family-reserve-1838', 459, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Family_Reserve_1838.png?v=1787047354', 'Old St. Croix (tidligere "A.H. Riise") Family Reserve 1838 er en ældre variant af den populære XO Reserve Superior Cask version. Old St. Croix Family Reserve 1838 sukkerrørsspiritus er håndblandet af destillater fra De vestindiske Øer i Caribien, der er op til 20 år gamle. Den har en flot gylden farve og solbær, appelsin, frugter, frisk, kokos i næsen. Smag: sød, cremet, banan, likør, appelsin, krydderier, vanilje, mango papaya. Old St. Croix Family Reserve 1838 har en lang eftersmag til den søde tand. 42% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Frogman Conventus Ranae 60%', 'https://rombo.dk/products/old-st-croix-frogman-60-conventus-ranae', 499, true, 70, 60, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Frogman_Conventus_Ranae_60.png?v=1787051882', 'Old St. Croix (tidligere "A.H. Riise") Frogman Conventus Ranae er en hyldest til det danske Frømands Korps. "The Frogman Association Conventus Ranae" blev oprettet i 1957, hvor man var blevet inspireret af den britiske specialbådtjeneste (SBS), Amerikas undervandsnedrivningshold (UDT og Navy Seals) samt de norske marinejægere. Maritime operationer har altid været en af Frømands Korpsets centrale opgaver. Efter afsluttet tjeneste kan Frømændene melde sig ind i ”Conventus Ranae” ("en samling af frøer" på latin), der er frømændenes forening, som har til formål at styrke båndet mellem aktive og pensionerede Frømænd. Old St. Croix Royal Danish Navy Frogman Conventus Ranae er håndblendet, modnet i egetræsfade og tappet ved 60% ABV. I de senere år har Old St. Croix samarbejdet med Conventus Ranae, hvilket blandt andet førte til lanceringen af Old St. Croix Royal Danish Navy Frogman 58%. I 2017 kom desuden Royal Danish Navy Frogman 60% ifm. Frømands korpsets 60-års jubilæum. Nu er der så kommet denne Old St. Croix Frogman Conventus Ranae 60% udgave som erstatning for de andre to, og smagen ligger meget tæt op ad jubilæumsudgaven. Old St. Croix Frogman Conventus Ranae 60% har en duft af balsamisk glasur, mokka, brændte mandler og appelsin. I smagen finder man de samme noter samt bl.a. også ananas, kokos og chokolade. 60% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Julekalender 2026', 'https://rombo.dk/products/old-st-croix-julekalender-2026', 599, true, NULL, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/OldStCroixJulekalender2026.png?v=1790087683', 'Old St. Croix (tidligere AH Riise) Julekalender 2026 er en mulighed for at forkæle dig selv, eller en du holder af med en personlig smagsoplevelse. Med 24 varianter fra Old St. Croix'' tidligere sortiment, nuværende sortiment og kommende produkter er denne julekalender den perfekte introduktion til Old St. Croix'' søde univers. Denne kalender indeholder smagsprøver på nogle af de mest udsøgte og velsmagende Old St. Croix udgaver, du måske endnu ikke har smagt. Den gemmer også på nogle af de historier, møder og begivenheder, der har bragt de velsmagende dråber til live. I 1838 rejste en ung apoteker ved navn ALBERT HEINRICH RIISE til Vestindien. Her producerede han rom (under navnet "Old St. Croix) og medicin og bidrog til opdagelsen af flere nye plante- og dyrearter. Men først og fremmest grundlagde han en stor familie og mange venskaber, der fører helt frem til i dag. De 24 OPLEVELSER i denne 24 Treasures-boksen repræsenterer en historisk rejse i Old St. Croix smagsunivers, fra prisvindende blends baseret på deres vestindiske arv og flådetraditioner til moderne fortolkninger baseret på ny samarbejder. Bag hver låge gemmer sig et eksklusivt 2 cl blend. Skål og velkommen til en rejse gennem de Vestindiske øers rige historie med Old St. Croix Julekalender 2026. 24 x 2 cl. = i alt 48 cl. spirit drinks med 40% - 60% alkohol.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Non Plus Ultra Ambre d''Or Excellence', 'https://rombo.dk/products/old-st-croix-non-plus-ultra-ambre-d-or-excellence', 799, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/OldSt.CroixNonPlusUltraAmbred_OrExcellence.png?v=1770215423', 'Old St. Croix (tidligere "A.H. Riise") Non Plus Ultra Ambre d''Or Excellence er en "Ultra Premium" flaske indenfor Old St. Croix sortimentet. Begrebet "Non Plus Ultra" stammer fra Herkules'' søjler, der ifølge den romerske mytologi blev bygget nær Gibraltarstrædet og markerede grænsen af den kendte verden. Søjlerne bar skriften "Non Plus Ultra" (Lat. Nothing Further Beyond) som en advarsel til søfarende om ikke at fortsætte sejladsen ud i det ukendte. Denne Old St. Croix udgave lever op til sit navn "Non Plus Ultra", som frit oversat betyder "Den Bedste" eller "Intet efter dette". Old St. Croix Non Plus Ultra Ambre d''Or Excellence er en speciel version af Non Plus Ultra Very Rare, da den har været yderligere 6 måneder på bl.a. Sauternes fade. Meget fyldig og frugtagtige noter af honning, abrikos og fersken og en fløjlsagtig blød og delikat sød eftersmag samt en finish med noter af vanille og rosiner. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Non Plus Ultra Black Edition', 'https://rombo.dk/products/old-st-croix-non-plus-ultra-black-edition', 825, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Non_Plus_Ultra_Black_Edition.png?v=1787057155', 'Old St. Croix (tidligere "A.H. Riise") Non Plus Ultra Black Edition refererer til refererer til inskriptionen på Herkules'' søjler, der ifølge den romerske mytologi blev bygget nær Gibraltar-strædet og markerede grænsen til den ukendte verden. Søjlerne bar skriften "Non Plus Ultra" (latin for ''hertil og ikke længere'') som en advarsel til søfarende om ikke at fortsætte sejladsen ud i det ukendte. Old St. Croix Non Plus Ultra Black Edition er baseret på den første "Very Rare" udgave, men NPU Black Edition er et blend af andre fade (efter sigende mere end 50 forskellige). Old St. Croix Non Plus Ultra Black Edition er meget mørk / sort i farven, og den har en duft af bl.a. melasse, egetræ, tobak, lakrids og krydderier. Smagen byder på noter af bl.a. cedertræ, vanilje, karamel og melasse. 42% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Non Plus Ultra La Galante', 'https://rombo.dk/products/ah-riise-non-plus-ultra-la-galante', 899, true, 70, 43.4, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/A.H.RiiseNonPlusUltraLaGalante.png?v=1770216492', 'Old St. Croix (tidligere "A.H. Riise") Non Plus Ultra La Galante er en limited edition i Old St. Croix eksklusive Non Plus Ultra-serie. Old St. Croix Non Plus Ultra La Galante er som resten af serien en spiritus baseret på nøje udvalgte vestindiske og centralamerikanske fade. Hvert fad i blended er valgt, fordi det på bedste vis indfanger essensen af Vestindiens flora. Old St. Croix Non Plus Ultra La Galante har duftnoter af appelsin, karamel, creme brulee, vanilje, mahogni, laurbær og egefad. Smagen er sødmefuld, fyldig og kompleks, krydret og velafrundet med strejf af vanilje, appelsin og citron. Rig, cremet og lang eftersmag. Old St. Croix Non Plus Ultra La Galante kommer i en flot, facetsleben karaffel i gaveæske, og ligesom med de forrige udgivelser i Non Plus Ultra-serien er der tale om et samlerobjekt i begrænset antal. 43,4% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Non Plus Ultra Very Rare', 'https://rombo.dk/products/ah-riise-non-plus-ultra-very-rare', 725, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Non_Plus_Ultra_Very_Rare.png?v=1787051065', 'Old St. Croix (tidligere "A.H. Riise") Non Plus Ultra Very Rare refererer både til legenden, hvor inskriptionen var en advarsel til søfarende om ikke at fortsætte sejladsen ud i det ukendte og til det, udtrykket senere kom til at dække over: det fuldendte, det, der simpelthen ikke kan blive bedre. Denne Old St. Croix lever op til sit navn "Non Plus Ultra", som frit oversat betyder "Den Bedste" eller "Intet efter dette". Old St. Croix (tidligere "A.H. Riise") Non Plus Ultra Very Rare har en mørk mahogniagtig farve med en krydret bouquet og noter af melasse, egetræ, tobak og appelsin. I smagen er Old St. Croix Non Plus Ultra Very Rare fyldig, lang og frugtagtig med toner af cedertræ, vanilje, karamel, sherry og appelsin. 42% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Royal Danish Navy Naval Cadet', 'https://rombo.dk/products/old-st-croix-royal-danish-navy-naval-cadet', 399, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Royal_Danish_Navy_Naval_Cadet.png?v=1787056642', 'Old St. Croix (tidligere A.H. Riise) Royal Danish Navy Naval Cadet er historien om kadetdolken. I 1848 blev en ensartet dolk obligatorisk for Søe Cadet Compagniet, der blev grundlagt i 1701 og idag er kendt som Søværnets officerskole. Kadetdolken har været stort set uændret siden, og den bæres i en sort kappe hængt over højre skulder. Når en flådekadet udnævnes til officer, udskiftes kadetdolken med en sabel. Old St. Croix Royal Danish Navy Naval Cadet har en duft af bl.a. lakridsrod, appelsinskal, kokosnød, mynte og frugtkælder. I smagen finder man noter af bl.a. eukalyptus, mynte, citrus, lakrids og balsamico. Lukker man øjnene under indtagelsen af Old St. Croix Royal Danish Navy Naval Cadet, er det lige før, at de tonstunge bronzekanoner både kan smages og duftes. 42% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Royal Danish Navy Strength', 'https://rombo.dk/products/old-st-croix-navy-strength-55', 435, true, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Royal_Danish_Navy_Strength.png?v=1787059826', 'Til Old St. Croix (tidligere "A.H. Riise") 55% Royal Danish Navy Strength er der brugt Wedderburn og Plummer-destillater - eller kort og godt W&amp;P - som er frembragt ved langsom gæring. Den bliver efterfølgende kedeldestilleret i den traditionelle "Pot Still" til en spiritus med 85% alkoholstyrke. Resultatet er en spiritus på 55% med en ekstrem mørk - ja, næsten sort farve - med toner af kaffe, anis, lakrids, brændt karamel, melasse, krydderier og cedertræ. Old St. Croix Royal Danish Navy Strength har en smag af pomerans og bergamot frugter afsluttende med en lang og sødmefuld eftersmag. 55% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Royal Danish Navy The Original', 'https://rombo.dk/products/old-st-croix-royal-danish-navy', 375, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_Royal_Danish_Navy_The_Original.png?v=1787040348', 'Denne Old St. Croix (tidligere "A.H. Riise") Royal Danish Navy The Original er en relancering af en gammel Dansk Flåde spiritus, som havde sit udspring i blending i Flensborg. I stil adskiller den sig fra den berømte og historiske engelske navy spiritus ved at være lettere at gå til og drikke. Der er ikke den samme tørre stil, og der er flere søde frugtnoter. Old St. Croix Royal Danish Navy The Original har aroma af appelsin, krydderi, lakrids, banan og gummi. Smag: olieret, kandiserede æbler, kokos, sødme og krydderi i harmoni. Slutter med abrikos. Eftersmag: sød og krydret. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix The Thin Blue Line', 'https://rombo.dk/products/old-st-croix-thin-blue-line', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_68852c3b-498c-45c3-a65b-02ce6e6bf60c.png?v=1769422894', 'Old St. Croix (tidl. A.H. Riise) The Thin Blue Line Denmark er en sukkerrørsspiritus, der er udgivet til støtte for dansk politi. The Thin Blue Line er en frivillig non-profit forening, som er stiftet af menige ansatte hos politiet på baggrund af 2 alvorlige skudepisoder i 2016 (den ene med dødelig udgang). Foreningens formål er at støtte ansatte (eller deres pårørende og efterladte) ved politiet, som er kommet alvorligt fysisk eller psykisk til skade ved udøvelsen af deres hverv. Ved købet af Old St. Croix The Thin Blue Line Denmark støtter man denne forening, der også samarbejder med foreningen "Politiveteranerne". 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Anniversary 175 års Jubilæumsudgave', 'https://rombo.dk/products/old-st-croix-anniversary-175-jubilaeum', 425, false, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_XO_Anniversary_175_rs_Jubil_umsudgave.png?v=1787046021', 'Old St. Croix (tidligere "A.H. Riise") XO Anniversary 175 års jubilæums-udgivelsen er en "limited edition", der er blandet fra nogle af Old St. Croix'' ældste og fineste reserver. 2 af disse, som indgår i Old St. Croix XO Anniversary-blandingen, er blevet modnet på gamle PX og Oloroso sherryfade, hvilket tilføjer denne flaske en større kompleksitet med noter af karamel, vanille og skovbær. En hyggespiritus i den søde ende. Kan indeholde spor af: valnødder. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Haakon Royal Reserve', 'https://rombo.dk/products/old-st-croix-haakon', 425, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_XO_Haakon_Royal_Reserve.png?v=1787048876', 'Old St. Croix (tidligere "A.H. Riise") Haakon XO Royal Reserve er lanceret for at fejre venskabet mellem Kong Haakon VII af Norge og Valdemar Riise, der var indehaver af A.H. Riise Rum og apotek, som blev grundlagt af hans far Albert Heinrich Riise i 1838 på øen St. Thomas i Dansk Vestindien (det nuværende United States Virgin Islands). Kong Haakon VII var oprindelig Prins Carl af Danmark, før han blev kronet som konge af Norge i 1905. Forældrene var Kong Frederik VIII og Dronning Louise af Danmark. Old St. Croix Haakon XO Royal Reserve skulle være baseret på den oprindelige gamle rom-opskrift, der var kong Haakon''s favorit. Når man dufter til Old St. Croix XO Haakon Royal Reserve, fornemmes bl.a. vanilje, kokos, karamel og æblekage. Smagen byder på noter af bl.a. vanilje, karamel og appelsinskal. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve Ambre d''Or', 'https://rombo.dk/products/old-st-croix-xo-reserve-ambre-dor', 385, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ab3c1dfb-9937-4018-8cae-fb41a244d039.png?v=1769423724', 'Old St. Croix (tidligere "A.H. Riise") XO Reserve Ambre d''Or er en "spirit drink", der er baseret på destillater fra det caribiske og mellemamerikanske område, og man har taget udgangspunkt i A.H. Riise XO Reserve. Til forskel fra denne har man ved XO Reserve Ambre d''Or benyttet sig af lagring i egetræsfade, der ttidligere har været anvendt til søde vine. Old St. Croix XO Reserve Ambre d''Or har en duft af bl.a. hø, vanilje, blomster, karamel og creme brulée. Smagen byder på noter af bl.a. lemon, vanilje og sød sauternes vin. 42% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve Legacy', 'https://rombo.dk/products/old-st-croix-legacy', 399, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Old_St._Croix_XO_Reserve_Legacy.png?v=1787056981', 'Denne Old St. Croix Legacy er den første lancering efter nyheden om, at A.H. Riise fremover skifter navn til Old St. Croix. Old St. Croix er en genoplivning af det varemærke, som apotekeren Albert Heinrich Riise selv navngav sine flasker for 150 år siden, da han solgte dem på St. Thomas i Vestindien som en hyldest til den sukkerrørsfremstillende nabo-ø, St. Croix. Old St. Croix Legacy er som sagt den første udgave af det genfødte varemærke, og flasken er lavet som en Limited Edition til de mere end 30 lande, der i dag sælger A.H. Riise og altså fremover Old St. Croix. Old St. Croix'' Master Blender har omhyggeligt udvalgt fade fra anerkendte destillerier i Vestindien og Centralamerika for at sammensætte Old St. Croix Legacy. Når man dufter, fornemmes noter af toffee og solmodne frugter, mens smagen byder på egetræs-umami, fyldig tobak, læder, karamelliserede figner og citrus. Eftersmagen er lang med en oplevelse af tørrede frugter. 42% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve Port Cask', 'https://rombo.dk/products/old-st-croix-xo-port-cask', 435, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_56532c5d-d576-44a3-882b-132915cfd0da.png?v=1769422039', 'Old St. Croix (tidligere "A.H. Riise") XO Reserve Port Cask har en mørk mahogniagtig farve med rubinrøde refleksioner. Den har en fyldig, let krydret vaniljesmag og en frugtagtig afslutning med toner af skovbær og portvin. Alle Old St. Croix XO Reserve Port Cask flasker er mærket med et individuelt flaskenummer og batch-nummer. 45% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve Superior Cask', 'https://rombo.dk/products/old-st-croix-superior-cask', 359, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4e22126d-2d6c-4dc3-8ecb-ced76065cd45.png?v=1769420578', 'Old St. Croix (tidligere "A.H. Riise") XO Reserve Superior Cask er skabt som en hyldest til én af de mest markante og entreprenante danskere, Apoteker og Etatsråd Albert Heinrich Riise, som var bosat og virkede på de tidligere Dansk Vestindiske Øer i perioden 1838 til 1878. Albert Heinrich Riise blev den første apoteker på Skt. Thomas. Han fik ved Kongelig resolution i 1838 det privilegium til at drive apotek i hovedstaden Charlotte Amalie i Dansk Vestindien, hvor han også fremstillede og solgte sin egen rom. A. H. Riise døde d. 18. oktober 1882 og er stedt til hvile på Frederiksberg Assistens Kirkegård. A.H. Riise var Ridder af Dannebrog samt bærer af den Svenske Vasa orden. Old St. Croix (tidligere "A.H. Riise") XO Reserve Superior Cask er fra Caribien, og den er håndblended af flere forskellige destillater. Først duftes en kølig mynte på toppen af ​​karamel og læder og derefter et strejf af citrus. Smagen er fyldig eukalyptus, blommefyldt tarte tatin og et strejf af hvid te med bergamot. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve Tribute', 'https://rombo.dk/products/old-st-croix-xo-reserve-tribute', 639, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/OldStCroixTributeXOReserve.png?v=1786968286', 'Old St. Croix XO Reserve Tribute er en hyldest til Albert Heinrich Riise, der var den første apoteker på Sankt Thomas i 1838. Udover at være apoteker fremstillede A. H. Riise også rom, der bl.a. blev solgt på apoteket, da det i tidernes morgen også havde medicinske formål. Dette Old St. Croix XO Reserve Tribute blend er inspireret af den samme nysgerrighed og konstante søgen efter kvalitet, der kendetegnede A. H. Riise''s liv fra opbygningen af et apotek, klarlægning af øernes flora og fauna, og ikke mindst skabelsen af blends, der i dag bærer hans navn under det historiske varemærke: Old St. Croix. Tribute udgaven er fremstillet af melassebaseret spiritus, der er nøje udvalgt fra anerkendte destillerier i Vestindien og Centralamerika. Den langsomme fermentering, den tradionelle destillering og lagringen af de yngre komponenter på egetræsfade giver Tribute en fyldig og elegant karakter. Når man dufter til Old St. Croix XO Reserve Tribute, fornemmes noter af c hokolade, bergamot og et lille strejf af tobak. Smagen er blød og frugtig med noter af pebermynte og bergamot, og i eftersmagen fremkommer også mælkechokolade og et hint af tobak.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Oliver''s Exquisito Soleras 1990 Rom', 'https://rombo.dk/products/olivers-exquisito-soleras-1990-rom', 499, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_bea8f7ca-41e3-4124-aca0-b7e379fd8866.png?v=1769421975', 'Oliver''s Exquisito Soleras 1990 Ron de Santo Domingo er en flot repræsentant for den spanske/cubanske romstil. Her får man en melasse- baseret og kolonnedestilleret rom fra Den Dominikanske Republik, der er lagret og blendet af Oliver &amp; Oliver. Basen for denne rom er et destillat fra 1990, der er blendet med en moderrom, som har en gennemsnitsalder på 15-25 år. Denne blanding er herefter lagret efter solera-metoden. Olivers Exquisito 1990 indleder med en let duft af tobak, der bliver efterfulgt af sød vanille og masser citrusfrugt. En meget velafbalanceret smag af karamelliseret æble, ristede nødder, egetræ samt fine hints af mokka. Oliver''s Exquisito Soleras 1990 Ron de Santo Domingo vandt dobbelt guld i kategorien Super Premium (over 21 års lagring) på Rum kongressen i Madrid 2013. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 25 år Solera Rom Malt Whisky Finish', 'https://rombo.dk/products/opthimus-malt-whisky-finish-rum', 749, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c30728b8-56a6-4c5c-bfc2-8f5dd142b429.png?v=1769420856', 'Opthimus Barricas de Malt Whisky Finish Solera Rum 25 år er en rom, der med sin malt whisky finish er et oplagt sted at starte, hvis du er til whisky, men vil gerne vil gå på opdagelse i det stadig mere populære rom-segment. Opthimus-rommen har lagret i mindst 25 år i ex-bourbon tønder og er derefter modnet på en brugt single malt tønde. Næse: Honning, kandis, sirup, moden frugt og en snert af malt whisky. Smag: Markant sødme, nougat smelter ned i tungen, meget fed og fyldig rom. Krydderi fra malt whiskyen Tomatin. Eftersmag: Lang, fyldig eftersmag. Luftige krydderier og en sød hale. 43% 70cl .');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 25 år Solera Rom Oporto Finish', 'https://rombo.dk/products/opthimus-oporto-finish-rum-25', 749, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Opthimus25arSoleraRomOportoFinish_b03973db-0b46-45d1-b8f6-2eb7015db6f5.png?v=1770900033', 'Opthimus Oporto Finish Solera Rum 25 år er ligesom sin yngre bror, Opthimus Oporto Finish Solera Rum 15 år, lagret på brugte portvinsfade i slutfasen af lagringsprocessen. Næse: sødme, figner, tørrede frugter og kanel. Smag: sød, men også en anelse tør og krydret med fin balance imellem det søde og det krydrede. Eftersmag: portvinssødme, krydderier fra fadet og harmonisk. Opthimus Oporto Finish Solera Rum 25 år er produceret i begrænset antal. 43% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pampero Aniversario Extra Añejo Reserva Exclusiva Rom', 'https://rombo.dk/products/pampero-aniversario-reserva-exclusiva-rum', 265, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_dc88734e-c128-430c-a930-91e0b8292c8a.png?v=1769421150', 'Pampero Aniversario Extra Añejo Reserva Exclusiva er en rom fra Venezuela, der er lagret på egetræsfade i op til 6 år (nogle påstår op til 8 år). Denne rom er premium-udgaven fra Pampero, og den blev første gang lanceret i 1963 ifm. Pampero-husets 25 års jubilæum. Rommen har kaffe, nødder og fad i næsen, mens smagen har noter af kakao og vanille. Flasken er charmerende indbundet i en læderpose. Pampero Aniversario Extra Añejo Reserva Exclusiva er absolut velegnet til at blive indtaget rent og kan også anvendes til cocktails. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Panamonte 12 års rom', 'https://rombo.dk/products/panamonte-12-ars-rom', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Panamonte12arsPanamarom.png?v=1778055457', 'Panamonte 12 år er en Single Estate rom, der er blevet dyrket, destilleret og lagret på den over 100 gamle Hacienda San Isidro ejendom i Las Cabras, Panama, hvor man både laver sukkerrør og rom. Panamonte rommen er lagret på brugte bourbonfade i Panama''s tropiske klima i 12 år. Når man dufter til denne Panamonte 12 års rom, fornemmes noter af karamel, krydderier, vanilje og citrus, mens smagen byder på noter af brun farin, vanilje, karamel og egetræskrydderier. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Paranubes Oaxaca aguardiente de caña rom', 'https://rombo.dk/products/paranubes-oaxaca-aguardiente', 375, true, 70, 54, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/ParanubesOaxacaRecorterom.png?v=1789980934', 'Paranubes Oaxaca 100% Cane Juice Rum er en lys, ulagret mexicansk rom, der er fremstillet af den rene sukkerrørsjuice "aguardiente de caña" og vildfermenteret. Denne gæringsproces gør, at Paranubes Oaxaca er en høj-aromatisk og smagfuld rom. Hvis man tør, kan rommen nydes rent, og ellers gør den sig også godt i en cocktail, der gerne må være lidt ekstra punchy. 54% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom Gaveæske 3 x 20 cl', 'https://rombo.dk/products/patridom-3-box-gaveaeske-20cl', 399, true, NULL, 40.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9995027a-bc4e-49ab-b0ae-9e8cf398390e.png?v=1769425076', 'Patridom 3-box gaveæsken indeholder 3 af de Patridom udgaver med sukkerrørsspiritus, som p.t er på markedet: Patridom Gran Reserva , Patridom Seleccion Exclusiva 12 og Patridom XO i flasker á 20 cl. Det giver dig en unik mulighed for at smage og sammenligne disse 3 aftapninger produceret af den danske producent og importør 1423 Aps. Patridom er en serie af sukkerrørsspiritus fra Den Dominikanske Republik, som alle bliver destilleret hos Alcoholes Finos Dominicanos, og Patridom ligger sig indenfor den søde spanske stil, der er særdeles populær. Dette sæt er derfor en oplagt mulighed for at smage de primære varianter i Patridom serien, inden du eventuelt køber de større flasker. Og så er det jo en perfekt lille gave til enhver lejlighed. Gennemsnits-ABV: 40,7%. Indhold: 3 x 20 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom Gaveæske 3 x 5 cl', 'https://rombo.dk/products/patridom-gaveaeske', 149, false, NULL, 40.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2463208f-9c0b-4c28-ac7e-696148a47dd6.png?v=1769436703', 'Patridom gaveæsken indeholder 3 af de Patridom varianter af sukkerrørsspiritus, som p.t er på markedet: Patridom Gran Reserva , Patridom XO og Patridom Seleccion Exclusiva i flasker á 5 cl. Det giver dig en unik mulighed for at smage og sammenligne disse 3 aftapninger produceret af den danske producent og importør 1423 Aps. Patridom er en hyldest til Den Dominikanske Republiks historie, sukkerrør og rom / sukkerrørsspiritus. Serien består af delikate premiumblandinger fra Den Dominikanske Republik, der alle er tropisk lagret. Hver udgave er skabt med lidenskab ved brug af håndskåret sukkerrør. Patridom bliver destilleret hos Alcoholes Finos Dominicanos, og ligger sig indenfor verdenen af rom og sukkerrørsspiritus i den søde spanske stil, der er særdeles populær. Dette sæt er en oplagt mulighed for at smage de primære varianter i Patridom-serien, inden du eventuelt køber de større flasker. Og så er det jo en perfekt lille gave til enhver lejlighed. Gennemsnits-ABV: 40,7%. Indhold: 3 x 5 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom Gran Reserva', 'https://rombo.dk/products/patridom-gran-reserva', 249, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_559e2928-8007-4568-976f-0bda268bd3f8.png?v=1769435824', 'Patridom Gran Reserva er lavet af frisk sukkerrørsjuice, som modnes i det tropiske klima i Den Dominikanske Republik. Lagret i en periode på fire til seks år, både i amerikanske ege- og franske egefade, før det blandes og tilsættes med rørsukker. Patridom er en hyldest til historien om Den Dominikanske Republik, sukkerrør, rom og sukkerrørsspiritus. Serien består af delikate premium blandinger fra Den Dominikanske Republik, alle tropisk modnet. Duft: saftige abrikoser med en let syrlig note, der omdannes til brunt sukker, mælkechokolade og ahornsirup. Smag: behagelig sødme med antydninger af frisk vanilje. En let krop med subtile aromaer af kaffe og mørk chokolade, der tilføjer dybde og kompleksitet. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom Gran Reserva "Bag In Tube" 3 liter', 'https://rombo.dk/products/ron-esclavo-gran-reserva-3l', 895, true, 30, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PatridomGranReservaBagInTube3literRomFront.png?v=1771589023', 'Patridom (tidligere kaldt "Ron Esclavo") Gran Reserva er lavet af frisk sukkerrørsjuice, som modnes i det tropiske klima i Den Dominikanske Republik. Lagret i en periode på fire til seks år, både i amerikanske ege- og franske egefade, før det blandes og tilsættes med rørsukker. Patridom er en hyldest til historien om Den Dominikanske Republik, sukkerrør, rom og sukkerrørsspiritus. Serien består af delikate premium blandinger fra Den Dominikanske Republik, alle tropisk modnet. Duft: saftige abrikoser med en let syrlig note, der omdannes til brunt sukker, mælkechokolade og ahornsirup. Smag: behagelig sødme med antydninger af frisk vanilje. En let krop med subtile aromaer af kaffe og mørk chokolade, der tilføjer dybde og kompleksitet. Denne udgave kommer i en såkaldt Bag-in-Tube®, som er et smart emballagekoncept. Først paprøret og inden i, en dobbeltlaget pose. Rommen tappes fra en højeffektiv Vitop® hane. (ligesom man kender fra pap-vinen, dog i top kvalitet) Når først den er åbnet, beskytter Bag-in-Tube® rommen mod ilt og giver dermed forlænget holdbarhed. 40% vol. - 3 liter.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom Navidad Exclusiva', 'https://rombo.dk/products/patridom-navidad-exclusiva', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e06164be-0067-460e-a9b0-68e354cdea64.png?v=1769438005', 'Navidad er det spanske ord for jul, som vi kender det fra udtrykket "Feliz Navidad" (Glædelig Jul), og Patridom Navidad Exclusiva er netop også især skabt til de gode stunder ved juletid. Patridom Navidad Exclusiva er lavet af frisk sukkerrørsjuice, som modnes i det tropiske klima i Den Dominikanske Republik. Denne sukkerrørsspiritus er lagret i op til tolv år, både i amerikanske ege- og franske egefade, før det blandes og tilsættes med rørsukker og julenoter. Patridom er en hyldest til historien om Den Dominikanske Republik, sukkerrør, rom og sukkerrørsspiritus. Serien består af delikate premium blandinger fra Den Dominikanske Republik, og alle er tropisk modnet. Duft: friske noter af citrus, appelsinskal, budding, chokolade og nødder. Smag: sødmefuld, fed og fyldig med noter af chokolade/kakao, appelsin og kokos. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom Reserva Especial', 'https://rombo.dk/products/patridom-reserva-especial', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_fe06948a-ba3b-4092-90f8-7998477144dd.png?v=1769437384', 'Patridom Reserva Especial er lavet af frisk sukkerrørsjuice, som modnes i det tropiske klima i Den Dominikanske Republik. Lagret i en periode på fire til tolv år, både i amerikanske ege- og franske egefade, før det blandes og tilsættes med rørsukker. Patridom er en hyldest til historien om Den Dominikanske Republik, sukkerrør, rom og sukkerrørsspiritus. Serien består af delikate premium blandinger fra Den Dominikanske Republik, alle tropisk modnet. Duft: frisk frugt med en karamelliseret note, der omdannes til brunt sukker, vanilje og ahornsirup. Smag: behagelig sødme med antydninger af frisk vanilje. En let krop med subtile aromaer af kaffe og karamel, der tilføjer dybde og kompleksitet. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom Selección Exclusiva Islay Cask Finish', 'https://rombo.dk/products/patridom-seleccion-exclusiva-islay-cask-finish', 425, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a9938a4a-77db-414a-a3d5-af2fd6c9baf5.png?v=1769434130', 'Patridom Seleccion Exclusiva er baseret på både melasse og frisk sukkerrørsjuice. Efter destillering har denne "premium spirit drink" lagret på amerikanske og franske egetræsfade i tropisk klima i Den Dominikanske Republik. Lagringen foregår i mellem 6 og 12 år, og herefter har den fået en efterlagring i Danmark på Islay whiskyfade. Patridom Selección Exclusiva Islay Cask Finish har med efterlagringen på Islay-fad fået tilført intense duftnoter af røg, barbeque og brændt karamel, der efterhånden udvikler sig til noter af sød nougat. Smagen er først røget og derefter sødmefuld med strejf af hasselnød, sirup og vanilje, der munder ud i en let træagtig finish. Limited 2022 edition på 1976 flasker. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom Seleccion Exclusiva Solera 12 år', 'https://rombo.dk/products/patridom-seleccion-exclusiva', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Patridom_Seleccion_Exclusiva_Solera_12_r.png?v=1787054018', 'Patridom Seleccion Exclusiva er baseret på både melasse og frisk sukkerrørsjuice. Efter destillering har denne "premium spirit drink" lagret på amerikanske og franske egetræsfade i tropisk klima i Den Dominikanske Republik. Lagringen foregår i mellem 6 og 12 år, og her udvikles duft og smag. Patridom Seleccion Exclusiva dufter af sødt bagværk, budding, karamel og vanilje og har kraftige smagsnoter af mørk sukker, kokosnød og vanilje. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom XO', 'https://rombo.dk/products/patridom-xo', 475, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c9ffd181-b530-4aa0-99ab-93c1511eb4dd.png?v=1769425948', 'Patridom XO er en del af 1423’s Patridom-serie af dominikanske udgivelser med hver deres udtryk. Destilleriet bag, Alcoholes Finos Dominicanos, bruger kun deres egne, lokale sukkerrør til produktionen. Patridom XO er en "premium spirit drink", som er fremstillet på både frisk sukkerrørsjuice og melasse. Efter destillering har den lagret i tropisk klima i mellem 12-15 år på amerikanske og franske egetræsfade. Patridom XO har en krydret duft med et hint af modne frugter og et strejf af bivoks. Den har frugtige, krydrede smagsnoter med antydning af kokosnød og vanilje. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom XO Cask 65%', 'https://rombo.dk/products/patridom-xo-cask-65', 499, false, 50, 65, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a3e25105-8081-4ebc-89ca-a4e165c9fbe9.png?v=1769436851', 'Patridom XO Cask er fremstillet af både frisk sukkerrørsjuice og melasse. Denne sukkerrørsspiritus lagres i Den Dominikanske Republiks tropiske klima, i amerikanske og franske egetræsfade, i en periode fra tolv til femten år. Patridom er en hyldest til Den Dominikanske Republiks historie, sukkerrør, rom og sukkerrørsspiritus. Serien består af delikate premium-blandinger fra Den Dominikanske Republik, alle tropisk lagrede. Hver udgave er skabt med lidenskab ved hjælp af håndskåret sukkerrør. Patridom XO Cask destilleres af Alcoholes Finos Dominicanos, der kun forarbejder deres egen sukkerrør, hvilket sikrer at der kun benyttes Dominikanske sukkerrør. I duften er der en sammensmeltning af sødme og syrlighed, ledsaget af nuancer af kokosnød og bivoks. Når det kommer til smagsoplevelsen, kan man forvente en fyldig karakter, der støttes af en olieagtig struktur. Noter af rosiner kombineres med toner af mørk chokolade, hvilket tilføjer en behagelig bitterhed til finishen. 65% - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom XO Limited Edition Cherry Wine Cask Finish', 'https://rombo.dk/products/patridom-xo-limited-edition-cherry-wine-finish', 599, false, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_dcbc635b-d957-4d2e-9c99-5808033139bf.png?v=1769438158', 'Patridom XO Limited Edition Cherry Wine Finish er baseret på Patridom XO , som er en "premium spirit drink" fra Den Dominikanske Republik, der er tappet af 1423 og destilleret af Alcoholes Finos Dominicanos fremstillet af frisk sukkerrørsaft og melasse. Patridom XO har lagret mellem 12 og 15 år i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Patridom XO Limited Edition udgave med Cherry Wine Cask Finish har derudover gennemgået en ekstra kontinental lagring i ex-Cherry Wine fade, hvilket tilføjer en frugtagtig note. De brugte fade kommer faktisk fra Ukraine, hvor kirsebærvin er en meget udbredt nydelse. Patridom XO Cherry Wine Cask Finish er blevet aftappet i juni 2024 med et resultat på kun 2.237 flasker. Når du først dufter til den, vil du blive mødt af friske, livlige og græsagtige undertoner, der blødt afrundet af blød vanilje og en antydning af kirsebær. Ved første smag vil du straks mærke den delikate sødme og blødhed af modne kirsebær og blandede bær, der afsluttes med en lang og tør eftersmag. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom XO Limited Edition Cognac Cask Finish 2022 edt.', 'https://rombo.dk/products/patridom-xo-cognac-cask-finish', 599, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8d65e431-8e61-4adf-8c1b-329fed9e1370.png?v=1769434126', 'Patridom XO Cognac Cask Finish er 2022-udgaven af 1423’s Patridom-serie af sukkerrørsspiritus med hver sit udtryk. Destilleriet bag, Alcoholes Finos Dominicanos, bruger kun deres egne, lokale sukkerrør til produktionen og er en af verdens mest miljøvenlige og socialt ansvarlige destillerier. Patridom XO er en "premium spirit drink", som er fremstillet på både frisk sukkerrørsjuice og melasse. Efter destillering har den lagret i tropisk klima i mellem 12-15 år på amerikanske og franske egetræsfade. Patridom XO Cognac Cask Finish har derefter fået en finish i Danmark på tidligere cognacfade, der har givet ekstra frugtig karakter. Denne sukkerrørsspiritus har duftnoter af pære og gule blommer med et strejf af creme og vanilje. Smagen er rund og frugtig med noter af æblekompot, mandler og honning, der munder ud i en mild eftersmag. Limited 2022 edition på 1373 flasker. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom XO Limited Edition Cognac Cask Finish 2023 edt.', 'https://rombo.dk/products/patridom-xo-limited-edition-cognac-finish', 599, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ad7c08f8-7cf3-4e2f-8aa2-ee36acb1c68e.png?v=1769436028', 'Patridom XO Limited Edition Cognac Finish er baseret på Patridom XO , som er en "premium spirit drink" fra Den Dominikanske Republik, der er tappet af 1423 og destilleret af Alcoholes Finos Dominicanos fremstillet af frisk sukkerrørsaft og melasse. Patridom XO har lagret mellem 12 og 15 år i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave har gennemgået en ekstra kontinental lagring i ex-Cognac-fade, hvilket tilføjer en frugtagtig note. Patridom XO Cognac Cask Finish er blevet aftappet i juli 2023 med et resultat på 2333 flasker. Når du først dufter til den, vil noter af vin og søde frugter komme frem, suppleret af subtile strejf af kanel og abrikoser. Ved første smag vil du opleve sød vin og frisk frugt, som hurtigt suppleres af et hint af vanilje, der afsluttes med en krydret finish. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom XO Limited Edition Marsala Cask Finish', 'https://rombo.dk/products/patridom-xo-limited-edition-marsala-finish', 599, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_88b825b4-82ee-4d59-819a-e5c5cc27e05f.png?v=1769438155', 'Patridom XO Limited Edition Marsala Finish er baseret på Patridom XO , som er en "premium spirit drink" fra Den Dominikanske Republik, der er tappet af 1423 og destilleret af Alcoholes Finos Dominicanos fremstillet af frisk sukkerrørsaft og melasse. Patridom XO har lagret mellem 12 og 15 år i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Patridom XO Limited Edition udgave med Marsala Cask Finish har derudover gennemgået en ekstra kontinental lagring i ex-Marsala-fade, hvilket tilføjer en fyldig og cremet note. Patridom XO Marsala Cask Finish er blevet aftappet i juni 2024 med et resultat på kun 2.237 flasker. Når du først dufter til den, vil du blive mødt af rig karamel og blød vanilje med subtile strejf af tørret frugt og tobak. Ved første smag vil du straks mærke cremet vanilje og brun sukker, der er smukt afbalanceret med noter af moden abrikos og gylden honning. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Patridom XO Limited Edition Tawny Port Finish', 'https://rombo.dk/products/patridom-xo-limited-edition-tawny-port-finish', 599, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1031e464-ed4a-41e7-a978-785c74d6074f.png?v=1769436035', 'Patridom XO Limited Edition Tawny Port Finish er baseret på Patridom XO , som er en "premium spirit drink" fra Den Dominikanske Republik, der er tappet af 1423 og destilleret af Alcoholes Finos Dominicanos fremstillet af frisk sukkerrørsaft og melasse. Patridom XO har lagret mellem 12 og 15 år i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave har derudover gennemgået en ekstra kontinental lagring i ex-Tawny Port fade, hvilket tilføjer en sød note. Patridom XO Tawny Port Cask Finish er blevet aftappet i juli 2023 med et resultat på 1961 flasker. Når du først dufter til den, vil du i begyndelsen møde noter af frisk slået græs, som gradvist overgår til aromaer af tørrede frugter, kaffe og krydderier. På smagspaletten vil du opleve søde røde bær, karamel, kirsebær og solbær, der tilsammen skaber en langvarig sød finish. 45% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation XO 20th Anniversary Rom 35 cl', 'https://rombo.dk/products/plantation-xo-20th-anniversary-35-cl', 249, true, 35, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_984f4954-079e-41ca-bf70-4b4dc4a2c1f5.png?v=1769438443', 'Plantation XO 20th Anniversary har en mørk farve som mahogni med ravgyldent skær. Duft: Vanille, tørrede frugter, kokos og bagte bananer er de allerførste kælne toner, der rammer næsen. Mørk sødmefuld toffee, mælkechokolade og orientalske krydderier vidner om mange års stille lagring i mørke kældre. Til sidst fornemmes en smule brændt fad og teblade. Smag: En stor sødme fylder hele munden. Masser af vanille, abrikos og rosin er blandt de første fornøjelser, der smages. Herefter kommer en lækker mørk og krydret smag af kanel, Demerara rørsukker og kakao. Plantation 20 Anniversary har toner af sød ulmende eg, whiskymelange, pibetobak og Crème Brulée afslutter en fantastisk stor rom oplevelse. Eftersmagen er utrolig blød og fortryller sanserne i adskillige minutter. Plantation XO 20th Anniversary fra Barbados har en utrolig lækker og indbydende smag, som de fleste rom-feinschmeckere vil elske. Her fås den i en charmerende "halvflaske". 40% – 35 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray 3 Stars Rom', 'https://rombo.dk/products/planteray-3-stars-rom', 189, true, 70, 41.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Planteray_3_Stars_Rom.png?v=1787049715', 'Planteray (tidligere "Plantation") 3 Stars Artisanal Rum er et blend af rom fra Barbados, Jamaica og Trinidad, der som "3 stjerner" indenfor romverdenen står for forskellige stilarter. Planteray Master Blender, Alexander Gabriel, har forsøgt at skabe det perfekte blend af disse. Planteray 3 Stars Artisanal Rum har florale noter og smag af bl.a. tropisk frugt og frisk sukkerrørssaft. Rommen er ideel til forskellige cocktails. 41,2% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Belize 2008 Vintage Collection Terravera Limited Edition Rom', 'https://rombo.dk/products/planteray-belize-2008-terravera-rom', 799, false, 70, 48.3, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b703f01a-79b1-40ad-a3df-6df7aafaf97e.png?v=1769437333', 'I januar 2024 annoncerede Plantation Rum, at de ville skifte navn til Planteray Rum, og nu begynder vi så langsomt at se implementeringen af dette navneskifte. Planteray Belize Vintage 2008 Terravera rom er den første Vintage Collection limited edition udgave i Danmark efter navneskiftet fra Plantation til Planteray. Planteray Vintage Collection rom-serien er lige som den gamle Plantation rom-serie også fra den uafhængige aftapper Ferrand i Frankrig. Planteray Belize Vintage Collection Terravera rom blev destilleret i 2008 hos Travellers destilleriet i Belize. Rommen er baseret på sukkerrørsmelasse, der har fermenteret i 3-4 dage, hvorefter den er blevet destilleret i et kolonne destilleringsapparat. Ved at udnytte Plantation Rums karakteristiske dobbeltmodningsteknik er rommen blevet tropisk modnet i 13 år hos Travellers i Belize, efterfulgt af en transatlantisk rejse til det sydvestlige Frankrig og 2 års modning på franske egetræsfade, som tidligere har indeholdt Ferrand Cognac. For at fuldende processen har de efterfølgende tilsat 8 gram sukker pr. liter, så den i vores regi falder under kategorien mellemsød rom. Planteray Belize 2008 Vintage Collection Terravera Rom har en duft af kanel, vanilje, muskatnød, mandler, læder, kakao, honning og banan. I smagen finder man bl.a. citrus, pære, karamel, kokos, peber, kryddernellike, lakrids og tobak. Eftersmagen er lang og intens med tørret frugt, kirsebær, vanilje, kaffe og subtile grønne noter. 48,3% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Cut & Dry Coconut Spirit Drink', 'https://rombo.dk/products/planteray-cut-dry-coconut', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_236fdd3f-93d6-4c7f-a441-7c7dcb5a8521.png?v=1769438026', 'Planteray Cut &amp; Dry Coconut Spirit Drink blev skabt af Alexandre Gabriel, kældermesteren hos Plantation, der nu har skiftet navn til Planteray . Siden europæerne opdagede Caribien, har de været tiltrukkede af den eksotiske og velsmagende kokosnød. Kokospalmen giver i gennemsnit kun 45 kokosnødder om året på Barbados, hvor man har skåret kokosnødderne i små stykker og derefter ladet dem tørre (derfor Cut &amp; Cry). De tørrede kokosstykker er herefter blevet infuseret i sukkerrørsspiritussen fra West Indies Rum Distillery for at give den færdige Planteray Cut &amp; Dry Coconut Spirit Drink. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray El Salvador 2017 Rombo Single Cask rom', 'https://rombo.dk/products/planteray-el-salvador-2017-rombo-single-cask-rom', 699, true, 70, 47.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Planteray_El_Salvador_2017_Rombo_Single_Cask_rom.png?v=1792229307', 'Denne helt unikke Planteray El Salvador 2017 Single Cask 9 års rom er tappet til Rombo og et par andre vinhandlere, der er gået sammen om at købe fadet. Rommen er kolonne-destilleret hos Ingenio la Cabaña i El Salvador i 2017 efter en gæring på 2-3 dage. Efter 7 års tropisk lagring i bourbonfade i Mellemamerika, har den i Frankrig fået yderligere 6 måneder i Cognac Ferrand fade og til sidst 18 måneder i Moscatel-fade. Alt i alt en 9 års rom på 3 forskellige fadtyper. Der er ikke tilsat sukker, så her får man den helt naturlige og ikke-søde rom. Når man dufter til Planteray El Salvador 2017 Rombo Single Cask rommen, fornemmes karamelliseret appelsin, kakao, marcipan, rosiner, abrikos, banan, valnødder, ristede mandler, pistacie og ingefær. Smagen byder på noter af kandiseret appelsin, ingefær, blommer, stjernefrugt (carambola), vaniljecreme og lavendel. I eftersmagen følger litchi, passionsfrugt, mandarin, cedertræ, guava, mandler og bagekrydderier. Limited edition - enkeltfadsaftapning. 47,7% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Guatemala & Belize Gran Anejo Rom', 'https://rombo.dk/products/planteray-gran-anejo-guatemala-belize-rum', 275, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_20a33550-d12d-4b40-b653-86fc94ee89c8.png?v=1769422410', 'Planteray (tidligere "Plantation") Gran Anejo Guatemala &amp; Belize Rum er en pot still-destilleret, dobbeltlagret rom. Først lagres den på bourbonfade i det tropiske klima i Guatemala og Belize, og derefter sendes Plantation Guatemala &amp; Belize rommen til Chateau de Bonbonnet i Frankrig, hvor den lagres i mindre Pierre Ferrand-cognacfade. Planteray Gran Anejo Guatemala &amp; Belize Rum har aroma af grønne æbler, vanille og pærer og smagnoter af karamelsauce, bagte æbler og melasse. Let drikkelig rom, der kan nydes alene eller i cocktails. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Hogo Monsta High Ester Barbados Rum 20 cl', 'https://rombo.dk/products/planteray-hogo-monsta-high-ester', 299, false, 20, 56.6, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_03c3cff5-2b76-4dc7-9450-eb9624e782e1.png?v=1769439672', 'Planteray Hogo Monsta er en såkaldt høj-ester rom fra West Indies Rum Distillery (WIRD) på Barbados. Faktisk er ester-tallet på hele 2.029 h/HL AA, så det er lidt en vildbasse, hvad angår aroma og smag. En af årsagerne til det høje ester-indhold er den lange fermentering, hvor de forskellige melasse- og gær-typer ligger i gæringstankene i 14-21 dage. Den anden årsag er, at man har valgt to forskellige pot stills til destilleringen, der begge er "skræddersyet" til fremstilling af høj-ester rom. Først destilleres rommen i John Dore #88 pot still, og herefter destilleres den anden gang i WIRD''s heritage Old Gregg pot still. Efterfølgende er Planteray Hogo Monsta High Ester Barbados Rum lagret i 3 år, hvoraf de 6 måneder er foregået på Barbados, og de sidste 2,5 år er foregået i Frankrig. Hogo er en forkortelse for "Haut Goût", som betyder "meget smag" på fransk, og det henviser i dette tilfælde til den intense og funky aroma, der findes i højester-rom. Team''et på WIRD, der fermenterede og destillerede rommen, betegnede den selv som "Monsta", og derfor fik denne rom navnet Hogo Monsta. 56,6% abv. Bemærk : 20 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Isle of Fiji Rum Double Aged Rom', 'https://rombo.dk/products/planteray-isle-of-fiji-rum', 275, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_cb675e3e-0a7c-4f6a-b072-7bcc18ff1b6d.png?v=1769423813', 'Planteray (tidligere "Plantation") Isle of Fiji Rum er en dobbeltlagret rom fra Pacific Distillery på Stillehavsøen Fiji. Rommen er melasse-baseret og efter en indledende, tropisk lagring i ex-bourbonfade har Plantation Isle of Fiji rom fået en efterlagring i ex-cognacfade hos Ferrand i Frankrig. Der er næsten altid nogle Jamaica-noter over Fiji-rom, og det finder man også her (især i næsen). I smagen finder man noter af bl.a. eksotiske frugter og rosiner. Der er tilsat 16 gram sukker i denne Planteray Isle of Fiji rom, der derfor kan kategoriseres som mellemsød. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Jamaica Vintage 2000 Long Pond ITP Ping 16 rom', 'https://rombo.dk/products/planteray-jamaica-2000-long-pond-ping-16-rum', 1995, true, 70, 58.4, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c6645fee-eb3f-4ecc-9a14-93309ee2125e.png?v=1769438248', 'Planteray Jamaica Vintage 2000 Long Pond ITP Ping 16 er en limited edition single cask rom fra Planteray Rum (det tidligere Plantation Rum). Rommen er destilleret i en John Dore double retort pot still hos Long Pond Distillery på Jamaica. Efter 17 års lagring på et ex-bourbonfad har denne rom fået en afslutttende lagring i 7 år på et Ferrand ex-cognacfad i Frankrig. Planteray Jamaica Vintage 2000 Long Pond ITP Ping 16 rom byder på "sædvanlige Jamaica-noter" samt noter af bl.a. tørret frugt og krydderier. Estertallet er let / let-medium, men den høje ABV på 58,4% giver rommen masser af karakter og intensitet. Limited edition enkeltfadsrom, der er tappet til det danske marked af Juuls Engros. 58,4% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Mister Fogg Navy Rum', 'https://rombo.dk/products/planteray-mister-fogg-navy-rum', 399, true, 70, 55.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c6a10797-135e-4db4-9205-7356f5989641.png?v=1769439697', 'Planteray Mister Fogg Navy Rum er et blend af rom fra Barbados (WIRD), Trinidad (TDL), Guyana (DDL), Mauritius (Saint Aubin) og Jamaica (Hampden og NRJ). Man har med denne rom og i samarbejde med en historiker forsøgt at genskabe den gamle "navy rum" så godt som muligt. Rommen er oprindeligt lagret i brugte bourbonfade hos de forskellige destillerier, og herefter er den transporteret til Frankrig, hvor den er blendet sammen. Derpå har den fået en ekstra lagring i brugte egetræsfade samt en omfattende iltning i store, åbne "wooden vats" for at kopiere det gamle, fugtige miljø i de gamle havnemiljøer i London. Når man dufter til Planteray Mister Fogg Navy Rum, fornemmes noter af tørret frugt, appelsinskal, chokolade, vanilje, blomme og karamel. Smagen er fyldig og byder på noter af brændt melasse, karamel og moden frugt. 55,7% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Oceana Australia Vintage 2016 Rum', 'https://rombo.dk/products/planteray-oceana-australia-vintage-2016-rum', 675, true, NULL, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PlanterayOceanaAustralia2016rom.png?v=1793023264', 'Denne helt særlige Planteray Oceana Australia Vintage 2016 er en Limited Edition udgave og én af kun i alt tre flasker i Vintage Collection No. 4 udgivelsen (de øvrige to er Fiji Islands og Mauritius). Planteray Vintage Collection serien hylder rom fra fjerne øer og områder, og den byder på dobbeltlagret rom, der har fået en tropisk lagring på bourbonfade efterfulgt af kontinental lagring på Ferrand cognacfade. Planteray Oceana Australia Vintage 2016 er en 10 års rom, der er lavet på melasse og kolonnedestilleret i Australien, hvor den har fået 8 års tropisk lagring på bourbonfade, inden de i alt 12 fade har fået yderligere 2 års kontinental lagring i Frankrig på Ferrand cognacfade. Slutresultatet er en blød, varm og indbydende rom med duft af vanilje, toffee, fersken, abrikos, moden banan og sød mandel. Smagen er silkeblød med guava, ananas, mælkechokolade, ristet kokos og citrusskal. Eftersmagen er lang med mineralsk tørhed, let tannin, tropisk frugt, kakao, kanel og muskatnød. Bemærk: 6 gram sukker/liter, hvilket er en lille smule tilsat sødme. Limited edition - 52% vol.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Oceana Fiji Islands Vintage 2012 Rum', 'https://rombo.dk/products/planteray-oceana-fiji-islands-vintage-2012-rum', 599, true, NULL, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PlanterayOceanaFijiIslands2012rom.png?v=1793024385', 'Denne helt særlige Planteray Oceana Fiji Islands Vintage 2012 er en Limited Edition udgave og én af kun i alt tre flasker i Vintage Collection No. 4 udgivelsen (de øvrige to er Australia og Mauritius). Planteray Vintage Collection serien hylder rom fra fjerne øer og områder, og den byder på dobbeltlagret rom, der har fået en tropisk lagring på bourbonfade efterfulgt af kontinental lagring på Ferrand cognacfade. Planteray Oceana Fiji Islands Vintage 2012 er en 14 års rom, der er lavet på melasse og pot still destilleret hos Paradise Beverage Distillery i Fiji, hvor den har fået 11 års tropisk lagring på bourbonfade, inden de i alt 31 fade har fået yderligere 3 års kontinental lagring i Frankrig på Ferrand cognacfade. Slutresultatet er en intens, kompleks og frugtig rom med duft af guava, kvæde, appelsin og ristet ananas med læder, let tobak og nellike. Smagen er fyldig og olieret med ananas, mango, kirsebær, karamel, mørk chokolade og ingefær. Eftersmagen er lang med vanilje, passionsfrugt, lakrids og vulkansk mineralitet. Bemærk: naturlig rom uden tilsat sødme. Limited edition - 45% vol.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Oceana Mauritius Vintage 2014 Rum', 'https://rombo.dk/products/planteray-oceana-mauritius-vintage-2014-rum', 649, true, NULL, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PlanterayOceanaMauritius2014rom.png?v=1793025311', 'Denne helt særlige Planteray Oceana Mauritius Vintage 2014 er en Limited Edition udgave og én af kun i alt tre flasker i Vintage Collection No. 4 udgivelsen (de øvrige to er Fiji Islands og Australia). Planteray Vintage Collection serien hylder rom fra fjerne øer og områder, og den byder på dobbeltlagret rom, der har fået en tropisk lagring på bourbonfade efterfulgt af kontinental lagring på Ferrand cognacfade. Planteray Oceana Mauritius Vintage 2014 er en 12 års rom, der er lavet på melasse og pot still destilleret i Mauritius, hvor den har fået 8 års tropisk lagring på bourbonfade, inden de i alt 24 fade har fået yderligere 4 års kontinental lagring i Frankrig på Ferrand cognacfade. Slutresultatet er en elegant, eksotisk og krydret rom med duft af karamel, vanilje, citronskal, passionsfrugt, banan og kokos med muskatnød og sød tobak. Smagen byder på tørret frugt og guava med fine florale nuancer og et strejf af rosenblade. Eftersmagen er lang og elegant med sort te, knust peber og kandiseret appelsinskal. Bemærk: Naturlig rom uden tilsat sødme (der er 5 gram sukker/liter, hvilket kan være naturlig restsukker). Limited edition - 50% vol.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Original Dark Double Aged Rom', 'https://rombo.dk/products/planteray-original-dark-double-aged', 185, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Planteray_Original_Dark_Double_Aged_Rom.png?v=1787043825', 'Plantation Original Dark Double Aged er et blend af rom fra Barbados, 1 til 3 år gammel - lavet på twin Column &amp; Pot Still og rom fra Jamaica 10 til 15 år gammel - lavet på Pot Still (John Dore). Efter blending er rommen modnet færdig i Frankrig 3 til 6 måneder på unge bourbonfade. Næse: peberkorn, nellike, kanel, kirsebær, sveske. Smag: Først frugtagtig med hvide rosiner, tørret ananas og let tør. Siden kommer en krydret, pikant, mineralsk og væsentligt mere tør eftersmag, der afsluttes med mere krydderi. Bemærk: flasken hed tidligere Plantation Original Dark, men man har nu skiftet navn til Planteray. 40% - 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Overproof OFTD 69% Rom', 'https://rombo.dk/products/planteray-rum-overproof-oftd', 299, true, 70, 69, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Planteray_Overproof_OFTD_69_Rom.png?v=1787051717', 'Planteray (tidligere "Plantation") Rum Overproof OFTD 69% er blandet specielt til at indgå i drinks snarere end til at være sippe- og hyggerom, og den kan virkelig sætte fut i en mai tai. Når det er sagt kan rommen stadig drikkes rent, selvom den er stærk, og har både smag og karakter. Duft: kaffe, appelsin, blommer, syltetøj og trøffel. Smag: karamel-creme, chokolade, vanilje, kanel, rosin, muskatnød, egetræ og melasse. Planteray Rum Overproof OFTD er en del af Planteray rom-serien fra C. Ferrand i Frankrig. 69% vol. – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Paraguay 2018 Rombo Single Cask rom', 'https://rombo.dk/products/planteray-paraguay-2018-single-cask', 599, true, 70, 49, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Planteray_Paraguay_2018_Rombo_Single_Cask_rom.png?v=1787055006', 'Denne Paraguay 2018 rom er vores helt egen Rombo Single Cask aftapning fra Planteray Rum (det tidligere Plantation Rum). Da vi for 10 måneder siden prøvesmagte forskellige valgmuligheder var vi ikke et sekund i tvivl om, at profilen på netop denne rom matchede vores egne smagsløg, og at dette skulle være 2025-udgaven af Rombo Single Cask aftapningen fra Planteray Rum. Som vi normalvis gør, så har vi valgt en rom uden sukkertilsætning, og de 49% bidrager ligeledes til de komplekse nuancer og den robuste intensitet. Planteray Paraguay 2018 Rombo Single Cask rom er først lagret i 4 år på bourbonfade, herefter 14 måneder på Maison Ferrand cognacfade, og afslutningsvis har rommen fået 20 måneders lagring på Chardonnay vinfade. Den sjældent sete sekvens af de 3 fadtyper var en af grundene til, at vi valgte netop denne rom. Det vigtigste var dog, at vi selv var meget begejstrede for den unikke smag. Når man dufter til Planteray Paraguay 2018 Rombo Single Cask rom, fornemmes inviterende og komplekse noter af anis, rosiner, banan, appelsinskal, grønne æbler, cantaloupe og græs. Smagen er rund og fyldig med noter af bl.a. kvæde, svesker, figner, fersken, kryddernellike og lakrids. Eftersmagen er lang med lakrids, karamel, peber, dadler og honning. Limited edition på kun i alt 150 flasker. 49% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Rum Jamaica STCE 1995 Prestige Cellar rom', 'https://rombo.dk/products/planteray-rum-jamaica-stce-1995-prestige-cellar-rom', 2495, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PlanterayRumJamaicaSTCE1995PrestigeCellarrom.png?v=1790668101', 'Planteray Rum Jamaica STCE 1995 Prestige Cellar er en single cask rom, der er tappet udelukkende til Danmark ifm. 100 års jubilæet for importøren Juuls Engros. Rommen er lavet på melasse, fermenteret i 2 uger og destilleret i en John Dore Double Retort pot still hos Long Pond Distillery. Efter 23 års tropisk lagring på et bourbonfad har den fået yderligere 8 års kontinental lagring hos Ferrand i Frankrig på et cognacfad. Når man dufter til denne Planteray Rum Jamaica STCE 1995 Prestige Cellar rom, fornemmes bl.a. kamper, læder, kokos, grape, blomme og nødder. Smagen byder på noter af kaffe, ananas, mynte, bivoks, nelliker, kanel, lakrids, safran, cedertræ og nougat. Her får du en helt unik rom med fuld smæk på duft og smag. Ester-indholdet er på 648 g/hLAA, og der er ikke tilsat sukker. Limited Edition. 52% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Sealander Rom', 'https://rombo.dk/products/plantation-sealander-rom', 395, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PlanteraySealanderRom.png?v=1791980830', 'Planteray har sejlet mellem de store romproducerende øer i mere end 25 år, for at frembringe de fineste rom. Sealander fejrer denne historie ved at kombinere tre af de store romproducerende ører. Planteray Sealander er resultatet af en rejse, der forener traditionerne fra tre passionerede øer, denne visionære transoceaniske rejse strækker sig over Atlanterhavet, Stillehavet og det Indiske Ocean. Det er blend af rom fra Barbados, nærmere bestemt West Indies Rum Distillery, Saint Aubin fra Mauritius og RUM Co. of Fiji Distillery. Da rommene kommer fra tre så forskellige lokationer, er de også produceret på tre meget forskellige måder. Komponenten fra Mauritius er lavet på frisk sukkerrørssaft, mens de to andre er lavet på melasse. De har fermenteret i 3 dage til 3 uger og derefter destilleret på enten pot still eller kolonne still. De har lagret i adskillige år på bourbon i et tropisk klima, inden de kommer til Frankrig og lagrer et ekstra år på Ferrand cognac-fade. Det endelige blend doseres med 20 gram sukker/liter inden aftapningen til flaske. Duften åbner med en blid og fyldig aroma, der indeholder noter af pære, kvædegele og stikkelsbær, samt antydninger af røget melasse. Når du smager rommen, oplever du en rig og delikat smag med hints af kløverhonning, lakrids, bivoks, vaniljefudge og sveske. Eftersmagen er lang og vedvarende med nuancer af bagte æbler, tonkabønne og tørret banan, der fuldender denne fortryllende romoplevelse. 40% -70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Stiggins Fancy Pineapple Spirit Drink', 'https://rombo.dk/products/plantation-pineapple', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PlanterayStigginsFancyPineappleSpiritDrink.png?v=1781088729', 'Planteray (tidligere "Plantation") Stiggins Fancy Pineapple Original Dark blev skabt af Alexandre Gabriel, kældermesteren hos Planteray og David Wondrich, forfatter til bogen "Imbibe!" Det er en hyldest til den ansete pastor Stiggins, hvis foretrukne drink var " ananas rom " i Pickwick Papers af Charles Dickens. Oprindeligt var denne sukkerrørsspiritus ikke beregnet til salg, men blev skabt til at dele blandt kolleger og venner på Tales of the Cocktail 2014. Men Planteray Stiggins Fancy Pineapple Original Dark blev så populær, at den nu er tilgængelig på markedet . Fremstillingsprocessen for Stiggins'' Fancy Plantation Pineapple er kompleks . 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Xaymaca Special Dry Rom', 'https://rombo.dk/products/plantation-xaymaca-special-dry', 299, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_0cfd7b2c-be9a-4362-a400-54af68e85e27.png?v=1769423445', 'Plantation Xaymaca Special Dry er en jamaicansk rom af den "gamle skole". Den er 100% pot still-destilleret, og har intense, traditionelle "rum funk" aromaer og smag af overmoden banan og flamberet ananas. Plantation Xaymaca har ligget på tidligere cognac fade. Næse: kompleks, næsten let røget, med moden frugt som banan, orange, ananas og let urtet, vanilje og brød. Smag: tør, med en floral og frugtagtig profil. Pære, grape, modent æble, kokosmælk, brød og nødder. 43% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray XO 20th Anniversary PX Cask Finish rom', 'https://rombo.dk/products/planteray-xo-px-cask-finish-rom', 499, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Planteray_XO_20th_Anniversary_PX_Cask_Finish_rom.png?v=1770199455', 'Planteray XO 20th Anniversary PX Cask Finish rom er en opfølger til den klassiske og meget populære "Plantation XO 20th Anniversary rom". Siden har Plantation dog skiftet navn til Planteray, og nok så væsentligt så har denne nye Planteray XO 20th Anniversary fået en ekstra lagring på brugte Pedro Ximenez (PX) sherry fade fra Andalusien i Spanien. Rommen i Planteray XO 20th Anniversary PX Cask Finish udgaven er fra West Indies Rum Distillery på Barbados, hvor den er gæret, destilleret og indledningsvis lagret på ex-bourbonfade. Herefter er rommen bragt til Frankrig for yderligere lagring på brugte Ferrand cognacfade og afslutningsvis på PX sherryfadene. Noterne af bl.a. vanilje, kokos og tropiske frugter fra den oprindelige Plantation XO findes også i denne Planteray XO PX Cask Finish rom. Derudover bidrager PX sherryfadet med noter af nødder og rosiner. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray XO 20th Anniversary Rom', 'https://rombo.dk/products/plantation-xo-20th-anniversary', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PlanterayXO20thAnniversaryRom.png?v=1786101029', 'Planteray (tidligere kaldt Plantation) XO 20th Anniversary rom har en mørk farve som mahogni med ravgyldent skær. Duft: Vanille, tørrede frugter, kokos og bagte bananer er de allerførste kælne toner, der rammer næsen. Mørk sødmefuld toffee, mælkechokolade og orientalske krydderier vidner om mange års stille lagring i mørke kældre. Til sidst fornemmes en smule brændt fad og teblade. Smag: En stor sødme fylder hele munden. Masser af vanille, abrikos og rosin er blandt de første fornøjelser, der smages. Herefter kommer en lækker mørk og krydret smag af kanel, Demerara rørsukker og kakao. Planteray 20 Anniversary har toner af sød ulmende eg, whiskymelange, pibetobak og Crème Brulée afslutter en fantastisk stor rom oplevelse. Eftersmagen er utrolig blød og fortryller sanserne i adskillige minutter. Planteray XO 20th Anniversary fra Barbados har en utrolig lækker og indbydende duft og smag, som de fleste rom-feinschmeckere vil elske. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray XO 20th Anniversary Rom Gaveæske m/2 glas', 'https://rombo.dk/products/plantation-xo-20th-anniversary-gaveaeske', 449, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_cfe27352-9ab5-4125-aff3-5876674b93d5.png?v=1769423392', 'Planteray XO 20th Anniversary Barbados rom er efterlagret på fine små cognacfade hos cognachuset Pierre Ferrand i hjertet af Cognac i Frankrig. De bløde, franske limousine egefade, som først er blevet brugt til modning af den allerbedste Grande Champagne Cognac, bidrager med blød frugt, revet appelsinskal og fine vanilletoner. Bemærk, at denne vare tidligere hed: Plantation XO 20th Anniversary Rom Gaveæske m/glas, men Plantation har nu skiftet navn til Planteray. Planteray XO 20th Anniversary har en mørk farve som mahogni med ravgyldent skær. Duft: vanilje, tørrede frugter, kokos og bagte bananer er de allerførste toner, der rammer næsen. Mørk sødmefuld toffee, mælkechokolade og orientalske krydderier vidner om stille lagring i mørke kældre. Til sidst fornemmes en smule brændt fad og teblade. Smag: en stor sødme fylder hele munden. Masser af vanilje, abrikos og rosin er blandt de første noter, der smages. Herefter kommer en krydret smag af kanel, Demerara rørsukker og kakao. Planteray XO 20th Anniversary har toner af sød ulmende eg, whiskymelange, pibetobak og Crème Brulée. Med det gamle navn - Plantation XO 20th Anniversary - vandt man guld i kategorien "Premium Aged Rum" ved Miami Rum Festival 2015. Her får du rommen i en indbydende gaveæske med 2 originale Planteray glas. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pullimut The Infinite Blend 2026 Edition', 'https://rombo.dk/products/pullimut-2026-edition', 449, true, 70, 47.4, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PullimutTheInfiniteBlend2026Edition.png?v=1773063611', 'Pullimut 2026 Edition er årets udgave af det eksperimenterende blend fra 1423s infinite 600 liters ex-sherry fad. Af de 600 liter bliver typisk kun noget tappet på flaske, mens den resterende del med sukkerrørsspiritus fortsætter lagringen og indgår i næste års blend. Dette kan man jo gøre igen og igen og i teorien gøre for evigt – deraf navnet Infinite. Pullimut 2026 Edition sukkerrørsspiritus er således en unik blanding af rom og sukkerrørsspiritus fra forskellige årgange, lande og destillerier og dermed et helt særligt bekendtskab. I 2026 er det blevet til sølle 634 flasker, hvoraf kun nogle vil blive solgt i Danmark. Pullimut 2026 Edition er mørk og intens med noter af melasse, brun farin, toffee og krydderier. Eftersmagen er lang og varm med hints af chokolade og tør sherry. 47,4% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Puntacana Club Tesoro Whisky Finish Rom', 'https://rombo.dk/products/puntacana-tesoro-rom', 349, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b7477bb0-7e60-454d-9ae4-7bafd7d2226c.png?v=1769421264', 'Puntacana Tesoro Whisky Finish lagres efter Solera-metoden i 12-20 år på amerikanske egetræsfade. Slutteligt har Puntacana Tesoro rom fået en lagring på ex-single malt whisky fade fra den skotske whisky producent Tomatin. Duft: eg, sukkerrør og karamel. Smag/eftersmag: sødme, malt, eg, karamel og tobak. 38% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pusser''s 15 års Rom', 'https://rombo.dk/products/pussers-15-british-navy-rum', 599, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f31406b0-94ab-4ea5-85cf-ddf04d30e8fd.png?v=1769423513', 'Pusser''s 15 år British Navy Rum adskiller sig fra den tidligere Nelson''s Blood 15 års udgave fra Pusser''s. Den indeholdt nemlig også rom fra Trinidad, men her er man altså gået over til et rent Guyana-blend. Pusser''s 15 år British Navy Rum er ikke en Solera-rom, men den er lagret i minimum 15 år og blended af rom, der er destilleret og påbegyndt lagring før 2003 (gældende i skrivende stund: februar 2019). Pusser''s 15 års British Navy rom har noter af bl.a. Demerara sukker, melasse, tørret frugt, krydderier og karamel. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pusser''s Blue Label Rom', 'https://rombo.dk/products/pussers-british-navy-rum-40-blue', 225, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_98e9c8ac-85c1-4be3-bfec-f55ea9200035.png?v=1769422402', 'Pusser''s British Navy Blue Label Rum er ikke tilsat smagsstoffer og er 100% naturlig. Næse: fyldig sødme. Smag: kraftige smagsnoter af træ. Eftersmag: lang og rund. Pusser''s British Navy Blue Label Rum er en ud af blot en håndfuld, der bliver destilleret I trædistillatorer, der er en gammel og udfordrende måde at lave rom på i British Guyana. Denne metode giver rommen en utrolig fylde allerede ved endt destillation - en fylde, der ikke vil være mulig at fremhæve uden trædestillatorerne. Derfor får rommen en ekstraordinær start, som overgår alt destilleret i metal. Pusser''s British Navy Blue Label Rum 40% er meget velegnet til en Painkiller Cocktail, hvor følgende opskrift kan anvendes: 2 dele Pusser''s rom 1 del kokosnød creme 4 dele ananas juice 1 del appelsin juice. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pusser''s Gunpowder Proof 54,5% Rom', 'https://rombo.dk/products/pussers-gunpowder-proof-rum-54-black', 299, true, 70, 54.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Pusser_s_Gunpowder_Proof_54_5_Rom.png?v=1787053847', 'Pusser''s British Navy Gunpowder Proof Black Label Rum navnet henviser til, at de 54,5% var nok til at man kunne antænde rommen med krudt, og dermed var den stærk nok = Gunpowder Proof (der står også "original admiralty strength" på flasken). Pusser''s British Navy Gunpowder Proof Rum har noter af bl.a. melasse, toffee, honning, vanilje, egetræ, kanel, muskatnød og ingefær, og smagen/eftersmagen er fyldig og lang. Rom fra Guyana - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pusser''s Night Watch Black Strap Rum', 'https://rombo.dk/products/pussers-night-watch-black-strap-rum', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Pusser_sRumNightWatchBlackStraprom.png?v=1775653138', 'Pusser''s Night Watch Black Strap Rum er - lige som resten af Pusser''s romserien - en hyldest til den historiske romtradition og særligt til sømændene, der drak rom i den britiske flåde (indtil 1970). Denne særlige Pusser''s Night Watch er et blend af klassisk Guyana rom og af amerikansk rom lavet på Black Strap melasse fra Louisiana. Dette giver en helt særlig smag, der er præget af lakridsagtige noter. Rommen er mellemsød. Limited Edition. 40% abv - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pusser''s Rum Founder''s Reserve Limited Edition rom', 'https://rombo.dk/products/pussers-rum-founders-reserve-limited-edition-rom', 699, true, 70, 47.75, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/PussersRumFoundersReserverom.png?v=1793718708', 'Pusser''s Rum Founder''s Reserve er en "British Navy" rom, der indeholder destillater fra Guyana, Trinidad og British Virgin Islands. Kombinationen bidrager til rommens mange noter. Blended indeholder sjældne og eftertragtede dråber fra det legendariske og lukkede Caroni-destilleri i Trinidad, hvilket tilføjer en helt unik dybde og kompleksitet, som sjældent findes i dag. De historiske Caroni-komponenter er flot blendet med klassisk Demerara-stil fra Guyanas berømte Port Mourant Double Wooden Pot Still og en klassisk navy-profil fra Callwood-destilleriet i British Virgin Islands. Pusser''s Rum Founder''s Reserve udkommer i en begrænset mængde og er en fejring af, at grundlæggeren af Pusser''s Rum, Charles Tobias, i 1979 overtalte British Royal Navy til at overtage opskrifterne på de historiske rom. Charles Tobias var gik desværre bort i oktober 2025, og denne Founder''s Reserve udgave er en hyldest til ham. Som der står på flasken: "We raise a glass to a life lived without limits". Limited edition med 6.652 flasker til det globale marked. 47,75% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pusser''s Rum Select Age 151 75,5%', 'https://rombo.dk/products/pusser-s-rum-select-age-151-overproof', 435, true, 70, 75.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ad6278b1-d22b-440b-9da3-3bcddd822255.png?v=1769424973', 'Pusser''s Rum Select Age 151 Overproof rom på hele 75,5% er fra Diamond Distillery i Guyana. Rommen er inspireret af den gamle "sømandsrom", som man dagligt fik rationeret i The British Navy fra midten af 1600-tallet og helt frem til Black Tot Day den 31. juli 1970, hvor udskænkningen stoppede. Pusser''s Rum Select Age 151 Overproof minder om den rom, der dengang blev leveret i fadstyrke til Royal Navy værfterne i Deptford, Devonport og Gosport. Pusser''s Rum Select Age 151 Overproof er lagret i minimum 3 år på 1st fill ex-bourbonfade og har en duft af bl.a. marmelade, marcipan, kanel og tobak. I smagen finder man bl.a. noter af sirup, krydderier, frugt, læder, rosiner, egetræ og engelsk lakrids. 75,5% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pyrat XO Reserve', 'https://rombo.dk/products/pyrat-xo-reserve', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c504d759-c325-448d-a3dc-518c368ed347.png?v=1769421046', 'Pyrat XO Reserve Spirit Drink er en sukkerrørsspiritus fra Caribien. De anvendte destillater kommer ikke fra et bestemt land, men fra udvalgte fade fra forskellige destillerier fra forskellige øer i Caribien. Pyrat XO Reserve har lagret på franske limousin og amerikanske egetræsfade efter solera-metoden. Væsken har en gylden farve med et blidt skær. Duften er blød og sød, med friske Grand Marnier-agtige noter af appelsin, men også noter af vanilje, karamel og kanel. Smagen er fyldig med nuancer af røget fad, melasse og appelsin. En behagelig og sødmefuld sukkerrørsspiritus. 40% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Quorhum Encanto 13 Artisanal Rum', 'https://rombo.dk/products/quorhum-encanto-13-artisanal-rum', 499, false, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/QuorhumRumEncanto13Artisanalrom.png?v=1771943936', 'Da Casa Oliver i 2013 lancerede deres Ron Quorhum (QRM) serie med udgaverne 12, 15, 23 og især Quorhum 30, så "eksploderede salget" fuldstændigt, og serien var i mange år derefter en af de mest solgte indenfor datidens rom-kategori. Der er sidenhen kun kommet et par sporadiske lanceringer, men nu sker der langt om længe noget på QRM igen. Quorhum 2026-serien indeholder bl.a. denne Encanto 13 Artisanal Rum, der kombinerer rom fra Colombia og rom fra Venezuela. Den colombianske rom har karakter og dybde, mens den venezuelanske rom tilfører blødhed og elegance. Rommen er baseret på både yngre og ældre romdestillater af forskellige art – såvel kraftigere som lettere typer. Quorhum Encanto 13 indeholder op til 13 år gamle romdestillater, der er modnet i ex-rye whiskeyfade af amerikansk egetræ. Quorhum Encanto er en harmonisk blanding, der indfanger essensen af Colombia og Venezuela. Duften byder på delikate sukkerrør og den søde tiltrækning af honning og vanilje. I smagen finder man bitter chokolade, sukkerrør, egetræ, bitter kaffe, vanilje og fyldig melasse.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Quorhum Fundador 30 Aniversario Artisanal Rum', 'https://rombo.dk/products/quorhum-fundador-30-aniversario-artisanal-rum', 899, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/QuorhumRumFundador30AniversarioArtisanalrom_ab1b6c70-0da6-4fd9-a80e-1c1c2a920539.png?v=1772013990', 'Da Casa Oliver i 2013 lancerede deres Ron Quorhum (QRM) serie med udgaverne 12, 15, 23 og især Quorhum 30, så "eksploderede salget" fuldstændigt, og serien var i mange år derefter en af de mest solgte indenfor datidens rom-kategori. Der er sidenhen kun kommet et par sporadiske lanceringer, men nu sker der langt om længe noget på QRM igen. Quorhum 2026-serien indeholder bl.a. denne Fundador 30 Aniversario Artisanal Rum, der er et blend af rom fra Den Dominikanske Republik, Colombia, Venezuela og Cuba. Det unikke produkt bringer de fire romtraditioner sammen, der har formet Casa Olivers karakter – dominikansk, colombiansk, venezuelansk og cubansk – all in one. Rommen er baseret på både yngre og ældre romdestillater af forskellige art – såvel kraftigere som lettere typer. Quorhum Fundador 30 indeholder op til 30 år gamle romdestillater, der er modnet i ex-rye whiskeyfade af amerikansk egetræ. Quorhum Fundador 30 Aniversario Artisanal Rum duften byder på cremet vanilje, honning, peber, melasse, sukkerrør, ahornsirup og frugtige noter. I smagen finder man vanilje, ahornsirup, let kaffe og tobak.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Quorhum Orígenes 24 Artisanal Rum', 'https://rombo.dk/products/quorhum-origenes-24-artisanal-rum', 699, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/QuorhumRumOrigenes24Artisanalrom_7b48a08a-34d7-4566-9cfb-d08cf44bf9a5.png?v=1772013899', 'Da Casa Oliver i 2013 lancerede deres Ron Quorhum (QRM) serie med udgaverne 12, 15, 23 og især Quorhum 30, så "eksploderede salget" fuldstændigt, og serien var i mange år derefter en af de mest solgte indenfor datidens rom-kategori. Der er sidenhen kun kommet et par sporadiske lanceringer, men nu sker der langt om længe noget på QRM igen. Quorhum 2026-serien indeholder bl.a. denne Orígenes 24 Artisanal Rum, der er et blend af dominikansk, colombiansk, venezuelansk og cubansk rom. Hvert land bidrager med noget særligt til Quorhum Orígenes 24 rommen: dominikanernes delikatesse og blødhed, colombianernes intensitet og rigdom, venezuelanernes elegance og lethed og cubanernes robusthed og kompleksitet. Rommen er baseret på både yngre og ældre romdestillater af forskellige art – såvel kraftigere som lettere typer. Quorhum Orígenes 24 indeholder op til 24 år gamle romdestillater, der er modnet i ex-rye whiskeyfade af amerikansk egetræ. Quorhum Orígenes duften byder på friskbrygget kaffe, chokolade, vanilje, mynte, honning og frugtige undertoner. I smagen finder man vanilje, egetræ, kaffe, chokolade og tobak.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Quorhum Port Cask Limited Edition rom', 'https://rombo.dk/products/quorhum-port-cask-limited-edition', 299, true, 50, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2676fd7b-3e24-48f5-baaf-f24f9b74de6d.png?v=1769439740', 'Quorhum Port Cask Limited Edition rom er en (re)lancering fra det tidligere så storsælgende Quorhum mærke (også kaldet QRM). Det er efterhånden mange år siden, at Quorhum 30 tog Danmark med storm, så det er skønt, at der endeligt sker noget igen. Den nye Quorhum Port Cask Limited Edition er en 50 cl. rom, der er lavet eksklusivt til det danske marked. Oliver Rums i Den Dominikanske Republik står fortsat bag, og de har givet denne QRM rom en efterlagring på brugte portvinsfade, hvilket har bidraget til de søde og frugtige noter. Når man dufter og smager, så byder denne rom på noter af moden frugt, karamelliseret sukker, vanilje, hedvin og egetræskrydderier. Begrænset udgivelse til det danske marked. 40% - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Quorhum Terra Nova 16 Artisanal Rum', 'https://rombo.dk/products/quorhum-terra-nova-16-artisanal-rum', 549, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/QuorhumRumTerraNova16Artisanalrom_26c7e890-9707-45eb-bbdc-205bee86a621.png?v=1772013809', 'Da Casa Oliver i 2013 lancerede deres Ron Quorhum (QRM) serie med udgaverne 12, 15, 23 og især Quorhum 30, så "eksploderede salget" fuldstændigt, og serien var i mange år derefter en af de mest solgte indenfor datidens rom-kategori. Der er sidenhen kun kommet et par sporadiske lanceringer, men nu sker der langt om længe noget på QRM igen. Quorhum 2026-serien indeholder bl.a. denne Terra Nova 16 Artisanal Rum, der kombinerer rom fra Cuba, Venezuela og Colombia. Denne rom forener den kraftfulde cubanske stil, de rige colombianske noter og den lette, elegante rom fra Venezuela. Rommen er baseret på både yngre og ældre romdestillater af forskellige art – såvel kraftigere som lettere typer. Terra Nova 16 indeholder op til 16 år gamle romdestillater, der er modnet i ex-rye whiskeyfade af amerikansk egetræ. Quorhum Terra Nova 16 er en harmonisk rom-blanding, der indfanger essensen af Cuba, Colombia og Venezuela. Duften byder på egetræ, nødder og modne frugter. I smagen finder man egetræskrydderier, lette frugtnoter, karamel og vinøse drue-noter.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('R.L. Seales 10 års Rom', 'https://rombo.dk/products/rl-seales-rum-10-ex', 399, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_de37e155-810c-4c93-9ba9-eafa05f8b019.png?v=1769420719', 'R.L. Seales 10 års bliver lavet af Foursquare Rum Distillery og den legendariske Richard Seale på Barbados, og destilleriet står bl.a. også bag Doorly''s rom-serien . R.L. Seales 10 års rommen har en duft af overmoden banan, frugtcocktail, sødme, melon, ananas, vanille, tørrede abrikoser og figner. Smag: fad, syrlig, varmende, krydderi, god sødme til sidst. Eftersmagen byder på olieagtig melasse, krydderi, kanel og af god længde. Bemærk, at denne udgave har en lidt højere alkoholstyrke end den tidligere udgave på 43%. 46% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Oloroso Cask Finish Limited Edition Rum - inkl. 2 tumbler glas', 'https://rombo.dk/products/rammstein-oloroso-cask-finish-limited-edition-rum-inkl-2-tumbler-glas', 599, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RammsteinRumOlorosoCaskFinishmglas.png?v=1788336638', 'Rammstein Oloroso Cask Finish Rum er en unik blanding af rom fra Jamaica, Guyana og Trinidad, som har lagret op til 12 år i ex-bourbon-fade. Denne begrænsede udgave har fået en ekstra lagring i 32 måneder på ex-Oloroso sherryfade. Resultatet er en fyldig og intens rom med noter af tørret frugt, ristede nødder, mørk chokolade og varme krydderier fra Oloroso-fadene. Rammstein Oloroso Cask Finish Rum er den seneste Limited Edition rom fra bandet Rammstein, der blev grundlagt i 1994 og idag er et af verdens største rockbands. Rammstein er kendt for kæmpe shows med masser af pyroteknik og mørk stemning. I anledning af deres 25-årige jubilæum udgav bandet deres første Rammstein Rum. Siden har de udgivet både vodka, whisky, gin og stout, og er nu klar med denne Limited Edition rom. I duften finder man fyldige aromaer af tørret frugt, ristede nødder, appelsinskal og varme krydderier. Smagen er fyldig og intens med noter af rosiner, mørk chokolade, karamel og ristede nødder. BEMÆRK : der medfølger 2 stk officielle Rammstein glas pr. flaske, som du bestiller. 46% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum', 'https://rombo.dk/products/rammstein-rum', 375, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rammstein_Rum.png?v=1787141087', 'Rammstein Rum er fra fra bandet Rammstein, der blev grundlagt i 1994 og idag er et af de mest berømte rockbands i hele verden. De er kendte for kæmpe shows med masser af pyroteknik og mørk stemning. I anledning af deres 25-årige jubilæum tog Rammstein på turné i 2019, hvor de bl.a. spillede koncert i København. For at forkorte ventetiden udgav bandet deres første Rammstein Rum. Denne rom er en afbalanceret blanding af jamaicansk og guyanesisk potstill rom og kolonnerom fra Trinidad. Både guyanesisk og jamaicansk rom er højt værdsat blandt masterblendere og eksperter for sin kraftige krop og dybe aromaer. De stærke karakterer i begge potstill rom er tæmmet af den elegante natur af den trinidadiske partner. Rammstein Rum modnes i ex-Bourbon fade i op til 12 år. En afbalanceret rom med krydrede aromaer, lette frugtnoter og et hint røg. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum Limoux Cask Finish rom', 'https://rombo.dk/products/rammstein-rum-limoux-cask-finish-rom', 599, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_024e40e2-097a-429f-8e79-6c78193c7850.png?v=1769438013', 'Rammstein Rum Limoux Cask Finish er en unik blanding af rom fra Jamaica, Guyana og Trinidad, som har lagret op til 12 år i ex-bourbon-fade. Denne begrænsede udgave har fået en ekstra lagring i 28 måneder på ex-Limoux vinfade. Resultatet er en frugtagtig rom med elegante noter af sprøde æbler, druer og vanilje fra fadene. Denne udgave er begrænset til 6.100 flasker. Rammstein Rum Limoux Cask Finish rom er den seneste romudgivelse fra bandet Rammstein, der blev grundlagt i 1994 og idag er et af verdens største rockbands. Rammstein er kendte for kæmpe shows med masser af pyroteknik og mørk stemning. I anledning af deres 25-årige jubilæum udgav bandet deres første Rammstein Rum. Siden har de udgivet både vodka, whisky, gin og stout, og er nu klar med denne romudgivelse. I duften finder man bl.a. tropiske frugter med et funky twist, suppleret med grønne æbler og et strejf af eg og krydderi. Smagen er elegant og frugtig med noter af sprøde æbler og saftige druer. Den afsluttes med en langvarig eftersmag af modne frugter og cremet vanilje. Limited Edition. 46% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum Port Cask Finish', 'https://rombo.dk/products/rammstein-rum-port-cask-finish-rom', 599, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_763dee00-6c19-4a3c-9f38-f0e37ac2cb30.png?v=1769434267', 'Rammstein Rum Port Cask Finish rom er den seneste romudgivelse fra bandet Rammstein, der blev grundlagt i 1994 og idag er et af verdens største rockbands. Rammstein er kendte for kæmpe shows med masser af pyroteknik og mørk stemning. I anledning af deres 25-årige jubilæum udgav bandet deres første Rammstein Rum. Siden har de udgivet både vodka, whisky, gin og stout, og er nu klar med denne romudgivelse, Rammstein Rum Port Cask Finish rom, der er en limited edition rom udgivet i efteråret 2022. Rommen er et blend af rom fra Jamaica, Guyana og Trinidad, der har lagret i op til 12 år og har fået en 11 måneders finish på tidligere portvinsfade. Rommen har delikate duftnoter af modne, røde bær og stenfrugter som kirsebær, blommer og brombær med et strejf af egetræ. Smagen er frugtig med noter af tørret tobak, mørk chokolade og egetræ. Begrænset udgivelse på 9.378 flasker. 46%­ – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum PX Sherry Cask Finish limited edition rom', 'https://rombo.dk/products/rammstein-rum-sauternes-finish-limited-edition-rom-copy', 599, true, NULL, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RammsteinRumPXCaskSherryFinishrom.png?v=1772635602', 'Denne Rammstein Rum PX Sherry Cask limited edition rom er en unik blanding af tropiske rom fra Jamaica, Guyana og Trinidad, der er lagret op til 12 år. Derefter har den fået en ekstra lagring i 5 måneder på Pedro Ximenez sherryfade. Resultatet er en frugtrig og aromatisk rom med tørre vanilje-noter fra bourbonfadet og sødmefulde rosiner og mørke bær fra sherryfadene. Udgivelsen af Rammstein Rum Sauternes Finish 2025 er begrænset til 1.930 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum Sauternes Cask Finish', 'https://rombo.dk/products/rammstein-rum-sauternes-cask-finish-rom', 499, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a1cddbc5-cede-4991-b36c-520bf119b9be.png?v=1769426038', 'Rammstein Rum Sauternes Cask Finish rom er fra bandet Rammstein, der blev grundlagt i 1994 og idag er et af de mest berømte rockbands i hele verden. De er kendte for kæmpe shows med masser af pyroteknik og mørk stemning. I anledning af deres 25-årige jubilæum tog Rammstein bandet på turné i 2019, hvor de bl.a. spillede koncert i København, og inden da udgav bandet deres første Rammstein Rum. Siden har de udgivet både vodka, whisky, gin og stout, og er nu klar med deres fjerde romudgivelse, Rammstein Rum Sauternes Cask Finish, der er en limited edition rom udgivet i foråret 2022. Hvor de tidligere romudgaver fra Rammsteins har fået finish på hhv. Islay whisky-fade og cognacfade, har denne udgave fået sin finish på sauternesfade. Rammstein Rum Sauternes Cask Finish dufter af brun farin og melasse, med hints af valnødder, appelsin og honning. Smagen er frugtig, med syrlige noter af citrusfrugter som kumquats og appelsiner. 46%­ – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum Sauternes Finish limited edition rom', 'https://rombo.dk/products/rammstein-rum-sauternes-finish-2025', 599, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ee86fb71-48c4-4111-8298-4592ee82be47.png?v=1769439442', 'Denne Rammstein Rum Sauternes Finish 2025 limited edition rom er en unik blanding af tropiske rom fra Jamaica, Guyana og Trinidad, der er lagret op til 12 år. Derefter har den fået en ekstra lagring i 39 måneder på ex-Sauternesfade. Resultatet er en frugtrig rom med sødmefulde noter af gylden honning, blød karamel og modne frugter fra Sauternes-fadene. Udgivelsen af Rammstein Rum Sauternes Finish 2025 er begrænset til 6.085 flasker til det globale marked. Når man dufter til rommen, fornemmes forførende aromaer af mørk melasse, frisk citrus og solmodne, tørrede abrikoser. Smagen er rund og fyldig med sødmefulde noter af gylden honning, blød karamel og saftige, modne frugter. 46% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Renegade Cane Rum Pre Cask Dunfermline Column Still', 'https://rombo.dk/products/renegade-rum-pre-cask-dunfermline-column-still', 465, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Renegade_Cane_Rum_Pre_Cask_Dunfermline_Column_Still.png?v=1770199572', 'Renegade Rum Pre Cask Dunfermline Column Still er blandt de første 5 pre-cask aftapninger fra Renegade Rum Distillery på den caribiske ø Grenada. Bag brandet står Mark Reynier, der er kendt for sin innovative og ambitiøse tilgang til spiritus. Han har taget terroir-tanken, som man kender fra vin, med ind i romproduktionen og inddelt rommen alt efter, hvilken type sukkerrør, den er lavet på, og hvor sukkerrørene har groet. Bag på hver flaske er der således en CaneCode, der fortæller om sukkerrørstype, destilleringsapparat og specifikke vejr- og jordbundsforhold, der har været med til at give rommen karakter. Rommens egenart kan smages i denne rå, pre-cask romudgivelse, der ikke har modnet på fad. Renegade Rum Pre Cask Dunfermline Column Still er lavet på sukkerrør af typen Lacalome Red, der udelukkende har vokset på marken Skean’s Field. Rommen har en meget botanisk karakter med noter af hø, tomatstængler og colanød. 50%- 70.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Renegade Cane Rum Pre Cask Dunfermline Pot Still', 'https://rombo.dk/products/renegade-rum-pre-cask-dunfermline-pot-still', 465, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Renegade_Cane_Rum_Pre_Cask_Dunfermline_Pot_Still.png?v=1770199673', 'Renegade Rum Pre Cask Dunfermline Pot Still er blandt de første 5 pre-cask aftapninger fra Renegade Rum Distillery på den caribiske ø Grenada. Bag brandet står Mark Reynier, der er kendt for sin innovative og ambitiøse tilgang til spiritus. Han har taget terroir-tanken, som man kender fra vin, med ind i romproduktionen og inddelt rommen alt efter, hvilken type sukkerrør, den er lavet på, og hvor sukkerrørene har groet. På bagsiden af hver flaske er der således en CaneCode, der fortæller om sukkerrørstype, destilleringsapparat og specifikke vejr- og jordbundsforhold, der har været med til at bestemme rommens karakter. Rommens egenart kan smages i denne rå, pre-cask romudgivelse, der ikke har modnet på fad. Renegade Rum Pre Cask Dunfermline Pot Still er fra Anderson’s Field-marken i terroiret Mango Lane, der ligger ved bjergene på øens nordvestlige kyst, hvor man har dyrket sukkerrør i århundreder. Renegade Rum Pre Cask Dunfermline Pot Still er udelukkende lavet på sukkerrørstypen Lacalome Red og har masser af frugt, fylde og krydderier med noter af rose, koriander og havvand. 50%- 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Renegade Cane Rum Pre Cask New Bacolet Pot Still', 'https://rombo.dk/products/renegade-rum-pre-cask-new-bacolet-pot-still', 465, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e7f10ff5-4eee-457e-accc-20dd7f1305ff.png?v=1769426133', 'Renegade Rum Pre Cask New Bacolet Pot Still er en af de første 5 pre-cask aftapninger fra Renegade Rum Distillery på den caribiske ø Grenada. Bag brandet står Mark Reynier, der er kendt for en innovativ og ambitiøs tilgang til spiritus. Han har taget terroir-tanken, som man kender fra vin, med ind i romproduktionen og inddeler rommen alt efter hvilken type sukkerrør, den er lavet på, og hvor sukkerrørene har groet. På bagsiden af hver flaske finder man således en CaneCode, der fortæller om sukkerrørstype, specifikke vejr- og jordbundsforhold samt destilleringsapparat, der er med til at bestemme rommens karakter. Rommens egenart kan smages i denne pre-cask, rå romudgivelse, der ikke har modnet på fad. Renegade Rum Pre Cask New Bacolet Pot Still er fra terroiret Upper Combe, helt specifikt marken Goat Hill, der ligger på en solbeskinnet, sydvendt skråning. Rommen kommer fra den tørkeresistente sukkerrørstype Lacalome Red og har en elegant frugtighed med noter af vanilje, peber og rå kakao. 50%- 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Renegade Cane Rum Pre Cask Pearls Pot Still', 'https://rombo.dk/products/renegade-rum-pre-cask-pearls-pot-still', 465, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Renegade_Cane_Rum_Pre_Cask_Pearls_Pot_Still.png?v=1770200016', 'Renegade Rum Pre Cask Pearls Pot Still er en af de første 5 pre-cask aftapninger fra Renegade Rum Distillery på Grenada. Bag brandet står Mark Reynier, der både har en innovativ og ambitiøs tilgang til spiritus. Han har taget terroir-tanken, som man kender fra vin, med ind i romproduktionen, således at rommen flaskes alt efter, hvilken type sukkerrør, den er lavet på, og på hvilken farm sukkerrørene har groet. Bag på hver flaske finder man derfor en CaneCode, der fortæller alle detaljer om sukkerrørstype, destilleringsapparat og specifikke vejr- og jordbundsforhold, der har været med til at bestemme rommens karakter. Rommens egenart kan smages i denne pre-cask rom, rå rom, der endnu ikke er modnet på fad. Renegade Rum Pre Cask Pearls Pot Still kommer fra Grapefruitmarken i det kystnære terroir Flats, hvor der er lerholdig jord og rigeligt med vand. Rommen er udelukkende lavet på sukkerrørstypen Yellow Lady og har stor og fyldig smag med noter af blandt andet brændt banan, trøffelolie, røget paprika og peber. 50%- 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rhum J.M VSOP Vieux Agricole Rom', 'https://rombo.dk/products/rhum-jm-vsop-vieux-agricole-rom', 435, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9e114d22-d127-4ea3-81e0-c098db17737d.png?v=1769421624', 'Rhum J.M VSOP Vieux Agricole har det reneste kildevand fra Mount Pelée som en vigtig ingrediens. Efter gæringen foregår destilleringen i 2 "Creole" kobber kolonnedestilleringsapparater, der fremstiller 65-75% rom-destillater, der herpå lagres i forkullede ex-bourbon egetræsfade. Rhum J.M VSOP Vieux Agricole rommen har en duft af egetræ, stenfrugter, krydderier og ristet kaffe. Smagen har noter af krydderier, vanille, kanel, og tørrede frugter. Lang og fløjsagtig eftersmag. Rhum J.M VSOP Vieux Agricole har påført tappedato bagpå rom-flasken, og den er særlig populær hos dem, der også kan lide en god whisky eller brandy. 43% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rhum J.M XO Vieux Agricole Rom', 'https://rombo.dk/products/rhum-jm-xo-vieux-agricole-rom', 599, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_782d7647-7f24-41cb-b4a9-1f6e501723f6.png?v=1769421957', 'Rhum J.M XO Vieux Agricole har det reneste kildevand fra Mount Pelée som en vigtig ingrediens. Efter gæringen foregår destilleringen i 2 "Creole" kobber kolonnedestilleringsapparater, der fremstiller 65-75% rom-destillater, der siden lagres i forkullede ex-bourbon egetræsfade. Rhum J.M XO Vieux Agricole rommen har en intens og sød duft med noter af krydderier og eksotiske frugter. Smagen er rund og frisk med noter af frugttærte og krydderier. Lang og blød eftersmag med vedholdende krydderier. Rhum J.M XO Vieux Agricole har påført tappedato bagpå rom-flasken, og den er særlig populær hos dem, der også kan lide en god whisky eller brandy. 45% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rom Julekalender 2026', 'https://rombo.dk/products/rom-julekalender-2026', 649, true, NULL, 42.37, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Julekalender2026Rom.png?v=1790161046', 'Rom Julekalenderen 2026 indeholder 24 forskellige produkter, og der er repræsentanter fra de 3 stilarter: Britisk, Fransk og Spansk. Du finder både sød rom, mellemsød rom og naturlig rom i blandt flaskerne. Kalenderen byder dermed på noget for enhver smag, noget for begynderen og noget for den erfarne. Udover at nyde de skønne flasker, så åbner der sig hver dag i december også en låge i den virtuelle kalender, så du kan se beskrivelser og information om dagens produkt. Du skal bare følge linket via QR-koden på undersiden af kalenderen, og så er du inde i universet. Kalenderen indeholder 24 x 2 cl. flasker med en gennemsnitlig alkoholprocent på 42,37% vol. Hvis du på forhånd ønsker at vide, hvad der gemmer sig i kalenderen i vilkårlig rækkefølge, så kan du se listen herunder (og hvis du ikke vil vide det på forhånd, må du hellere stoppe med at læse videre :) Her er indholdet i alfabetisk rækkefølge: Abuelo 12 år Anejo Gran Reserva - Panama Abuelo 7 år Anejo Reserva Superior - Panama Abuelo XII Anos "Three Angels" Abuelo XII Anos "Two Oaks" Abuelo XV Finish Collection Napoleon Doorly''s Fine Old Rum 14 YO Barbados Dos Maderas Atlantic Dos Maderas Caribbean Seleccion Triple Aged Rum Kirk &amp; Sweeney Rum - Gran Reserva Kirk &amp; Sweeney Rum - Reserva Pusser''s British Navy Rum (Blå) Pusser''s British Navy Rum Gunpowder Proof Spiced 54,5% RL Seales Barbados rum 10 år 46% Ron Cueva 1501 - Sistema 12 - Panama Ron Cueva 1501 - Sistema 18 - Panama Ron Millonario XO Reserva Espicial fra Peru Rum Nation - Dominicana 8 YO Rum Nation - Guatemala XO Rum Nation - Mauritius 6 YO Rum Nation - Panama 18 år Rum Nation - Panama 21 år Rum Nation - Mauritius 8 år Cask Strength Rum St. Etienne Martinique Rhum Vieux VO St. Etienne Martinique Rhum Vieux XO');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rombo Exclusive Cask Rum Australia KLK Virgin Oak', 'https://rombo.dk/products/rombo-exclusive-cask-rum-australia-klk', 499, true, 50, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rombo_Exclusive_Cask_Rum_Australia_KLK_Virgin_Oak.png?v=1772185852', 'Vores 50 liters Virgin Oak fad er endelig klar til at blive aftappet, og det vil foregå den 17. maj, hvor man kan komme forbi Rombo butikken på Frederiksberg i åbningstiden (kl. 10-15) for at smage den unikke Rombo Exclusive Cask Rum Australia KLK Virgin Oak, og hvor flasken også sættes til salg online kl. 10 til alle andre. Den 16. august 2024 fyldte vi fadet med en vanvittig lækker og fræk ulagret rom fra Killik destilleriet - marque KLK - i Australien. Masser af funky intensitet og jordbær-noter. Efter de 9 måneders lagring er der sket en revolution, og det lille Virgin Oak fad har på kort tid forvandlet rommen til en mørk og vellagret smagsbombe. Jordbærnoten er der stadig i baggrunden, men nu er rommen også fyldt med skønne, krydrede og vaniljefyldte fadnoter. Den 17. maj 2025 kl. 10.00 begynder vi at tappe Rombo Exclusive Cask Rum Australia KLK Virgin Oak flasker i butikken, og det fortsætter vi med indtil kl. 15.00 eller så længe haves. Limited edition. 75 flasker. 50% - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rombo Exclusive Cask Rum Jamaica TECC', 'https://rombo.dk/products/rombo-exclusive-cask-rum-jamaica-tecc', 499, true, 50, 65, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rombo_Exclusive_Cask_Rum_Jamaica_TECC.png?v=1771946849', 'Rombo Exclusive Cask Rum Jamaica TECC er en funky, udfordrende og naturlig (ikke sød) høj-ester rom fra vores eget 50 liters fad i Rombo butikken på Frederiksberg. Den 3. juni 2025 fyldte vi vores 50-liters fad med ulagret Jamaica TECC rom ved 65% abv. Fadet har tidligere indeholdt Killik KLK rom fra Australien, og inden da var det et "virgin oak" fad, så der er teknisk set tale om et 2nd-fill virgin oak fad / 1st-fill KLK romfad. Vi prøvesmagte løbende Jamaica TECC fra fadet, og da vi ønskede, at denne rom skulle være ung og rå, så nåede den at lagre i lidt over 6 måneder i dette helt unikke fad, inden den var klar. Limited edition. 85 flasker. 65% - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rombo Exclusive Cask Rum Panama 12 år', 'https://rombo.dk/products/rombo-exclusive-cask-rum-panama', 499, true, 50, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rombo_Exclusive_Cask_Rum_Panama_12_ar_40_L_PX_Cask.png?v=1771946883', 'Rombo Exclusive Cask Rum Panama 12 år er en skøn, naturlig (ikke-sød) og kompleks rom fra vores eget 40 liters fad i Rombo butikken på Frederiksberg. Den 25. marts 2025 fyldte vi vores 40-liters fad med Panama 12-års rom ved 50% abv. Fadet har tidligere indeholdt Venezuela rom og inden da sherry, så der er teknisk set tale om et 2nd-fill sherryfad / 1st-fill (Venezuela) romfad. Panama-rommen når således at få 8½ måned ekstra i dette helt unikke fad. Vi har løbende prøvesmagt fra fadet, og nu er Rombo Exclusive Cask Rum Panama 12 års rommen klar til at blive aftappet. Det vil foregå lørdag den 13. december, hvor man kan komme forbi Rombo butikken på Frederiksberg i åbningstiden (kl. 10-15) for at smage den helt unikke rom, og hvor flasken også sættes til salg online kl. 10 til alle andre. Flaskerne vil blive tappet på selve dagen. Bemærk for god ordens skyld, at flaskerne sælges så længe lager haves, og at der kun kan smages i butikken. så længe der er noget tilbage i fadet. Limited edition. 57 flasker. 50% - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rombo Reserve Dominican Batch IV', 'https://rombo.dk/products/rombo-reserve-dominican-batch-iv', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rombo_Reserve_Dominican.png?v=1787050099', 'Rombo Reserve Dominican Batch IV er den fjerde udgave i Rombo''s helt egen Reserve-serie. Vi har hos Rombo igennem mere end 8 år været kendte for vores friske og humoristiske skilte udenfor butikken, og temaet på etiketten er derfor et print af tidligere populære skilte, som vi har haft. Denne gang hedder skiltet: "Take Life One Sip at A Time". Rombo Reserve er en serie af sød, sukkerrørsbaseret spiritus, som ikke længere må hedde rom, når der mere end 20 gram sukker pr. liter i flasken. Denne Dominican Batch IV udgivelse har mere præcist en tilsætning på 40 gram sukker pr. liter, hvilket svarer til 4% af indholdet. Skiltet på etiketten er nyt, men ellers er Rombo Reserve Dominican Batch IV det samme indhold som Batch I, Batch II og Batch III: sød, blød og hyggelig, som de fleste foretrækker det. I blandt noterne finder man bl.a. créme brulée, karamel og tørret frugt (abrikos/figner). Der er tale om en dominikansk "spirit drink" fra AFD destilleriet, der har anvendt den friske sukkerrørsjuice ved gæring og destillering, hvorefter fadene er lagret i 8-12 år i amerikanske og franske egetræsfade. Der er kun lavet 96 flasker af denne Dominican Batch IV, og når disse er solgt, vil der efter planen blive lavet en Batch V med et nyt skilt på etiketten. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Australia Handcrafted New Make Rom', 'https://rombo.dk/products/romdeluxe-australia-handcrafted-new-make-rom', 599, true, 70, 84, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ac127859-8d1f-459e-ac4e-419b240a4434.png?v=1769436749', 'Australia Handcrafted Rum fra danske Romdeluxe er en "new make" hvid rom, der er ulagret, og som præsenteres ved fuld destillationsstyrke på 84% ABV. Den kommer fra Killik Handcrafted Rum, som er et destilleri, der er dedikeret til at skabe noget helt unikt inden for romverdenen. Killik Handcrafted Rum kommer fra et lidt uventet men spirende romscene i fuld gang: Belgrave, Victoria i Australien. Det er en familiedrevet destilleri, der sigter efter at udfylde et hul inden for australsk rom. De ønsker at skabe produkter, der ikke kun er af topkvalitet, men også er den mest unikke australske rom, man kan finde. De benytter en vild gæring for at skabe en høj esterkarakter kendt. Killik er det første dedikerede romdestilleri, der forpligter sig til denne traditionelt jamaicanske stil inden for romproduktion. Ligesom på Jamaica gør Killik også brug af Pot Still destillation. 84% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Collectors Series Rum No. 8 Dominican Republic', 'https://rombo.dk/products/collectors-series-dominican-republic-rum', 1195, true, 70, 65, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_58a93bb4-3dfd-4fb7-a230-6d5239d0e26c.png?v=1769425915', 'Den nye Collectors Series Dominican Republic rom bringer minderne tilbage til 2016, hvor RomdeLuxe udgav deres første rom-aftapning fra netop den Dominikanske Republik og netop ved 65%, som det også er tilfældet her. RomdeLuxe har derfor søgt efter en dominikansk rom-udgivelse, der var endnu bedre. Det mener man nu at have gjort med denne rom, der er kolonnedestilleret, melassebaseret og et blend af et 15 år gammelt tropisk rom, som er lagret på et ex-bourbon fad (80% af indholdet), samt noget så sjældent som en dominikansk højester-rom kaldet Aroma Grande (20% af blendet). Den nye Collectors Series Dominican Republic rom er tappet ved fadstyrke og findes i et begrænset antal på kun 592 flasker. 65% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Distillery Series Rum No. 3 Australia 2007', 'https://rombo.dk/products/romdeluxe-distillery-series-rum-no-3-australia', 1295, true, 70, 66.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_817098b2-5cd7-4b2a-86f9-51d0111b5364.png?v=1769437272', 'De første 2 udgaver i Distillery Series Rum fra Romdeluxe blev hurtigt udsolgt, og nu er de så klar med den 3. udgave. Distillery Series Rum No. 3 er destilleret hos et hemmeligt destilleri, der blev grundlagt i 1884 i Queensland, Australien, og det er faktisk Australiens ældste destilleri, der fortsat er i funktion. Destillery Series Rum No. 3 Australia er baseret på melasse og destilleret i 2007 i gamle, tradionelle pot stills. Efterfølgende har denne rom fra fad #34 lagret på brugte bourbonfade indtil aftapningen i april 2024. Den 16-årige rom har mærket "MAIC", hvilket nogenlunde svarer til "inner circle" af australsk rom. De 10 år af lagringen er foregået i Australien, og de 6 år er foregået i Europa. Duft og smag er på baggrund af fremstillingsprocessen og alkoholstyrken intens, rig, krydret og karakterfuld. Romdeluxe Distillery Series Rum No. 3 Australia rommen er tappet i kun 262 flasker ved fuld fadstyrke på 66,2% ABV. 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Dominican Republic New Make Rom Batch 1', 'https://rombo.dk/products/dominican-republic-new-make-batch-1-rom-93', 595, true, 50, 93, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9e5a24bc-2d48-46aa-960d-e13646ebc9a8.png?v=1769425978', 'Dominican Republic New Make 93% Batch 1 rom fra Romdeluxe er udover sin høje alkoholstyrke også kendetegnet ved et højt antal estere – ikke mindre end 474 ­– hvilket er et særsyn, når vi taler rom fra Den Dominikanske Republik. Dominican Republic New Make 93% Batch 1 rom er tænkt som en cocktailrom, der med garanti kan sparke en hvilken som helst drink op under loftet, men bør bruges med omtanke. 93% - bemærk: 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Guadeloupe Red Cane New Make Rom', 'https://rombo.dk/products/guadeloupe-red-cane-new-make-romdeluxe', 595, true, 70, 83, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_bab7027c-4456-47e9-8cca-66a92474915e.png?v=1769436283', 'Guadeloupe Red Cane fra danske Romdeluxe er en "new make" hvid rom, der er ulagret, som præsenteres ved fuld destillationsstyrke. Det er en rom som er lavet af frisk sukkerrørssaft. Saften kommer fra 3 forskellige typer af røde sukkerrør, som har vokset på en bjergsside med vulkansk jord, og derfor har optaget smag herfra. De tre typer af sukkerrør er hver især blevet presset, fermenteret og destilleret i en kolonne still. Den kommer fra destilleriet Montebello, og er deres premium blend, som er det absolut bedste de kan præstere. Den færdige rom bliver til sidst blendet af deres dygtige masterblender. Resultatet af dette store arbejde er i denne flaske. Duften af denne drik er domineret af friskklippet græs, akkompagneret af noter af citrus og modne frugter. På tungen kan man smage en jordagtig og let saltet profil, der bliver suppleret med en syrlig ribs-tone og afsluttes med en varm frugtig eftersmag. Der er fuld smæk for skillingen med en destillationsstyrke på 83% ABV. 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Kong Hjarne - Caribbean Rum', 'https://rombo.dk/products/kong-hjarne-caribbean-rum', 395, true, NULL, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_59566ce5-0460-43b2-a80f-1ad3cda6db2d.png?v=1769435510', 'Kong Hjarne - Caribbean Rum er fra Romdeluxes nye romserie ''Vikinger i Kystlandet'', som de har lavet i samarbejde med Destination Kystlandet og historiker Casper Clemmensen. Serien består af 3 rom, og denne rom hylder Kong Hjarne, som tog magten i Jylland. Han rejste sin vikingehal på Hjarnø, hvorfra han regerede sit rige. De to andre rom i serien hylder Kong Hjarnes kone, Dronning Alrune, og hans søn, Prins Endlau. Kong Hjarne - Caribbean Rum er et blend af rom fra Jamaica, Trinidad og Venezuela. Der er tale om rom i den søde ende af skalaen, dog med max. 20 gr. sukker pr. liter, men byder stadig på saft og kraft. Ved første indtryk indfanger næsen duften af ​​vanilje, brun farin, læder og overmoden tropisk frugt. Når rommen rammer munden, oplever man noter af peber, egetræ, vanilje, syltede ferskner, røde bær, brændt karamel og tørret frugt, som frembringer en kompleks og dyb smag. Den efterfølgende langvarige finish er præget af en varm krydret fornemmelse, med en subtil tilstedeværelse af muscovado sukker. Rommen er tappet ved 40% og flasken indeholder 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Le Galion Martinique New Make Rom Batch 2', 'https://rombo.dk/products/le-galion-martinique-rom-de-luxe-batch-2', 595, true, NULL, 59.1, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b790cb31-c9a8-4f28-8b25-dcb8976d98bd.png?v=1769436279', 'Le Galion Martinique fra danske Romdeluxe er en "new make" hvid rom, der er ulagret, melassebaseret og kolonnedestilleret. Det lille destilleri Le Galion på den franske Martinique er nok relativ ukendt fra de fleste, og man har med melasse og kolonnedestillering valgt at gå i en anden retning end det meste rom / Rhum Agricole, som man kender det fra Martinique. Denne flaske er batch 2. Denne Le Galion fra Rom de Luxe har dog også grønne friske noter og duft af friskhøstet hø. Der er kun fremstillet 80 flasker af denne Le Galion "Rhum Grand Arome", der kommer i små 50 cl stentøjsflasker, og der er fuld smæk for skillingen med de 59,1% ABV.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Limited Batch Series Ghana Rom', 'https://rombo.dk/products/limited-batch-series-ghana-romdeluxe', 795, true, 70, 60.3, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f65de167-3cc9-4807-b2f0-fa94f83d300a.png?v=1769424998', 'Limited Batch Series Ghana RomdeLuxe er den 5. rom i Limited Batch Series (LBS) serien fra den uafhængige aftapper RomdeLuxe, og denne lagrede Ghana rom er en opfølger til den hvide Ghana udgave, der tidligere udkom i samme serie. LBS rom-serien har som formål at udgive rom med helt eget særpræg til den nysgerrige romdrikker eller connaisseuren, der gerne vil prøve noget helt særligt i meget begrænset mængde. Limited Batch Series Ghana rom er en del af et udviklingsprojekt i Ghana, og rommen er lavet af den friskpressede sukkerrørsjuice samt pot still destilleret. Lagringen af Limited Batch Series Ghana RomdeLuxe er foregået i Danmark i et 130 liters American Virgin Oak fad, hvor rommen udviklede sig så hurtigt, at den var klar til aftapning allerede efter 7 måneder, og der er kun tappet i 188 eksemplarer ved fadstyrke. Duften byder på noter af bl.a. vanilje, læder, træ og toffee, imens smagen præges af mørke bær, Demerara sukker, læder og tobak. 60,3% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Limited Batch Series Nicaragua 21 års Rom', 'https://rombo.dk/products/limited-batch-series-nicaragua-21-ar-rom-61', 1395, true, 70, 61, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_cdee6a9a-1fc9-41cb-ac8f-77a46c5fbfe2.png?v=1769425711', 'Limited Batch Series Nicaragua 21 års rom er baseret på sukkerrørsmelasse og blev kolonnedestilleret i april 2000. Rommen har herefter lagret på tidligere bourbonfade i kontinentalt klima i 21 år. Den kontinentale lagring har medvirket til, at rommen på trods af sin høje alder har beholdt sin friskhed. Limited Batch Series Nicaragua 21 års er en naturlig rom, der ikke er tilsat sukker, og er tappet i november 2021 ved fadstyrke 61% ABV. Rommen kommer i meget begrænset oplag på bare 187 flasker. 61% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Limited Batch Series Panama 21 års Rom', 'https://rombo.dk/products/limited-batch-series-panama-21-romdeluxe', 895, true, 70, 57.18, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8b19ccd2-1fc5-4f01-9b19-b87a0f78a522.png?v=1769424730', 'Limited Batch Series Panama 21 år er den 3. rom i Limited Batch Series (LBS) serien fra den uafhængige aftapper RomdeLuxe. LBS rom-serien har som formål at udgive rom med helt eget særpræg til den nysgerrige romdrikker eller connaisseuren, der gerne vil prøve noget helt særligt i meget begrænset mængde. Limited Batch Series Panama 21 års rom er fra et "hemmeligt destilleri" i Panama, hvor rommen er tropisk lagret i 21 år i ex-bourbonfade. Duft: vanilje, mørk farin, tobak, læder og brændt egetræ. Smag: vanilje, brændt sukker, læder og peber. Der er tilsat 9,2 gram sukker/L i denne Limited Batch Series Panama 21 års rom, og der er kun tappet i 289 eksemplarer. 57,18% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe No. 3 White Rum Jamaica St. Catherine', 'https://rombo.dk/products/no-3-white-rum-jamaica-st-catherine', 395, true, 50, 65, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1d3d2f4f-1c29-48a0-9f39-4f7b9714e9b4.png?v=1769427454', 'No. 3 White Rum Jamaica St. Catherine er en hvid, ulagret rom fra Jamaica, der er baseret på melasse og destilleret på Forsyth pot still. Rommen har marque WPH og er en mildere rom med en estercount på 240-360. No. 3 White Rum Jamaica St. Catherine er den tredje udgivelse i Romdeluxes serie af hvide rom, der udgives som en del af Romdeluxes ’hvide romskole’, der skal kaste lys over egenskaber og kendetegn ved den ulagrede rom. Bagpå flasken finder man en QR-kode, der fører ind til Romdeluxes hvide romunivers, hvor man også finder opskrifter på lækre cocktails. 65% vol. - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Selected Series Rum Dominican Republic', 'https://rombo.dk/products/selected-series-rum-dominican-republic-rom-de-luxe', 395, true, 70, 41, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d0712e70-da9d-4914-85f2-2656bbdf8a59.png?v=1769423807', 'Denne Dominican Republic 5 års rom er den 2. rom i Selected Series Rum (SSR) serien fra den uafhængige aftapper Rom De Luxe. Den nye serie har som formål "at være fantastisk rom til en fornuftig pris". Selected Series Rum Dominican Republic er såkaldt spansk/cubansk stil, og det er en rom med noter af vanilje og mørk chokolade. Der er tilsat ca. 20 gr. sukker pr. liter, hvilket gør, at rommen bliver sød. Leveres i gaveæske. 41% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Wild Series Diamond 20 år Enmore MEE Unicorn rom', 'https://rombo.dk/products/wild-series-diamond-20-ar-enmore-mee-unicorn-rom', 1495, true, 70, 59.8, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_51339434-1df3-4172-8e1b-ce181f0eeb54.png?v=1769438140', 'Denne Wild Series Diamond 20 år Enmore MEE rom er en af de i alt 3 rom, der findes i det populære Wild Series Unicorn Coffret Set Vol. 2 fra Romdeluxe (en begrænset udgivelse på kun 195 sæt til Danmark). Sættet er samlet set så enestående, at det har fået navnet Unicorn – eller enhjørning - og vi har valgt at åbne et sæt, så man kan købe flaskerne hver for sig. Wild Series Diamond 20 år Enmore MEE single cask rom kommer fra den legendariske Enmore-kedel, som er det eneste tilbageværende kolonnedestilleringsapparat lavet af træ. Rommen har marque MEE og en ABV på 59,8%. 59,8% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Wild Series Origin No. 5 Guadeloupe Rom', 'https://rombo.dk/products/wild-series-origin-guadeloupe', 649, true, 70, 60, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2fef082b-b26d-4d1d-9912-5dc8604e1c00.png?v=1769436039', 'Wild Series Origin No. 5 Guadeloupe er en ulagret rom baseret på sukkerrørsjuice fra Montebello Distillery på Guadeloupe. Her laver de rom ifølge den franske romstil - også kendt som Rhum Agricole. Her er rommen baseret på frisk sukkerrørsjuice og destilleret i et Creole destilleringsapparat (enkelt kolonne still). Denne stil dominerer på de franske koloniøer, såsom Martinique, Reunion og Guadeloupe, selvom Guadeloupe også producerer melassebaseret rom. Romdeluxes Wild Series Rum Origin er en serie håndplukkede, ulagrede rom, der er særligt udvalgt på grund af deres kraftige smagsprofil. Wild Series Origin No. 5 Guadeloupe er tappet ved fadstyrke på 60% ABV og destilleret 2023, og den kan nydes ren eller i fantastiske cocktails. 60% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Wild Series Rum No. 57 Jamaica 2024 MAGNUM 150 cl', 'https://rombo.dk/products/wild-series-rum-no-57-jamaica-berlin-rumfest-magnum', 3895, true, 150, 84.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_74c0cba4-567a-41ef-8d88-65a1d8d0e76b.png?v=1769437880', 'Romdeluxe Wild Series Rum No. 57 Jamaica MAGNUM er en 2 år gammel rom og en særlig aftapning, der frigives ifm. 2024 Berlin Rumfest. Denne single cask rom er fremstillet hos et hæderkronet destilleri, der er kendt for sin høj-ester rom. Destilleriet har i processen anvendt sukkerrørsmelasse til gæringen, og herefter er rommen destilleret i en pot still, inden den er lagt på et amerikansk Virgin Oak fad (Cask 305, Marque HGML). Fadet har lagret kontinentalt og er afslutningsvist tappet hos Romdeluxe i Danmark. Romdeluxe Wild Series Rum No. 57 Jamaica MAGNUM 2024 Berlin Rumfest rom er en stærkt begrænset udgivelse på kun 45 flasker. 84,5% - 150 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Wild Series Rum No. 62 Barbados', 'https://rombo.dk/products/romdeluxe-wild-series-rum-62-barbados', 945, true, 70, 65, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_894ab8ea-2d3e-44ee-87be-dff0a29fca06.png?v=1769439366', 'Wild Series Rum No. 62 Barbados fra Romdeluxe er en single cask rom med fuld smæk for skillingen. Den melasse-baserede rom kommer fra West Indies Rum Distillery (WIRD) på Barbados, hvor den er blevet gæret og pot still destilleret. Herefter er lagringen foregået kontinentalt i et ex-bourbonfad i 7 år, inden den blev tappet på flaske i 2025. Der er kun lavet 213 flasker af denne Limited Edition enkeltfadsudgave med klassiske Barbados noter. 65% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Wild Series Rum No. 63 Martinique', 'https://rombo.dk/products/romdeluxe-wild-series-rum-63-martinique', 945, true, 70, 65.4, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b65d0be2-3baf-45ca-8ba2-ec53e5b925b6.png?v=1769439371', 'Wild Series Rum No. 63 Martinique fra Romdeluxe er en single cask rom med fuld intensitet. Rommen er lavet på den friskpressede sukkerrørsjuice og kolonnedestilleret, og den kommer fra et hemmeligt Martinique destilleri, der er kendt for sin franske Rhum Agricole. Lagringen er foregået kontinentalt i amerikanske egetræsfade i 7 år, inden den blev tappet på flaske i 2025. Der er kun lavet 258 flasker af denne Limited Edition Wild Series Rum No. 63 Martinique enkeltfadsudgave. 65,4% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Wild Series Rum No. 64 Trinidad 9 år', 'https://rombo.dk/products/romdeluxe-wild-series-rum-64-trinidad', 895, true, 70, 65.8, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d7111638-f2f7-48d4-bd86-8cce530f2945.png?v=1769439393', 'Romdeluxe Wild Series Rum No. 64 Trinidad er en eksklusiv 9-års single cask rom-aftapning fra den danske aftapper, Romdeluxe. Rommen er produceret af Trinidad''s eneste tilbageværende destilleri, Trinidad Distillers Limited (TDL), hvor den også er blevet tropisk modnet i de første 3 år. Den resterende 6 års lagring er foregået i Europa. Fadet er af amerikansk egetræ og har nummer 101063. Der er saft og kraft i smagen, da der er tale om en naturlig rom uden tilsætning af sukker, og fadet er desuden tappet ved høj fadstyrke. Meget begrænset udgivelse på blot 263 flasker. 65,8% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Wild Series Rum No. 65 Jamaica 7 år', 'https://rombo.dk/products/romdeluxe-wild-series-65-jamaica', 895, true, 70, 66, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_46ccc45d-2cf0-4e7a-89ae-8aeedf7cd664.png?v=1769439396', 'Romdeluxe Wild Series Rum No. 65 Jamaica er en eksklusiv 7-års single cask rom-aftapning fra den danske aftapper, Romdeluxe. Rommen er produceret af Long Pond i Trelawny Parish på Jamaica, og destilleriet går helt tilbage til 1753. De første 2 år er denne rom blevet tropisk lagret hos Long Pond, hvorefter de resterende 5 års lagring er foregået i Europa. Wild Series Rum No. 65 Jamaica er baseret på melasse, og efter gæringen er rommen pot still destilleret iht. de traditionelle Jamaica-metoder, og vi finder derfor også en del af de klassiske "funk-noter" i duft og smag. Der er vanen tro fuld power, da der er tale om en naturlig rom uden tilsætning af sukker, og fadet er desuden tappet ved høj fadstyrke. Meget begrænset udgivelse på blot 246 flasker. 66% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Romdeluxe Wild Series Unicorn Coffret Set vol. 2', 'https://rombo.dk/products/wild-series-unicorn-coffret-set-romdeluxe-vol-2', 3999, true, NULL, 59.8, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f4f878db-b1a9-43b1-917c-c1099f972615.png?v=1769434228', 'Wild Series Unicorn Coffret Set Vol. 2 fra Romdeluxe indeholder 3 nøje udvalgte single cask-aftapninger fra 3 forskellige typer destillationskedler hos Diamond Distillery i Guyana. Sættet er samlet set så enestående, at det har fået navnet Unicorn – eller enhjørning. Den første er en 20-års rom, der blev destilleret på Enmore EHP Coffey still, et legendarisk kolonnedestilleringsapparat i træ. Rommen blev destilleret i februar 2002 og har marque MEE, Tappet ved 59,8 % ABV. Den næste er en 18-års rom, der kommer fra Savalle-kedlen, der har 4 kolonner. Rommen blev destilleret i december 2003, har marque SVL og er tappet ved en ABV på 59,3%. Den tredje rom er en 18-års rom, der blev destilleret på Versailles pot still i juli 2004. Denne pot still er den eneste enkelt pot still i træ, der er tilbage. Rommen har marque MDXC og har en ABV på 54,9%. BEMÆRK: Wild Series Unicorn Coffret Set Vol. 2 er en begrænset udgivelse på kun 195 sæt til salg i Danmark. 3x70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cartavio XO Rom', 'https://rombo.dk/products/ron-cartavio-xo', 675, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Cartavio_XO_Rom.png?v=1770200161', 'Ron Cartavio XO er fra Peru, hvorfra vi også finder den meget populære Millonario-serie . Cartavio XO rommen har solera-lagret i 18 år på fade af hhv. fransk, amerikansk og slovensk eg, der har gjort rommen rig på smag og fylde. Den lange lagring har også givet rommen en dyb, mørk mahognifarve. Smagsnoterne er mangfoldige og byder bl.a. på citrus, vanilje, valnød, tørrede frugter og sherry. Ron Cartavio XO indeholder blended rom fra 10 til 30 år gammel med en forventet gennemsnitsalder på omkring 18 år. Flasken er flot designet og kommer i et gaverør. Ron Cartavio XO er en anbefalelsesværdig flaske i kategorien af søde rom, da den holder sødmen og det krydrede i en god balance. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario 20 år Solera Fundación Rom', 'https://rombo.dk/products/ron-centenario-20-fundacion-rum', 499, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_aed3555e-ecf7-46d0-9129-ca85057f78f7.png?v=1769421107', 'Ron Centenario Fundación XX Años er en rom i den spanske stil, fremstillet på baggrund af en unik blending proces med langsom aldring i toastede, hvide egetræsfade. Ron Centenario Fundación XX Años har banan, varm karamel, stjerneanis og vanilje i næsen og er kendetegnet ved behagelig romsødme, krydrede nødder, kanel, sød karamelsmag, røget træ og noter af cognac. Egner sig godt til at drikke rent eller som akkompagnement til ost eller dessert. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario 25 år Solera Gran Reserva Rom', 'https://rombo.dk/products/ron-centenario-25-gran-reserva-rum', 699, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_63bf8737-a8e9-4143-8300-cc4a2101debd.png?v=1769421135', 'Ron Centenario Gran Reserva 25 år er en sød og elegant Solera rom med en rig aroma af tropiske frugter, melasse, tobak, og eg. Smagen er blød med vanille og sød frugtsmag ledsaget af sarte noter af træ og citrus. Farven er som mørk rav. En fantastisk rom, der vandt guld ved German Rum Fest i 2012 indenfor kategorien: Solera Rum. Kommer i gaveæske. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario 30 år Solera Edición Limitada Rom', 'https://rombo.dk/products/ron-centenario-30-edicion-limitada-rum', 1299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8060667d-d652-4545-b8ff-16c58338fc76.png?v=1769421137', 'Ron Centenario Edicion Limitada Solera 30 år er belvet skabt på nogle af de ældste tønder på destilleriet, der er blevet blev åbnet til netop denne rom. Her er alt fra Ron Centenario Fundacion 20 år og opefter. Ron Centenario Edicion Limitada 30 års Solera rom er blød, rund og fyldig med masser af smag og duft. Det hele bliver præsenteret i en flot og æstetisk flaske. Vandt sølv ved German Rum Fest i 2012 indenfor kategorien: Solera Rum. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario Edicion 1985 Cask Selection Rom', 'https://rombo.dk/products/ron-centenario-edicion-1985-second-batch', 499, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6cb97f0f-d230-4aa9-b517-23d3c38dcfe9.png?v=1769434418', 'Ron Centenario Edicion 1985 rom Cask Selection Rum Second Batch er 2022-udgaven af en romudgivelse fra 2020 ifm. Ron Centenario''s 35 års jubilæum. 1985 refererer således til året, hvor Ron Centenario blev grundlagt i Costa Rica. I denne second batch er der som ved første batch tale om en blanding af rom, som er fra 6 år til 20 år gammelt, og der er både anvendt lette og lidt tungere rumdestillater. Ron Centenario Edicion 1985 rom Cask Selection Rum har haft en afsluttende lagring i skotske whiskyfade i regnskoven i Costa Rica. Som det også gælder Ron Centerario 20, 25 og 30 udgaverne er der tale om rom i den sødere ende af skalaen, men dog med lidt kant og præg fra de brugte whiskyfade. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cristóbal 151 Proof rom', 'https://rombo.dk/products/ron-cristobal-151-proof-rom', 349, true, 70, 75.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RonCristobal151Proofrom.png?v=1793717004', 'Ron Cristóbal serien præsenterer en række rom til verdens eventyrere. Rommen er dyrket, destilleret og lagret i det tropiske klima i Den Dominikanske Republik, og den er fremstillet med frisk sukkerrørssaft fra lokalt høstede sukkerrør. Rommen bliver desuden produceret under stærke principper for cirkulær økonomi, der beskytter miljø og sikring af en bæredygtig fremtid. Vi introducerede denne særlige Ron Cristóbal 151 Proof rom på Whisky &amp; Rom Festivalen i oktober 2026, og der var rigtig mange kunder, der faldt for kombinationen af lidt sødme og den høje alkohol på 75,5% vol. Duften byder på sød og mørk schokolade med noter af krydderier og brunt sukker. Smagen har friske græsnoter med sødme af melasse sirup og en afslutning med karamel og vanilje. 75,5% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cristóbal Gran Añejo rom', 'https://rombo.dk/products/ron-cristobal-gran-anejo-rom', 235, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RonCristobalGranAnejorom.png?v=1793712788', 'Ron Cristóbal er en romserie fra Den Dominikanske Republik, der modnes i landets tropiske klima. Denne "value-for-money" Ron Cristóbal Gran Añejo er en aromatisk rom, som er fremstillet af frisk sukkerrørsaft og kolonnedestilleret. Rommen lagres i det tropiske klima i Den Dominikanske Republik i 3-5 år. Duft: søde noter af karamelbudding og friskbagte hvedeboller med et let grønt strejf fra de anvendte friske sukkerrør. Smag: meget mild på ganen med noter af smurt scone og brunt sukker samt et strejf af vanilje. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cubaney Centenario Solera Rom', 'https://rombo.dk/products/ron-cubaney-centenario-rum-25-30', 975, false, 70, 41, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_74afb278-bc9a-4c69-93f9-6ff569fd640a.png?v=1769420682', 'Ron Cubaney Centenario Rum 25-30 år smagsnoter. Næse: mokka, mørk chokolade, appelsin, markant næse, tung sødme. Smag: elegant, mange komplekse nuancer imellem det krydrede og det søde. Eftersmag: let orange sødme, der er behagelig og så tørrer ud. Denne luksusrom har opnået 97/100 points på Romhatten.dk - se deres bedømmelse her. Ron Cubaney Centenario Rum 25-30 år vandt guld ved German Rum Fest 2012 indenfor kategorien: Aged Rum 15-30 years old. 41% 70cl');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cueva San Blas Exclusiva 12 Panama rom', 'https://rombo.dk/products/ron-cueva-1501-sistema-12', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/CuevaSanBlasExclusiva12Panamarom.png?v=1790675524', 'Ron Cueva San Blas Exclusiva 12 Solera fra Panama er en afbalanceret rom, der er lagret op til 12 år i et solera system. Det fugtige og tropiske klima er det perfekte forhold til at modne rommen, der modnes hurtigt i varmen ift. det tempererede klima i Europa. Når man dufter til denne Ron Cueva San Blas Exclusiva 12 Panama rom, fornemmes citrus, honning, vanilje og romkugler. Smagen er blød og cremet, og den byder på noter af chokolade, dadler, egetræskrydderier, rosiner og abrikos. Ron Cueva navnet henviser til Cueva stammen, der blev opdaget i Panama i 1501 af de spanske erobrere. Desværre uddøde Cueva stammen allerede i 1535 pga. kampen mod spanierne og de medbragte sygdomme fra Europa. Udover at hylde fortiden, så hjælper Ron Cueva også med at forbedre de indfødte stammers livskvalitet i form af forskellige projekter, som stammerne nyder godt af. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cueva Sueno Del Chagres 25 Panama rom', 'https://rombo.dk/products/ron-cueva-1501-sistema-25', 799, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RonCuevaSuenoDelChagres25Panamarom.png?v=1779880451', 'Ron Cueva Sueno Del Chagres 25 fra Panama er en kompleks og mellemsød rom, der er lagret op til 25 år i et solera system. Det fugtige og tropiske klima er det perfekte forhold til at modne rommen, der modnes hurtigt i varmen ift. det tempererede klima i Europa. Når man dufter til denne Ron Cueva Sueno Del Chagres 25 Panama rom, fornemmes ristede kaffebønner, tropiske frugter, mørk chokolade og vanilje. Smagen er fløjlsagtig med noter af dadler, rosiner, karamel, kirsebær og varme krydderier (kanel og nellike). Eftersmagen er vedholdende og supplerer med kanel, æbler og mørk chokolade. Ron Cueva navnet henviser til Cueva stammen, der blev opdaget i Panama i 1501 af de spanske erobrere. Desværre uddøde Cueva stammen allerede i 1535 pga. kampen mod spanierne og de medbragte sygdomme fra Europa. Udover at hylde fortiden, så hjælper Ron Cueva også med at forbedre de indfødte stammers livskvalitet i form af forskellige projekter, som stammerne nyder godt af. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Espero Ultimo - Tin Box', 'https://rombo.dk/products/ron-espero-ultimo', 599, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Espero_Ultimo_tin_box.png?v=1774444804', 'Ron Espero Último er en udsøgt romoplevelse fra Esperos fineste udvalg. Den består af et blend af 15 nøje udvalgte solera- og årgangsrom fra Den Dominikanske Republik, Jamaica, Trinidad, Barbados og Guyana. Hoveddelen er af gammel dominikansk rom lagret 14–20 år, blendet med sjældne årgangsrom fra de Caribiske øer på 9–18 år. Ron Espero Último afsluttes med 8 måneders lagring på cognacfade, hvilket giver en rig, kompleks og samtidig afrundet karakter med noter af mørk vanilje, karamel og krydderier. Resultatet er en fyldig, elegant og uimodståelig rom. Kommer i flot metalæske. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Espero XO Extra Anejo Limitada Rom', 'https://rombo.dk/products/ron-espero-xo-limitada', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_bfd4a03e-e25e-4fb2-a2b7-84131aef986c.png?v=1769439521', 'Ron Espero XO Extra Anejo Limitada er en unik blanding af 15 forskellige Solera og Vintage rom, der er blended i Costa Rica. Den valgte rom kommer fra udvalgte destillerier i Guyana, Trinidad, Den Dominikanske Republik, Barbados og Jamaica. Den helt særlige kombination af destillerier har resulteret i en sødmefuld rom med komplekse smagsnoter fra de forskellige lande. Når man dufter til Ron Espero XO Extra Anejo Limitada rommen, fornemmes tropiske frugter og ristet egetræ. Smagen er blød og har noter af bl.a. citrus, banan, kokos, honning og krydderier. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Malteco Reserva Añeja 10 års Rom', 'https://rombo.dk/products/ron-malteco-10-rum', 275, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d77fb428-e86e-439c-b3ba-1bc22be40c18.png?v=1769421068', 'Ron Malteco Reserva Añeja 10 år bliver lavet på frisk sukkerrørsjuice og destilleret i kolonne-apparater, som der er tradition for hos Ron Malteco. Lageringen foregår efter solera-metoden på brugte bourbon-fade fra USA. Duft: chokolade, karamel, vanille og sødme. Smag: Masser af sødme med flødekaramel og honning. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Malteco Reserva Maya 15 års Rom', 'https://rombo.dk/products/ron-malteco-15-rum', 325, true, 70, 41.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f2b73339-617a-4113-865a-88181efb62da.png?v=1769421013', 'Ron Malteco 15 år Reserva Maya bliver lavet på frisk sukkerrørsjuice, der destilleres i kolonne-apparater. Herefter har rommen lagret i 15 år på brugte bourbon-fade fra USA. Ron Malteco Reserva Maya 15 år har noter af kanel og brun farin i næsen og frugtige smagsnoter med strejf af vanilje og kanel. Eftersmage er lang og god med noter af tørret frugt. Ron Malteco 15 år Reserva Maya er en let tilgængelig rom med god værdi for pengene. 41,5% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Matusalem Gran Reserva 15 års Rom', 'https://rombo.dk/products/ron-matusalem-15-rum', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8be910b5-d75f-470e-90a1-7dfd4fc4f6fd.png?v=1769421072', 'Ron Matusalem 15 år Gran Reserva har en rødlig kobberfarve med okker toner. Næsen er kompleks, fin og komplet. Vedvarende, tørre, træagtige noter, der giver en rig, intens aroma af ristede, tørrede frugter og karamel. Smag: Meget behagelig med en blød tekstur og en kompleks, vedvarende udvikling med noter af egetræ. Indbydende fornemmelse af kakao. Cognac-lignende eftersmag. Ron Matusalem Gran Reserva 15 år er en super premium rom, der er ideel til at drikke rent eller "on the rocks". 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Matusalem Gran Reserva 23 års Rom', 'https://rombo.dk/products/ron-matusalem-23-rum', 475, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_159906ad-5110-4e83-96b4-b04cb86a6394.png?v=1769421143', 'Ron Matusalem Gran Reserva Rum Solera 23 år er så absolut kransekagefiguren fra Matusalem-huset. Rommen har lagret efter solerametoden, hvor rommen får en rund og komples smag ved at blande forskellige rom af forskellige alder. Som tommelfingerregel gælder, at jo længere lagringsproces, desto bedre bliver rommen. Præcis hvordan blandingen til denne rom er sammensat er en velbevaret hemmelighed, som kun master blenderne, der er efterkommere af grundlæggerne, kender til. En blød og afbalanceret rom med spor af honning, vanilje og melasse med en krydret og vedvarende afslutning. Mellemsød rom med tilsætning af 10,5 gram sukker per liter. Ron Matusalem Gran Reserva Rum Solera 23 års rommen er tappet på en gaveværdig flaske. 40% –70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario Aniversario Cincuenta 10 års Rom', 'https://rombo.dk/products/ron-millonario-10-aniversario-cincuenta', 325, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6cc218db-4771-4fc0-844a-aa01fa9693ad.png?v=1769423394', 'Ron Millonario 10 Aniversario Cincuenta Rum er således en 10-års jubilæumsrom og navnet betyder ikke, at produktet er 10 år gammelt. Det er som altid Fabio Rossi, der står bag, og han har med Ron Millonario 10 Aniversario kreeret et blend af en større andel af yngre rom, der har været lagret på bourbonfade og en mindre andel af ældre rom, der har været lagret på sherryfade. Ron Millonario 10 Aniversario Rum har noter af vanilje, frugt og krydderier, og disse noter bliver ekstra fremtrukne i denne Cincuenta (betyder 50 på spansk) 50%-udgave. 50% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario Numero 10 Aniversario Rom', 'https://rombo.dk/products/ron-millonario-10-aniversario-reserva', 285, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RonMillonarioNumero10Aniversariorom.png?v=1793710120', 'Ron Millonario Numero 10 Aniversario Rom er en lillebror til den meget kendte Ron Millonario Numero 15 . Den markerer Ron Millonario husets 10 års jubilæum, og navnet betyder ikke, at produktet er 10 år gammelt. Det er som altid Fabio Rossi, der har stået bag (inden overtagelsen af agenturet fra Mac Y), og han har i denne udgave kreeret et blend af en større andel af yngre rom, der har været lagret på bourbonfade og en mindre andel af ældre rom, der har været lagret på sherryfade. Ron Millonario Numero 10 Aniversario Rom har noter af vanilje, frugt og krydderier, og rommen kan nydes rent eller anvendes til premium cocktails. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario Numero 15 Reserva Especial', 'https://rombo.dk/products/ron-millonario-numero-15', 375, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Millonario_Numero_15_Reserva_Especial.png?v=1787043387', 'Ron Millonario Numero 15 Reserva Especial er en peruviansk dram, der har vundet adskillige priser og stort set altid er i top-5 på Rombo''s top-10 over mest solgte rom &amp; sukkerørsspiritus. Flasken har fået nyt design i 2025 i stedet for den legendariske bastflaske igennem ca. 20 år, men det indholdet er stadig det samme. Den gamle Ron Millonario Reserva Especial Solera 15 år blev kåret til verdens bedste premium rom og "best of show" ved International Rum Festival i 2009. Næse: Brun farin, brændte mandler, vanilje, fad, rosin, mørk chokolade, kandiserede frugter, kakao, kokos, blomme og nellike. Smag: formfuldendt sødme, nuanceret og afvekslende. Nellike, toffee, rosin, sirup, figen, dadel og karamelliseret sukker i flot balance. Eftersmag: lang eftersmag, masser af søde og krydrede nuancer. Ron Millonario Numero 15 Reserva Especial er en meget populær dram i den søde ende til hygge og forkælelse. Behagelig afrundet og kompleks. 40% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario XO', 'https://rombo.dk/products/ron-millonario-xo-rum', 699, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Millonario_XO.png?v=1787047910', 'Kun de allerbedste fade bliver til Ron Millonario XO, og det er således en meget limited edition. Næse: tung appelsin, let tobak, sukker sødme, en kompleks duft af krydderier indhyldet i sødme og karamelliserede, tropiske frugter. Smag: først sødme, så krydderier der trækker ud, og så sødme igen. Hints af nougat, kandis, figner og dadler. Eftersmag: velbehagelig fornemmelse af sødme, brun farin, sarte krydderier og fad i eftersmagen. Ron Millonario XO fra Peru er en sød dram, og måske også en smule sødere end Ron Millonario 15? Men krydderierne kan ikke overses heller. Gaveæsken er sort og ligner krokodille skind i strukturen. Ron Millonario eller "Ron Millionaire", som nogle ynder at kalde den: Verdens Bedste Rom 2008-2009 og Best of Show 2009. 97/100 på Romhatten.dk - se bedømmelse her . 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario XO Reserva Especial Rom Magnum 1,5 liter', 'https://rombo.dk/products/ron-millonario-xo-rum-magnum', 2195, true, NULL, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Millonario_XO_Reserva_Especial_Rom_Magnum_1_5_liter.png?v=1770200373', 'Denne ældre aftapning af Ron Millonario, der blev kåret som Verdens Bedste Rom i 2008 og 2009 - og kaldet XO - er en Solera version af rommen fra Peru. Med en alder på 15 - 20 år er den blandt Sydamerikas ældste rom, og fadene er omhyggeligt udvalgt af brand ejer - Fabio Rossi. Kun de allerbedste fade bliver til Ron Millonario XO, og det er således en meget limited edition. Næse: Tung appelsin, let tobak, sukker sødme, en kompleks duft af krydderier indhyldet i sødme og karamelliserede, tropiske frugter. Smag: Først sødme, så krydderier der trækker ud, og så sødme igen. Hints af nougat, kandis, figner og dadler. Eftersmag: Velbehagelig fornemmelse af sødme, brun farin, sarte krydderier og fad i eftersmagen. Ron Millonario XO fra Peru er en sød rom, og måske også en smule sødere end den 15 årige? Men krydderierne kan ikke overses heller. Gaveæsken er sort og ligner krokodille skind i strukturen. Ron Millonario eller "Ron Millionaire", som nogle ynder at kalde den: Verdens Bedste Rom 2008-2009 og Best of Show 2009. 97/100 på Romhatten.dk - se bedømmelse her .');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Mulata de Cuba Anejo Reserva 5 år', 'https://rombo.dk/products/mulata-cuba-5', 169, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Mulata_de_Cuba_Anejo_Reserva_5_ar.png?v=1770200477', 'Ron Mulata de Cuba Anejo Reserva 5 år er fra den statsejede Ron Mulata producent, der har fremstillet i Cuba siden 1844. Den unge rom har lagret på egetræsfade, og den vil være særligt egnet til cocktails, rom og cola, osv. Hvis man forsøger at nyde den rent, vil man finde frugtige noter, lidt sødme og en "kort smag". 38% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Mulata de Cuba Gran Reserva 15 år', 'https://rombo.dk/products/mulata-cuba-15', 349, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Mulata_de_Cuba_Gran_Reserva_15_ar.png?v=1770200604', 'Ron Mulata de Cuba Gran Reserva 15 år er fra den statsejede Ron Mulata producent, der har fremstillet rom i Cuba siden 1844. Smagen er mellemsød og blød. Ron Mulata de Cuba Gran Reserva 15 års rommen har lagret i egetræsfade, der har bidraget til noter af vanilje, tørret frugt og kokos. 38% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 12 år Solera - Rom fra Den Dominikanske Republik', 'https://rombo.dk/products/ron-quorhum-12-qrm-rom', 375, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_8c77c7bf-9db7-4439-8544-fc25364bc529.png?v=1769421244', 'Ron Quorhum (QRM) 12 års solera rom hører til blandt de mest populære rom i Den Dominikanske Republik. Rommen har lagret på gamle bourbonfade i et solerasystem, hvor op til 12 år gammel rom blandes med anden rom af forskellig alder. Duft: sukkerrørsjuice, bourbon, vanilje, karamel, tørret frugt og egetræ. Ron Quorhum 12 års solera rom har en smag af vanilje, karamel, egetræ og mørk chokolade. 40% 70cl');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 15 år Solera Rom', 'https://rombo.dk/products/ron-quorhum-15-qrm-rom', 449, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a1f409ac-2ab1-493f-ab68-4799a925bf6d.png?v=1769421246', 'Ron Quorhum 15 års solera rom er blandet af destillater på både sukkerrørsjuice og melasse, der har lagret på både amerikanske og franske egefade. Rommen har god fylde og kompleksitet og man mærker, at denne 15 års rom er en anelse rundere end de yngre udgaver. Duft: sødme, brun farin, karamel og kokos. Ron Quorhum 15 års solera rom har smagsnoter af karamel, træ, tobak samt hints af sukkerrør, brun farin og ristede nødder. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Relicario', 'https://rombo.dk/products/ron-relicario', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b6087355-0f6d-4eb1-b5b5-f673ef80fea8.png?v=1769422590', 'Ron Relicario er en sød rom fra Oliver &amp; Oliver i Den Dominikanske Republik. Rommen er solera-lagret (blending af ældre og yngre rom) og indeholder romdestillater, der er op til 10 år gamle. Ron Relicario har en duft af blommer og druer, mens smagen bl.a. byder på noter af egetræ, vanilje og mandler. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Sostenible 15 år La Isabela 2008 rom', 'https://rombo.dk/products/ron-sostenible-15-la-isabela-2008', 649, true, 70, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_3b4967f0-efa1-4c3c-9bc1-ae63bd578bee.png?v=1769437903', 'Ron Sostenible 15 år La Isabela 2008 Rare Vintage Collection rom er i skrivende stund en flot udvidelse af Ron Sostenible rom-serien, der bl.a. indeholder "den almindelige" Ron Sostenible 8 år og Ron Sostenible Triple Cask rom . Den nye Ron Sostenible 15 år La Isabela 2008 Rare Vintage Collection rom er baseret på sukkerrørsmelasse og destilleret hos La Isabela i Den Dominikanske Republik. Rommen er blevet tropisk lagret i mindst 15 år i bourbonfade, og den er herefter transporteret til Europa med det bæredygtige sejlskib, Tres Hombres. I munden fornemmer man nuancer af karamel, egetræskrydderier og vanilje. Smagen byder på noter af vanilje, blommer, muscovado sukker og markante fadnoter fra den lange, tropiske lagring. Ron Sostenible er en bæredygtig romserie lavet af A Clean Spirit, der har betroet produktionen af Ron Sostenible til ekstremt kyndige hænder på et destilleri i Den Dominikanske Republik. Destilleriet har maksimal fokus på en miljømæssig grøn praksis. Alt CO₂ fra gæringsprocessen opsamles i trykbeholdere, som bruges til sodavand. Alt organisk materiale og spildevand fra gæringsprocessen ledes ud på sukkerrørsmarkerne som organisk gødning til nye sukkerrør, og biomassen bruges som brændstof til at destillere alkoholen. Den færdige rom transporteres fra Den Dominikanske Republik til Europa med sejlskib - helt uden motorkraft. Flaskerne er lavet af omsmeltet genbrugsglas og produceret i Europa for at reducere CO2-udledningen. Etiketten er trykt på bæredygtigt papir, og korken er bæredygtigt produceret uden brug af lim. 46% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Sostenible 8 år Rom', 'https://rombo.dk/products/ron-sostenible-8-ars-rom', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5789c77c-282f-4865-915d-3b2738b581a1.png?v=1769434136', 'Ron Sostenible 8 års rom er en mørk, dominikansk rom lavet af lokaldyrkede, dominikanske sukkerrør. Den resterende biomasse fra sukkerrørene bruges som brændstof på destilleriet, og den CO2, der frigives under fermenteringsprocessen indfanges og genbruges som brus i sodavand. Ron Sostenible 8 års rom har efter destillering lagret 8 år i tropisk klima på tidligere bourbonfade. Herefter er rommen transporteret 100% klimaneutralt til Europa med sejlskib over Atlanten. Efter endt sejlads er rommen tappet på flasker af 96% genbrugsglas med bomuldsetiketter. Ron Sostenible 8 års rom er en let drikkelig, kompleks og lækker rom med aroma og smag af krydret eg, appelsinskal, vanilje og karamel. Mellemsød rom. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Sostenible 8 år Triple Cask Rom', 'https://rombo.dk/products/ron-sostenible-8-triple-cask', 499, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_525d7734-e3d1-4a18-99c7-9083c8c4a5e6.png?v=1769437173', 'Ron Sostenible 8 år Triple Cask Rom er en utrolig velsmagende rom med en perfekt balance mellem sødme og kompleksitet. Den er lavet af friskpresset sukkerrørsjuice, hvilket er usædvanligt for rom lavet i Den Dominikanske Republik. Denne premium rom er blevet lagret i mindst 8 år i bourbonfade, efterfulgt af 5 måneder i tidligere Pedro Ximenes sherryfade og Oloroso sherryfade, hvilket giver en meget karakteristisk fyldig, blød og helt lækker rom, der egner sig til at blive nydt langsomt. I munden fornemmer man nuancer af figner, dadler og rosiner samt karamel, vanilje, appelsinskal og krydret egetræ. Ron Sostenible er en bæredygtig romserie lavet af A Clean Spirit, der har betroet produktionen af Ron Sostenible til ekstremt kyndige hænder på et destilleri i Den Dominikanske Republik. Destilleriet har maksimal fokus på en miljømæssig grøn praksis. Alt CO₂ fra gæringsprocessen opsamles i trykbeholdere, som bruges til sodavand. Alt organisk materiale og spildevand fra gæringsprocessen ledes ud på sukkerrørsmarkerne som organisk gødning til nye sukkerrør, og biomassen bruges som brændstof til at destillere alkoholen. Den færdige rom transporteres fra Den Dominikanske Republik til Europa med sejlskib - helt uden motorkraft. Flaskerne er lavet af omsmeltet genbrugsglas og produceret i Europa for at reducere CO2-udledningen. Etiketten er trykt på bæredygtigt papir, og korken er bæredygtigt produceret uden brug af lim. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Sostenible Experimental Cask Rioja rom', 'https://rombo.dk/products/ron-sostenible-experimental-cask-rioja-rom', 499, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c1a71d4d-5fc0-4416-9f8c-ca1b3a4e90c1.png?v=1769438357', 'Ron Sostenible Very Limited Experimental Cask Rioja er en rom, der tappet eksklusivt til Østjysk Vinforsyning i samarbejde med producenten, A Clean Spirit. Ron Sostenible er en bæredygtig romserie lavet af A Clean Spirit, der har betroet produktionen af Ron Sostenible til ekstremt kyndige hænder på et destilleri i Den Dominikanske Republik. Destilleriet har maksimal fokus på en miljømæssig grøn praksis. Alt CO₂ fra gæringsprocessen opsamles i trykbeholdere, som bruges til sodavand. Alt organisk materiale og spildevand fra gæringsprocessen ledes ud på sukkerrørsmarkerne som organisk gødning til nye sukkerrør, og biomassen bruges som brændstof til at destillere alkoholen. Den færdige rom transporteres fra Den Dominikanske Republik til Europa med sejlskib - helt uden motorkraft. Flaskerne er lavet af omsmeltet genbrugsglas og produceret i Europa for at reducere CO2-udledningen. Etiketten er trykt på bæredygtigt papir, og korken er bæredygtigt produceret uden brug af lim. Denne Ron Sostenible Very Limited Experimental Cask Rioja rom byder på en spændende smagsoplevelse, hvor den udsøgte og traditionelle bourbon-lagring, der kendetegner Ron Sostenible rom-serien, har fået et unikt twist. I stedet for den mere klassiske lagring på sherryfade, som også bruges til Ron Sostenible Triple Cask, er denne udgave efter 8 års lagring på et bourbonfade blevet færdiglagret på et udsøgt Rioja vinfad, der tilfører en ekstra dimension til smagsprofilen. Ron Sostenible Very Limited Experimental Cask Rioja rom byder på noter af bl.a. tørret frugt, vanilje, toffee, karamel, chokolade, appelsinskal og egetræskrydderier. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Tepuy Destino rom', 'https://rombo.dk/products/ron-tepuy-destino-rom', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Tepuy_Destino_rom.png?v=1781176622', 'Producenten bag Diplomatico er på banen med en nyere rom-serie! Ron Tepuy Destino er en mellemsød rom fra DUSA (Destilerías Unidas S.A.) i Venezuela, der også laver den yderst populære og kendte Diplomatico rom-serie . DUSA arbejder både med pot still- og kettle still-destillater, og dette giver fine muligheder for forskellig struktur, fylde og kompleksitet i den fremstillede rom. Tepuy navnet stammer i øvrigt fra de ikoniske Tepuy-bjerge i Venezuela. Ron Tepuy Destino - lanceret i Danmark i juni 2026 - er en alsidig og let-tilgængelig rom, der er lagret i op til 8 år og afrundet på Amontillado sherryfade. Rommen har modtaget guldmedalje ved London Spirits Competition. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Tepuy Monumento rom', 'https://rombo.dk/products/ron-tepuy-monumento-rom', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ron_Tepuy_Monumento_rom.png?v=1781176567', 'Producenten bag Diplomatico er på banen med en nyere rom-serie! Ron Tepuy Monumento er en mellemsød rom fra DUSA (Destilerías Unidas S.A.) i Venezuela, der også laver den yderst populære og kendte Diplomatico rom-serie . DUSA arbejder både med pot still- og kettle still-destillater, og dette giver fine muligheder for forskellig struktur, fylde og kompleksitet i den fremstillede rom. Tepuy navnet stammer i øvrigt fra de ikoniske Tepuy-bjerge i Venezuela. Ron Tepuy Monumento - lanceret i Danmark i juni 2026 - er en kompleks og dybdegående rom, der er lagret i op til 12 år og afsluttet på tre forskellige sherryfade (Pedro Ximénez, Amontillado og Oloroso). Rommen har modtaget guldmedalje ved London Spirits Competition. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Zacapa Solera Gran Reserva', 'https://rombo.dk/products/ron-zacapa-gran-reserva', 449, false, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ac13ef25-1fd1-43e7-ba5a-75a5257f75d0.png?v=1769437210', 'Ron Zacapa Solera Gran Reserva er en opfølger til den gamle, kendte Ron Zacapa Solera 23. Rommen har en balance mellem delikate og unikke smagsoplevelser, som opnås gennem en blanding af lagrede rom destilleret via "Sistema Solera" lagringsprocessen. Ron Zacapa Solera Gran Reserva lagres i udvalgte fade, der tidligere har indeholdt kraftig amerikansk whiskey, delikate sherryer og fine Pedro Ximénez vine, hvilket gør den både blød og afbalanceret. Navnet ”Solera” refererer til en lagringsmetode, som er meget anvendt i Jerez hvor man laver sherry. I rom-verdenen har ordet ikke nogen officiel definition, men betyder som regel, at flere tønder med rom af forskellige årgang og alder blandes. Ligesom den gamle Ron Zacapa Solera 23 så starter også Ron Zacapa Solera Gran Reserva blidt og sødt i næsen, med aromaer der inkluderer karamel, vanilje, kakao og karamel. Den udvikler sig videre til at omfavne sherrytoner af karamelliserede ristede brasilianske nødder og ristede hasselnødder, hvilket afrundes af noter af toffee, banan og tørret ananas. Ved første smag opleves en kompleks og generøs fylde. Den begynder med en dybde af tørret frugt og abrikos, og udvikler sig til krydrede elementer af egetræ, muskatnød, læder og tobak, der ledsages af subtile noter af kaffe og vanilje. Alt dette balanceres elegant af et krydret strejf af kanel og ingefær. Eftersmagen er kompleks med noter af honningagtig karamel, krydret egetræ og tørret frugt. Ron Zacapa Solera Gran Reserva serveres bedst ren, på is eller i din foretrukne cocktail.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Barbados 8 år', 'https://rombo.dk/products/rum-nation-barbados-8', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1630e718-b7df-4d9d-805b-df16fc7b60cc.png?v=1769423839', 'Rum Nation Barbados 8 års rom har erstattet den gamle Rum Nation Barbados 10 års rom. Den nye Rum Nation Barbados 8 års rom er en "limited edition 2019 release". I duft og smag finder du noter af bl.a. honning, blomster, blodappelsin, fersken, abrikos, dadler, banan og rosiner. Rum Nation Barbados 8 års rom kommer i en flot, sort gaveæske. Produceret af den uafhængige italienske aftapper, Rossi &amp; Rossi. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation British Guyana 7 år Cask Strength', 'https://rombo.dk/products/rum-nation-british-guyana-7-cask-strength', 499, true, 70, 59, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rum_Nation_British_Guyana_7_ar_Cask_Strength.png?v=1770200711', 'Rum Nation British Guyana cask strength 7 års rom er blandet af tung rom fra et antikt wooden still, der har mere end 250 år på bagen, og en lettere rom fra et double wooden kolonnestill. Rum Nation British Guyana cask strength 7 års rom har en intens, esterfyldt duft med noter af dadler, cigaræsker, chokolade og tropiske frugter. Smagen har en sherryagtig tørhed, igen er der godt med estere, noter af rosiner, gæret frugt, kanel og peber. Krydret og frugtig uden at være sød. Eftersmagen er godt krydret og intens varmende. Tappet ved fadstyrke. 59% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Dominicana 8 år', 'https://rombo.dk/products/rum-nation-dominicana-8-aar', 349, true, 70, 40.9, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d310eb5d-84b9-401d-bd8a-efdbbcd20570.png?v=1769437213', 'Rum Nation Dominicana 8 år er en sprudlende 8-årig rom fra den Dominikanske Republik, lavet på frisk sukkerrørssaft. Rommen kommer fra et moderne og økobevidst destilleri øst for Santo Domingo, men er det første Rum Nation produkt der er blandet, smagsat og tappet i Frederiks, Danmark. Selvom rommen teknisk set er i den Spanske stilart, er den mere kompleks og mørk end de fleste andre spanske rom, hvilket skyldes at den er lavet direkte på sukkerrørssaften, hvor spansk rom typisk laves på sukkerrørsmelasse. Rum Nation Dominicana 8 år har en duft med en karakter af frisk og sprudlende sukkerrørssaft, med noter af grøn eukalyptus, frisk frugt og modne pærer, samt lette chokoladearomaer. Rommen har en yderst blød konsistens med noter af appelsinskal, ananas og modne frugter, som hænger ved på ganen, inden den til sidst går over i en langvarig og blød eftersmag fyldt med noter af chokolade og kaffe. En kompleks og dog letdrikkelig rom med en underspillet sødme som er velegnet til desserten eller som en aftendram. 40,9% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Guadeloupe Blanc Rhum Agricole', 'https://rombo.dk/products/rum-nation-guadeloupe-blanc-rhum-agricole', 249, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9773bddb-c090-4b10-aada-d5e28b72e0bc.png?v=1769434572', 'Rum Nation Guadeloupe Blanc Rhum Agricole er fra det familieejede Reimonenq-destilleri på øen Guadeloupe i Caribien. Rommen er lavet på frisk sukkerrørsjuice og er således en ''rhum agricole'', en landbrugsrom. Rum Nation Guadeloupe Blanc Rhum Agricole har en saltet og mineralsk duft med noter af mint og grønne oliven. Smagen er kraftig med mineralske noter af hav og grønne oliven, der suppleres af sødlige noter af sukkerrørssaft. Olieret og meget mineralsk eftersmag. Den friske, mineralske smag gør rommen perfekt til cocktials eller alene tilsat knust is. 50% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Guatemala XO 20th Anniversary Edition Decanter', 'https://rombo.dk/products/rum-nation-guatemala-xo-anniversary-edition', 475, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ab7d6cb3-c9c4-4cb6-950b-c5b7ec820322.png?v=1769423554', 'Rum Nation Guatemala XO 20th Anniversary Edition rom er lavet på et blend af de mere sødmefulde fade. Rommen er lavet på sukkerrørs melasse og destilleret på et kolonnedestillations apparat. Derefter er rommen først lagret i mindst 4 år på ex-bourbon egetræsfade i det tropiske klima nær Hondo-floden i Guatemala. for derefter at få en anden lagring, på Olorosso og Pedro Ximenez sherry fade i 16 måneder, i mere kølige lagerbygninger i Italien. Her udvikler rommen sine vinøse og frugtige egenskaber. Næse: Vanilje og rosin. Smag: Sødmefuld og behagelig, næsten nøddeagtig med et strejf af honning, den er vedhængende og yderst delikat. Rommen kommer i en flot "decanter" flaske og i gaveæske.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Jamaica 5 år', 'https://rombo.dk/products/rum-nation-jamaica-5', 349, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b5a9b4a5-b12c-45e0-aef5-45c0fe3ac8e9.png?v=1769422084', 'Rum Nation Pot Still Jamaica 2016 har fået sin indledende lagring på Worthy Park destilleriet i St. Catherine. Rommen er herefter lagret på primært Oloroso Sherry fade, men også en mindre del Pedro Ximenez sherryfade fra Rum Nation inden den afsluttende blending. Duft og smag er "sædvanlig Jamaica" kompleks og aromatisk, men med den ekstra sherry/rosin note. Rum Nation Pot Still Jamaica 2016 Release 5 års rommen følger efter den meget populære 8 års 2015 Release udgave. 50% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Jamaica 5 år Cask Strength', 'https://rombo.dk/products/rum-nation-jamaica-5-cask-strength', 495, true, 70, 57.84, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7b8ae10c-6712-4c7c-b52b-e6fa28a7c11e.png?v=1769435807', 'Rum Nation Jamaica 5 år Cask Strength er en intens, aromatisk og esterfyldt jamaicansk pot still rom med et særligt præg! Den har gennemgået en omhyggelig 5-årig ældningsproces i et kontinentalt klima, lagret på oloroso sherryfade, der tidligere indeholdt skotsk highland malt whisky. Det kølige klima og fadenes fine touch har bevaret den jamaicanske roms robuste basissmag, mens den samtidig har fået en dyb og sødmættet nuance. I duften mødes man af alle de funky kendetegn fra jamaicansk rom – trælim og voks, fermenterede frugter og hvedemel. I smagen træder sherryfadets indflydelse tydeligt frem, i form af en frugtig, tør note der er flot integreret med den jamaicanske roms balsamico karakter. Her opdager man også dybe noter af brun farin, lakridsrod, kamfer og kanel. Eftersmagen er langvarig, varm og krydret med antydninger af hvid peber og en antydning af græs. 57,84% - 700 ml.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Jamaica White Pot Still', 'https://rombo.dk/products/rum-nation-jamaica-pot-still', 299, true, 70, 55.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RumNationJamaicaWhitePotStill.png?v=1780052982', 'Denne nye rom-udgave af Rum Nation Jamaica White Pot Still 55,5% vol. er en opdateret udgave af den gamle og populære 50% vol. udgave, der desværre udgik. Den nye udgave er fortsat baseret på rom fra Worthy Park destilleriet i St. Catherine, Jamaica. Duft: tropisk frugt, intense estere, varme krydderier, overmoden banan og sukkerrør. Rum Nation Jamaica White Pot Still har en kraftfuld smag med noter af bl.a. saftig ananas, grøn banan, intens krydderivarme, "Jamaica funk" og en rå sødme fra sukkerrør. En højst intens og karakterfuld rom, der kan nydes rent eller bruges som ingrediens i cocktails. 55,5% vol. – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Mauritius 6 år Triple Cask rom', 'https://rombo.dk/products/rum-nation-mauritius-triple-cask', 399, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_bbedcec3-aa40-4a96-af5a-6333b2ec2cc4.png?v=1769439798', 'Rum Nation Mauritius 6 år Triple Cask er en rom, der er tropisk lagret på tre forskellige fade: Virgin oak, bourbonfade og sherryfade. Kombinationen har skabt en kompleks rom i flot balance. Virgin oak fadet har bidraget med dybde og egetræskrydderier, bourbonfadet har bidraget med vanilje-noter og sødme, og sherryfadet har bidraget med frugtige noter. Når man dufter til Rum Nation Mauritius 6 år Triple Cask rommen, fremkommer noter af røde bær, ahornsirup, frisk egetræ, sherry-rosin og citrus. Smagen er blød og fyldig med noter af læder, egetræ, bourbonvanilje, tropiske frugter og appelsinskal. Der er tilsat 8 gram sukker/liter, så rommen er meget lidt sød. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Mauritius 8 år Cask Strength rom', 'https://rombo.dk/products/rum-nation-mauritius-cask-strength', 549, true, 70, 54.9, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rum_Nation_Mauritius_8_ar_Cask_Strength_rom.png?v=1770120113', 'Rum Nation Mauritius 8 år Cask Strength er en kraftfuld rom, som er lagret i 5 på ex-bourbonfade og herefter i 40 måneder på first-fill bourbonfade. Cask Strength rom-udgivelsen er begrænset til kun 1.983 flasker til verdensmarkedet. Når man dufter til Rum Nation Mauritius 8 år Cask Strength rommen, fornemmes noter af toffee, ahornsirup, karamel, tropisk frugt og vanilje. Smagen og eftersmagen er fyldig med noter af lime, mynte, egetræskrydderier, banan og mango. Der er tale om en naturlig rom uden tilsætning af sødme. 54,9% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Meticho Chocolate & Toffee', 'https://rombo.dk/products/rum-nation-meticho-chocolate-toffee', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ed4d614e-102a-4392-9362-0f8704606e01.png?v=1769434292', 'Rum Nation Meticho Chocolate &amp; Toffee er en "spirit drink" lavet på Centralamerikansk sukkerrørsspiritus, der har fået tilsat sukker og naturlige smagsgivere som chokolade, karamel og vanilje. Varmen og sødmen fra smagsgiverne smelter sammen til en konfektagtig, cremet Rum Nation Meticho Chocolate &amp; Toffee, der kan nydes on the rocks, sammen med dessert ­– eller som en flydende dessert i sig selv. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Meticho Citrus', 'https://rombo.dk/products/rum-nation-meticho-citrus', 289, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1f3f37ac-2963-4748-bc8d-af915b29751f.png?v=1769425315', 'Rum Nation Meticho Citrus er en "Spirit Drink", der forsøger at skabe den perfekte balance i mellem sukkerrørsspiritus og citrus. Der er tale om en blanding af smagen fra den italienske appelsinskal og en blød mellemamerikansk sukkerrørsspiritus, og den særlige opskrift indeholder også rød appelsin, citrus og mandarin. Rum Nation Meticho har udover citrusnoterne også et tydeligt strejf af vanilje og honning. Den kan nydes rent (evt. kold eller med isterninger), og den fungerer også glimrende i en cocktail. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation No. 14 Demerara', 'https://rombo.dk/products/rum-nation-solera-no-14-demerara', 299, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_16fe8a51-3cd9-4b4e-bce8-e7c3e2660c19.png?v=1769420727', 'Rum Nation Demerara nr. 14 solera rom har lagret på brugte amerikaske bourbonfade og fået finish i gamle oloroso-og Pedro Ximenez-sherryfade. Næse: Meget harmonisk, udover den primære melasse duft er der mange nuancer af mokka, vanille og nødder. Smag: Alkoholen er temmelig vedholdende, en frisk mokka nuance ligger forsigtigt under duften af vanille og nødder. Eftersmag: Tør med dufte af træ, der svinder ind i den typiske sødme af sukkerrør og melasse. Rum Nation Demerara Solera No. 14 har en god balance imellem krydderier og sødme. En god rom til prisen, hvis man er til det halvsøde. 40% 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Panama 10 år', 'https://rombo.dk/products/rum-nation-panama-10', 325, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_81141062-bf34-4d0e-9f12-921153d79cfd.png?v=1769422615', 'Rum Nation Panama 10 års rom er fra den afhængige italienske aftapper, Rossi &amp; Rossi. Rommen har en sød, frisk og frugtagtig duft. Rum Nation Panama 10 års rom byder på en smag med noter af bl.a. sukkerrørssødme, acacia honning, rosiner, mælkechokolade, appelsin og abrikos.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Panama 18 år Decanter', 'https://rombo.dk/products/rum-nation-panama-18-decanter', 485, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rum_Nation_Panama_18_ar_Decanter.png?v=1770200802', 'Rum Nation Panama 18 års rom er en populær flaske, hvis man er til den søde / mellemsøde stil, og her er den så i en ny emballage og karaffelflaske. Sukkerindholdet er blevet reduceret til under 20 gram/ltr i forhold til den gamle udgave, således at den holder sig indenfor foreskrifterne for, hvad der nu må kalde sig rom. Rum Nation Panama 18 års rom Decanter har en duft af bl.a. honning, cola, bergamot, dadler, appelsinskal og vermouth. I smagen finder man bl.a. frugtige noter og hints af melasse, chokolade, rosin, appelsinskal, cola og kokos, mens eftersmagen byder på noter af sort te, sødme og honning. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Panama 21 år Black Decanter', 'https://rombo.dk/products/rum-nation-panama-21-black-decanter', 749, false, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rum_Nation_Panama_21_ar_Black_Decanter.png?v=1770200912', 'Rum Nation Panama Black Decanter 21 år er en vellagret rom, der manøvrerer friskheden på trods af alderen. Den er ikke for tung, og den friske, bløde stil er lidt usædvanlig for så gammel en rom. Den forbliver stimulerende og livlig samtidig med, at den ikke har for megen indflydelse fra træet. Rum Nation Panama Black Decanter 21 år smagsnoter. Næse: frisk og sød på samme tid. Smag: fløjlsblød - slet ikke for skarp eller for fed. Chokolade, kandiseret appelsin og orangelikør. Tørrede figner og blandede tropiske frugter. Meget behagelig at drikke. Eftersmag: en smule pebret i kontrast til det bløde. Moderat sødme og lethed. Den umiddelbare forskel på den "almindelige" Decanter-udgave og denne Black Decanter udgave er, at flaskerne og alkoholprocenten varierer. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Peruano 8 år', 'https://rombo.dk/products/rum-nation-peruano-8', 299, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4d96d5a9-86a4-47df-9d80-d59a503672b1.png?v=1769420626', 'Rum Nation Peruano 8 år er en rom med stor karakter og overraskelser. Etiketten lover en sjælden Inka-oplevelse, og det får du. Næse: Massiv sødme, toffee, kaffe, mælke chokolade, abrikos, vanille, nødder. Smag: Krydderi bombe, appelsin, sød mokka chokolade og nødder. Karakteristiske gummi noter. Overrasker med en markant anderledes smag i.f.t. duften. Eftersmag: Lang krydret eftersmag, men udvikler en sødme og er en reprise af smagen. Vanille slutter af. Rum Nation Peruano vandt prisen som bedste rom op til 8 år i 2009. 2015 Release. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Barbados 2008 Foursquare single cask rom', 'https://rombo.dk/products/rum-nation-rare-rums-barbados-2008', 1295, false, 70, 56, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a6ffb6b7-4d08-49ba-b297-a7466c07d5ec.png?v=1769438183', 'Rum Nation Rare Rums Barbados 2008 er en single cask rom fra det velrenommerede Foursquare Distillery. Rommen er destilleret hos Foursquare i 2008, herefter lagret i et ex-bourbonfad, og afslutningsvis er den tappet af Mac Y i 2024 fra Cask No. 9. Aromaen byder på kokos, vanilje, egetræskrydderier, læder og citrus. Når denne rom smages, fremkommer rige noter af mørk chokolade, brunt sukker, kandiserede mandler og kaffe, mens eftersmagen tilføjer vanilje, egetræ og tanniner. Kun 217 flasker eksklusivt til det danske marked. 56% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Belize 2008 Cask No. 10', 'https://rombo.dk/products/rum-nation-rare-rums-belize-2008', 1249, true, 70, 53.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9c0e20fb-4c51-4c2e-ad8c-b39171c06f28.png?v=1769419950', 'Rum Nation Rare Rums Belize 2008 Cask No. 10 er en 17 års single cask rom, der er tappet eksklusivt til Danmark. Rommen er fremstillet hos Traveller''s destilleriet i Belize, hvor den først er blevet tropisk lagret i 5 på et ex-bourbonfad, inden den er blevet færdiglagret i tempereret klima i 12 år. Rum Nation Rare Rums Belize 2008 har en duft af kokos, tropiske frugter og melasse, mens smagen byder på vanilje, kokos og mandler. Det enkelte fad (cask no. 10) har givet i alt 290 flasker rom, der er tappet ved fadstyrke. BEMÆRK : på bag-etiketten står der ved en fejl, at rommen er lagret 5 + 2 år, men sandheden er 5 + 12 år, som skrevet i vores tekst. 53,2% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Caroni 25 år', 'https://rombo.dk/products/rum-nation-rare-rums-caroni-25', 4799, true, NULL, 59, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rum_Nation_Rare_Rums_Caroni_25_ar.png?v=1770201209', 'Rum Nation Rare Rums Caroni 25 års kommer fra det legendariske lukkede destilleri i Trinidad. Efter 70 måneder på tidligere whisky-fade, er rommen blevet ''tæmmet'' en smule. Taninerne i rommen forstærkes af en fyldig smag af rosiner, uden at de på nogen måde overdøves. I næsen oplever du først og fremmest estere som bergamotte og cola, men også mere aromatiske krydderier som anis og lakrids, samt de ''sædvanlige'' mørke egetræsnoter. Finishen på whisky-fade er mere mærkbar i smagen. Rommen begynder med at være fyldig, saftig, ja nærmest fløjlsblød med sin rosin-karakter og smag af appelsinmarmelade. Lige når du tror, at denne rom er mere sød og blød end forventet, rammer de mere typiske og kraftige noter af lakrids, nellike og sort kaffe for fuld styrke. Du sidder tilbage med kraftige og syrlige taniner. En rom med stor kompleksitet, der udvikler sig meget i glasset.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Enmore 25 år', 'https://rombo.dk/products/rum-nation-rare-rums-enmore-25', 3249, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rum_Nation_Rare_Rums_Enmore_25_ar.png?v=1770201288', 'Rum Nation Rare Rums Enmore 25 års rom er en ekstremt aromatisk rom, destilleret på en kolonnekeddel bygget i træ. På trods af sin muskuløse og kraftfulde karakter har den en blødhed fra de mange år på træfade. Det første, der rammer næsen, er en eksplosion af ''funky estere'': overmodne frugter såsom banan, papaya og avocado, sammen med en ''drillende'' note af trælim. Senere følger cola, bergamotte, peber, kanel og andre krydderier samt et hint af træ. I smagen finder du de samme frugtige og krydrede noter som i duften. Rommen er lang, saftig og sødmefyldt med en nærmest overvældende smag af estere, men er alligevel rund og cremet.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Hampden 24 år', 'https://rombo.dk/products/rum-nation-rare-rums-hampden-24', 2499, true, 70, 61.6, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c3539331-667f-4463-80a2-a057f5943edb.png?v=1769422765', 'Rum Nation Rare Rums er en "small batch" rom-serie i meget begrænset udgave. Rum Nation Rare Rums er kommet med 2 Hampden udgaver, hvor denne er en 24 års rom. Rommen er destilleret i 1992 og tappet på flaske i 2016 fra fadene #1-12. Rum Nation Rare Rums Hampden 24 år er meget esterfyldt og eksplosiv med noter af bl.a. gæret frugt, kanel, tjære, salt, grønne sukkerrør og den klassiske jamaicanske "funk". Der er produceret 504 flasker. 61,6% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Jamaica 10 år', 'https://rombo.dk/products/rnrr-jamaica-10-aar', 975, false, 70, 59.9, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9c8c858b-efde-437a-9a1e-56d8a551f61a.png?v=1769437167', 'Rum Nation Rare Rums Jamaica 10 år er destilleret i St. Catherine Parish i Jamaica - hvor der blot ligger et stort Single Estate Distillery. Her blev der i 2013 høstet sukkerrør og sukkerrørsmelassen blev senere destilleret på Pot Stills. Herefter er rommen lagret i 10 år på ex-bourbon fade. Rommen er sødmefuld, krydret og meget kompleks. Selvom den er fra Jamaica er den ikke overvældende præget af den karakteristiske jamaicanske funk, der dog stadig er tydeligt til stede i både duft og smag. Rum Nation Rare Rums Jamaica 10 år er lagt på flaske ved en fadstyrke af 59,9% alkohol. I duften mødes man af friske – næsten grønne – bananer. Banankage også! Esteren er tydelig men ikke tung. Sødmefuld krydderi (som Five Spice), med noter af grillet ananas, stjerne anis, kakao. Mange af noterne fra duften optræder også i smagen, men her tilføjes en dyb, cremet mundfylde (som lagkageflødeskum). Mange lag og noter. Esteren er til stede men er ikke overvældende. Eftersmagen er langvarig, og her finder man noter af tørrede frugter, krydderi, estere og igen med en tyk cremet mundfulde. 59,9% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Marie Galante rom', 'https://rombo.dk/products/rum-nation-rare-rums-marie-galante', 825, true, 70, 55.4, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1f9db7b1-03d2-4b7c-aa36-ce6640f3c188.png?v=1769439621', 'Denne unikke Rum Nation Rare Rums Marie Galante rom er destilleret i 2017 hos Pere Labat på øen Marie Galante, der er en del af Guadeloupe. Rommen er tropisk lagret i 5 år på ex-cognacfade, hvorefter den har fået en afsluttende lagring i 2 år på Oloroso sherryfade i Europa (Cask 291 og Cask 292). Når man dufter og smager Rum Nation Rare Rums Marie Galante, fornemmes en livlig og pompøs rom med vinøsitet og noter af bl.a. citrus, tørret frugt og krydderier. Der er ikke tilsat sødme, så her får du den naturlige rom med smæk på, og så er den ovenikøbet tappet ved højere alkoholstyrke. 55,4% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Port Mourant 12 år', 'https://rombo.dk/products/rum-nation-rare-rums-port-mourant-12-ars-rom', 865, true, 70, 59, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_685a8366-466c-4201-90b1-8a6ab0d419f1.png?v=1769434115', 'Rum Nation Rare Rums Port Mourant 12-års Sherry Finish rom er destilleret på en Port Mourant dobbelt pot still af træ, hvilket har givet rommen en moderat esterfyldt karakter. Esterne er blevet yderligere forstærket af 22 måneders efterlagring på tidligere Oloroso sherryfade. Rum Nation Rare Rums Port Mourant 12-års Sherry Finish rom har milde, frugtige og søde duftnoter af rosiner og sherrylagret whisky, tilsat et jordet strejf fra tønden. Rommen har tørre, vinøse og tanninfyldte smagsnoter med et strejf af lakrids, sandeltræ og lavendel. Begrænset udgivelse tappet i 2022 fra fad nr. 18 og 19 på i alt 984 nummererede flasker. 59% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Savanna 16 år', 'https://rombo.dk/products/rum-nation-rare-rums-savanna-16ars-rom', 1049, true, 70, 57.65, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_77f3f66d-b796-4089-99f3-a4a600240fbb.png?v=1769434108', 'Rum Nation Rare Rums Savanna 16-års Sherry Finish rom er en rom, der efter en lang fermentering blev destilleret på Savanna Distillery i 2006. Rommen har siden lagret 12 år i tropisk klima på tidligere cognacfade efterfulgt af 3,5 år i kontinentalt klima på Oloroso sherryfade. Rommen er tappet i 2022 fra de nøje udvalgte fade 816 og 817. Rum Nation Rare Rums Savanna 16-års Sherry Finish rom er en esterfyldt, aromatisk rom med duftnoter af bergamot, appelsinskal, nelliker, kaffe, cola og urter. Smagen er en balance af tanniner og søde noter af kakao og brændt sukker med et strejf af vermouth. Meget mørk og krydret eftersmag. Begrænset udgivelse på kun 1278 nummererede flasker. 57,65% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Venezuela rom', 'https://rombo.dk/products/rum-nation-rare-rums-venezuela', 895, true, 70, 54.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b07e9dd9-8d2f-4898-a4fd-f798c211b242.png?v=1769439624', 'Denne helt særlige Rum Nation Rare Rums Venezuela er en 15 års rom, der er fremstillet i 2010 hos Destilleria Sofa i Venezuela. Efter gæringen og destilleringen er rommen blevet tropisk lagret i 13 år i Venezuela på Cask No. 72-74, hvorefter den har fået yderligere 2 års lagring i Europa. Lagringen er hele vejen igennem foregået i brugte bourbonfade. Når man dufter til den vellagrede Rum Nation Rare Rums Venezuela 15 års rom, fornemmes bl.a. tropiske frugter, kandiseret citrus og varm vanilje. Smagen er cremet og byder på noter af mango, ristet banan og egetræskrydderier. Der er ikke tilsat sødme, så her får man den rå og kraftfulde rom og ovenikøbet ved højere alkoholstyrke. 54,2% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Versailles 16 år Peated Cask Finish', 'https://rombo.dk/products/rnrr-versailles-16-peated-cask', 1599, true, 70, 58.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_da123844-d411-42b9-96fa-179fb35b6548.png?v=1769437164', 'Rum Nation Rare Rums Versailles 16 år Peated Cask Finish er destilleret i en traditionel wooden pot still, og har derefter haft en lang modningsproces, afsluttet med en ekstralagring på fade som tidligere har indeholdt røget skotsk whisky. Rommen er aftappet ved 58,2% alkohol. Som et resultat er denne rom yderst fyldig og kompleks. Versailles var et af Guyanas mindste destillerier, og producerede rom helt frem til 1975, hvor det blev tvunget til at lukke. I 1977 opkøbte Enmore destilleriet Versailles’ gamle wooden pot still. Da Enmore lukkede i 1993 gik kedlen videre til Uitvlugt, og da Uitvlugt lukkede i 2000 gik kedlen videre til Guyanas eneste tilbageværende romdestilleri – Diamond Distillery. Diamond Distillery bruger stadig Versailles’ 250 år gamle trækedel til produktion af romspiritus, og navngiver ofte udgivelser efter kedlen. Rom som er produceret på Versailles-kedlen er kendetegnet ved at være fyldige og yderst aromatiske, og Versailles rom er højt værdsat iblandt romentusiaster for sin yderst særprægene smag og duft. I næsen mødes man af Agave og let røgede noter – som en god mezcal. Nok et resultat af lagring på røgede whiskyfade. Dog kan man stadigt dufte, at det er en rom der er tale om. Overmoden ananas og papaja, sødmefuld og med mild krydderi. Ganske kompleks. I smagen er tørvenoterne tydelige. Tør, med havsalt med syrlige bolsjer. Guyanarommens karakteristiske olierede fedme er til stede, ligeså den elegance som er karakteristisk for Versailles-kedlens destillater. Eftersmagen er lang, med noter af eukalyptus og stjerne anis, der særligt ligger sig langs kanten af tungen. Denne small batch rom fra Guyana er kun produceret i et begrænset omfang af 1136 flasker. 58,2% -70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Versailles 18 år Whisky Finish', 'https://rombo.dk/products/rum-nation-rare-rums-versailles-whisky-finish-18-ars-rom', 1249, true, 70, 59, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_718940bf-17c0-49e9-baa5-54d3c8fe420f.png?v=1769434111', 'Rum Nation Rare Rums Versailles Whisky Finish 2004/2022 er en rom, der blev destilleret på en Versailles pot still af træ i 2004 og har efter lang lagring fået yderligere karakter med 4,5 års eftermodning på skotske whiskyfade. Det har givet en rom med fyldig krop og florale aromaer af blandt andet kamille og medicinske urter med en antydning af kamfer og hvid peber. Rum Nation Rare Rums Versailles 18-års Whisky Finish rom har smagsnoter af bivoks, peber, citronskal og frugt, men uden funky estere, og en lang eftersmag med noter af te og kamille. Begrænset udgivelse tappet i 2022 fra fad nr. 74, 95 og 97 på i alt 972 nummererede flasker. 59% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums Versailles 30 år', 'https://rombo.dk/products/rum-nation-rare-rums-versailles-30-ars-rom', 4679, true, NULL, 56.8, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_36c9230d-b9ba-4f0b-aa42-b76e19ec8983.png?v=1769425533', 'Med Rare Rum Versailles 30 års rom får man en forrygende, intens rom, der er destilleret på en pot still af træ. Det har givet den kraftige estere, jordede, træede noter og en vinøt finish, som den har fået af sin afsluttende lagring på tønder, der tidligere har været brugt til skotsk whisky. En spændende fuldfed, vild og uregerlig rom, der nok har fået slebet kanterne under sin lange lagring, men ikke er blevet forudsigelig. Gaveæske med 50 cl – 56,8%');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Venezuela XO 25th Anniversary', 'https://rombo.dk/products/rum-nation-venezuela-xo', 565, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Rum_Nation_Venezuela_XO_25th_Anniversary.png?v=1770201531', 'Rum Nation Venezuela XO 25th Anniversary er en mellemsød rom, der udgives af den danske importør Mac Y ifm. Rum Nation mærkets 25 års jubilæum. Faktisk har Mac Y for nogle år siden overtaget det internationalt velkendte Rum Nation mærke fra den italienske grundlægger, Fabio Rossi, der stadig er tilknyttet som konsulent. Rommen er tropisk lagret i Venezuela i 6 år i ex-bourbonfade, og den er justeret med 15,4 gram sukker pr. liter, hvilket gør, at den kan betegnes som en mellemsød rom. Når man dufter til Rum Nation Venezuela XO 25th Anniversary rom, fornemmes noter af ristede mandler, nougat og kandiseret appelsinskal. Smagen byder på mørk chokolade, appelsin og eksotiske krydderier, der afsluttes med en lang, blød og cremet eftersmag. 43% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Samaroli Over the World Blended Rum 2015 2nd Edition', 'https://rombo.dk/products/samaroli-over-the-world-2016-edition-rum', 1175, false, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f7d38368-afea-4812-a85d-c4e33495767b.png?v=1769422657', 'Samaroli Over the World 2015 2nd Edition Rum er produceret af italienske Samaroli, der har tappet blendet rom fra Fiji, Jamaica, Barbados og Guyana på flaske efter endt lagring i Skotland i september 2016. Samarolis master blender har sammensat rommen far de single casks, der blev udgivet i 2015, blandt andet fra Uitvlugt og Hampden. Der er tale om en begrænset udgivelse på kun 260 flasker. Samaroli Over the World 2015 2nd Edition Rum har mangfoldige noter i god balance og med kendetegn fra de 3 regioner. 45% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santa Teresa 1796 Rom', 'https://rombo.dk/products/santa-teresa-1796', 475, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_79e60caf-f8c9-424b-988c-dda6a234e316.png?v=1769436726', 'Den prisbelønnede Santa Teresa 1796 Ron Antiguo de Solera Rum har en minimumsalder på 15 år - men der er også meget ældre rom i blandingen. Faktisk siger rygtet, at rommen rummer op til 80 år gamle romelementer. Rommens stil er en elegant mellemting mellem Guatemala og Guyana-rom. Næse: let, krydret, gummi-præg, sød, frisk, kanel/kardemomme, vanille, smeltet sukker/sirup, lys farin og rørsukker. Smag: let, frisk, sødme, så kommer krydderierne, vanille, meget kompleks og balanceret. En meget elegant rom. Eftersmag: lige tilpas fad, olieret og en krydret, syrlig-sød fornemmelse. Santa Teresa 1796 Ron Antiguo de Solera Rum 15 år vandt i 2010 International Rum Expert Panel sølv-medalje. 40% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santa Teresa Bicentenario AJ Vollmer Rom', 'https://rombo.dk/products/santa-teresa-bicentenario-aj-vollmer', 1995, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_621ed52a-533c-4fe1-8207-9f7f28cbf31b.png?v=1769420615', 'Denne romblanding har en gennemsnitsalder på 25 år. Hvert år tappes der 1.200 liter fra de mange fade, og så får de lov til at stå ''og simre'' i yderligere 15 år. Hver Santa Teresa Bicentenario AJ Vollmer Ron Anejo flaske er nummereret og bærer underskriften fra grundlæggeren af Santa Teresa huset - Alberto J. Vollmer. Denne rom blev første gang frigivet i 1996 og alderen har givet masser af smag og duft. Næse: Markant appelsin, typisk Santa Teresa, krydderier, behageligt rørsukker og i god balance. Smag: Kaffe, chokolade, krydderier og rørsukker. Eftersmag: Behagelige krydderier med en let sødme. 40% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santiago de Cuba 20 års rom', 'https://rombo.dk/products/santiago-de-cuba-20-ars-rom', 1995, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SantiagodeCuba20arsrom.png?v=1778057608', 'Ron Santiago de Cuba 20 Años Extra Añejo Gran Reserva er illustrationen af, hvad cubansk rom er i stand til, når rommen er tropisk lagret i høj varme i 20 år. Rommen er lagret på egetræsfade og kan kategoriseres som mellemsød. Når man dufter til denne Santiago de Cuba 20 års rom, fornemmes noter af karamel, tørret frugt og egetræskrydderier. Smagen byder på noter af kakao, toffee, vanilje og modne frugter. 40% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santiago de Cuba Ron Añejo 8 års Rom', 'https://rombo.dk/products/santiago-de-cuba-ron-anejo-8', 275, false, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_722062cc-0470-47c6-b12a-7762b339a333.png?v=1769421156', 'Santiago de Cuba Ron Anejo 8 år er en klassisk cubansk rom, som har et lidt lettere udtryk end andre rom, men allgevel har den lagrede roms noter. Rommen er blød, frugtig og rig på delikat aroma af honning, vanilje og kakao. Santiago de Cuba Ron Anejo er som andre rom fra Santiago de Cuba DOP-certificeret, hvilket betyder, at produktionsmetoder og alt fra sukkerrør til flaske er af cubansk oprindelse. Det betyder også, at rommen i Anejo 8 års-flasken er minimum 8 år gammel og at der kan være ældre rom i blandingen. Santiago de Cuba Ron Anejo 8 år har smagsnoter af tropisk frugt, honning, kaffe og kakao, der munder ud i søde noter af fad og krydrede noter. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santiago de Cuba Ron Extra Añejo 11 års Rom', 'https://rombo.dk/products/santiago-de-cuba-11-extra-anejo', 375, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_114b766e-48fb-4b62-adcb-366c7d9846bb.png?v=1769436041', 'Ron Santiago de Cuba Extra Añejo 11 Years Old er en magisk blanding af rom som er lagret i minimum 11 år. Rom fra Santiago de Cuba modnes i de berømte Don Pancho lagerbygninger, kendt som den cubanske roms katedral. Ifølge legenden er bygningerne anlagt med så kort afstand til togskinnerne, at fadene med rom skælver, hver gang et tog passerer, hvilket efter sigende skulle påvirke modningsprocessen. Santiago de Cuba Rom 11 år Ron Extra Anejo har et imponerende udseende; den fremstår klar med en dyb ravfarve, der er prydet med polerede bronze højdepunkter. Dens aroma er domineret af en træagtig essens snarere end en frugtagtig, hvilket komplementeres af noter af vanilje, kokos, mocha, melasse, honning og kanel. Der er også subtile antydninger af ahornsirup, grillede mandler og sort peber, som tilføjer en dybde til dens duftprofil. På ganen er den medium til fyldig og har en tør tekstur. Dog fornemmes svage noter af karamel og honning, der smelter sammen med smagsnuancer af smørkaramel, chokolade, mocha, vanilje og valnød. Dens eftersmag er langvarig, hvilket gør at man længe kan nyde indtryk af kanelkrydderi, brændt karamel og chokolade fudge. Dette afrundes med vedvarende noter af kanel, appelsinskal og en krydret undertone af sort peber.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santiago de Cuba Ron Extra Añejo 12 års Rom', 'https://rombo.dk/products/santiago-de-cuba-12-extra-anejo', 449, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_40aaa7b2-1c96-474b-a780-29e5476534d3.png?v=1769420724', 'Santiago de Cuba Ron Extra Anejo 12 års rom har en fyldig næse af sød, mørk kandis, nougat, sukkerrør og pikant krydret. Et hint af mint. Smag: Kompleks rom med klassisk Cuba-sødme og kombineret med krydderier. Smagen af vellagret rom er markant, og det giver ligesom en "peber" fornemmelse på tungen. Toner af mokka-chokolade. Fylder hele munden hurtigt. Eftersmag: Lang eftersmag af krydrede noter, og rom sødmen nærmest trækker ned i tungen. Santiago de Cuba Ron Extra Anejo 12 års rom vandt guld ved German Rum Fest i 2012 indenfor kategorien: Aged Rum 10-14 years old. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santos Dumont XO', 'https://rombo.dk/products/santos-dumont-xo', 399, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2ea14a8e-787c-49e5-9e39-096e45348c43.png?v=1769424696', 'Santos Dumont XO er fremstillet på den friskpressede sukkerrørsjuice og er et blend fra Brasilien, Mellemamerika og Vestindien. I det færdige blend er der anvendt bourbonfade, PX sherryfade og portvinsfade, der hver især giver forskellige noter til denne sukkerrørsspiritus. Santos Dumont XO har en duft af bl.a. banan, kokos og abrikos. I smagen finder man noter af bl.a. honning og gæret frugt, og eftersmagen er lang og sød. Santos Dumont, der levede 1873 - 1932 var iøvrigt arvtager til en brasiliansk sukkerrørsplantage, og han var sidenhen en legendarisk luftfartspioner, der bl.a. fløj rundt om Eifeltårnet i 1901 i et luftskib. 40% ABV - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Savanna Cuvee Maison Blanche Edition Grand Millesime 10 års Rom', 'https://rombo.dk/products/savanna-10-cuvee-maison-blanche', 699, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_36aa7091-f912-4b11-90eb-1a66f6008f3f.png?v=1769423831', 'Savanna 10 års rom Cuvee Maison Blanche Edition Grand Millesime 2008 er fra det meget anerkendte destilleri Savanna, der ligger på øen Reunion i det Indiske Ocean. Her producerer man en bred vifte af rom: lette rom-typer velegnet til cocktail, Rhum Tradionnel til ren nydelse, Grand Arome med ekstra aroma/esterindhold/smag, og så laver man også visse Rhum Agricole produkter, der er fremstillet af sukkerrørsjuice istedet for melasse (som de andre er). Savanna tilsætter ikke sukker i deres produkter, og der er derfor tale om ikke-sød naturlig rom. Lagringen foregår typisk i franske egetræsfade fra Limousin eller Allier. Denne Savanna 10 års rom er en såkaldt Cuvee Maison Blanche, hvilket betyder melasse-baseret rom og lagring i minimum 10 år i de franske egetræsfade. Dette er en special-udgave "Edition Grand Millesime 2008", hvilket vil sige, at rommen er destilleret i 2008. Savanna 10 år Cuvee Maison Blanche er en rom med noter af bl.a. frugtkompot og vanilje. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Savanna Lontan Straight Rhum Grand Arome', 'https://rombo.dk/products/savanna-lontan-straight-rhum-grand-arome', 549, true, 50, 74.9, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SavannaLontanStraightRhumGrandArome.png?v=1790000124', 'Den særlige Savanna Lontan Straight Rhum Grand Arome er en Limited Edition 2024 udgave, og der kun er lavet i 5.800 skønne eksemplarer af denne lyse rom ved intet mindre end 74,9% vol. Det er ovenikøbet en Grand Arome, og efter selv at have smagt den, var vi jo nødt til at have den på hylden ... Savanna Lontan Straight rommen er lavet på melasse fra Bois Rouge-sukkerrør, gæret i 8 dage og destilleret i en kolonne hos Distillerie Savanna på øen Réunion. Ester-indholdet er på 784,6 g/HLAP, så der er fuld fart på duft og smag. I næsen fornemmes noter af ananas, oliven og banan, mens smagen byder på tropiske frugter og (igen) oliven. 74,9% vol. - 50 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Savanna Rhum Vieux Traditionnel 7 års Rom', 'https://rombo.dk/products/savanna-7-rhum-traditionnel-vieux', 599, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_1e3b0492-ed33-4a96-9189-f5476a346529.png?v=1769423826', 'Savanna 7 års Rhum Traditionnel Vieux Savanna er fra det velrenommerede destilleri Savanna på øen Reunion i det Indiske Ocean. Her producerer man en bred vifte af rom: lette rom-typer velegnet til cocktail, Rhum Tradionnel til ren nydelse, Grand Arome med ekstra aroma/esterindhold/smag, og så laver man også visse Rhum Agricole produkter, der er fremstillet af sukkerrørsjuice i stedet for melasse (som de andre er). Savanna tilsætter ikke sukker i deres produkter, og der er derfor tale om ikke-sød naturlig rom. Lagringen foregår typisk i franske egetræsfade fra Limousin eller Allier. Denne Savanna 7 års rom er en såkaldt Rhum Traditionnel Vieux, hvilket betyder melasse-baseret rom og lagring i minimum 7 år i de franske egetræsfade. Savanna 7 år Rhum Traditionnel Vieux er en rom med noter af bl.a. frugtkompot og vanilje. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Savanna Rhum Vieux Traditionnel Vieux 5 års Rom', 'https://rombo.dk/products/savanna-5-rhum-traditionnel-vieux', 399, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2b52591c-4173-444f-a566-2ba8160d6455.png?v=1769423822', 'Savanna destilleriet ligger på øen Reunion i det Indiske Ocean, og her producerer man en bred vifte af rom: lette rom-typer velegnet til cocktail, Rhum Tradionnel til ren nydelse, Grand Arome med ekstra aroma/esterindhold/smag, og så laver man også visse Rhum Agricole produkter, der er fremstillet af sukkerrørsjuice istedet for melasse (som de andre er). Savanna tilsætter ikke sukker i deres produkter, og der er derfor tale om ikke-sød naturlig rom. Lagringen foregår typisk i franske egetræsfade fra Limousin eller Allier. Denne Savanna 5 års rom er en såkaldt Rhum Traditionnel Vieux, hvilket betyder melasse-baseret rom og lagring i minimum 5 år i de franske egetræsfade. Savanna 5 år Rhum Traditionnel Vieux er en rom, der har noter af træ, mango, ananas, vanilje og mandler. Nydes bedst ren eller med is. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Savanna The Very Rare Casks 2nd Release', 'https://rombo.dk/products/savanna-the-very-rare-casks', 3895, true, 70, 51, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_91c31b3e-6803-4f33-a660-d7f02ccc06b6.png?v=1769438507', 'Savanna The Very Rare Casks 2nd Release er en meget limiteret single cask no. 537 udgivelse fra øen Reunion, hvor Distillerie de Savanna har fremstillet rom i 75 år. Rommen er destilleret i en Savalle kolonne i 2001, hvorefter den er tropisk lagret i 17 år på Reunion. Herefter har rommen hvilet i ca. 6 år, inden den blev frigivet til verdensmarkedet i november 2024 (og kom til Danmark i maj 2025). Savanna The Very Rare Casks 2nd Release er en Grand Arome rom, der har været igennem en særlig gæringsproces, som intensiverer både duft og smag. Lagringen er foregået i franske ex-cognacfade. Der er kun lavet 300 flasker af denne "Rhum Traditionnel". 51% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS 2026 Romjulekalender 24 Days of Rum', 'https://rombo.dk/products/forudbestilling-af-sbs-2026-romjulekalender-24-days-of-rum', 995, true, NULL, 50.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS2026Romjulekalender24DaysofRum_39636bec-fd9f-43da-97a4-2a6522a5f2c5.png?v=1781881185', '2026-udgaven af 24 Days of Rum går i en helt anden retning end de tidligere udgaver, da den udelukkende indeholder ikke-søde rom fra SBS (Single Barrel Selection). 24 Days of Rum møder Single Barrel Selection. SBS Single Barrel Selection er - som navnet siger - single cask rom fra kun et enkelt fad. Her får man således 24 forskellige, unikke og eksklusive smagsoplevelser med naturlig rom, der ikke nøjagtigt kan genskabes. I kalenderen finder du mange forskellige, lande, destillerier, fadtyper, smagsprofiler, m.v. Den gennemsnitlige Vol. / Abv. er på 50,7%, så du får "smæk for skillingen". Udover de 24 x 2 cl., så medfølger der også 2 stk romglas, så du evt. kan smage sammen med kæresten, vennen eller naboen. BEMÆRK OGSÅ : hvis du ikke ønsker at vide, hvad SBS 2026 Romjulekalender 24 Days of Rum præcist indeholder, så skal du IKKE læse videre. Nedenfor følger programmet i kalenderen: French Antilles 2020 Grand Arome, Danish Virgin Oak Cask 50% Trinidad 2016, Bourbon &amp; Recioto Cask 46% Denmark 2018, Oloroso Cask 52% Mauritius 2009, Bourbon &amp; Port Cask 46% Nicaragua 2015, Bourbon &amp; Virgin Oak Cask 52% Guyana 2011 SVL, Bourbon Cask 55% Tahiti 2017, Bourbon &amp; Virgin Oak Cask 52% Jamaica 2012, Bourbon Cask 62,8% Caribbean (Blend), Bourbon &amp; Limoux Cask 52% India 2016, Bourbon Cask 55% Indonesia (blend), Bourbon &amp; PX Cask 50% Fiji 2020, Virgin Oak Cask 55% Jamaica 2020 MMW, Oloroso Cask 54% Panama 1998, Bourbon &amp; Stauning Whisky Cask 46% Phillipines 2019, Bourbon &amp; Virgin Oak Cask 52% Ecuador 2016, Bourbon &amp; Virgin Oak Cask 46% Ghana 2019 ARC, PX Cask 48% Reunion 2009, Bourbon &amp; PX Cask 50% Colombia 2012, Bourbon &amp; Port Cask 46% Jamaica EMB 2015, Bourbon Cask 52% Guatemala 2016, Bourbon &amp; Oloroso Cask 46% Venezuela 2010, Bourbon &amp; Parajete Cask 50% Scotland DS/TS 2022, Virgin Oak Cask 48% Jamaica 2020 WPE, Virgin Oak Cask 50%');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Antigua 2015 Rom', 'https://rombo.dk/products/sbs-antigua-2015-rom', 849, true, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e641be09-6d73-493f-b17c-0f87a31be829.png?v=1769437938', 'SBS Antigua 2015 Rom er en enkeltfadsrom, der er baseret på melasse og destilleret i et kolonne destilleringsapparat på øen Antigua i 2015. Rommen har lagret på henholdsvis et bourbon-fad og et marsala-fad, og den er tappet ved 55% alkoholstyrke i august 2024. SBS står for "Single Barrel Rum" og laves af den danske importør og uafhængige aftapper 1423 ApS. Den populære rom-serie har eksisteret i efterhånden nogle år, og man har med de nyeste "SBS Fall 2024" udgivelser netop passeret mere end 200 forskellige aftapninger siden begyndelsen. SBS Antigua 2015 Rom er begrænset til kun 369 flasker. Limited edition. 55% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Barbados 2013 Bourbon & Amontillado rom', 'https://rombo.dk/products/sbs-barbados-2013-bourbon-amontillado-rom', 799, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_aa42abcc-6749-4eed-a1b7-08b43b5c6997.png?v=1769438379', 'SBS Barbados 2013 rom er enkeltfadsrom, der er baseret på melasse og destilleret i såvel en pot still som i et kolonne destilleringsapparat på Barbados i 2013. Rommen har lagret på et ex-bourbonfad og herefter et amontillado-fad, inden den blev tappet ved 50% alkoholstyrke i februar 2025. I skrivende stund har vi også i sortimentet en SBS Barbados 2013, der er lagret på ex-bourbonfad og herefter et portvinsfad, så det kunne være interessant at smage disse op imod hinanden. SBS står for "Single Barrel Rum" og laves af den danske importør og uafhængige aftapper 1423 ApS. Den populære rom-serie har eksisteret i efterhånden nogle år, og man har med de nyeste "SBS Spring 2025" udgivelser lavet mere end 200 forskellige aftapninger siden begyndelsen. Når man dufter til SBS Barbados 2013 rommen, fornemmes noter af tørrede frugter, nødder, brunt sukker og blød vanilje. Smagen er lang og elegant med noter af ristede nødder, mandler, egetræskrydderier og modne druer. SBS Barbados 2013 rom er begrænset til kun 210 flasker og eksklusivt tappet til det danske marked. Denne rom er ikke kølefiltreret. 50% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Barbados 2013 Bourbon and Port Cask rom (bottled for Germany & Austria)', 'https://rombo.dk/products/sbs-barbados-2013-bourbon-port', 875, true, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6a1d0cb2-d78b-4386-bdd5-e3fa8b7e3e4a.png?v=1769439720', 'SBS Barbados 2013 Bourbon and Port Cask rom er "bottled for Germany &amp; Austria ", men vi fik ifm. en SBS romsmagning lov til at købe nogle flasker til butikken. SBS står for Single Barrel Selection, og denne serie af rom er lavet af den danske importør af rom, 1423 ApS. SBS Rum udgivelserne er ikke-søde (uden tilsat sukker), non-chill filtered og ved højere alkohol-styrke. Denne særlige Single Barrel Selection Barbados 2013 rom er baseret på melasse og destilleret i både et kolonneapparat og en pot still i 2013. Rommen er modnet på hhv. ex-bourbonfade og brugte portvinsfade, og den er aftappet ved 55% abv. i september 2025. I duften finder man vanilje, kokos, karamel, egetræskrydderier, tobak, læder, røde bær og blommer. Smagen er tør og fyldig med noter af bl.a. byder på noter af flødekaramel, krydret egetræ, mørke frugter og et strejf af peber. S.B.S Barbados 2013 rommen er ikke koldfiltreret, og den er begrænset til kun 312 flasker. 55% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Dominican Republic 2009 rom', 'https://rombo.dk/products/sbs-dominican-republic-2009-rom', 699, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_59a97699-c1b8-4125-bb60-3c51d8ca0729.png?v=1769438376', 'SBS Dominican Republic 2009 rom er enkeltfadsrom, der er baseret på sukkerrørsjuice og destilleret i et kolonne destilleringsapparat i Den Dominikanske Republik i 2009. Rommen har lagret på et ex-bourbonfad og herefter et cognacfad, inden den blev tappet ved 52% alkoholstyrke i februar 2025. SBS står for "Single Barrel Rum" og laves af den danske importør og uafhængige aftapper 1423 ApS. Den populære rom-serie har eksisteret i efterhånden nogle år, og man har med de nyeste "SBS Spring 2025" udgivelser lavet mere end 200 forskellige aftapninger siden begyndelsen. Når man dufter til SBS Dominican Republic 2009 rommen, fornemmes noter af grønne æbler, saftige druer og et elegant strejf af egetræ. Smagen er tør og fadpræget med noter af tørrede frugter, cremet vanilje og modne druer. SBS Dominican Republic 2009 rom er begrænset til kun 386 flasker og eksklusivt tappet til det danske marked. Denne rom er ikke kølefiltreret. 52% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Ecuador 2016 Rom - Bourbon and Virgin Oak Cask', 'https://rombo.dk/products/sbs-ecuador-2016-rom-bourbon-and-virgin-oak-cask', 799, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-249_ecuador-2016.png?v=1788953852', 'Denne SBS Ecuador 2016 er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS Ecuador 2016 rommen er lavet på melasse og kolonnedestilleret. Lagringen er foregået tropisk i 5 år i Ecuador på bourbonfade og derefter i 4 år på Fyn i et 200 liters Virgin Oak fad. Duften byder på karamel, vanilje, tropisk frugt, appelsinskal, kokos og egetræ. Smagen har noter af bl.a. toffee, frugt, kakao og kanel. Limited edition enkeltfadsaftapning med kun 221 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Fiji 2002 Rom', 'https://rombo.dk/products/sbs-fiji-2002-rom', 1299, true, 70, 57.1, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_cc19637a-6921-4a89-b599-600078efba35.png?v=1769435915', 'SBS Fiji 2002 er en enkeltfadsrom, baseret på 100% melasse og destilleret i en pot still i 2002. Denne rom er modnet på et ex-Bourbon-fad og er aftappet ved en styrke på 57,1% i februar 2021. Rommen er ikke koldfiltreret, og der er ikke brugt tilsætningsstoffer. Rommen er fra South Pacific Distillery, som er kendt for sine karakteristiske smagsnoter, som inkluderer en unik blanding af frugtige, røgede og næsten medicinske nuancer. Duften byder på en markant og funky profil, som man ofte associerer med jamaicanske rom, og giver noter af syrlige tropiske frugter kombineret med spor af wasabi og honning. På tungen starter den blød og tør, hvor en let syrlighed snart suppleres af modne tropiske frugter og honning, alt sammen afrundet af en let prikkende afslutning. SBS Fiji 2002 er begrænset til kun 240 flasker. 57,1% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Fiji 2004 Rom', 'https://rombo.dk/products/sbs-fiji-2004-rum', 1749, true, 70, 68.3, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5e74269b-290e-4c46-a0c7-1dfff14ce64f.png?v=1769434045', 'SBS Fiji 2004 Single Barrel Selection rom er udgivet i oktober 2022 som en del af 1423s serie af enkeltfadsaftapninger fra hele verden. Kendetegnet for serien er, at de enkelte fade tappes, når de er på deres højeste og ofte ved fadstyrke. Dette gælder også SBS Fiji 2004 Single Barrel Selection, der er blevet tappet i 2022 ved fadstyrke 68,3 % ABV efter at have ligget på fad i 18 år. SBS Fiji 2004 rom har florale duftnoter med strejf af creme, læder valnødder og vanilje og smagsnoter af ristede kaffebønner, brændt karamel, kokos og mentol. Begrænset oplag på bare 210 flasker. 68,3 % –70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Fiji 2020 Virgin Oak rom', 'https://rombo.dk/products/sbs-fiji-2020-rom', 649, true, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e7680cff-7bdd-4c3a-bbf1-5c3916a94a75.png?v=1769438369', 'SBS Fiji 2020 rom er enkeltfadsrom, der er baseret på melasse og destilleret i et pot still destilleringsapparat på Stillehavs-øen Fiji i 2020. Rommen har lagret på et frisk Virgin Oak fad, og den er tappet ved 55% alkoholstyrke i februar 2025. SBS står for "Single Barrel Rum" og laves af den danske importør og uafhængige aftapper 1423 ApS. Den populære rom-serie har eksisteret i efterhånden nogle år, og man har med de nyeste "SBS Spring 2025" udgivelser lavet mere end 200 forskellige aftapninger siden begyndelsen. Når man dufter til SBS Fiji 2020 rommen, fornemmes noter af moden melon, pærer, ristede nødder og et strejf af grønne oliven. Smagen er frugtig og krydret med fine noter af vanilje og tørrede frugter. SBS Fiji 2020 rom er begrænset til kun 384 flasker og eksklusivt tappet til det danske marked. Denne rom er ikke kølefiltreret. 55% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS French Antilles Grand Arome 2020 Rom - Danish Virgin Oak Cask', 'https://rombo.dk/products/sbs-french-antilles-grand-arome-2020-rom-danish-virgin-oak-cask', 899, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-246_french-antilles-2020-grand-arome.png?v=1788953951', 'Denne SBS French Antilles Grand Arome 2020 er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS French Antilles Grand Arome 2020 rommen er lavet på melasse og kolonnedestilleret. Vi kan hviske højt, at vi taler om rom fra Martinique. Lagringen er foregået i 6 år på Fyn i et 200 liters Virgin Oak fad. Duften byder på overmoden frugt, oliven, vanilje og egetræskrydderier. Smagen har noter af bl.a. tropisk frugt, sukkerrørssirup, salt og tanniner fra det danske egetræ. Limited edition enkeltfadsaftapning med kun 54 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Ghana 2019 ARC Rom - PX Cask', 'https://rombo.dk/products/sbs-ghana-2019-arc-rom-px-cask', 999, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-250_ghana-2019-arc.png?v=1788953918', 'Denne SBS Ghana 2019 ARC er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS Ghana 2019 ARC rommen er lavet på den friskpressede sukkerrørssaft og destilleret i en pot still. Lagringen er foregået i 7 år på Fyn i et 130 liters PX (Pedro Ximenez) sherryfad. Duften byder på grønne bananer, gæret frugt, rosiner, dadler, honning og ristede nødder. Smagen har noter af bl.a. tørret frugt, kakao og krydderier. Limited edition enkeltfadsaftapning med kun 75 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Guatemala 2016 Rom - Bourbon and Oloroso Cask', 'https://rombo.dk/products/sbs-guatemala-2016-rom-bourbon-and-oloroso-cask', 699, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-254_guatemala-2016.png?v=1788954163', 'Denne SBS Guatemala 2016 er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS Guatemala 2016 rommen er lavet på melasse og kolonnedestilleret. Lagringen er foregået tropisk i 4 år i Guatemala på bourbonfade og derefter i 5 år på Fyn i et 130 liters Oloroso sherryfad. Duften byder på honning, vanilje, ristede nødder, appelsinmarmelade og rosiner. Smagen har noter af bl.a. karamel, tørret frugt, chokolade og nødder. Limited edition enkeltfadsaftapning med kun 115 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Guyana 1990 Rum Uitvlugt (PM) rom', 'https://rombo.dk/products/sbs-guyana-1990-rum-uitvlugt-pm', 3699, true, NULL, 53.1, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9c24f08c-3bc4-4023-b681-b394b1fed8f5.png?v=1769424987', 'SBS Guyana 1990 Rum Uitvlugt (PM) rom er en enkeltfadsaftapning eller Single Barrel Selection (SBS), der er destilleret på den berømte Port Mourant Double Wooden Pot Still, som også er verdens ældste pot still lavet af træ. Port Mourant pot still stod på Uitvlugt Distillery, da rommen blev destilleret, hvormed Uitvlugt er angivet på flaskens label. Uitvlugt lukkede tilbage i 2000 og blev flyttet til Diamond Distillery (DDL). De kun ialt 192 flasker SBS Guyana 1990 Rum Uitvlugt (PM) rom er færdiglagret hos den danske importør 1423 ApS og tappet i februar 2021 ved 53,1% fadstyrke. SBS Guyana 1990 Rum Uitvlugt (PM) rom har en duft af bl.a. anis, hvid peber, træ og vanilje, mens smagen er kraftfuld og tør med noter af bl.a. toffee, salt og lakrids. 53,1% Cask Strength - Non Chill Filtered - ingen tilsætningsstoffer. 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Guyana 1993 Rom', 'https://rombo.dk/products/sbs-guyana-1993-rom', 3995, true, 70, 59.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_50e0ecdf-49e9-4829-a8a8-dd13170ded45.png?v=1769435881', 'SBS Guyana 1993 er en enkeltfadsrom, der er baseret på melasse. UDS henviser til, at rommen er destilleret på det legendariske ''Enmore Wooden Column Still'', da det stod på Uitvlugt Distillery i 1993. Rommen er modnet på et ex-Bourbon-fad og er aftappet ved en fadstyrke på 59,2 % vol i august 2023. Rommen er ikke koldfiltreret, og der er ikke brugt tilsætningsstoffer. Duften er fortryllende med noter af sød frugt, der udfolder sig smukt. Disse frugtagtige noter ledsages af subtile hints af vanilje og en blid duft af eg. Når det kommer til smagen, kan man opleve en harmonisk fusion af både frugtagtige og krydrede nuancer. Denne komplekse smagsoplevelse kulminerer i en tilfredsstillende finish med en rig smag af toffee. SBS Guyana 1993 er begrænset til kun 136 flasker. 59,2% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Guyana 2012 LBI rom (bottled for Germany & Austria)', 'https://rombo.dk/products/sbs-guyana-2012-lbi', 1195, true, 70, 59.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_3b51e612-aaee-4d68-887d-77337e9974dc.png?v=1769439723', 'SBS Guyana 2012 LBI er "bottled for Germany &amp; Austria", men vi fik ifm. en SBS romsmagning lov til at købe nogle flasker til butikken. SBS står for Single Barrel Selection, og denne serie af rom er lavet af den danske importør af rom, 1423 ApS. SBS Rum udgivelserne er ikke-søde (uden tilsat sukker), non-chill filtered og ved højere alkohol-styrke. Denne særlige SBS Guyana 2012 LBI rom er baseret på melasse og destilleret i et kolonneapparat i 2012. Rommen er modnet på et ex-bourbonfad, og den er aftappet ved 59,7% abv. i september 2025. Duften er elegant og floral med urter, grøn te, tropisk frugt og kokos. Smagen er let og afrundet med friske urter, citrus, grønne æbler, vanilje og en let krydret finish. SBS Guyana 2012 LBI rommen er ikke koldfiltreret, og den er begrænset til kun 204 flasker. 59,7% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Indonesia 2021 Rom - Bourbon and PX Cask', 'https://rombo.dk/products/sbs-indonesia-2021-rom-bourbon-and-px-cask', 799, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-240_indonesia-blend.png?v=1788954126', 'Denne SBS Indonesia 2021 er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS Indonesia 2021 rommen er lavet på melasse og destilleret i en pot still. Lagringen er foregået tropisk i 1 år i Indonesien på bourbonfade og derefter i 4 år på Fyn i et 250 liters PX sherryfad. Duften er mineralsk og krydret, og den byder desuden på melasse, rosiner, figen og ristede nødder. Smagen har noter af bl.a. tørret frugt, chokolade og sirup. Limited edition enkeltfadsaftapning med kun 229 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Jamaica 2010 EMB rom (bottled for Germany & Austria)', 'https://rombo.dk/products/sbs-jamaica-2010-emb', 1249, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_45161d86-ebda-40f9-b3f1-e782ddbb9347.png?v=1769439727', 'SBS Jamaica 2010 EMB rom er "bottled for Germany &amp; Austria", men vi fik ifm. en SBS romsmagning lov til at købe nogle flasker til butikken. SBS står for Single Barrel Selection, og denne serie af rom er lavet af den danske importør af rom, 1423 ApS. SBS Rum udgivelserne er ikke-søde (uden tilsat sukker), non-chill filtered og ved højere alkohol-styrke. Denne særlige Jamaica 2010 EMB rom er baseret på melasse og destilleret i en pot still i 2010. Rommen er modnet på et ex-bourbonfad, og den er aftappet ved 57% abv. i september 2025. I duften finder man overmoden banan og mango med noter af kokos, grønne oliven og urter. Smagen er intens og frugtig med tobak, sort peber, karamel, toffee og krydret egetræ. SBS Jamaica 2010 EMB rommen er begrænset til kun 224 flasker. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Jamaica 2016 WPL rom', 'https://rombo.dk/products/sbs-jamaica-2016-wpl-rom', 599, false, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_31bbb925-e3ce-46b3-9a69-263826f1558b.png?v=1769438373', 'SBS Jamaica 2016 WPL rom er enkeltfadsrom, der er baseret på melasse og destilleret i et pot still destilleringsapparat på Jamaica i 2016. Rommen har først lagret på et ex-bourbonfad og sidenhen et Marsala-fad, inden den blev tappet ved 57% alkoholstyrke i februar 2025. SBS står for "Single Barrel Rum" og laves af den danske importør og uafhængige aftapper 1423 ApS. Den populære rom-serie har eksisteret i efterhånden nogle år, og man har med de nyeste "SBS Spring 2025" udgivelser lavet mere end 200 forskellige aftapninger siden begyndelsen. Når man dufter til SBS Jamaica 2016 WPL rommen, fornemmes noter af vanilje, æbler, tørrede frugter og et strejf af læder. Smagen er intens og funky med dybe noter af tørrede frugter, moden frugt, karamel og cremet vanilje. SBS Jamaica 2016 WPL rom er begrænset til kun 376 flasker og eksklusivt tappet til det danske marked. Denne rom er ikke kølefiltreret. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Jamaica 2016 WPL rom (bottled for Belgium/France)', 'https://rombo.dk/products/sbs-jamaica-2016-wpl-rom-bottled-for-belgium-france', 749, true, NULL, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-218Jamaica2016WPLrom.png?v=1773829853', 'SBS Jamaica 2016 WPL Bourbon and Marsala Cask rom er en del af Single Barrel Selection serien, der består af unikke enkeltfadsaftapninger, som er "non-chill filtered" og uden tilsætning af sødme eller farve. Denne helt særlige SBS Jamaica 2016 WPL Bourbon and Marsala Cask rom er nr. 218 i SBS-serien, og den er faktisk udgivet i Belgien og Frankrig, men vi fik mulighed for at skaffe nogle få flasker ifm. en SBS-romsmagning i butikken. Single Barrel Selection Jamaica 2016 WPL er baseret på melasse og destilleret i en pot still i 2016. Rommen er modnet på både bourbonfade og Marsalafade, og den er aftappet i september 2025. WPL står for "Worthy Park Light", som er et marque, der referer til Ester-indholdet i rommen. Når man dufter til denne rom, fornemmes noter af moden banan, ananas, papaya, tørret frugt, nødder og et strejf af honning. Smagen byder på tropiske frugter såsom mango og ananas, kombineret med karamel og ristede nødder. Der er kun tappet 396 flasker ved 52% abv.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Jamaica 2020 DOK Port Cask 20 cl. rom', 'https://rombo.dk/products/sbs-jamaica-2020-dok-port-20-cl', 199, true, 20, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2d9eff6d-84c7-4787-8b9a-fb8643af91e0.png?v=1769439737', 'Denne skønne 20 cl. smagsprøve på SBS Jamaica 2020 DOK Port Cask rom er en del af en tidligere gaveæske på i alt 4 x 20 cl. Jamaica DOK med forskellige typer fadlagring, som i 2023 har været udgivet i Danmark, men nu er udsolgt. Vi fik dog mulighed for at købe de overskydende løse flasker hos producenten, 1423 ApS. SBS Jamaica 2020 DOK Port Cask er baseret på melasse og lagret i godt og vel 2 år i portvinsfade. "DOK" eller Dermot Owen Kelly er et legendarisk mark fra Hampden Estate på Jamaica, og det er rommen med det højeste esterindhold på Hampden Estate. DOK når de højeste lovlige niveauer af esterindhold for rom på 1.500-1.600 gr/HLPA. At smage på DOK er en ekstrem intens, men yderst informativ oplevelse. Oftest finder man DOK rom, der er lagret på bourbonfade, men her er der mulighed for at prøve, hvordan den smager på portvinsfade. 57% - 20 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Jamaica 2020 Rom - Oloroso Cask', 'https://rombo.dk/products/sbs-jamaica-2020-rom-oloroso-cask', 799, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-243_jamaica-2020-mmw.png?v=1788953985', 'Denne SBS Jamaica 2020 er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS Jamaica 2020 rommen er lavet på melasse, pot still destilleret, og den har marque MMW, hvilket vil sige, at det er Wedderburn typen, hvad angår ester-indholdet. Lagringen er foregået i 6 år på Fyn i et 130 liters Oloroso sherryfad. Duften byder på banan, ananas, rosiner, valnødder og brunt sukker. Smagen har noter af bl.a. tropisk frugt, sherrysødme, egetræskrydderier og nødder. Limited edition enkeltfadsaftapning med kun 69 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Jamaica 2020 WPE rom (bottled for Germany/Austria)', 'https://rombo.dk/products/sbs-jamaica-2020-wpe-rom-bottled-for-germany-austria', 949, true, NULL, 58.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-222Jamaica2020WPErom.png?v=1773832461', 'SBS Jamaica 2016 WPE Virgin Oak rom er en del af Single Barrel Selection serien, der består af unikke enkeltfadsaftapninger, som er "non-chill filtered" og uden tilsætning af sødme eller farve. Denne helt særlige SBS Jamaica 2016 WPE Virgin Oak rom er nr. 222 i SBS-serien, og den er faktisk udgivet i Tyskland og Østrig, men vi fik mulighed for at skaffe nogle få flasker ifm. en SBS-romsmagning i butikken. Single Barrel Selection Jamaica 2016 WPE er baseret på melasse og destilleret i en pot still i 2016. Rommen er modnet på et helt frisk egetræsfad (virgin oak), og den er aftappet i september 2025. WPE står for "Worthy Park Extra", som er et marque, der referer til Ester-indholdet i rommen. Når man dufter til denne rom, fornemmes intense og funky noter af overmoden banan, saftig ananas og varme krydderier. Smagen byder på tørret frugt, mango, cremet vanilje og muskat. Der er kun tappet 323 flasker ved 58,7% abv.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Jamaica C<>H 2021 Rom', 'https://rombo.dk/products/sbs-jamaica-2021-ch', 699, true, 70, 59.7, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_913522c9-f6d0-4f2b-a9ed-aab0b1752ec1.png?v=1769436995', 'SBS Jamaica 2021 C&lt;&gt;H er en enkeltfadsrom, der er baseret på melasse og destilleret i et pot still i 2021. Rommen er ikke koldfiltreret. Rommen har lagret på en Virgin Oak-fad og er tappet ved 59,7% alkoholstyrke i januar 2024. C&lt;&gt;H er et marque, der angiver en rom, der er produceret med et esterindhold på mellem 1300-1400, meget tæt på det maksimum tilladte ifølge jamaicansk regulering. SBS Jamaica 2021 C&lt;&gt;H byder på en unik og livlig duftoplevelse, hvor næsen bliver mødt af funky, ester-noter, der præsenterer overmodne ananas- og bananaromaer. Ved første smag forkæler du dine smagsløg med de rige smagsoplevelser af overmodne frugter, ledsaget af sød vanilje. Denne fornøjelse fører til en træagtig og ristet afslutning, der tilføjer dybde og kompleksitet til hver eneste tår. SBS Jamaica 2021 C&lt;&gt;H er begrænset til kun 367 flasker. Eksklusivt flasket til det danske marked. 59,7% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Jamaica WPE 2020 Rombo Edition  63,3% Rom', 'https://rombo.dk/products/sbs-jamaica-2020-wpe-rombo', 899, true, 70, 63.3, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS_Jamaica_WPE_2020_Rombo_Edition_63_3_Rom_36e07eae-b2a7-4688-90ec-d557fe6ca4ac.png?v=1780487510', 'SBS Jamaica 2020 WPE Rombo Edition er en melassebaseret enkeltfadsrom, destilleret i en pot still i 2020. Rommen har modnet på et ex-bourbon-fad og er blevet aftappet ved en styrke på 63,3% vol i november 2023. Den er ikke koldfiltreret, og der er ikke brugt tilsætningsstoffer. Rommen stammer fra Worthy Park i Jamaica og bærer marque WPE, der står for Worthy Park Extra. Dette marque har det højeste esterniveau, som Worthy Park producerer, og det kan nå op til 800 gr/hL AA. Da Worthy Park normalt er kendt for at producere rom med esterniveauer i den lavere til medium ende af skalaen, finder vi denne rom særligt spændende, da den repræsenterer et anderledes udtryk fra destilleriet. SBS Jamaica 2020 WPE Rombo Edition er begrænset til kun 118 flasker og er eksklusivt tappet til Rombo. 63,3% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Nicaragua 2015 Rom - Bourbon and Virgian Oak Cask', 'https://rombo.dk/products/sbs-nicaragua-2015-rom-bourbon-and-virgian-oak-cask', 799, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-234_nicaragua-2015-svl.png?v=1788953884', 'Denne SBS Nicaragua 2015 er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS Nicaragua 2015 rommen er lavet på melasse og kolonnedestilleret. Lagringen er foregået tropisk i 5 år i Nicaragua på bourbonfade og derefter i 6 år på Fyn i et 225 liters Virgin Oak fad. Duften byder på vanilje, kokos, honning, egetræ, appelsinskal og bagekrydderier. Smagen har noter af bl.a. karamel, vanilje, tropisk frugt, kanel og toastet egetræ. Limited edition enkeltfadsaftapning med kun 282 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Australia KLK Rom', 'https://rombo.dk/products/sbs-origin-australia-klk', 435, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_83cd4346-0d49-4855-a76f-7a63dd4e44b2.png?v=1769437028', 'SBS Origin Australia KLK er en del af 1423s SBS Origin Selection, som er en serie af håndplukket ulagret rom, der er specielt udvalgt for deres kraftfulde profil og smag. De valgte rom og marks er velkendte fra den lagrede rom fra SBS serien, og 1423 SBS Origin Selection er muligheden for at smage oprindelsen af den rommen. Nyd den ren, on the rocks eller brug den til dine cocktails. Denne flaske indeholder en vidunderlig hvid rom destilleret i traditionelle pot stills, hvilket giver fantastiske Daiquiris. SBS Origin Australia KLK har en ekstraordinært funky esterduft, der danser sammen med essens af jordbær og den saftige sødme fra modne pærer. Det første indtryk af smagen opleves som en dejlig kombination af pebret krydderi og sødme, som afsluttes af med en cremet og frugtagtig eftersmag. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Dominican Republic Aroma Grande Rom', 'https://rombo.dk/products/sbs-origin-dominican-republic-aroma-grande-rom', 375, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2fcee196-5bcb-420a-9c10-a169ae3d83a1.png?v=1769427551', 'SBS Origin Dominican Republic Aroma Grande rom er en ulagret, hvid kolonnedestilleret rom fra Den Dominikanske Republik. Rommen har et estercount på 500 gr/hl AA. SBS Origin Dominican Republic Aroma Grande har aroma af tørrede blomster, hvid peber og acetone, der suppleres af citrusskal og kraftige grapefrugtnoter. Smagen byder på masser af citrus, marcipan, florale noter med et strejf af lavendel og en olieret mundfølelse med en lang, tør finish. Forrygende rom til at booste en daiquiri, ren eller on the rocks. Ikke koldfiltreret. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Dominican Republic Consuelo Rom', 'https://rombo.dk/products/sbs-origin-dom-rep-consuelo', 385, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_7a112ecc-53ab-4c2b-809d-80cdfe6af977.png?v=1769437024', 'SBS Origin Dominican Republic Consuelo er en del af 1423s SBS Origin Selection, som er en serie af håndplukket ulagret rom, der er specielt udvalgt for deres kraftfulde profil og smag. De valgte rom og marks er velkendte fra den lagrede rom fra SBS serien, og 1423 SBS Origin Selection er muligheden for at smage oprindelsen af den rommen. Nyd den ren, on the rocks eller brug den til dine cocktails. Denne flaske indeholder en vidunderlig hvid rom destilleret i traditionelle pot stills, hvilket giver fantastiske Daiquiris. Med SBS Origin Dominican Republic Consuelo kan du i duften nyde sammenspillet mellem salt og græsnoter, der ledsages af subtile antydninger af ananas og den friskheden fra grønne peberfrugter. Ved første tår bemærkes en smule peber og funkiness, der balanceres smukt af en sød undertone og en forfriskende citrusnote. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Ecuador Malacatos Rom', 'https://rombo.dk/products/sbs-origin-ecuador-malacatos-hvid-rom', 399, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_b923c6c1-3f84-4ab9-8ca9-c5aa9966edfa.png?v=1769434466', 'SBS Origin Ecuador Malacatos hvid rom er en ny udgivelse i SBS Origin-serien, der er ulagrede versioner af velkendte, lagrede rom og marks fra SBS-serien. Serien giver mulighed for at smage rommen i sin oprindelige form, inden den har fået fad. SBS Origin Ecuador Malacatos er en hvid rom fra Ecuador, der er baseret på frisk sukkerrørsjuice og blev destilleret på kolonne stills i 2022. SBS Origin Ecuador Malacatos er en kraftig rom med duft af masser af modne frugter og hints af lime, oliven og lim. Smagen er knap så overvældende som duften, og romens smag er velafbalanceret med strejf af lime, sukkerrørsjuice, oliven og friske, grønne frugter. SBS Origin Ecuador Malacatos er skarp og intens, men stadig delikat, og egner sig både til at drikke ren og i f.eks. en daiquiri. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin French Antilles Grand Arome Rom', 'https://rombo.dk/products/sbs-origin-french-antilles-grand-arome-rom', 499, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_fb82d0ba-11cf-4597-9400-961fc2ac3a26.png?v=1769427555', 'SBS Origin French Antilles Grand Arome rom er en ulagret, hvid rom fra De Franske Antiller. Rommen er baseret på melasse, er destilleret på et dobbelt kolonnedestilleringsapparat af træ og har et estercount på ca. 500 gr/hl AA. SBS Origin French Antilles Grand Arome har frugtige og græsagtige duftnoter, der suppleres af modne appelsiner, friske sukkerrør, eukalyptus og et strejf af citrusfrugt. Smagen er tør med noter af hvid peber og fermenterede stenfrugter. Kan nydes ren, on the rocks eller som booster i cocktails. Ikke koldfiltreret. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Guadeloupe Red Cane Rom', 'https://rombo.dk/products/sbs-origin-guadeloupe-red-cane', 449, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_90b26de7-3a75-4b17-a34a-dfb9aee8d491.png?v=1769439703', 'SBS Origin Guadeloupe Red Cane er en hvid, ulagret rom, der er baseret på "Red Cane" sukkerrøret. Rommen er lavet af den friskpressede sukkerrørsjuice, som er blevet gæret og herefter kolonnedestilleret i 2022. Efter ankomsten til 1423 ApS i Danmark er den hvide rom ikke blevet lagret. Den har ligget på palletank for at "gifte sig", og den er blevet udgivet i 2023. SBS Origin Guadeloupe Red Cane rom er en del af 1423’s Origin-serie af ulagrede rom, der er nøje udvalgt ud fra deres kraftfulde karakter og smagsprofil. Serien er en mulighed for at smage de ulagrede versioner af 1423’s Single Barrel Selection-serie af lagret rom. Rommen kan nydes rent og gør det også fremragende som rom-ingrediens i en cocktail. Når man dufter til SBS Origin Guadeloupe Red Cane, fornemmes noter af friskklippet græs, citrus og modne frugter. Smagen er jordagtig og let saltet med noter af syrlighe ribs og en varm frugtig finish. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Guyana PM Rom', 'https://rombo.dk/products/sbs-origin-guyana-pm-rom', 399, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_cac266db-ad6e-4e26-a207-d6c9d7c6da8d.png?v=1769427559', 'SBS Origin Guyana PM rom er en ulagret, hvid rom, der er blevet destilleret på en dobbelt pot still i træ. Rommen har dermed fået en meget all-round smagsprofil, der gør den perfekt til at løfte de fleste cocktails. SBS Origin Guyana PM rom har spændende, krydrede og salte duftnoter med et strejf af ristet majs og tørrede dadler. Smagen er mild og sødmefuld med noter af skumfiduser, candyfloss og et hint af smør i eftersmagen. Kan nydes ren, on the rocks eller som booster i cocktails. Ikke koldfiltreret. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Jamaica Cane Juice Rom', 'https://rombo.dk/products/sbs-origin-jamaica-cane-juice-rom', 385, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e829ac2a-0454-4d70-92ff-b36330a1efda.png?v=1769436082', 'SBS Origin Jamaica Cane Juice Rom er en del af 1423''s SBS Origin-serie, der er nøje håndplukket ulagret rom, der er specielt udvalgt for deres kraftfulde profil og smag. Serien er en mulighed for at smage de ulagrede versioner af 1423’s Single Barrel Selection-serie af lagret rom. Nyd dem rene, on the rocks eller brug dem til dine cocktails. Denne flaske indeholder en vidunderlig hvid rom destilleret i traditionelle pot stills, hvilket giver fantastiske Daiquiris. SBS Origin Jamaica Cane Juice Rom lægger ud med en aroma af græsagtige undertoner, modne frugter, et strejf af sort peber og sødmen fra sukkerrør. Rommen har en let saltet smag der blandes med en overflod af friske tropiske frugter, hvilket fører til en delikat lang finish. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Jamaica TECC Rom', 'https://rombo.dk/products/sbs-origin-jamaica-tecc-rom', 475, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6f7629d2-d1c6-415c-85e7-7cb60f5e8bda.png?v=1769434587', 'SBS Origin Jamaica TECC rom er en ulagret, hvid pot still-rom i den tungere ende med et estercount på 1500-1700 gr/hl AA. Rommen har således marque TECC og er fra Long Pond Distillery. SBS Origin Jamaica TECC lægger ud med en intens og funky aroma, der udvikler sig med noter af tropiske frugter og sukkerrørsjuice. Rommen har funky, tropiske og krydrede noter, der munder ud i en sødere eftersmag. Nyd den ren, on the rocks eller som booster i din Daiquiri cocktail. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Origin Jamaica WPH Rom', 'https://rombo.dk/products/sbs-origin-jamaica-wph-hvid-rom', 399, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e985e6fa-eaae-4b99-ba5e-970ef0da254d.png?v=1769434463', 'SBS Origin Jamaica WPH hvid rom er en ny udgivelse i SBS Origin-serien, der er ulagrede versioner af velkendte, lagrede rom og marks fra SBS-serien. Serien giver mulighed for at smage rommen i sin oprindelige form, inden den har fået fad. SBS Origin Jamaica WPH er en hvid rom fra Jamaica, der er baseret på melasse, og blev destilleret på pot still i 2021. Destilleringen på pot still giver en kraftig, smagfuld og lækker rom, der egner sig fortrinligt til daiquiris, men også kan nydes ren. SBS Origin Jamaica WPH dufter af nyslået græs og tropisk frugt og bliver ved at udvikle sig i glasset. Den har smag af eksotiske frugter, banan og frisk sukkerrørsjuice samt godt med jamaicansk ’funkyness’. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Panama 2010 Rom', 'https://rombo.dk/products/sbs-panama2010-rom', 649, false, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_dd3139e2-c08f-48c2-952a-3c975fdae670.png?v=1769435906', 'SBS Panama 2010 er en enkeltfadsrom, der er baseret på melasse og destilleret i et kolonne still i 2010. Rommen er modnet på både ex-Bourbon og virgin oak fad og er aftappet ved en styrke på 55 % vol i august 2023. Rommen er ikke koldfiltreret, og der er ikke brugt tilsætningsstoffer. Duften åbner med en forfriskende aroma af grønne æbler, som straks suppleres af en harmonisk blanding af forskellige tørrede frugter. Dertil tilføjes et delikat strejf af mandler, der beriger profilen. På smagssiden præsenteres en kombination af krydrede, træagtige elementer, der smukt balanceres med noter af sød karamel. Denne smagsoplevelse kulminerer i en vedvarende og delikat tør finish. SBS Panama 2010 er begrænset til kun 419 flasker. Eksklusivt flasket til det danske marked. 55% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Panama 2012 Rom', 'https://rombo.dk/products/sbs-panana-2012', 695, true, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6e9dcf45-efc7-4e70-8e71-7213aaba0a9e.png?v=1769437004', 'SBS Panama 2012 er en enkeltfadsrom, der er baseret på melasse og destilleret i et kolonne still i 2012. Rommen har lagret på et Bourbon-fad og er tappet ved 55% alkoholstyrke i januar 2024. Rommen er ikke koldfiltreret. SBS Panama 2012 har en nuanceret aroma, hvor forfriskende mynte, sødmen fra melasse og subtile træagtige noter smelter sammen. Ved første sip åbenbares en tør og tanninrig smagsoplevelse, ledsaget af vaniljesødme, et strejf af hvid peber og en vedvarende finish af rig karamel. En smagsoplevelse af balanceret kompleksitet, der tilfredsstiller ganen fra start til slut. SBS Panama 2012 er begrænset til kun 282 flasker. Eksklusivt flasket til det danske marked. 55% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Phillipines 2019 Rom', 'https://rombo.dk/products/sbs-phillipines-2019-rom', 599, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4569eaf9-6651-47e1-ba95-67c1da9dce49.png?v=1769435897', 'SBS Philippines 2019 er en enkeltfadsrom, der er baseret på melasse og destilleret i et kolonne still i 2019. Rommen er modnet på både et ex-bourbon og virgin oak-fad og er aftappet ved en styrke på 57 % vol i August 2023. Rommen er ikke koldfiltreret, og der er ikke brugt tilsætningsstoffer. Duften er en forfriskende blanding af citrusnuancer, der smukt kombineres med sødmen fra karamel og vanilje. Dertil kommer subtile træundertoner, der giver profilen ekstra dybde. Når du smager, vil du først bemærke en let karamelliseret sødme, der hurtigt komplementeres af et væld af tørrede frugter. Dette ledsages af den varme og rige smag af bourbon vanilje. SBS Philippines 2019 er begrænset til kun 312 flasker. Eksklusivt flasket til det danske marked. 57% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Scotland 2022 DS/TS Rom - Virgin Oak Cask', 'https://rombo.dk/products/sbs-scotland-2022-ds-ts-rom-virgin-oak-cask', 649, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-247_scotland-ds-ts-2022.png?v=1788954078', 'Denne SBS Scotland 2022 er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS Scotland 2022 rommen er lavet på melasse og pot still destilleret. Lagringen er foregået kontinentalt i et 200 liters Virgin Oak fad. Duften byder på vanilje, toastet egetræ, melasse og citrus. Smagen har noter af bl.a. karamel, egetræskrydderier, tropisk frugt og peber. Limited edition enkeltfadsaftapning med kun 219 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Trinidad 2016 Rom - Bourbon and Recioto Cask', 'https://rombo.dk/products/sbs-trinidad-2016-rom-bourbon-and-recioto-cask', 649, true, NULL, NULL, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS-255_trinidad-2016.png?v=1788954044', 'Denne SBS Trinidad 2016 er en af de udvalgte rom i den særlige SBS Single Barrel Selection 2026 romjulekalender, hvor der er tappet 24 unikke og forskellige single casks. Der er lavet 5.000 eksemplarer af julekalenderen til det globale marked, og en stor del af fadene er gået til dette formål. Der har dog været en resterende beholdning i de fleste af de 24 fade, og denne har man tappet på almindelige 70 cl. flasker i et meget begrænset antal. Hos Rombo har vi udvalgt 9 af de 24 rom i kalenderen, og disse kan nu købes i den fulde flaskestørrelse. SBS Trinidad 2016 rommen er lavet på melasse og kolonnedestilleret. Lagringen er foregået tropisk i 5 år i Trinidad på bourbonfade og derefter i 4 år på Fyn i et 225 liters Recioto fad. Duften byder på mint, eucalypsos, citrus, kirsebær, rosiner og kakao. Smagen har noter af bl.a. karamel, røde frugter, mørk chokolade, urter og egetræskrydderier. Limited edition enkeltfadsaftapning med kun 388 flasker til det globale marked.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Venezuela 2006 rom', 'https://rombo.dk/products/sbs-venezuela-2006-rom', 849, false, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_ff843b63-2963-4c6b-9a6e-8b8d0fbb5bc0.png?v=1769434482', 'SBS Venezuela 2006 rom er en enkeltfadsrom fra Venezuela, der er baseret på melasse og blev destilleret på kolonne still tilbage i 2006. Rommen har efter destillering lagret på tidligere bourbonfade og madeirafade frem til aftapning i januar 2023, hvor den blev tappet ved en fadstyrke på 52%. SBS Venezuela 2006 rom har aroma af mørke skovbær og melasse. Smagen er tør med markante noter fra madeirafadet, der følges af noter af brændt sukker og karamel. SBS Venezuela 2006 rom er ikke koldfiltreret og er ikke tilsat sukker, farve eller andre tilsætningsstoffer. Rommen er en limited edition på blot 334 flasker, kun tappet til det danske marked. 52 % - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Venezuela 2009 Rom (Bottled for Belgium/Holland/France)', 'https://rombo.dk/products/sbs-venezuela-2009-rom-bottled-for-belgium-holland-france', 725, true, NULL, 46, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBSSingleBarrelSelectionRumVenezuela2009Rom.png?v=1780997829', 'SBS Venezuela 2009 Bourbon Cask rom er en del af Single Barrel Selection serien, der består af unikke enkeltfadsaftapninger, som er "non-chill filtered" og uden tilsætning af sødme eller farve. Denne helt særlige SBS Venezuela 2009 Bourbon Cask rom er nr. 221 i SBS-serien, og den er faktisk udgivet i Belgien, Holland og Frankrig, men vi fik mulighed for at skaffe nogle få flasker ifm. en SBS-romsmagning i butikken. Single Barrel Selection Venezuela 2009 er baseret på melasse og kolonne-destilleret i 2009. Rommen er modnet på klassiske bourbonfade, og den er aftappet i september 2025. Når man dufter til denne rom, fornemmes noter af vanilje, cremet karamel, tørret frugt, kakao og honning. Smagen er blød og cremet med noter af vanilje, kokos, rosiner, overmoden banan, kanel, muskatnødder og mørk chokolade. Der er kun tappet 318 flasker ved 46% vol.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Venezuela 2014 Swedish Oak Rombo Edition', 'https://rombo.dk/products/sbs-venezuela-2014-swedish-oak', 699, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SBS_Venezuela_2014_Swedish_Oak_Rombo_Edition.png?v=1787057418', 'Denne unikke SBS Venezuela 2014 single cask rom er tropisk lagret i 9 år i Venezuela på ex-bourbonfade, og herefter er den lagret i 2 år i Danmark på noget så særligt som Swedish Virgin Oak / nyt svensk egetræ. Da vi hørte om fadet og derefter smagte på rommen, skyndte vi os at bestille hele fadet til Rombo. Vi erindrer ikke, at vi tidligere har smagt rom, der har lagret på Swedish Virgin Oak. Samtidig er smagen kompleks og vedholdende med noter af bl.a. mørk chokolade, kaffe, tørret frugt og egetræskrydderier. SBS Venezuela 2014 Swedish Oak Rombo Edition er den 215. udgivelse i den fantastiske SBS-serie (Single Barrel Selection). Vanen tro er der ikke tilsat sødme i rommen. For at bevare den naturlige smag er den ej heller blevet kølefiltreret. Limited edition med kun 245 flasker. 52% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SBS Venezuela 2016 Bourbon and Oloroso Cask (bottled for Sweden)', 'https://rombo.dk/products/sbs-venezuela-2016-sweden', 749, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_bc2a94c7-38f6-466b-af95-afc33b698bc6.png?v=1769439573', 'SBS Venezuela 2016 Bourbon and Oloroso Cask er en single cask rom, der egentlig er lavet eksklusivt til det svenske marked, men det lykkedes os at få fat på nogle meget få flasker, der blev fundet på lageret hos producenten 1423 ApS. Rommen er lavet på melasse og kolonnedestilleret i Venezuela. De 8 års lagring er foregået i henholdsvis ex-bourbonfade og moscatelfade. Fadet er udvalgt af "Lee Sernehov" i Sverige. Kun 423 flasker i alt. Non-chill filtered. 50% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Skotlander Bunker Rum', 'https://rombo.dk/products/skotlander-bunker-rum-batch-2', 499, false, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/SkotlanderBunkerRum.jpg?v=1776954844', 'Skotlander Bunker Rum fra danske Anders Skotlander er en helt unik rom, der - som navnet siger - faktisk har lagret i en nordjysk bunker fra 2. verdenskrig i 12 graders varme og med 90% luftfugtighed, hvilket giver en langsom modningsproces. Lagringen er foregået i bourbonfade samt små PX og Oloroso sherryfade, og rommen er lavet af alle 3 typer sukkerrør; dvs. melasse, friskpresset sukkerrørsjuice og sukkerrørssirup, der er blevet inddampet. Sammen med den lange fermentering på hele 30 dage, giver både de mangfoldige sukkerrørstyper og den specielle lagring en rom med fantastisk kompleksitet. Derudover har rommen en afbalanceret sødme, der samtidig gør den let at nyde. Når man dufter, fremkommer spændende aromaer af brunet smør, friske blomster og bergamotte. Smagen byder på noter af modne stenfrugter, nybagt brød og flødekaramel. Der er kun lavet 3.000 nummerede flasker af denne Skotlander Bunker Rum Batch No. 2. Destilleret i 2016 - Tappet i 2024. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Smith & Cross Traditional Jamaica Rum', 'https://rombo.dk/products/smith-cross-traditional-jamaica-rum', 275, true, 70, 57, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Smith_Cross_Traditional_Jamaica_Rum.png?v=1787046229', 'Smith &amp; Cross Traditional Jamaica Rum er en Pure Pot Still- rom med Navy Strength - altså 57% ABV. Rommen er ikke kølefiltreret, da man ønsker at bevare den høje kompleksitet og den fulde romsmag, der ofte forsvinder i denne proces. En række cocktails kan laves udfra Smith &amp; Cross Traditional Jamaica Rum, og det gælder bl.a. Million og The Doctor. Opskrifterne på disse står på etiketten bag på flasken. 57% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Stroh Original 80%', 'https://rombo.dk/products/stroh-rom-80', 349, true, 100, 80, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a3906249-b0c4-4633-810e-23094809d7b7.png?v=1769422113', 'Stroh Original Austria Inländer Rum 80% er en østrigsk klassiker. Den stærke spiritus er blevet krydret med en masse ekstrakter og essenser og har smag af demerara-sukker, flødekaramel, melasse og sirup. Lang eftersmag af krydderier som nelliker og muskat. Brug Stroh Original 80% til din jägertee, grog, punch, cocktail eller madlavning. 80% - 100 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Takamaka Extra Noir Charred Cask Rum', 'https://rombo.dk/products/takamaka-extra-noir-rum', 325, true, 70, 43, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_d818a9b7-0a18-4228-a4ab-79a573226399.png?v=1769438297', 'Takamaka Extra Noir Charred Cask Rum er rom fra den tropiske og smukke ø, Seychellerne, hvor Takamaka Rum laver både rom og likør på Trois Freres Distillery. Takamaka Rum blev grundlagt i 2002 af de lokale brødre, Richard og Bernard d’Offay, der ønskede at skabe en rom, som indkapsler sjælen af Seychellerne. Nu findes Takamaka i mere end 35 markeder på verdensplan, og takket være deres innovation og kvalitet vokser de hurtigt og har også vundet masser af flotte priser. Faktisk blev Takamaka''s Master Blender, Steven Rioux, også kåret til Blender of the Year 2024 af The Spirits Business Awards. Takamaka Extra Noir Charred Cask Rum er et godt sted at starte, hvis man vil kaste sig ud i "naturlig rom", hvor der ikke er tilsat nogen sødme. Den er et blend af pot og kolonne destilleret melassebaseret rom, der har trukket på fransk egetræ og presset med både fransk egetræ og tidligere bourbon fade. Til sidst hviler rommen på fade fra tidligere fransk sukkerrørsrom i 60 dage. Takamaka Extra Noir Charred Cask Rum har en fyldig smag med noter af vanilje og blide egetræskrydderier fra fadene. Non-chill filtered. 43% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Takamaka Koko Coconut likør', 'https://rombo.dk/products/takamaka-koko-likor', 169, true, 70, 25, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_67ea2fda-5fec-4925-8f06-ca2c2d638cb1.png?v=1769438291', 'Takamaka Koko likør er fra den tropiske og smukke ø, Seychellerne, hvor Takamaka Rum laver både rom og likør på Trois Freres Distillery. Takamaka Rum blev grundlagt i 2002 af de lokale brødre, Richard og Bernard d’Offay, der ønskede at skabe en rom, som indkapsler sjælen af Seychellerne. Nu findes Takamaka i mere end 35 markeder på verdensplan, og takket være deres innovation og kvalitet vokser de hurtigt og har også vundet masser af flotte priser. Faktisk blev Takamaka''s Master Blender, Steven Rioux, også kåret til Blender of the Year 2024 af The Spirits Business Awards. Takamaka Koko Coconut likør har markante noter af kokos fra Seychellerne samt antydninger af vanilje, og man henføres næsten til paradiset, når man dufter og smager. Likøren kan nydes rent eller on the rocks. Alternativt kan den toppes of med ananasjuice som en Pina Colada. 25% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Takamaka Kreol Cask rom', 'https://rombo.dk/products/takamaka-kreol-cask', 375, true, 70, 40.3, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_e2044a37-d655-4b90-bf0f-7fd6ddc1fb9c.png?v=1769439693', 'Takamaka Kreol Cask er en sød/mellemsød rom fra Takamaka Rum på den eksotiske ø, Seychellerne, og den er destilleret på Trois Freres Distillery. Rommen er fremstillet efter den traditionelle ø-ånd med anvendelse af den friskpressede sukkerrørsjuice. Denne lokale rom er slutteligt blendet sammen med rom fra Foursquare Distillery på Barbados, som har lagret i 8 år på amerikanske egetræsfade. Når man smager denne Takamaka Kreol Cask, får man en harmonisk, rund og blød rom med tydelige frugtnoter, brunt sukker, kaffe og kakao i fin balance. 40,3% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Takamaka Overproof Rum', 'https://rombo.dk/products/takamaka-overproof-rum', 325, true, 70, 69, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6134b1b8-8399-49f1-a855-4b5b41f3d6e8.png?v=1769438294', 'Takamaka Overproof Rum er rom fra den tropiske og smukke ø, Seychellerne, hvor Takamaka Rum laver både rom og likør på Trois Freres Distillery. Takamaka Rum blev grundlagt i 2002 af de lokale brødre, Richard og Bernard d’Offay, der ønskede at skabe en rom, som indkapsler sjælen af Seychellerne. Nu findes Takamaka i mere end 35 markeder på verdensplan, og takket være deres innovation og kvalitet vokser de hurtigt og har også vundet masser af flotte priser. Faktisk blev Takamaka''s Master Blender, Steven Rioux, også kåret til Blender of the Year 2024 af The Spirits Business Awards. Takamaka Overproof Rum repræsenterer den ærlige, rå karakter af klassisk hvid rom. Pga. alkoholstyrken leveres en høj intensitet med stærke og varmende undertoner. Rommen har noter af citrus, vanilje, banan og græs. Takamaka Overproof Rum kan nydes/tæmmes med frisk lime og sukker, eller den kan give din tropiske cocktail et kick. 69% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Tanduay Matured Dark 10 års rom', 'https://rombo.dk/products/tanduay-matured-dark-10-ars-rom', 275, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Tanduay_Matured_Dark_10_ars_rom.png?v=1770818085', 'Denne Tanduay Matured Dark Rum er en 10 års rom fra Filippinerne, og den er ganske anderledes i sit udtryk end Don Papa, der også kommer derfra. Tanduay Matured Dark 10 års rom er mindre sød og kan klassificeres som mellemsød. Rommen er lagret i minimum 10 år på bourbonfade. I duft og smag finder man vanilje, karamel og tropiske frugter. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Tanduay Overproof Reserve Dark rom', 'https://rombo.dk/products/tanduay-overproof-reserve-dark-rom', 349, true, 70, 50.5, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Tanduay_Overproof_Reserve_Dark_rom.png?v=1770818084', 'Denne Tanduay Overproof Reserve Dark Rum er en rom fra Filippinerne, og den er fundamentalt anderledes i sit udtryk end Don Papa, som også kommer derfra. Tanduay Overproof Reserve Dark rom kan klassificeres som mellemsød og så ovenikøbet med et ekstra "pift", da den er tappet ved en højere alkohol-procent. Rommen er et blend af kolonnedestillater og pot still rom, og den lagret i minimum 3 år på bourbonfade. I duft og smag finder man vanilje, karamel og tropiske frugter. 50,5% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Terra Verde A Christmas Spirit', 'https://rombo.dk/products/terra-verde-a-christmas-spirit', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9f68179c-600a-4edc-898a-d0289f476758.png?v=1769438066', 'Terra Verde A Christmas Spirit er skabt for at glæde sanserne hos enhver, der værdsætter en sødere, men stadig karakterfuld og smagfuld sukkerrørsspiritus. Noterne gør den særlig god i juleperioden, og den smager også godt resten af året. Terra Verde A Christmas Spirit byder på en harmonisk blanding af vanilje, karamel og kokos, der dominerer smagsoplevelsen. Den efterlader en virkelig spændende og blød fornemmelse, der ledsages af en langvarig sødme. Aldringen på bourbonfade er tydelig i denne spiritus, og det tilføjer kompleksitet til oplevelsen. Terra Verde betyder ''grøn jord'', og som resten af ​produkterne fra ’A Clean Spirit’ er denne sukkerrørsspiritus baseret på et ønske om at gøre en bæredygtig forskel. Destilleriet, som Terra Verde A Christmas Spirit er lavet på, er et af de mest bæredygtige i verden, blandt andet ved at være selvforsynende i grøn energi og ved genbrug af biomasse fra produktionen til brug som naturlig gødning. Derudover er alle flasker lavet af 100% genbrugsglas. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Terra Verde A Midsummer Spirit', 'https://rombo.dk/products/terra-verde-a-midsummer-spirit', 349, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f046d4cf-b2a4-4bb9-86e7-698159fd93c6.png?v=1769437335', 'Terra Verde A Midsummer Spirit er en dejlig imødekommende sukkerrørsspiritus, der er præget af en vedvarende sødme med en blød afslutning! Denne XO dominikanske Midsummer Spirit gennemgår omhyggelig lagring i bourbon-fade, hvilket tilfører en imponerende kompleksitet og velkendte smagsindtryk. De lækre Terra Verde A Midsummer Spirit noter omfatter chokolade, delikate hints af egetræ og mørke krydderier, samt en markant indflydelse fra modningen i bourbon-fade. Smagen er blød og sød, og den ulmer med de velkendte smagsindtryk af chokolade, diskret eg og mørke krydderier, samt tydelige indtryk fra bourbon-fadet. Terra Verde betyder ''grøn jord'', og som resten af ​produkterne fra ’A Clean Spirit’ er denne drik baseret på et ønske om at gøre en bæredygtig forskel. Destilleriet, som A Midsummer Spirit er lavet på, er et af de mest bæredygtige i verden, blandt andet ved at være selvforsynende i grøn energi og ved genbrug af biomasse fra produktionen til brug som naturlig gødning. Derudover er alle flasker lavet af 100% genbrugsglas. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Terra Verde Retro XO', 'https://rombo.dk/products/terra-verde-retro-xo', 235, true, 70, 35, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Terra_Verde_Retro_XO.png?v=1779171383', 'Retro XO er en del af Terra Verde serien, der byder på sød sukkerrørsspiritus fra Den Dominikanske Republik. Med Terra Verde Retro XO får man god værdi for pengene. Den kan sagtens nydes rent, og den kan også anvendes som ingrediens til cocktails. Smagen er blød, sød og behagelig, og flasken kan vel nærmest beskrives som en "crowd pleaser" med noter af vanilje, karamel og moden frugt. 35% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Terra Verde Twin Cask Rum', 'https://rombo.dk/products/terra-verde-twin-cask-rum', 225, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/RomboTerraVerdeTwinCaskRum.png?v=1770724364', 'Terra Verde Twin Cask Rum er lidt mindre sød end de øvrige Terra Verde udgaver, så den kommer lidt tættere på den mellemsøde rom. Terra Verde Twin Cask er er en rom fra Den Dominikanske Republik, der er lagret i minimum 4 år på bourbonfade, og efterfølgende har den fået en ekstra lagring på Oloroso sherryfade. Den kombinerede lagring giver rommen en smuk dybde og en elegant kompleksitet, og den kan både nydes ren og som base til din cocktail. Noter af vanilje, karamel og tørret frugt. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Terra Verde XO Cask Strength', 'https://rombo.dk/products/terra-verde-xo-cask-strength', 349, true, 70, 54, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f45ee111-60e5-479c-9c3c-71ec947f984b.png?v=1769435620', 'Terra Verde XO Cask Strength præsenterer en ekstraordinær sammensætning af raffinerede elementer og med en højere alkoholprocent end Terra Verde XO Original er det en virkelig fornøjelig og kraftfuld sukkerrørsspiritus. Når du smager denne bløde og delikate Terra Verde XO Cask Strength, vil noter af mørk chokolade, brændt sukker og appelsinskal omslutte din næse og mund. Den langvarige aldringsproces på bourbonfade er tydeligt tilstede og tilføjer en imponerende kompleksitet til drikken. Selvom den er tilsat 65 gram sukker, er dens kraft og kompleksitet uomtvistelig, hvilket gør den ideel at sippe. Sødmen er smukt afbalanceret og harmonisk og forener sig på fortryllende vis med den højere alkoholprocent. Resultatet er komplekst, afbalanceret og utrolig behageligt. Terra Verde betyder ''grøn jord'', og som resten af produkterne fra ’A Clean Spirit’ er denne spiritus baseret på et ønske om at gøre en bæredygtig forskel. Destilleriet, som Terra Verde XO er lavet på, er et af de mest bæredygtige i verden, blandt andet ved at være selvforsynende i grøn energi og ved genbrug af biomasse fra produktionen til brug som naturlig gødning. Derudover er alle flasker lavet af 100% genbrugsglas. 54% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Terra Verde XO Original', 'https://rombo.dk/products/terra-verde-xo-original', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6e13cf68-95ec-4271-8bd9-227c12832b15.png?v=1769435626', 'Terra Verde XO Original er skabt for at glæde sanserne hos enhver, der værdsætter en sødere, men stadig karakterfuld og smagfuld sukkerrørsspiritus. Terra Verde XO Original byder på en harmonisk blanding af mørk chokolade, flødekaramel, karamel og appelsinskal, der dominerer smagsoplevelsen. Den efterlader en virkelig spændende og blød fornemmelse, der ledsages af en langvarig sødme. Aldringen på bourbonfade er tydelig, og det tilføjer kompleksitet til oplevelsen. Terra Verde betyder ''grøn jord'', og som resten af ​produkterne fra ’A Clean Spirit’ er denne sukkerrørsspiritus baseret på et ønske om at gøre en bæredygtig forskel. Destilleriet, som Terra Verde XO er lavet på, er et af de mest bæredygtige i verden, blandt andet ved at være selvforsynende i grøn energi og ved genbrug af biomasse fra produktionen til brug som naturlig gødning. Derudover er alle flasker lavet af 100% genbrugsglas. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Terra Verde XOS Chocolate Extra Old Sweet', 'https://rombo.dk/products/terra-verde-chocolate-xos', 349, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_60ec1da8-694a-4350-bb09-16ab1164401e.png?v=1769439614', 'Terra Verde Chocolate XOS Extra Old Sweet er en sukkerrørsspiritus, der er gæret og destilleret i Den Dominikanske Republik, og den har fået tilført noter af mælkechokolade og kakao. Terra Verde betyder ’grøn jord’, og som resten af produkterne fra '' A Clean Spirit ’ er disse produkter baseret på et ønske om at gøre en bæredygtig forskel. Det betyder bl.a. også, at flaskerne er lavet af 96 % genbrugsglas. Terra Verde Chocolate XOS Extra Old Sweet er ekstra sød, blød og hyggelig. Udover noterne af mælkechocolade og kakao, så finder man også karamel og hints af mandler. 38% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Terra Verde XOS Extra Old Sweet Coconut', 'https://rombo.dk/products/terra-verde-extra-old-sweet', 325, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f863de18-1fc8-4a2e-92de-7fea470b13d7.png?v=1769437339', 'Terra Verde XOS Extra Old Sweet en dominikansk sukkerrørsspiritus, der leverer en rund, blød og mild smagsoplevelse med en lækker sød eftersmag. Denne sukkerrørsspiritus er lagret omhyggeligt på bourbonfade, og den opnår en flot kompleksitet samt flere dimensioner. Terra Verde tilbyder en helt speciel og unik oplevelse, og den er perfekt til dem, der elsker en sødere smag. Terra Verde betyder ''grøn jord'', og som resten af ​produkterne fra ’A Clean Spirit’ er denne drik baseret på et ønske om at gøre en bæredygtig forskel. Destilleriet, som Terra Verde XOS Extra Old Sweet er lavet på, er et af de mest bæredygtige i verden, og det sker blandt andet ved at være selvforsynende i grøn energi og ved genbrug af biomasse fra produktionen til brug som naturlig gødning. Derudover er alle flasker lavet af 100% genbrugsglas. BEMÆRK: opdateret produktbillede følger. 40% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('The Real McCoy 12 års rom', 'https://rombo.dk/products/the-real-mccoy-12-years', 549, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_35996960-ce92-487c-b3a9-c2179e023c90.png?v=1769438174', 'The Real McCoy Rum 12 år er produceret på Barbados af Foursquare Distillery, og når Richard Seale fra Foursquare står bag noget, så er det garanti for en vis romkvalitet. Big McCoy var navnet på den vel nok mest kendte "romsmugler" under forbudstiden i 1920-1933 i USA, hvor alkohol var forbudt. Samtidig var han dog også kendt for at indsmugle rom af god og ærlig kvalitet i stedet for at blande spiritussen med kunstig og ofte også farlig tilsætning, og derfor blev hans produkter også kvalitetsstemplet som "The Real McCoy". The Real McCoy 12 års rommen er fadlagret i minimum 12 år, og den har bl.a. noter af egetræ, mørk chokolade, karamel, appelsinskal og tobak. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Tres Hombres La Palma 2013 Edition 04 rom', 'https://rombo.dk/products/tres-hombres-la-palma-2013-edition-04-rom', 599, true, 70, 42, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_0d8a22f7-b14b-479b-89fa-00bcd5ee367b.png?v=1769439595', 'Tres Hombres La Palma 2013 Edition 04 er en 15 år gammel rom, der er lavet til Tres Hombres af Aldea Distillery med lokale sukkerrør på Gran Canaria. Rommen er pot still destilleret, lagret på franske egetræsfade og mellemsød. Den spændende historie om Tres Hombres rom tager udgangspunkt i det smukke Tres Hombres sejlskib, der transporterer sin Fairtransport Rum fra romproducenter til Holland, hvorefter selvsamme skib sejler videre til bl.a. Danmark for at aflæsse årets "rom-høst". Det 2-mastede skib har ingen motor, så det kræver sin kaptajn at lægge til havn, hvis vinden blæser. Vi har ofte selv besøgt skibet, når det har været i København. Tres Hombres La Palma 2013 Edition 04 er en limited edition rom, der faktisk er udgået af markedet for mange år siden, men det lykkedes os i september 2025 at finde nogle glemte flasker hos den danske importør. 42% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Tres Hombres La Palma 2017 Ron Miel Edition 16', 'https://rombo.dk/products/tres-hombres-la-palma-2017', 375, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_6e8a35f6-e198-4a1d-95e7-63eb2cd00e95.png?v=1769439601', 'Tres Hombres La Palma Ron Miel 2017 Edition 16 er en rom, der er lavet til Tres Hombres af Aldea Distillery med lokale sukkerrør på Gran Canaria. Rommen er pot still destilleret og lagret på spanske egetræsfade. Der er iht. gamle traditioner på Gran Canaria tilsat en smule honning, og rommen er derfor sød. Den spændende historie om Tres Hombres rom tager udgangspunkt i det smukke Tres Hombres sejlskib, der transporterer sin Fairtransport Rum fra romproducenter til Holland, hvorefter selvsamme skib sejler videre til bl.a. Danmark for at aflæsse årets "rom-høst". Det 2-mastede skib har ingen motor, så det kræver sin kaptajn at lægge til havn, hvis vinden blæser. Vi har ofte selv besøgt skibet, når det har været i København. Tres Hombres La Palma Ron Miel 2017 Edition 16 er en limited edition rom (kun 1.789 flasker), der faktisk er udgået af markedet for mange år siden, men det lykkedes os i september 2025 at finde nogle glemte flasker hos den danske importør. 45% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Velier Chamarel 2017 Mauritius Pure Single Rum', 'https://rombo.dk/products/velier-chamarel-2017-mauritius-pure-single-rum', 1149, true, NULL, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/VelierChamarel2017MauritiusPureSingleRum_345985e0-22de-45ad-b7a7-5f23695127ca.png?v=1791281816', 'Denne unikke Velier Chamarel 2017 Mauritius Pure Single Rum blev lanceret på Whisky Live Paris i 2026. Rhumerie de Chamarel har siden 2008 destilleret deres egen rom med anvendelse af blå, gule og røde sukkerrørstyper fra den 200 hektar store "estate" på det sydvestlige Mauritius. Velier Chamarel 2017 rommen er lavet på den friskpressede sukkerrørsjuice, der er blevet fermenteret i to dage, pot still destilleret og tropisk lagret i 8 år i cognacfade, hvilket har ført til 45% angels'' share. Der er ikke tilsat sukker til denne rom, og den er tappet ved 63% fadstyrke. Profilen byder på florale, krydrede og medicinske noter samt tropiske frugter, sukkerrør, honning og friske urter.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Velier Clairin 2020 Vieux Sajous 5 års rom', 'https://rombo.dk/products/velier-clairin-vieux-sajous-caroni-cask-5-ars-rom', 999, true, 70, 59.52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/VelierClairin2020VieuxSajous5arsrom.png?v=1788264489', 'Velier Clairin 2020 Vieux Sajous 5 års rom kommer fra destilleriet Chelo i Saint-Michel-de-l’Attalaye, hvor Michel Sajous producerer Clairin fra sukkerrør af sorten Cristalline. Vieux Sajous fremhæver styrken fra en Clairin, der er lagret i 5 år i de 19 fade, som tidligere har indeholdt single malt whisky eller rom. Interaktionen mellem destillatet og fadet har gjort denne rom yderst kompleks, samtidig med at den bevarer den aromatiske friskhed fra råmaterialet. Haiti betragtes som rommens sidste grænse, og landets signaturrom, "Clairin", er indbegrebet af dette. Da Veliers CEO, Luca Gargano, besøgte Haiti for første gang i 2012, blev han overrasket over at finde hele 532 fungerende destillationsapparater på øen. Til sammenligning er der kun 42 destillerier i drift i hele Caribien. Haiti er fyldt med primitive destillerier. Disse små produktioner er spredt ud over øen, og er endnu ikke påvirket af den vestlige verdens modernisering. Fra det perspektiv virker Haiti stadig ''ren''. Biodiversiteten er overvældende, og hver region på øen har sin egen unikke produktionsmetode, sin egen variant af sukkerrør og sin egen specifikke Clairin med karakteristiske aromaer. Velier har udvalgt og aftappet Clairin, der virkelig viser denne diversitet, både i fermenterings- og destillationsteknikker samt i de anvendte sukkerrørssorter. Clairin, eller "Kleren" som det hedder på kreolsk, er den fattiges rom. Det står som et levende minde om den caribiske produktionsmetode fra slutningen af 1700-tallet, en tid hvor rom var et essentielt handelsprodukt. Velier''s Clairin er et eksempel på den ekstraordinære diversitet i haitianske produkter. For at kvalificere sig til Veliers sortiment skal Clairin dog opfylde nogle strenge krav. Sukkerrørssorterne skal være lokale og ikke hybride. Dyrkningen skal være økologisk, uden brug af kemikalier. Sukkerrør skal høstes i hånden og transporteres med traditionelle metoder. Fermentering skal ske naturligt, uden tilsætning af industriel gær, og samtidig vare i mindst 120 timer. Destillation skal foregå i specifikke apparater, og det endelige produkt skal tappes og flaskes i Haiti. 59,52% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Velier Distillerie de Port Au Prince White Rum', 'https://rombo.dk/products/velier-distillerie-de-port-au-prince-white-rum', 899, true, 70, 59, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_a3d7bf3c-23b5-45b3-a34a-82dababdf6b4.png?v=1769436805', 'Velier Distillerie de Port Au Prince White Rum er lavet udelukkende på sukkerrørssorten cristalline. Den er dobbelt-destilleret på pot still, første gang i Saint Michel de l’Attalaye hvor sukkerrørene dyrkes, og anden gang ved Distilerie du Port au Prince i Haitis hovedstad. Det er endnu en rom i Velier''s prestigefulde samling, hvor der kun unikke udgaver, både hvid og lagret rom, strengt taget kun fra pot stills. På hver etiket findes: En illustration af den anvendte alembic; destillationsåret; indholdet af estere i de enkelte aftapninger; fremhævelse af tropisk lagring og den let ironiske angivelse ''sugar free'' for at indikere, at der ikke er tilsat sukker. Etiketten bringer Velier''s nøglebegreber til den passionerede forbruger. Velier Distillerie de Port Au Prince White Rum har en duft, der afslører intense noter af guava, der kombineres med subtile toner af honning og friskklippet græs, hvilket skaber en indbydende og kompleks bouquet. Ved første tår udfolder rommens smagsprofil sig med livlige nuancer. Den komplekse blanding af tropisk frugt, især den markante smag af ananas, vækker sanserne og kombineres elegant med hints af hvid peber og kokos. Den har et esterniveau på 289 gr/hlAA. Kan nydes rent eller i cocktails. 59% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Velier National Rums of Jamaica Cambridge STC♥E 2005', 'https://rombo.dk/products/velier-national-rums-of-jamaica-cambridge-stce-2005', 2799, true, NULL, 75, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2c798a35-31cb-4137-88e2-e870c1b9c616.png?v=1769437147', 'Velier National Rums of Jamaica Cambridge STC♥E 2005 er en autentisk Pure Single Rum fremstillet af en blanding fra 10 ex-bourbonfade destilleret i 2005 og lagret på Jamaica i et helt tropisk klima indtil 2023. Ligesom alle Long Pond-rom bevares traditionen med de mest autentiske spiritus fra Trelawny, et område med stor biodiversitet, der historisk set repræsenterer grand cru''en af jamaicansk rom. Destillationen foregår i dobbelt retort Pot Still. Angels’ share er på over 75%. STC ❤ E er et kendt marque fra destilleriet Cambridge Estate, der lukkede i 1947, og som er blevet genskabt af Long Pond. Denne rom er lavet i Continental Flavoured-stilen, som er en af fire klassifikationer, der anvendes i Jamaica, og identificerer rom med et esterniveau på 700-1600 gr/hlpa ved destillationstidspunktet. Denne rom har det specifikke mark: STC♥E, hvilket står for Simon Thompson Cambridge Estate. I rommens historie betragtes Jamaica absolut som det førende land. For at genopdage dets historie har Velier skabt sortimentet ''National Rum of Jamaica'', som præsenterer enkeltmærke-udgaver af historisk jamaicansk rum. Formålet er at skabe et repertoire af disse opskrifter, som indtil for få år siden stort set ikke var blevet udforsket. Velier National Rums of Jamaica Cambridge STC♥E 2005 præsenterer sig som ældet gylden med kobberfarvede reflekser. Næsen er raffineret og distinkt med en vidunderlig velafbalanceret karakter, der kombinerer abrikos, vanilje samt mineralholdige og empyreumatiske noter med eksotiske frugter som mango og en krydret undertone af ingefær og kardemomme. Smagsoplevelsen er livlig og fyldig med en delikat tekstur, der nøjagtigt gengiver næsens kompleksitet, før den udfolder sig med frugtige noter af abrikos og mango, samt vanilje og træagtige nuancer på midten af ganen. Afslutningen er lang og rig, hvor rørsukker, melasse og geraniumhonning blødgør smagspaletten, mens eftersmagen afsluttes med noter af saltet smørkaramel og toffee, der tilføjer en fyldig og behagelig afrunding. BEMÆRK: Begrænset udgivelse med kun 2717 flasker til verdensmarkedet. Derfor sælges max. 1 stk. pr. kunde.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Velier Vieux Casimir 10 Years Rum', 'https://rombo.dk/products/velier-vieux-casimir-10-years-rum', 1795, true, NULL, 55.9, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/VelierVieuxCasimirAged10YearsRumFromHawaiiSugarCane.png?v=1791208092', 'Denne helt særlige Vieux Casimir 10 Years Rum blev lanceret af LM&amp;V (La Maison &amp; Velier) på Whisky Live Paris i 2026, og det er - sammen med Vieux Vaval - den ældste Clairin, der nogensinde er blevet tappet af The Spirit of Haiti. Faktisk er den også lavet på noget så sjældent som sukkerrør fra Hawaii. Vieux Casimir blev destilleret i 2016 i Grand Terroir of Baradères, og den er tappet på flaske ved 55,9% vol. De mange års tropisk lagring i ex-Caroni romfade har givet rommen meget komplekse aromaer. Næsen byder på bl.a. jod, sennepsfrø, mango, citrus, tørrede urter, kanel og kryddernellike. I smagen findes muskatnødder, sort peber, tropiske frugter, læder, tobak, appelsinskal, vanilje og kakao.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Veritas White Barbados og Jamaica Blended Rum', 'https://rombo.dk/products/veritas-white-blended-rum', 275, true, 70, 47, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_25dac371-173f-4641-9cc5-13c06fed2ca3.png?v=1769425175', 'Veritas White Rum blended af rom fra Foursquare-destilleriet på Barbados og Hampden-destilleriet på Jamaica. Veritas betyder "sandheden" og henviser vel nok til, at der ikke er tilsat sukker eller andet i denne rom. Blandingen består nærmere beskrevet af Coffey kolonnedestilleret rom fra Foursquare og pot still-destilleret rom fra Hampden. Veritas White Blended Rum er målrettet cocktail-folket og dem, der søger en rom med "lidt mere spark i". 47% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Warehouse #1 Legendary Marques MLC single cask rom', 'https://rombo.dk/products/warehouse-1-legendary-marques-mlc-rom', 699, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Warehouse_1LegendaryMarquesMLCrom_ce92d2ef-79f2-4e19-97ea-f783a33cacf2.png?v=1780411544', 'Warehouse #1, der ligger i Prag i Tjekkiet, er specialister i kvalitetsspiritus såsom rom, whisky, cognac, m.m., og derudover har de lavet deres helt egen serie af rom, der selvfølgelig også hedder Warehouse #1. Eller som det står på etiketten: "WRHS#1". Denne Warehouse #1 MLC rom fra det kendte Clarendon destilleri er en del af Rums of Jamaica Legendary Marques rom-serien, der består af høj-ester udgaver fra flere af de legendariske destillerier på Jamaica. I serien findes også DOK (fra Hampden), WPE (fra Worthy Park), TECA (fra Long Pond) og NYE-WK (fra New Yarmouth). Warehouse #1 Legendary Marques MLC single cask rommen er "vild-fermenteret" i 2 uger, pot still destilleret og kontinentalt lagret i 4 år på et Virgin Oak fad. MLC er ensbetydende med et ester-indhold på 500 – 600 g/hlpa, som er det højeste fra Clarendon Distillery. Profilen er aromatisk, frugtig og krydret. 52% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Warehouse #1 Legendary Marques NYE-WK single cask rom', 'https://rombo.dk/products/warehouse-1-legendary-marques-nye-wk-single-cask-rom', 699, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Warehouse_1LegendaryMarquesNYE-WKrom.png?v=1780470211', 'Warehouse #1, der ligger i Prag i Tjekkiet, er specialister i kvalitetsspiritus såsom rom, whisky, cognac, m.m., og derudover har de lavet deres helt egen serie af rom, der selvfølgelig også hedder Warehouse #1. Eller som det står på etiketten: "WRHS#1". Denne Warehouse #1 NYE-WK rom fra det kendte New Yarmouth Distillery er en del af Rums of Jamaica Legendary Marques rom-serien, der består af høj-ester udgaver fra flere af de legendariske destillerier på Jamaica. I serien findes også MLC (fra Clarendon), WPE (fra Worthy Park), TECA (fra Long Pond) og DOK (fra Hampden). Warehouse #1 Legendary Marques NYE-WK single cask rommen er pot still destilleret, kontinentalt lagret i 4 år på et Virgin Oak fad, og den har et ester-indhold på 1.500 – 1.600 g/hlpa. I duften og smagen finder du klassisk "Jamaica funk" samt noter af acetone, lime, pære, fersken, peber og medicinske undertoner. 52% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Warehouse #1 Legendary Marques TECA single cask rom', 'https://rombo.dk/products/warehouse-1-legendary-marques-teca-single-cask-rom', 699, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Warehouse_1LegendaryMarquesTECArom.png?v=1780469810', 'Warehouse #1, der ligger i Prag i Tjekkiet, er specialister i kvalitetsspiritus såsom rom, whisky, cognac, m.m., og derudover har de lavet deres helt egen serie af rom, der selvfølgelig også hedder Warehouse #1. Eller som det står på etiketten: "WRHS#1". Denne Warehouse #1 TECA rom fra Long Pond Dstillery er en del af Rums of Jamaica Legendary Marques rom-serien, der består af høj-ester udgaver fra flere af de legendariske destillerier på Jamaica. I serien findes også MLC (fra Clarendon), WPE (fra Worthy Park), DOK (fra Hampden) og NYE-WK (fra New Yarmouth). Warehouse #1 Legendary Marques TECA single cask rommen er gæret med "dunder", pot still destilleret, kontinentalt lagret i 4 år på et Virgin Oak fad, og den har et ester-indhold på 1.200 – 1.300 g/hlpa. I duften og smagen finder du klassisk "Jamaica funk" samt noter af overmoden banan, papaya, mango, oliven og peber. 52% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Warehouse #1 Legendary Marques WPE single cask rom', 'https://rombo.dk/products/warehouse-1-legendary-marques-wpe-single-cask-rom', 699, true, 70, 52, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Warehouse_1LegendaryMarquesWPErom.png?v=1780468945', 'Warehouse #1, der ligger i Prag i Tjekkiet, er specialister i kvalitetsspiritus såsom rom, whisky, cognac, m.m., og derudover har de lavet deres helt egen serie af rom, der selvfølgelig også hedder Warehouse #1. Eller som det står på etiketten: "WRHS#1". Denne Warehouse #1 WPE rom fra det kendte Worthy Park destilleri er en del af Rums of Jamaica Legendary Marques rom-serien, der består af høj-ester udgaver fra flere af de legendariske destillerier på Jamaica. I serien findes også MLC (fra Clarendon), DOK (fra Hampden), TECA (fra Long Pond) og NYE-WK (fra New Yarmouth). Warehouse #1 Legendary Marques WPE single cask rommen er destilleret i en Forsyth double-retort pot still, kontinentalt lagret i 4 år på et Virgin Oak fad, og den har et ester-indhold på 800+ g/hlpa. I duften og smagen finder du klassisk "Jamaica funk" samt medicinske noter, overmoden banan, tropisk frugt og acetone. 52% vol. - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Wild Series Rum No. 66 Australia', 'https://rombo.dk/products/wild-series-rum-66-australia', 1099, true, 70, 76.2, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_252731c2-7883-4098-ae67-bcde907462ba.png?v=1769439637', 'Wild Series Rum No. 66 Australia fra Romdeluxe er en rom fra det ældste operationenelle destilleri i Australien. Rommen er lokalt lagret hos producenten, hvorefter den har lagret 3 år ekstra i Danmark. Med sin høje alkoholstyrke og ingen tilsætning af sødme, så er der fuld smæk på duft og smag. Der er tale om en limited edition med kun 169 flasker i alt. 76,2% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('William Hinton Rum Agricola da Madeira 3 års rom', 'https://rombo.dk/products/william-hinton-rum-agricola-madeira-3', 475, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c30f7902-f325-48ca-b9f2-2a4e8baf268f.png?v=1769438449', 'William Hinton Rum Agricola da Madeira 3 års rom er fra producenten Engenho Novo på den portugisiske ø, Madeira, og rommen har faktisk været en del af 24 Days of Rum kalenderen i 2022, hvor flasken også er blevet aftappet. Rommen er lavet på den friskpressede sukkerrørsjuice. Det helt særlige ved flasken er det såkaldte "5 Cask Blend", da den færdigblandede William Hinton 3 års rom har lagret på ikke mindre end 5 forskellige fadtyper: ex-Madeira Wine, Ex-whisky, Ex-brandy, Ex-North of Portugal Fortified Wine og Ex-South of Spain Fortified Wine. De fem fadtyper har givet William Hinton rommen mange forskellige smagsnuancer og aromaer. Master Blenders tasting notes: "Sweet aroma from which the notes of vanilla and wood stand out. In the mouth it enters dry and an intense persistence takes over the senses to open its way to a smooth finish". Kun i alt 720 flasker, der alle er nummererede. 45% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Worthy Park Rum Bar Silver', 'https://rombo.dk/products/rum-bar-silver', 179, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_31364914-9a14-4b48-adc1-52e0b1d6f10d.png?v=1769425288', 'Rum Bar Silver er fremstillet hos Worthy Park Estate, der indimellem sælger sin rom i større partier til andre producenter, men her får du altså deres helt eget rom-mærke. Rum Bar Silver er "Traditional Jamaican Pot-Still" destilleret, baseret på melasse og uden nogen tilsætning, så man får den velkendte Jamaica "funk". I næsen finder man bl.a. tropisk frugt, banan, citrus og vanilje, imens smagen byder på noter af bl.a. banan, smør og eucalyptus. Rum Bar Silver er perfekt som ingrediens i cocktails. 40% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Worthy Park Select Rom', 'https://rombo.dk/products/worthy-park-select-rom', 249, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5929bcdf-ace1-41d7-a6de-c0c86ef53b7d.png?v=1769427316', 'Worthy Park Select er rom, der er produceret på Worthy Parks egne sukkerrør og destilleret, lagret, blandet og aftappet på Worthy Park Estate. Melassen er destilleret på kobber pot stills og har herefter lagret på tidligere bourbonfade af amerikansk hvideg i tropisk klima. Rommen er blandet af udvalgte fade, der har lagret i mellem 4 og 12 år, og tilsammen er de blevet en smooth, delikat rom. Worthy Park Select har aroma af vanilje, kanel, tropisk frugt, appelsin og banan og smagsnoter af melasse, chokolade og et strejf af fersken, der efterfølges af cremede karamelnoter og egetræ. 40% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Worthy Park Single Estate 12 års Rom', 'https://rombo.dk/products/worthy-park-single-estate-12-ars-rom', 799, true, 70, 50, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Worthy_Park_Single_Estate_12_rs_Rom.png?v=1787135322', 'Worthy Park Single Estate 12 års Rom er 100% destilleret i en kobber Pot still. Rommen er derefter tropisk lagret i 12 år på tidligere brugte American White Oak Ex-Bourbon fade. Den er aftappet ved 50 % ABV. Worthy Park Single Estate 12 års Rom er ikke-kølefiltreret, og du vil ikke finde sukker eller andre tilsætningsstoffer i flasken. Forestil dig at stå 1.200 fod over havets overflade, med udsigt over mere end 9.000 hektar frodig løv, en blanding af sukkerrørsmarker og naturlige skove. Betagende dale forener de bølgende bjergkæder, der står vagt over stilke af sukkerrør, der svajer i den kølige bjergbrise. Dette er Worthy Park Estate. Deres sukkerfabrik har produceret sukker og melasse med uformindsket styrke siden 1720; og denne selvsamme melasse bruges til destillation af al deres rom. Indledende duftnoter af banan og eg med saltlage, oliven, citrus, vanilje og en røget kombination af tobak og læder understreget med en mild sød note. Den milde sødme fortsætter i smagen sammen med honning, banan, citrus, karamel og eg. En lang finish med noter af læder og tobak. 50% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Worthy Park Single Estate Reserve Rom', 'https://rombo.dk/products/worthy-park-single-estate-reserve-rum', 499, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_2780ed2c-08b5-434b-8ddf-bb03aa4cdb29.png?v=1769423173', 'Worthy Park Single Estate Reserve Rum er lagret i ex-bourbonfade af hvid amerikansk eg i 6-10 år og afslutningsvis blendet. Der er ikke tilsat hverken sukker eller andre tilsætningsstoffer i Worthy Park Single Estate Reserve Rum på nær en smule karamel for at give en ensartethed i farven. En autentisk og traditionel Jamaica rom. 45% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Worthy Park Special Cask Release Virgin Oak Vintage 2013 Rum (bottled for Belgium)', 'https://rombo.dk/products/worthy-park-virgin-oak-vintage-2013', 799, true, 70, 55, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_4f3330d3-f262-49ea-91b7-690fbedc70d6.png?v=1769439579', 'Worthy Park Special Cask Release Virgin Oak Vintage 2013 Rum er faktisk en rom, der udelukkende er tappet til Belgien (bottled for The Nectar), men da der blev fundet nogle få overskydende flasker på lageret hos den danske importør, 1423 ApS, fik vi lov til at købe dem. Rommen er melasssebaseret og pot still destilleret hos Worthy Park på øen Jamaica i 2013. Her blev den også tropisk lagret i 4 år i ex-bourbonfade, inden den fik 2 års ekstra lagring på Virgin Oak fade i Danmark. En autentisk og klassisk Jamaica-rom med masser af udtryk og ingen tilsætning af sødme. Cask Selection Series #6. Limited edition - kun 342 flasker. 55% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Worthy Park Special Cask Series Calvados Rom', 'https://rombo.dk/products/worthy-park-rom-special-cask-series-calvados', 899, true, 70, 45, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Worthy_Park_Special_Cask_Series_Calvados_Rom.png?v=1787135380', 'Worthy Park Special Cask Series Calvados er en 10-årig rom destilleret i en 100% kobber pot Still. Først er den lagret i et Ex-Bourbon-fad derefter har fået en anden omgang modning på et Ex-Calvados-fad. Forestil dig at stå 1200 fod over havets overflade, med udsigt over mere end 9.000 hektar frodig løv, en blanding af sukkerrørsmarker og naturlige skove. Betagende dale forenes de bølgende bjergkæder, der står vagt over stilke af sukkerrør, der svajer i den kølige bjergbrise. Dette er Worthy Park Estate. Deres sukkerfabrik har produceret sukker og melasse med uformindsket styrke siden 1720; og denne selvsamme melasse bruges til destillation af al deres rom. Calvados-fadenes indflydelse er øjeblikkelig på næsen. Dette kombineret med traditionelle Worthy Park-noter minder om en frugtkurv; tropiske frugtsmage af banan og sapodilla blandet med æbler og blomsternoter. Sød karamel, lidt vanilje og kanel er afrundet med en subtil røgethed er også til stede i duften. Når man smager, bliver man mødt med en mere afdæmpet sødme med en indviklet blanding af de frugtsmage, der kommer igennem. En næsten menthol-agtig afkøling, der bliver hængende i finishen, kombineret med svage strejf af karamel og mørk chokolade. Det er en begrænset aftapning, så få fat i en, mens du kan! Du finder intet sukker eller andre tilsætningsstoffer i flasken, kun ren jamaicansk rom. 45% – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Worthy Park White Overproof 63%', 'https://rombo.dk/products/worthy-park-white-overproof', 249, true, 70, 63, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_5e7ba071-2e25-475d-8729-e31c5847b128.png?v=1769422605', 'Worthy Park White Overproof er fremstillet hos Worthy Park Estate, der ellers normalt sælger sin rom i større partier til andre producenter, men her får du altså deres helt eget rom-mærke. Worthy Park White Overproof er "Traditional Jamaican Pot-Still" destilleret, og med de 63% og den kraftige, frugtige smag er rommen perfekt som ingrediens i cocktails. 63% - 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Wray & Nephew White Overproof Rum 63%', 'https://rombo.dk/products/wray-nephew-overproof-rum', 275, true, 70, 63, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_9ede63c6-15d8-4eaa-9443-1211b3fdcc74.png?v=1769422538', 'Wray &amp; Nephew White Overproof Rum er den absolut førende, lokale rom i Jamaica, hvor den bruges til både medicin, husholdning og almindelig rom/cocktail-nydelse. Wray &amp; Nephew White Overproof Rum er destilleret hos Appleton (en del af Campari Group). J. Wray &amp; Nephew er en naturlig bestanddel i en del barer, der ynder at bruge den til cocktails som eksempelvis MaiTai. 63% – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ypióca Reserva Carvalho Cachaca', 'https://rombo.dk/products/cachaca-ypioca-carvalho', 199, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ypi_ca_Reserva_Carvalho_Cachaca.png?v=1787063628', 'Cachaca Ypióca Reserva Ouro Carvalho er en cachaca fra Brasilien, der er oplagt som ingrediens i en caipirinha - brasilianernes nationaldrik. Cachaca er Brasiliens svar på rom, da den også er baseret på sukkerrør, og I Ypiócas tilfælde kommer alle sukkerrør fra egne plantager. Cachaca Ypióca Carvalho er lagret i 2 år på fade fra Carvalho, der giver produktet en gylden farve. Ca. 4.000 mennesker er ansat til kun at flette basten, der dekorerer flasken. 38% – 70cl. Du kan finde Ypiócas egen opskrift på en caipirinha cocktail drink her.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ypióca Reserva Castanheira Cachaca', 'https://rombo.dk/products/cachaca-ypioca-prata', 199, true, 70, 38, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/Ypi_ca_Reserva_Castanheira_Cachaca.png?v=1787054377', 'Cachaca er Brasilien''s svar på rom, da den også er baseret på sukkerrør, og I Ypiócas tilfælde kommer alle sukkerrør fra egne plantager. Cachaca Ypióca Prata er lagret i 2 år på Freijo fade, der giver produktet en klar farve. Flasken kommer i en flot autentisk indpakning – de håndflettede bastcovers, og virksomheden har ca. 4.000 mennesker ansat alene til at flette basten, der dekorerer flasken. 38% vol. – 70cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Zafra Master Series 21 års Rom', 'https://rombo.dk/products/zafra-rum-21-master-reserve', 525, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_66213fed-ec6d-440f-b04b-2938ca8fba70.png?v=1769421496', 'Zafra Rum 21 år Ron Master Reserve er en rom fra Panama, der bl.a. også er vært for Ron Abuelo og Rum Malecon rom-serierne. Zafra 21 år Ron Master Reserve er lagret på ex. bourbon egetræsfade og har en flot, mørk farve. Duft: appelsin, kirsebær, pære, toffee og egetræ. Smag: krydderier og igen appelsin, toffee og egetræ. 40 % – 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Zafra Master Series 30 års Rom', 'https://rombo.dk/products/zafra-30-ar-master-reserve-rum', 1495, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_f141791d-faf0-409e-873d-e17a79c1848e.png?v=1769433961', 'Zafra Master Series 30 års er en helt unik rom, der er skabt af den tidligere Master Ronero fra Havana Club. Rommen er destilleret på et meget højt kolonnedestilleringsapparat, hvilket giver en meget ren rom. Efter destillering har rommen lagret i hele 30 år på tidligere bourbonfade, hvilket er ret usædvanligt. Gennem hele lagringen er fadene blevet sorteret, og kun de bedste er blevet udvalgt til at nå hele vejen til at blive tappet som Zafra 30 år Master Reserve Rum. Rommen har en flot balance mellem kompleksitet og sødme, som gør den perfekt at nyde sammen med en god cigar. Kun 6720 flasker er tappet til hele verdensmarkedet. Kommer i graveret og nummereret flaske og flot gaveæske. 40% ­­­– 70 cl.');
INSERT INTO stg_rombo_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Zaya Gran Reserva Rom', 'https://rombo.dk/products/zaya-gran-reserva-16', 499, true, 70, 40, 'https://cdn.shopify.com/s/files/1/0985/3911/0748/files/output_c5caa37d-962a-4920-b798-9343b0516e24.png?v=1769423412', 'Zaya Gran Reserva Solera 16 års rom er en længe ventet lancering efter den meget populære "Zaya 12 år Gran Reserva". Zaya er ejet af Infinium Spirits, og rommen bliver idag produceret af Trinidad Distillers Ltd., der er en del af Angostura i Trinidad &amp; Tobago. Zaya Gran Reserva var tidligere lagret i op til 12 år, hvorefter man skippede aldersbetegnelsen. Men i den nyere version af Zaya Gran Reserva Solera 16 år har rommen fået aldersbetegnelsen tilbage og nogle Solera år ekstra på bagen. Rommen har fortsat noter af bl.a. vanilje, chokolade og kaffe. 40% - 70 cl.');
