-- ============================================================
-- ROMBO.DK: Staging-tabel + 498 produkter (hentet 2026-11-07
-- via Shopifys products.json — ingen scraping nødvendig!)
--
-- Kør hele filen i Supabase SQL Editor.
-- Bagefter kør:  SELECT * FROM import_shop('Rombo.dk',
--                  'https://rombo.dk', 'stg_rombo_dk', 'Rom');
-- ============================================================

DROP TABLE IF EXISTS stg_rombo_dk;

CREATE TABLE stg_rombo_dk (
    name         TEXT,
    url          TEXT UNIQUE,
    price_dkk    NUMERIC,
    in_stock     BOOLEAN,
    volume_cl    NUMERIC,      -- NULL = ikke fundet (gaveæsker m.m.)
    abv          NUMERIC,
    image_url    TEXT,
    description  TEXT,
    scraped_at   TIMESTAMPTZ DEFAULT '2026-11-07 17:00:00+01'
);


-- KONTROL
SELECT count(*) AS total,
       count(*) FILTER (WHERE in_stock) AS paa_lager,
       count(*) FILTER (WHERE volume_cl IS NULL) AS uden_volumen,
       count(*) FILTER (WHERE abv IS NULL) AS uden_abv,
       min(price_dkk) AS billigste,
       max(price_dkk) AS dyreste
FROM stg_rombo_dk;
